/* ═══════════════════════════════════════════════════════════
   RESPONSIVE — tous appareils
   1280px  Desktop large
   1024px  Laptop / tablette paysage
   768px   Tablette portrait
   480px   Mobile large
   390px   Mobile compact (iPhone)
═══════════════════════════════════════════════════════════ */

/* ── (blocs ≤1280px / ≤1024px supprimés : doublons contredits par le bloc « RESPONSIVE —
   comprehensive overrides » de fin de fichier, qui reste l'unique source de vérité :
   flex-basis 55%/52% y écrasait déjà le 50% d'ici, .pd-drawer/.np-panel y sont identiques,
   `.clock-card` était une classe morte (la vraie classe est .clock-item) et clock-time 16px
   rendait l'heure plus petite à 1024px qu'à 768px (21px)) ── */

/* ── Tablette portrait (≤768px) ── */
@media (max-width: 768px) {
  :root {
    --topbar-h: 44px;
    --navbar-h: 40px;   /* = min-height tactile des .nav-item (bloc hover:none) → plus de rognage/scroll vertical dans la navbar */
    --header-h: calc(var(--topbar-h) + var(--navbar-h));
  }

  html, body { overflow-x: hidden; overflow-y: auto; }   /* pas de scroll horizontal parasite */

  /* Layout vertical sur mobile */
  .main-layout {
    height: auto;
    min-height: calc(var(--vph) - var(--header-h));
    flex-direction: column;
    overflow: visible;
  }

  /* views-col pleine hauteur (le flux occupe tout l'écran sur mobile) */
  .views-col {
    flex: 1;
    width: 100%;
    min-width: unset;
    height: calc(var(--vph) - var(--header-h));
    min-height: 0;
  }

  .view-panel { flex-direction: column; height: 100%; overflow: visible; }

  /* Panneau news */
  .panel-news {
    width: 100% !important;
    min-width: unset;
    flex: 1;
    border-right: none;
    border-bottom: none;
  }
  /* Colonne de droite (World Clock + Session Map + courbes) : masquée par défaut sur mobile…
     …mais accessible via l'onglet MARCHÉS (affichage plein écran). */
  .panel-right { display: none !important; }
  .nav-item--mobile-only { display: flex !important; }
  .main-layout.show-right-mobile .views-col { display: none !important; }
  .main-layout.show-right-mobile #panel-right {   /* #panel-right (1,2,0) bat le hide global .hide-right-panel #panel-right (1,1,0) */
    display: flex !important;
    width: 100%;
    min-width: 0;
    height: calc(var(--vph) - var(--header-h));
  }

  /* Topbar — icônes ESPACÉES et propres : plus aucun chevauchement AI / RISK ON / onde.
     Le centre (pilule sentiment) passe en overflow:hidden → au pire il se rogne proprement,
     il n'est PLUS recouvert par les icônes de droite ; chaque icône est en flex:none avec
     une taille tactile uniforme (30px) et un gap régulier. */
  .topbar-symbol-search { display: none; }
  /* CRUCIAL : en desktop .topbar-center est en position:absolute centré (50%/translate) → sur
     mobile la pilule restait PLANTÉE au milieu, SOUS les icônes de droite (chevauchement).
     On la repasse DANS LE FLUX flex : elle se place naturellement entre la gauche et la droite,
     se rétrécit si besoin (min-width 0 + overflow hidden) et ne peut plus être recouverte. */
  /* flex-START : les icônes Journal + Calculatrice se calent juste après le logo et restent
     TOUJOURS visibles ; si la place manque, c'est la pilule sentiment (dernière, à droite)
     qui se rogne — plus jamais le Journal (qui se faisait clipper à gauche en flex-end). */
  .topbar-center { position: static; transform: none; flex: 1 1 auto; display: flex; align-items: center; gap: 4px; padding: 0 6px; justify-content: flex-start; min-width: 0; overflow: hidden; }
  .topbar-right  { gap: 8px; padding-left: 10px; padding-right: 8px; flex: 0 0 auto; }
  .topbar-icon { width: 30px; height: 30px; flex: 0 0 auto; }
  .topbar-icon svg { width: 17px; height: 17px; }
  .topbar-icon--ai svg { width: 19px; height: 19px; }
  /* Bouton AI compact sur mobile (évite de surcharger la topbar) */
  .topbar-ai-btn { height: 28px; padding: 0 7px; font-size: 10px; }
  .topbar-ai-soon { font-size: 7px; padding: 1px 3px; }
  /* Pilule sentiment compacte : RISK ON lisible, flèche masquée, jamais recouverte */
  .topbar-sentiment { width: auto !important; min-width: 0; flex: 0 0 auto; padding: 0 8px; height: 28px; font-size: 9px; letter-spacing: .04em; }
  .sentiment-arrow { display: none; }
  #topbar-avatar { flex: 0 0 auto; }
  /* La bannière d'alerte prend trop de place sur mobile */
  .breaking-news-flash { display: none !important; }
  .logo { flex-shrink: 0; min-width: 0; }
  .logo-text { font-size: 15px; white-space: nowrap; }
  /* Onglet BANK : empilé, table scrollable, graphique dessous */
  .bank-layout { flex-direction: column; }
  .bank-chart-col { width: 100%; min-width: 0; border-left: none; border-top: 1px solid var(--border); height: var(--bank-chart-h, 340px); }   /* unifié avec le bloc ≤1100px */
  .bank-table-wrap { overflow-x: auto; }
  /* Smart Bias : grille scrollable horizontalement, horloges en grille */
  .sbm-grid-wrap { overflow-x: auto; -webkit-overflow-scrolling: touch; }   /* (était .sb-grid-wrap : classe morte — la classe réelle générée par app.js est .sbm-grid-wrap) */
  .sb-clock { min-width: 50%; }

  /* Navbar scroll horizontal */
  .navbar    { overflow-x: auto; flex-wrap: nowrap; -webkit-overflow-scrolling: touch; }
  .nav-item  { white-space: nowrap; flex-shrink: 0; font-size: 11px; padding: 0 10px; }

  /* Horloges COMPACTES sur mobile : une PUCE par ville (code or + heure + jour/nuit) au lieu des
     cartes desktop 5 lignes qui mangeaient la moitié de l'écran ET clippaient la ligne GMT
     (max-height 42% du panneau). Le détail complet (date/GMT/ville/météo/vent) reste sur desktop. */
  .clocks-panel { max-height: none; }
  .clocks-bar { display: flex; flex-wrap: wrap; gap: 6px; padding: 8px 10px 2px; background: transparent; }
  .clock-item, .clock-item--local { flex: 1 1 30%; flex-direction: row; align-items: center; justify-content: center; gap: 6px; padding: 6px 8px; border: 1px solid var(--border); border-radius: 6px; background: var(--bg1); }
  .clock-top-row, .clock-mid-row, .clock-sub-row { display: none; }
  .clock-time { display: flex; align-items: center; gap: 6px; font-size: 13.5px; margin: 0; }
  .clock-code { display: inline; font-size: 10px; font-weight: var(--fw-bold); color: var(--orange); letter-spacing: .06em; }
  .clock-dn-mini { display: inline; font-size: 10px; line-height: 1; }

  /* Calendrier */
  .cal-toolbar-top { flex-wrap: wrap; gap: 4px; }
  .cal-filter-bar  { flex-wrap: wrap; }

  /* Onglets panel droit */
  .right-panel-tabs { overflow-x: auto; flex-wrap: nowrap; }
  .right-tab { flex-shrink: 0; }

  /* Bias */
  .bias-layout  { flex-direction: column; }
  .bias-sidebar { width: 100%; height: auto; border-right: none; border-bottom: 1px solid var(--border); }

  /* Drawers pleine largeur */
  .pd-drawer  { width: 100%; border-left: none; }
  .np-panel   { width: 100%; }
  .settings-panel { width: 100%; }

  /* Bank Research */
  .br-document { padding: 24px 20px; font-size: 14px; }
  .br-doc-title { font-size: 22px; }
  .br-ing-tagline { font-size: 11px; }
  /* Reader rapport : le HTML « email » des banques (tables/divs à largeur FIXE + bannières larges)
     débordait à droite sur mobile — l'img était bornée à son PARENT fixe, pas à l'écran. On borne
     TOUT le contenu à la largeur de l'écran et on coupe le débordement horizontal résiduel. */
  .br-rcontent { overflow-x: hidden; }
  .br-doc-body, .br-doc-body * { max-width: 100% !important; box-sizing: border-box; }
  .br-doc-body img { width: auto !important; height: auto !important; }
  /* Tables « email-layout » : on les fait REFLOWER (cellules empilées, pleine largeur) au lieu de
     scroller/déborder → le contenu tient dans l'écran au lieu d'être coupé à droite. */
  .br-doc-body table, .br-doc-body thead, .br-doc-body tbody, .br-doc-body tr, .br-doc-body td, .br-doc-body th { display: block !important; width: 100% !important; }
  .br-doc-body td, .br-doc-body th { border-width: 0 0 1px 0 !important; }

  /* Analyst reader */
  .arlib-rcontent { padding: 12px; }

  /* INSTITUTION / ANALYST : la barre recherche + filtres passe sur 2 lignes au lieu de déborder à droite */
  .br-toolbar, .arlib-toolbar { flex-wrap: wrap; }
  .br-search-wrap, .arlib-search-wrap { flex: 1 1 100%; }
  /* …mais .br-filters était flex-shrink:0 + 3 selects à largeur FIXE (160+192+256 = 608px) → la
     barre restait à 608px (plus large que l'écran) → le 3e filtre « Tous les instituts » était
     coupé à droite (et inatteignable). On la met pleine largeur et les selects deviennent fluides
     (2 par ligne, plus rien de rogné). */
  .br-filters, .arlib-filters { flex: 1 1 100%; width: 100%; min-width: 0; }
  .br-filters > *, .arlib-filters > * { flex: 1 1 calc(50% - 4px) !important; width: auto !important; min-width: 0 !important; }

  /* News item */
  .news-item { padding: 9px 10px; }
}

/* ── Mobile large (≤480px) ── */
@media (max-width: 480px) {
  .views-col  { height: calc(var(--vph) - var(--header-h)); min-height: 0; }
  .panel-news  { height: 100%; }
  .news-expand-tabs { flex-wrap: wrap; }

  /* Topbar compact */
  .topbar-left  { gap: 6px; }
  .topbar-right { gap: 4px; }
  .topbar-symbol-search { display: none; }
  #topbar-avatar { width: 28px; height: 28px; font-size: 11px; }
  /* Sentiment réduit à sa pastille (label « NEUTRAL » masqué) → libère la place pour que les
     icônes Journal + Calculatrice tiennent ; l'état reste lisible via la couleur du point. */
  #sentiment-label-top { display: none; }
  .topbar-sentiment { padding: 0 6px; }
  /* Cibles tactiles : garder les icônes topbar assez grandes au doigt */
  .topbar-icon { width: 34px; height: 34px; }
  /* Logo raccourci en "DTP" → libère ~110px pour que tout (dont le bouton AI) tienne */
  .logo-text { font-size: 0 !important; letter-spacing: 0; }
  .logo-text::before { content: 'DTP'; font-size: 15px; font-weight: var(--fw-bold); letter-spacing: 0.5px; }

  /* Nav items plus petits */
  .nav-item { font-size: 10px; padding: 0 8px; }

  /* Clock compact */
  .clock-card  { min-width: 86px; padding: 3px 6px; }
  .clock-time  { font-size: 14px; }
  .clock-tz, .clock-city { font-size: 9px; }

  /* Drawers (100% et non var(--vpw) : évite le débordement dû à la scrollbar) */
  .pd-drawer  { width: 100%; }
  .np-panel   { width: 100%; }

  /* Documents */
  .br-document { padding: 16px 14px; }
  .br-doc-title { font-size: 18px; }

  /* Risk popup */
  .risk-popup { width: calc(var(--vpw) - 20px); min-width: unset; }
}

/* ── Mobile compact (≤390px) ── */
@media (max-width: 390px) {
  .nav-item   { font-size: 9px; padding: 0 6px; }
  .clock-card { min-width: 78px; }
  .clock-time { font-size: 13px; }
  .br-document { padding: 12px 10px; font-size: 13px; }
}

/* ── Touch devices : supprimer les :hover non désirés ── */
@media (hover: none) and (pointer: coarse) {
  .news-item:hover        { background: transparent; }
  .br-card:hover          { background: transparent; }
  .arlib-card:hover       { background: transparent; }
  .pd-section-trigger:hover { background: transparent; }
  /* Scrollbars invisibles sur mobile */
  .navbar::-webkit-scrollbar,
  .clocks-bar::-webkit-scrollbar,
  .right-panel-tabs::-webkit-scrollbar { display: none; }
}

