.wr-bullet::before { content:"•"; color:#e3b23a; position:absolute; left:0; }
.wr-bullet strong { color:#fff; font-weight:var(--fw-semibold); }
.wr-hint { color:#7a8493; font-size:12px; font-style:italic; margin:4px 0 0; }
/* Weekly Recap — Section BANQUES CENTRALES (synthèse par banque + Interprétation de marché) */
.wr-cb-grid { display:flex; flex-direction:column; gap:10px; margin:8px 0 4px; }
.wr-cb-card { background:#0f0f12; border:1px solid #17171c; border-left:2px solid #e3b23a; border-radius:8px; padding:12px 14px; }
