.wr-cb-stance { font-family:var(--tight); font-weight:800; font-size:10px; letter-spacing:.05em; padding:2px 9px; border-radius:20px; text-transform:uppercase; white-space:nowrap; }
.wr-cb-stance--hawkish { color:#fff; background:#059669; }   /* haussier → vert */
.wr-cb-stance--dovish { color:#fff; background:#dc2626; }    /* baissier → rouge */
.wr-cb-stance--neutral { color:#e5e7eb; background:#4b5563; }/* maintien/attentiste → gris */
.wr-cb-narr { color:#c9d1d9; font-size:13px; line-height:1.7; margin:0; }
.wr-cb-narr p { margin:0 0 8px; } .wr-cb-narr p:last-child { margin-bottom:0; }
.wr-cb-quote { margin:11px 0 0; padding-left:13px; border-left:2px solid rgba(227,178,58,.45); }
.wr-cb-q { margin:0; font-style:italic; font-size:13px; line-height:1.55; color:#e6d9b8; }
.wr-cb-q::before { content:"« "; } .wr-cb-q::after { content:" »"; }
.wr-cb-a { margin:5px 0 0; font-size:12.5px; line-height:1.6; color:#c3c6cc; }
.wr-cb-a::before { content:"→ "; color:#e3b23a; font-weight:700; }
.wr-cb-narr strong, .wr-cb-a strong { color:#fff; font-weight:var(--fw-semibold); }
/* Weekly Recap v18 — Banques Centrales NIVEAU INSTITUTIONNEL (biais 5 niveaux + probas marché + prochaine réunion) */
.wr-cb-card { margin-bottom:10px; }
.wr-cb-intro { color:#8b93a1; font-size:12px; line-height:1.55; margin:2px 0 12px; }
/* v21 : Banques Centrales EN PUCES (coherence avec les Points Macro) — petit badge biais + citation */
.wr-cb-bullet { line-height:1.65; }
.wr-cb-bullet strong { color:#fff; font-weight:var(--fw-semibold); }
.wr-cb-tag { display:inline-block; font-family:var(--tight); font-weight:800; font-size:9px; letter-spacing:.03em; padding:1px 7px; border-radius:20px; white-space:nowrap; vertical-align:1px; }
/* Couleur SÉMANTIQUE (demande user) : hawkish = HAUSSIER pour la devise → vert ; dovish = BAISSIER → rouge ;
   neutre/hold (attentiste) = gris. Même palette que la matrice Smart Bias (Very Bullish→Very Bearish). */
.wr-cb-tag--vhawk{ color:#fff; background:#047857; } .wr-cb-tag--hawk{ color:#fff; background:#059669; } .wr-cb-tag--neu{ color:#e5e7eb; background:#4b5563; } .wr-cb-tag--dov{ color:#fff; background:#dc2626; } .wr-cb-tag--vdov{ color:#fff; background:#991b1b; }
.wr-cb-qi { font-style:italic; color:#e6d9b8; }
/* Section Banques Centrales — STRUCTURE deux colonnes façon chronologie (nom+badge à gauche · contenu à droite) */
