.wr-cb-quote-line { font-size: 12px; color: #d7c9a6; font-style: italic; line-height: 1.5; margin-top: 5px; padding-left: 10px; border-left: 2px solid rgba(227,178,58,.4); }
.wr-cb-quote-line b { font-style: normal; color: #e3b23a; }
@media (max-width: 560px) {
