}
/* v20 : Banques Centrales EN LISTE (par banque : decision + prochaine reunion + guidance + propos) */
.wr-cb-list { display:flex; flex-direction:column; gap:8px; margin:2px 0 4px; }
.wr-cb-li { background:#0f0f12; border:1px solid #17171c; border-left:2px solid #e3b23a; border-radius:6px; padding:10px 13px; }
