.wr-cb-li-rate { margin-left:auto; font-family:var(--font-mono); font-size:11px; color:#9aa3b2; }
.wr-cb-li-row { font-size:12.5px; line-height:1.55; color:#c9d1d9; margin:2px 0; }
.wr-cb-li-row b { color:#e8eaed; }
.wr-cb-li-k { font-family:var(--tight); font-size:9.5px; font-weight:800; letter-spacing:.05em; text-transform:uppercase; color:#e3b23a; margin-right:5px; }
.wr-cb-li-guid { color:#aeb6c2; }
.wr-cb-li-quote { margin:6px 0 0; padding-left:11px; border-left:2px solid rgba(227,178,58,.4); }
.wr-cb-bias { font-family:var(--tight); font-weight:800; font-size:10px; letter-spacing:.04em; padding:2px 9px; border-radius:20px; white-space:nowrap; }
.wr-cb-bias--vhawk { color:#fff; background:#047857; }   /* très haussier → vert foncé */
.wr-cb-bias--hawk  { color:#fff; background:#059669; }   /* haussier → vert */
.wr-cb-bias--neu   { color:#e5e7eb; background:#4b5563; }/* maintien → gris */
.wr-cb-bias--dov   { color:#fff; background:#dc2626; }   /* baissier → rouge */
.wr-cb-bias--vdov  { color:#fff; background:#991b1b; }   /* très baissier → rouge foncé */
.wr-cb-src { font-size:9px; font-weight:700; letter-spacing:.03em; text-transform:uppercase; color:#8b93a1; background:#1a1a1f; border:1px solid #2a2a30; border-radius:4px; padding:1px 5px; white-space:nowrap; cursor:help; }
.wr-cb-rate { margin-left:auto; font-family:var(--font-mono); font-size:11px; color:#9aa3b2; white-space:nowrap; }
.wr-cb-head .wr-cb-src + .wr-cb-rate { margin-left:6px; }
.wr-cb-proba { display:flex; flex-wrap:wrap; gap:6px 16px; margin:2px 0 6px; }
.wr-cb-prob { display:inline-flex; align-items:center; gap:5px; font-size:12px; color:#aeb6c2; }
.wr-cb-prob b { color:#e8eaed; font-family:var(--font-mono); }
.wr-cb-dot { width:7px; height:7px; border-radius:50%; display:inline-block; }
.wr-cb-dot--hike { background:#22c55e; } .wr-cb-dot--hold { background:#6b7280; } .wr-cb-dot--cut { background:#ef4444; }   /* hausse=haussier vert · maintien gris · baisse=baissier rouge */
.wr-cb-bar { display:flex; height:5px; border-radius:3px; overflow:hidden; background:#17181d; margin:0 0 10px; }
.wr-cb-bar i { display:block; height:100%; }
.wr-cb-bar--hike { background:#22c55e; } .wr-cb-bar--hold { background:#4b5563; } .wr-cb-bar--cut { background:#ef4444; }
.wr-cb-next { font-size:12px; color:#c9d1d9; margin:0 0 10px; padding:6px 9px; background:#0c0c0f; border:1px solid #17171c; border-radius:6px; }
.wr-cb-next b { color:#e3b23a; }
.wr-cb-block { margin:0 0 8px; }
.wr-cb-lbl { display:block; font-family:var(--tight); font-size:10px; font-weight:800; letter-spacing:.06em; text-transform:uppercase; color:#e3b23a; margin:0 0 3px; }
.wr-cb-txt { color:#c9d1d9; font-size:13px; line-height:1.65; }
.wr-cb-txt strong { color:#fff; font-weight:var(--fw-semibold); }
.wr-cb-quotes { margin:10px 0 0; }
.wr-cb-mini-head { font-family:var(--tight); font-size:11px; font-weight:800; letter-spacing:.05em; text-transform:uppercase; color:#7a8493; margin:14px 0 8px; }
.wr-cb-mini-wrap { display:flex; flex-direction:column; gap:6px; }
.wr-cb-mini { display:flex; align-items:center; gap:10px; flex-wrap:wrap; background:#0f0f12; border:1px solid #17171c; border-radius:6px; padding:7px 11px; }
.wr-cb-mini-name { font-family:var(--tight); font-weight:var(--fw-bold); font-size:13px; color:#e8eaed; min-width:52px; }
.wr-cb-mini-proba { font-family:var(--font-mono); font-size:11px; color:#9aa3b2; }
.wr-cb-mini-next { margin-left:auto; font-size:11px; color:#8b93a1; }
@media (max-width:760px){ .wr-cb-mini-next { margin-left:0; } .wr-cb-proba { gap:4px 12px; } }
/* Weekly Recap v18 — Calendrier économique (À venir + Cette semaine), réutilise les styles gew-* */
.wr-cal-sub { font-family:var(--tight); font-size:11px; font-weight:800; letter-spacing:.05em; text-transform:uppercase; color:#e3b23a; margin:16px 0 4px; padding-bottom:5px; border-bottom:1px solid var(--border); }
.wr-cal-flagcell { display:inline-flex; align-items:center; gap:5px; flex-shrink:0; }
.wr-cal-flag { border-radius:2px; vertical-align:middle; }
.wr-cal-ccy { font-family:var(--font-mono); font-size:10px; font-weight:700; color:#9aa3b2; }
/* Global Economic Weekly — Consensus Forecasts JOUR PAR JOUR (façon pro) */
/* Calendrier GEW : structure deux-colonnes façon chronologie (jour rail or à gauche · événements à droite),
   séparateurs fins entre jours → cohérent avec le Récap Hebdo. */
.gew-day { display:flex; gap:16px; padding:13px 0; border-top:1px solid var(--hud-line,var(--border)); margin:0; }
.gew-day:first-child { border-top:0; padding-top:4px; }
.gew-day-h { flex:0 0 104px; display:flex; flex-direction:column; align-items:flex-start; gap:3px; padding-top:9px; color:#e3b23a; font-family:var(--tight,'Inter Tight',sans-serif); font-size:12.5px; font-weight:var(--fw-bold); letter-spacing:.05em; text-transform:uppercase; border-bottom:0; }
.gew-day-date { color:#7a8493; font-size:10.5px; font-weight:var(--fw-semibold); letter-spacing:.02em; text-transform:none; line-height:1.35; }
.gew-day-evs { flex:1 1 auto; min-width:0; }
.gew-ev { padding:9px 0 9px 11px; border-bottom:1px solid var(--bg2); border-left:2px solid #1c1d22; }
.gew-ev--high { border-left-color:#ff3d00; background:rgba(255,61,0,.03); }
.gew-ev--med  { border-left-color:rgba(255,179,0,.42); }
.gew-ev:last-child { border-bottom:none; }
.gew-flag { border-radius:2px; margin-right:6px; vertical-align:-2px; flex:0 0 auto; }
.gew-ev-top { display:flex; align-items:baseline; gap:10px; flex-wrap:wrap; }
.gew-ev-time { font-family:var(--font-mono); font-size:10px; color:#7a8493; min-width:64px; }
.gew-ev-ttl { color:#d6dde6; font-size:13px; flex:1; min-width:160px; line-height:1.4; }
.gew-ev-ttl b { color:#fff; font-weight:var(--fw-bold); }
.gew-imp { font-size:9px; font-weight:var(--fw-bold); letter-spacing:.5px; padding:1px 7px; border-radius:4px; flex-shrink:0; }
.gew-imp--high { color:#ff3d00; background:rgba(255,61,0,.13); border:1px solid rgba(255,61,0,.4); }
.gew-imp--med  { color:#ffb300; background:rgba(255,179,0,.12); border:1px solid rgba(255,179,0,.36); }
.gew-ev-cons { display:flex; gap:24px; margin:7px 0 0 74px; }
.gew-cons { display:flex; flex-direction:column; gap:1px; }
.gew-cons i { font-style:normal; font-size:9px; text-transform:uppercase; letter-spacing:.05em; color:#7a8493; }
.gew-cons b { font-family:var(--font-mono); font-size:12px; color:#e5e9ef; font-weight:var(--fw-bold); }
.gew-cons--actual i { color:#c79a4a; }
.gew-cons--actual b { color:#e3b23a; }   /* RÉEL = le résultat publié de la semaine écoulée, mis en avant (or) */
.gew-ev-cmt { margin:7px 0 0 74px; font-size:12px; line-height:1.55; color:#aab2bd; }   /* analyse Econoday-style sous l'événement */
/* Propos réels du discours (minés dans le flux news) : citation en italique, liseré or discret */
.gew-ev-quote { margin:6px 0 0 74px; padding-left:10px; border-left:2px solid rgba(227,178,58,0.45); font-size:12px; line-height:1.5; color:#cbd3dd; font-style:italic; }
@media (max-width:760px){ .gew-day{ flex-direction:column; gap:7px; } .gew-day-h{ flex-basis:auto; flex-direction:row; align-items:baseline; gap:9px; padding-top:0; } .gew-ev-cons{ margin-left:0; gap:18px; } .gew-ev-cmt{ margin-left:0; } .gew-ev-quote{ margin-left:0; } }
/* GEW « Temps forts de la semaine » : cartes scannables des événements à FORT impact (en tête de rapport) */
.gew-key-grid { display:grid; grid-template-columns:repeat(auto-fill, minmax(244px, 1fr)); gap:10px; margin:8px 0 6px; }
.gew-key { background:var(--bg2); border:1px solid var(--border); border-left:3px solid #ff3d00; border-radius:4px; padding:10px 12px; }
.gew-key-h { display:flex; align-items:center; justify-content:space-between; gap:8px; margin-bottom:5px; }
.gew-key-day { color:#e3b23a; font-size:11px; font-weight:var(--fw-bold); letter-spacing:.03em; }
.gew-key-ttl { color:#fff; font-size:13px; font-weight:var(--fw-semibold); line-height:1.35; }
.gew-key-ttl b { color:#cfd6df; font-weight:var(--fw-bold); }
.gew-key-nums { margin-top:6px; font-size:var(--fs-title); color:#8a93a0; }
.gew-key-nums b { font-family:var(--font-mono); color:#e5e9ef; font-weight:var(--fw-bold); }
.gew-key-cmt { margin-top:7px; font-size:12px; line-height:1.5; color:#aab2bd; }
/* Hiérarchie d'impact dans le calendrier : FAIBLE estompé, FORT accentué */
.gew-imp--low { color:#7a8493; background:rgba(122,132,147,.10); border:1px solid rgba(122,132,147,.30); }
.gew-ev--low { opacity:.66; }
.gew-ev--high .gew-ev-ttl { color:#fff; font-weight:var(--fw-semibold); }
/* Graphique de force isolé */
.wr-chart { height:380px; margin:8px 0 4px; background:var(--bg); border:1px solid var(--border); border-radius:4px; overflow:hidden; }
.wr-chart-loading { display:flex; align-items:center; justify-content:center; height:100%; color:#6b7280; font-size:12px; }
/* Bandeau "génération du Weekly Recap en cours" */
.arlib-genbanner { display:flex; align-items:center; gap:9px; margin:0 0 12px; padding:11px 14px; border-radius:4px;
  background:rgba(227,178,58,.08); border:1px solid rgba(227,178,58,.25); color:#ffb066; font-size:12px; }
.arlib-genspin { width:13px; height:13px; border:2px solid rgba(227,178,58,.3); border-top-color:#e3b23a; border-radius:50%; animation:dtpSpin .8s linear infinite; flex-shrink:0; }
@keyframes dtpSpin { to { transform:rotate(360deg); } }
@media (max-width:768px){
  .wr-insight-card { flex-basis:220px; }
  .wr-chart { height:300px; }
  /* Reader Weekly/Analyst : marges réduites pour gagner de la largeur de lecture */
  #arlib-ai-insights { padding:0 14px; }
  .wr-body { padding:0 2px; }
  .wr-doc-title { font-size:14px; }
  .wr-section-title { font-size:13px; }
