  .wr-text, .wr-bullet { font-size:13px; }
  .wr-macro-heading { font-size:12px; }
  /* Titre de la barre nav : le Week Ending passe dessous au lieu de déborder */
  .wr-weekending { display:block; margin-left:0; font-size:12px; }
}

/* ── AI Insights (cartes générées par IA en haut du rapport) ── */
/* AI Insights alignés sur la MÊME colonne centrée que le contenu (inset auto, min 32px) */
#arlib-ai-insights { background: var(--bg2); padding: 0 max(32px, calc((100% - 1040px) / 2)); }
#arlib-ai-insights:empty { display: none; }
.ai-insights-head {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  font-size: 13px; font-weight: var(--fw-bold); color: #e2e8f0;
  padding: 18px 0 12px;
}
.ai-insights-title { display: flex; align-items: center; gap: 8px; font-size: 12px; font-weight: var(--fw-semibold); color: #f4f4f5; }   /* zinc-100, text-xs semibold */
.ai-insights-dot { color: #e3b23a; font-size: 14px; }
.ai-insights-nav { display: flex; align-items: center; gap: 10px; }
.ai-insights-nav button {
  background: none; border: none; color: var(--text3); font-size: 16px; cursor: pointer; padding: 0 4px; line-height: 1;
}
.ai-insights-nav button:hover { color: #fff; }
.ai-insights-count { font-size: 11px; font-weight: var(--fw-medium); color: #737373; font-family: var(--font-mono); }   /* neutral-500 mono */
.ai-insights-load { font-size: 11px; font-weight: var(--fw-medium); color: var(--text4); font-style: italic; }
.ai-insights-loading { font-size: 12px; color: #6b7280; padding: 4px 0 2px; }   /* "Loading summaries…" sous le titre (même endroit que le header final) */
.ai-insights-cards {
  display: flex; gap: 12px; overflow-x: auto; padding-bottom: 18px;   /* gap-3 */
  align-items: stretch;             /* cartes TOUTES À LA MÊME HAUTEUR (cohérence, demande user) ; le texte est
                                       borné (line-clamp sur .ai-card-text) → jamais de carte démesurée qui creuse un gros vide */
  border-bottom: 1px solid #1e1e1e;
  scrollbar-width: none;            /* Firefox : barre masquée */
}
.ai-insights-cards::-webkit-scrollbar { display: none; }   /* Chrome/Safari : barre masquée */
.ai-insights-cards { scrollbar-width: none; }   /* volontairement masquée : la règle globale la ferait réapparaître */
/* Variante FIXE : grille statique, les cartes ne défilent plus / ne bougent plus */
.ai-insights-cards--fixed {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 12px;
  overflow: visible;
}
.ai-insights-cards--fixed .ai-insights-card { flex: none; width: auto; }
/* Icône puce IA (SVG fin, orange) */
.ai-chip { vertical-align: middle; flex-shrink: 0; }
.ai-insights-logo { width: 16px; height: 16px; object-fit: contain; flex-shrink: 0; }   /* logo Macro AI local */
/* Badge marque DTP (blanc, texte noir gras) — en haut du rapport */
.arlib-rnav-right { display: flex; align-items: center; gap: 12px; }
.arlib-dtp-badge {
  background: #ffffff; color: #000; font-weight: var(--fw-bold); font-size: 10px;
  letter-spacing: 0.02em; height: 20px; min-width: 20px; padding: 0 5px; border-radius: 3px;   /* carré net w-5 h-5 façon DTP */
  display: inline-flex; align-items: center; justify-content: center; font-family: var(--font-ui);
}
/* Bouton Masquer/Afficher Insights (en haut du rapport) */
.arlib-hide-insights {
  background: none; border: none; color: var(--text3); font-size: 12px; cursor: pointer;
  font-family: var(--font-ui); display: flex; align-items: center; gap: 6px; transition: color 0.15s;
}
.arlib-hide-insights:hover { color: var(--text); }
.arlib-hide-insights .eye { font-size: 13px; }
.ai-insights-card {
  flex: 0 0 280px; background: var(--bg); border: 1px solid #171717;   /* auto-cols-[280px], noir mat, border neutral-900 */
  border-radius: 4px; padding: 16px;                                  /* p-4 */
  font-size: 11px; line-height: 1.625; color: #e4e4e7; font-weight: 400;
}
.ai-card-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; margin-bottom: 9px; }
.ai-card-asset { font-size: 12px; font-weight: var(--fw-semibold); color: #e4e4e7; }   /* zinc-100 */
.ai-card-text { font-size: 11px; line-height: 1.625; color: #e4e4e7;       /* zinc-200, lisible style terminal */
  display: -webkit-box; -webkit-line-clamp: 5; -webkit-box-orient: vertical; overflow: hidden; }   /* borne la hauteur → cartes uniformes sans carte démesurée */
.ai-bias {
  font-size: 10px; font-weight: var(--fw-bold); letter-spacing: 0.04em; text-transform: uppercase; line-height: 1;
  padding: 3px 6px; border-radius: 3px; white-space: nowrap; border: 1px solid;
}
.ai-bias--buy     { background: rgba(0,204,153,0.10);  border-color: rgba(0,204,153,0.35);  color: #00cc99; }   /* BUY  vert émeraude */
.ai-bias--sell    { background: rgba(255,61,0,0.10);   border-color: rgba(255,61,0,0.35);   color: #ff5a2c; }   /* SELL rouge vif */
.ai-bias--neutral { background: rgba(255,179,0,0.09);  border-color: rgba(255,179,0,0.32);  color: #ffb300; }   /* NEUTRAL ambre doré */
/* Logo + bouton masquer */
.dtp-logo { color: #fff; font-weight: var(--fw-bold); letter-spacing: -0.01em; }

/* ═══════════════════ WEEK AHEAD ═══════════════════ */
.wa-scroll { height: 100%; overflow-y: auto; background: var(--bg); }
.wa-wrap { padding: 18px max(20px, calc((100% - 1040px) / 2)) 44px; }   /* colonne centrée façon DTP */
.wa-head { display: flex; align-items: baseline; gap: 12px; margin-bottom: 14px; }
.wa-title { font-family: var(--font-mono); font-size: 12px; font-weight: var(--fw-bold); color: #e9eaed; letter-spacing: 0.04em; }   /* = .fxl-title (Overview List) */
.wa-week { font-size: 12px; color: #e3b23a; font-weight: var(--fw-semibold); font-family: var(--font-mono); }
/* Navigation par semaine (flèches ‹ › façon calendrier — réutilise .cal-range-arrow). Vit dans la barre
   d'en-tête standard de la vue → alignement vertical centré (pas baseline, la barre est en align-items:center). */
.wa-weeknav { display: inline-flex; align-items: center; gap: 4px; }
.wa-weeknav .wa-week { min-width: 96px; text-align: center; }
.wa-empty { padding: 46px 24px; color: #8a8a90; font-size: 13px; text-align: center; line-height: 1.6; }
.wa-prep { display: flex; flex-direction: column; align-items: center; gap: 14px; padding: 50px 24px; }
.wa-prep-note { color: #8a8a90; font-size: 12px; text-align: center; max-width: 340px; line-height: 1.55; }
/* Sparkline amCharts (Weekly Risk Profile) */
.wa-chartbox { background: var(--bg); border: 1px solid #171717; border-radius: 4px; padding: 10px 12px 4px; margin-bottom: 22px; }
.wa-chart-label { font-size: 10.5px; font-weight: var(--fw-bold); letter-spacing: 0.08em; color: #9aa1ac; margin-bottom: 4px; }   /* plus lisible (demande user 26/07) */
.wa-chart { width: 100%; height: 74px; }
/* Timeline verticale — design "frise" : grands cercles + ligne dégradée + cartes à bordure d'impact */
.wa-timeline { position: relative; }
.wa-timeline::before { content: ''; position: absolute; left: 36px; top: 32px; bottom: 32px; width: 1px; margin-left: -0.5px; background: linear-gradient(to bottom, var(--border), rgba(227,178,58,0.32), var(--border)); }
.wa-day { display: flex; align-items: center; gap: 16px; margin-bottom: 16px; position: relative; }
.wa-node {
  flex: 0 0 72px; width: 72px; height: 72px; border-radius: 50%;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  background: var(--bg2); border: 2px solid var(--border); z-index: 1; transition: border-color .15s, box-shadow .15s, background .15s;
}
.wa-node:hover { border-color: var(--border2); }
.wa-dow   { font-size: 9px; font-weight: var(--fw-medium); color: var(--text2); letter-spacing: 0.08em; text-transform: uppercase; }
.wa-date  { font-size: 21px;  font-weight: var(--fw-bold); color: var(--text); line-height: 1.05; font-variant-numeric: tabular-nums; margin: 1px 0; }
.wa-month { font-size: 9px; font-weight: var(--fw-medium); color: var(--text2); letter-spacing: 0.08em; text-transform: uppercase; }
/* Jour actuel : halo orange */
.wa-day--today .wa-node { background: rgba(227,178,58,0.12); border-color: rgba(227,178,58,0.55); box-shadow: 0 0 18px rgba(227,178,58,0.30); }
.wa-day--today .wa-dow, .wa-day--today .wa-month, .wa-day--today .wa-date { color: var(--text); }
/* Carte du jour — bordure gauche colorée selon l'impact (façon design) */
.wa-card { flex: 1; min-width: 0; background: var(--bg3); border: 1px solid var(--border); border-left: 2px solid #2a2a32; border-radius: 0; padding: 12px 14px; transition: border-color .15s, background .15s; }
.wa-card:hover { border-color: var(--border2); }
.wa-card--high { border-left-color: rgba(255,61,0,0.6); }
.wa-card--med  { border-left-color: rgba(255,179,0,0.5); }
.wa-card-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; margin-bottom: 6px; }
.wa-card-headl { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.wa-card-title { font-family: var(--font-ui); font-size: 13px; font-weight: var(--fw-bold); color: #ffffff; line-height: 1.3; }   /* titres Week Ahead en GRAS + blanc pur (police Inter qui charge bien le 700) */
.wa-flags { display: inline-flex; align-items: center; gap: 5px; flex-wrap: wrap; }
.wa-flags .sbm-flag { width: 15px; height: 15px; border-radius: 50%; object-fit: cover; box-shadow: 0 0 0 1px var(--border); }
.wa-impact { flex-shrink: 0; font-size: 9px; font-weight: var(--fw-semibold); letter-spacing: 0.05em; text-transform: uppercase; padding: 2px 8px; border-radius: 999px; border: 1px solid; white-space: nowrap; display: inline-flex; align-items: center; gap: 4px; }
.wa-impact svg { width: 11px; height: 11px; }
.wa-impact--high   { color: #ff5a3c; background: rgba(255,61,0,0.18);  border-color: rgba(255,61,0,0.35); }
.wa-impact--medium { color: #ffb300; background: rgba(255,179,0,0.16); border-color: rgba(255,179,0,0.30); }
.wa-card-desc {
  font-size: 13px; line-height: 1.55; color: #e8eaed;   /* description en BLANC (demande utilisateur) */
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
}
.wa-card--open .wa-card-desc { -webkit-line-clamp: unset; overflow: visible; }
.wa-more { background: none; border: none; cursor: pointer; color: #e3b23a; font-size: 12px; font-weight: var(--fw-medium); font-family: var(--font-ui); padding: 6px 0 0; display: inline-flex; align-items: center; gap: 5px; }
.wa-more:hover { color: #e3b23a; }
.wa-more-chev { font-size: 10px; }
/* ── Liste d'événements DÉTAILLÉE par jour (façon DTP : heure · devise · intitulé · prév./préc. · impact) ── */
.wa-events { display: flex; flex-direction: column; max-height: 158px; overflow: hidden; }   /* ~4 lignes repliées → "Read More" déploie */
.wa-card--open .wa-events { max-height: none; }
.wa-ev { display: grid; grid-template-columns: 44px 36px minmax(0,1fr) auto 12px; align-items: center; gap: 10px; padding: 5px 0; border-top: var(--row-sep); font-size: 12px; }
.wa-ev:first-child { border-top: none; }
.wa-ev-time { color: #8a8a90; font-size: 11px; font-variant-numeric: tabular-nums; }
.wa-ev-ccy  { color: #e5e7eb; font-size: 11px; font-weight: var(--fw-bold); letter-spacing: 0.02em; }
.wa-ev-name { color: #cbd5e1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.wa-ev-data { color: #9aa0a6; font-size: 11px; font-variant-numeric: tabular-nums; white-space: nowrap; text-align: right; }
.wa-ev-k    { color: #6b7280; }
.wa-ev-imp  { width: 7px; height: 7px; border-radius: 50%; justify-self: center; }
.wa-ev-imp--high { background: #ff3d00; box-shadow: 0 0 5px rgba(255,61,0,.55); }
.wa-ev-imp--med  { background: #ffb300; }
.wa-card--open .wa-ev-name { white-space: normal; }   /* déployé → on lit l'intitulé complet */

/* ── Week Ahead : layout 3 panneaux (épuré) : Week Ahead | News + Calendar ── */
/* La vue empile désormais sa barre d'en-tête standard puis le layout 3 panneaux → colonne. */
#view-weekahead { flex-direction: column; }

/* ══ ALIGNEMENT AU PIXEL DES TITRES DE VUES (demande user 27/07 « tout au même emplacement, parfaitement ») ══
   Les vues ACTUS/BIAIS/TAUX/BANQUES enveloppent leur contenu dans `.panel`, qui porte un contour 1px : leur
   barre d'en-tête (et donc leur titre) était décalée de 1px en x ET en y par rapport aux vues sans wrapper.
   On donne ce MÊME contour aux conteneurs des autres vues → structure identique, décalage identique, titres
   parfaitement alignés, et contour visuel homogène d'une vue à l'autre. */
.cal-panel, .fxl-wrap, .br-wrap, .arlib-wrap, #view-weekahead {
  border: 1px solid rgba(255, 255, 255, 0.07);
}
.wa3 { flex: 1; min-width: 0; min-height: 0; width: 100%; display: grid; grid-template-columns: var(--wa-left, 47%) 6px minmax(0,1fr); overflow: hidden; }
/* Frise gauche : design "frise" (grands cercles + ligne dégradée), défilement interne si la semaine dépasse l'écran */
.wa3 > .wa-scroll { min-height: 0; min-width: 0; overflow-y: auto; overflow-x: hidden; padding: 12px 14px; }
.wa3 .wa-chartbox { margin: 8px 0 12px; padding: 6px 9px 2px; }
.wa3 .wa-chart { height: 84px; }   /* 44px → 84px : place pour le relief + les valeurs au-dessus des points (profil de risque « parlant », 26/07) */
.wa3 .wa-chart-label { margin-bottom: 1px; }
.wa3 .wa-timeline { gap: 14px; }
.wa3 .wa-card-desc { -webkit-line-clamp: 2; }
.wa3 .wa-card--open .wa-card-desc { -webkit-line-clamp: unset; overflow: visible; }   /* FIX Show Less : déploiement complet (priorité sur le clamp 2) */
/* Splitters glisser-redimensionner (volatils : reset au reload) */
/* Resizers identiques à l'onglet News (.layout-resizer) : trait fin neutre au repos, orange au survol/drag */
.wa3-vsplit { background: transparent; cursor: col-resize; position: relative; z-index: 30; }
.wa3-vsplit::before { content: ''; position: absolute; top: 0; bottom: 0; left: 50%; transform: translateX(-50%); width: 2px; background: rgba(255,255,255,0.05); transition: background .12s; }
.wa3-vsplit:hover::before, .wa3-vsplit.dragging::before { background: rgba(227,178,58,0.72); }
.wa3-hsplit { background: transparent; cursor: row-resize; position: relative; z-index: 30; }
.wa3-hsplit::before { content: ''; position: absolute; left: 0; right: 0; top: 50%; transform: translateY(-50%); height: 2px; background: rgba(255,255,255,0.05); transition: background .12s; }
.wa3-hsplit:hover::before, .wa3-hsplit.dragging::before { background: rgba(227,178,58,0.72); }
.wa3.wa-dragging *  { pointer-events: none; user-select: none; }
.wa3.wa-dragging .wa3-vsplit, .wa3.wa-dragging .wa3-hsplit { pointer-events: auto; }
.wa3-right { display: grid; grid-template-rows: var(--wa-top, 1fr) 6px minmax(0,1fr); min-width: 0; min-height: 0; overflow: hidden; }
.wa3-panel { background: var(--bg); display: flex; flex-direction: column; min-height: 0; }
.wa3-phead { display: flex; align-items: center; gap: 8px; height: 32px; padding: 0 10px; border-bottom: 1px solid var(--border); background: var(--head-bg); flex: 0 0 auto; }   /* aligné sur .panel-header (cohérence inter-onglets) — meme fond --head-bg */
.wa3-ptitle { font-family: var(--font-mono); font-size: 12px; font-weight: var(--fw-bold); color: #e9eaed; letter-spacing: 0.04em; }   /* = .fxl-title (Overview List) — identité homogène */
.wa3-pmeta { font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 10px; color: #e3b23a; letter-spacing: .04em; }
.wa3-live { margin-left: auto; font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 10px; letter-spacing: .1em; color: #00e676; display: inline-flex; align-items: center; gap: 5px; }
.wa3-live::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: #00e676; box-shadow: 0 0 5px rgba(0,230,118,.5); }
.wa3-pbody { overflow-y: auto; min-height: 0; flex: 1 1 auto; }
/* Calendrier "doublé" : on garde TOUTES les colonnes lisibles (scroll horizontal si le panneau est étroit) */
#wa-cal-body { overflow-x: auto; }
#wa-cal-body .cal-table { min-width: 760px; }
.wa3-fbar { display: flex; align-items: center; gap: 6px; padding: 7px 14px; border-bottom: 1px solid var(--border); flex: 0 0 auto; background: var(--bg); }
.wa3-fbtn { font-size: 11px; font-weight: var(--fw-semibold); color: #a6a6ad; background: #121216; border: 1px solid var(--border); border-radius: 4px; padding: 3px 10px; cursor: pointer; font-family: inherit; }
.wa3-fbtn.on { color: #1a1206; background: #e3b23a; border-color: #e3b23a; }
.wa3-empty { color: #6f6f78; font-size: 12px; padding: 22px 14px; text-align: center; }
/* Week Ahead — RESPONSIVE : sous 1024px on EMPILE en FLEX colonne (frise → ticker → calendrier).
   On passe en flex (au lieu de grid) ET on neutralise tout reliquat de grille/style inline laissé
   par les splitters desktop (grid-template-* en !important) → empilement vertical garanti, JAMAIS
   de superposition des panneaux. Le panneau scrolle globalement ; chaque sous-panneau garde un
   scroll interne borné (ticker/calendrier) pour ne pas faire une page interminable. */
@media (max-width: 1024px) {
  #view-weekahead { height: 100%; overflow-y: auto; -webkit-overflow-scrolling: touch; }
  .wa3 {
    display: flex !important; flex-direction: column; height: auto; min-height: 0;
    grid-template-columns: none !important; grid-template-rows: none !important;
    overflow: visible;
  }
  .wa3-vsplit, .wa3-hsplit { display: none !important; }
  .wa3 > .wa-scroll { flex: 0 0 auto; height: auto; max-height: none; overflow: visible; }
  .wa3-right {
    display: flex !important; flex-direction: column; flex: 0 0 auto;
    grid-template-rows: none !important; grid-template-columns: none !important; grid-auto-rows: auto !important;
    min-height: 0; overflow: visible;
  }
  .wa3-panel { flex: 0 0 auto; background: var(--bg); border-top: 1px solid var(--border); }
  .wa3-panel .wa3-pbody { max-height: 65vh; overflow-y: auto; -webkit-overflow-scrolling: touch; }
}
@media (max-width: 560px) {
  /* ══ RESPONSIVE MOBILE « Semaine à venir » (demande user 27/07 « améliore le responsive mobile, les
     flèches ne sont pas alignées, c'est pas clean ») ══
     Mesuré à 375px AVANT : le titre de carte tombait à 75px de large sur 4 LIGNES, écrasé par le badge
     d'impact (109px) posé À CÔTÉ de lui, pendant que le cercle du jour + son écart mangeaient 111px. */
  .wa3 .wa-node { flex: 0 0 46px; width: 46px; height: 46px; border-width: 1px; }
  .wa3 .wa-date { font-size: 15px; margin: 0; }
  .wa3 .wa-dow, .wa3 .wa-month { font-size: 8px; letter-spacing: .04em; }
  .wa3 .wa-timeline::before { left: 23px; }
  .wa3 .wa-day { gap: 10px; margin-bottom: 12px; }
  .wa3 > .wa-scroll { padding: 10px; }
  .wa3 .wa-card { padding: 10px 11px; }
  /* Le badge d'impact passe SOUS le titre → le titre récupère toute la largeur de la carte. */
  .wa3 .wa-card-head { flex-direction: column; align-items: flex-start; gap: 6px; }
  .wa3 .wa-card-headl { width: 100%; }
  .wa3 .wa-card-title { font-size: 12.5px; }
  .wa3 .wa-impact { align-self: flex-start; }
  /* Navigation de semaine : la flèche droite frôlait le bord → on rapproche le bloc et on compacte la
     plage de dates (le libellé « 27-31 juillet » n'a pas besoin de 96px ici). */
  .wa-weeknav { gap: 2px; }
  .wa-weeknav .wa-week { min-width: 0; font-size: 11px; }
  #view-weekahead .panel-header { padding-right: 6px; }
}
/* News (panneau droite haut) */
.wan-day { font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 10px; font-weight: var(--fw-bold); letter-spacing: .06em; color: #6f6f78; padding: 8px 14px 4px; text-transform: uppercase; }
.wan { display: grid; grid-template-columns: 44px 1fr; gap: 10px; padding: 8px 14px; border-top: 1px solid var(--border); }
.wan-time { font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 11px; color: #6f6f78; white-space: nowrap; }
.wan-time .wan-dot { display: inline-block; width: 6px; height: 6px; border-radius: 50%; margin-right: 5px; vertical-align: middle; background: #6f6f78; }
.wan--high .wan-dot { background: #ff3d00; box-shadow: 0 0 5px rgba(255,61,0,.5); }
.wan-cat { font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 9px; letter-spacing: .05em; text-transform: uppercase; color: #e3b23a; display: block; margin-bottom: 3px; }
.wan-head { font-size: 12px; line-height: 1.45; color: #f0f0f2; }
.wan-tags { margin-top: 5px; display: flex; gap: 5px; flex-wrap: wrap; }
.wan-tag { font-size: 9px; font-weight: var(--fw-semibold); color: #a6a6ad; background: #17171c; border: 1px solid var(--border); border-radius: 3px; padding: 1px 6px; }
/* Calendar (panneau droite bas) */
.wac-day { font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 10px; font-weight: var(--fw-bold); letter-spacing: .06em; color: #6f6f78; padding: 8px 14px 4px; text-transform: uppercase; background: #121216; }
.wac-th, .wac-row { display: grid; grid-template-columns: 46px 28px 36px 30px minmax(0,1fr) 58px 58px 58px; gap: 8px; align-items: center; }
.wac-th { padding: 6px 14px; border-bottom: 1px solid var(--border); font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 9px; letter-spacing: .05em; text-transform: uppercase; color: #6f6f78; position: sticky; top: 0; background: var(--bg); z-index: 1; }
.wac-th span:nth-child(n+6) { text-align: right; }
.wac-row { padding: 6px 14px; border-top: 1px solid var(--border); font-size: 12px; }
.wac-row:hover { background: #121216; }
.wac-time { font-family: ui-monospace, Menlo, Consolas, monospace; color: #6f6f78; font-size: 11px; }
.wac-flag img { width: 18px; height: 13px; border-radius: 2px; object-fit: cover; display: block; }
.wac-ccy { font-family: ui-monospace, Menlo, Consolas, monospace; font-weight: var(--fw-bold); font-size: 11px; color: #a6a6ad; }
.wac-imp { display: inline-flex; gap: 2px; }
.wac-imp i { width: 5px; height: 5px; border-radius: 50%; background: var(--border); }
.wac-imp.high i:nth-child(-n+3) { background: #ff3d00; }
.wac-imp.medium i:nth-child(-n+2) { background: #ffb300; }
.wac-imp.low i:nth-child(-n+1) { background: #6f6f78; }
.wac-ev { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: #dfe3ea; }
.wac-num { font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 11px; text-align: right; color: #a6a6ad; }
.wac-num.act { color: #f0f0f2; font-weight: var(--fw-bold); }
@media (max-width: 980px) { .wa3 { grid-template-columns: 1fr; overflow-y: auto; } }   /* (grid-template-rows 440px retiré : il écrasait le grid-auto-rows 380px du bloc ≤560px) */
.dtp-ins  { color: #e3b23a; font-weight: var(--fw-bold); margin-left: 4px; }
.ai-insights-toggle {
  background: none; border: none; color: var(--text3); font-size: 11px; cursor: pointer;
  margin-left: 8px; transition: color 0.15s; font-family: var(--font-ui);
}
.ai-insights-toggle:hover { color: var(--text); }
.ai-insights-toggle .eye { font-size: 12px; }

/* ── Document header (titre + date + source) ── */
.arlib-doc-header {
  margin-bottom: 24px;
  padding-bottom: 20px;
  border-bottom: 1px solid #1e1e1e;
}
.arlib-doc-type {
  font-size: 10px;
  font-weight: var(--fw-semibold);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #e3b23a;
  font-family: var(--font-ui);
  margin-bottom: 8px;
}
/* Titre standardisé "Préfixe: Sujet" — style DataTradingPro :
   text-[#e3b23a] text-sm md:text-base font-semibold leading-snug tracking-wide */
.arlib-doc-title {
  font-size: 14px;            /* text-sm */
  font-weight: var(--fw-semibold);           /* font-semibold */
  color: #e3b23a;             /* orange institutionnel */
  line-height: 1.375;         /* leading-snug */
  letter-spacing: 0.025em;    /* tracking-wide */
  font-family: var(--font-ui);
  margin-bottom: 10px;
}
@media (min-width: 768px) { .arlib-doc-title { font-size: 16px; } }   /* md:text-base */
/* Sous-titre (lead) ORANGE — structure DTP : type → titre → sous-titre → date */
.arlib-doc-subtitle {
  font-size: 12px;
  color: #e3b23a;
  font-weight: var(--fw-medium);
  line-height: 1.5;
  letter-spacing: 0.01em;
  margin: -2px 0 10px;
  font-family: var(--font-ui);
}
.arlib-doc-meta {
  font-size: 11px;
  color: #e8eaed;   /* date lisible (blanc cassé) — plus de gris sombre illisible */
  font-family: var(--font-mono);
}
.arlib-doc-desc {
  margin-top: 12px;
  font-size: 13px;
  color: #aaa;
  line-height: 1.6;
  font-style: italic;
}

/* ── Sources section ── */
.arlib-rbullet--source {
  display: flex;
  gap: 8px;
  padding: 6px 0;
  align-items: flex-start;
  margin-bottom: 2px;
}
.arlib-source-num {
  flex-shrink: 0;
  width: 18px;
  font-size: 10px;
  color: #555;
  font-family: var(--font-mono);
  padding-top: 2px;
  text-align: right;
}

/* ── Badge ING (orange ING) ── */
.arlib-badge-ing {
  background: var(--orange-dim) !important;
  color: #fff !important;
}

/* Content elements (legacy meta, kept for briefings) */
.arlib-rmeta {
  font-size: 11px;
  color: #555;
  font-family: var(--font-mono);
  margin-bottom: 20px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--bg2);
}
/* Titre de rubrique d'un rapport de séance : la RÈGLE est plus bas, PARTAGÉE MOT POUR MOT avec
   `.fxdr-section` du Récap Quotidien (26/08, demande utilisateur : « idem pour les titres des
   parties, genre pareil » / « pour que les rapports se ressemblent »). Deux blocs séparés auraient
   dérivé au premier ajustement — ils dérivaient déjà : le Quotidien portait un liseré or devant son
   titre, pas celui-ci. Un seul jeu de déclarations, deux sélecteurs. */
.arlib-rbullet {
  display: flex;
  gap: 10px;
  font-size: 13px;
  color: #e8e8e8;                 /* corps du rapport en blanc */
  line-height: 1.7;
  font-family: var(--font-ui);
  margin-bottom: 8px;
}
.arlib-rbullet strong { color: #ffffff; font-weight: var(--fw-bold); }
/* Liens dans le corps : blanc (pas d'orange), discrètement soulignés */
.arlib-rbullet a { color: #e8e8e8 !important; text-decoration: none; }
.arlib-rbullet a:hover { text-decoration: underline; text-decoration-color: rgba(227,178,58,0.6); }
.arlib-rbullet-dot {
  flex-shrink: 0;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #475569;
  margin-top: 8px;
}
/* Mini-badge actif (▲ SPX vert / ▼ Gold rouge) en début de puce */
.rx-asset {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 11px;
  font-weight: var(--fw-bold);
  font-family: var(--font-mono);
  padding: 1px 6px;
  border-radius: 3px;
  margin-right: 6px;
  white-space: nowrap;
}
.rx-asset--up { color: #22c55e; background: rgba(34,197,94,0.10); border: 1px solid rgba(34,197,94,0.28); }
.rx-asset--dn { color: #ef4444; background: rgba(239,68,68,0.10); border: 1px solid rgba(239,68,68,0.28); }
.arlib-rbullet-sub {
  display: flex;
  gap: 10px;
  font-size: 12px;
  color: #cbd5e1;
  line-height: 1.65;
  font-family: var(--font-ui);
  margin-bottom: 6px;
  margin-left: 16px;
}
.arlib-rbullet-sub .arlib-rbullet-dot {
  background: #2e2e2e;
  margin-top: 7px;
}
/* Sous-titre de rubrique dans un rapport (famille macro : Inflation, Emploi…). Un cran SOUS
   `.arlib-rsection` (titre or, capitales) : même graisse capitale mais plus petit et gris, comme
   `.fxdr-grp-title` du Récap Quotidien — les deux rapports se lisent à la suite, ils rangent pareil
   et doivent en avoir l'air. */
.arlib-rsubsection {
  font-size: 10px;
  font-weight: var(--fw-bold);
  letter-spacing: .06em;
  text-transform: uppercase;
  color: #7d7d86;
  margin: 14px 0 6px;
}
.arlib-rsubsection:first-child { margin-top: 6px; }

/* ── VERDICT D'UNE DONNÉE PUBLIÉE (26/08, demande utilisateur) ──────────────────────────────────
   Charte DTP, tokens sémantiques immuables : au-dessus du chiffre de référence = vert émeraude,
   en dessous = rouge d'alerte, conforme = jaune-orange doré. Mêmes trois couleurs qu'ailleurs sur
   le desk (badges ACHAT / VENTE / NEUTRE, matrice de biais) : un trader n'a pas deux grammaires de
   couleur à apprendre. Une hausse de taux est verte, une baisse rouge, un maintien neutre.
   Le gras vient de la mise en forme normale des chiffres : la couleur s'y ajoute, elle ne la
   remplace pas — une donnée reste lisible même pour qui distingue mal le vert du rouge. */
.dtp-val-pos { color: #00e676; }
.dtp-val-neg { color: #ff3d00; }
.dtp-val-neu { color: #ffb300; }
/* Mode clair : les mêmes teintes, assombries pour rester lisibles sur fond blanc (le vert vif et
   l'ambre y passent sous le seuil de contraste). */
html[data-theme="light"] .dtp-val-pos, body.theme-light .dtp-val-pos { color: #047857; }
html[data-theme="light"] .dtp-val-neg, body.theme-light .dtp-val-neg { color: #c2410c; }
html[data-theme="light"] .dtp-val-neu, body.theme-light .dtp-val-neu { color: #a16207; }
.arlib-rdivider {
  border: none;
  border-top: 1px solid #161616;
  margin: 20px 0;
}
.arlib-rno-content {
  font-size: 12px;
  color: #2a2a2a;
  font-family: var(--font-mono);
  padding: 32px 0;
  text-align: center;
}

/* ── Session Wrap reader ── */
.arlib-sw-loading { padding: 20px; color: var(--text2); }
.arlib-sw-badge { display: inline-block; padding: 3px 10px; border-radius: 4px; background: rgba(0,180,160,0.15); color: #00b4a0; font-size: 11px; font-weight: var(--fw-semibold); letter-spacing: 0.04em; }
.arlib-sw-author { font-size: 11px; color: var(--text3); margin-left: 8px; }
.arlib-sw-header { display: flex; align-items: center; gap: 8px; margin-bottom: 16px; padding-bottom: 12px; border-bottom: 1px solid var(--border2); }
.arlib-sw-body { font-size: 13px; line-height: 1.7; color: var(--text); }
.arlib-sw-body p { margin-bottom: 10px; }
.arlib-sw-body h2, .arlib-sw-body h3 { font-size: 14px; font-weight: var(--fw-semibold); color: var(--text); margin: 16px 0 8px; }
.arlib-sw-body ul { padding-left: 18px; margin-bottom: 10px; }
.arlib-sw-body li { margin-bottom: 4px; }
.arlib-sw-body a { color: var(--orange); text-decoration: none; }
.arlib-sw-footer { margin-top: 20px; padding-top: 12px; border-top: 1px solid var(--border2); }
.arlib-sw-link { color: var(--orange); font-size: 13px; text-decoration: none; }
.arlib-sw-link:hover { text-decoration: underline; }
.arlib-sw-spinner { margin-top: 8px; font-size: 12px; color: var(--text3); }

/* ═══════════ FX DAILY RECAP — rapport analyste du jour (structure la référence) ═══════════ */
.fxdr { display: flex; flex-direction: column; }
/* TITRE DE RUBRIQUE — LA MÊME RÈGLE POUR LES DEUX RAPPORTS (26/08). `.arlib-rsection` est le titre
   de rubrique du lecteur de rapports (récaps de séance), `.fxdr-section` celui du Récap Quotidien.
   Ils avaient chacun leur bloc et avaient déjà divergé : le liseré or vertical n'existait que d'un
   côté, et les marges différaient de quelques pixels. Un seul jeu de déclarations, deux sélecteurs :
   ils ne peuvent plus dériver. */
/* ⚠️ ALIGNÉS SUR LE RÉCAP HEBDO, ET SANS TRAIT À GAUCHE (04/09, demande user : « pour les autres
   récaps, sessions et quotidien, les titres doivent ressembler à celui-ci, sans avoir de trait à
   gauche du titre »). La référence est donc `.wr-section-title`, le titre de rubrique du Hebdo :
   même corps, même graisse, même interlettrage, même filet bas. Le liseré vertical de 3 px n'existait
   que sur ces deux rapports-ci — il faisait de la même information deux objets différents selon le
   rapport ouvert, alors que c'est le MÊME desk qui parle.
   Les valeurs sont recopiées plutôt que factorisées avec `.wr-section-title` : celui-ci porte déjà
   trois surcharges ailleurs (en-tête Currency Strength, mobile) qu'un sélecteur commun aurait
   étendues à ces deux rapports sans qu'on l'ait voulu. Le banc mesure les styles CALCULÉS des trois
   et exige qu'ils coïncident : c'est lui qui les empêche de dériver, pas la factorisation. */
.fxdr-section,
.arlib-rsection {
  display: flex; align-items: center; gap: 8px;
  font-family: var(--font-ui);
  font-size: 11px; font-weight: var(--fw-semibold); color: #e3b23a;
  letter-spacing: .09em; text-transform: uppercase;
  margin: 26px 0 12px; padding-bottom: 6px; border-bottom: 1px solid var(--border);
}
/* Le PREMIER titre d'un rapport ne pousse pas 26 px de vide au-dessus de lui. Le Hebdo rejoint la
   règle (04/09) : les trois rapports doivent se comporter pareil dans ce cas aussi, sinon
   l'alignement qu'on vient de faire ne tient que pour les titres du milieu. */
.fxdr-section:first-child,
.arlib-rsection:first-child,
.wr-section-title:first-child { margin-top: 4px; }
/* ENCADRÉ DE SYNTHÈSE — même règle, mêmes deux rapports. Le Quotidien ouvre sur un encadré à liseré
   or ; le récap de séance servait la même synthèse en puces nues. */
.fxdr-exec,
.arlib-rexec {
  border-left: 2px solid rgba(227,178,58,.55); background: rgba(227,178,58,.06);
  border-radius: 0 8px 8px 0; padding: 13px 16px;
}
.fxdr-exec .wr-p,
.arlib-rexec .wr-p { font-size: 13px; color: #e3e3e6; line-height: 1.7; margin: 0 0 9px; font-family: var(--font-ui); }
.fxdr-exec .wr-p:last-child,
.arlib-rexec .wr-p:last-child { margin: 0; }
/* v14 : intro d'ouverture du FX Daily (résumé des récaps de séance) — lead sobre sans encadré (l'encadré or reste à la Synthèse) */
.fxdr-intro { border-left: 0; background: transparent; border-radius: 0; padding: 2px 0 0; margin: 0 0 6px; }
.fxdr-intro .wr-p { font-size: 13.5px; color: #f0f0f2; }
.fxdr-bullets { margin: 0 0 4px; }
/* « À surveiller » : les puces expliquent, le tableau chiffre — un vrai blanc les sépare, sinon le
   calendrier semble collé à la dernière puce et on ne sait plus où finit le texte (retour user 11/08). */
.fxdr-bullets + .fxdr-callike { margin-top: 20px; padding-top: 16px; border-top: 1px solid var(--hud-line, #1a1a1e); }
/* ── ET DANS L'AUTRE SENS, POUR LE RÉCAP DE SÉANCE (30/08 : « c'est collé au calendrier ») ───────
   Le Récap Quotidien met ses fils ouverts AVANT le tableau, d'où la règle ci-dessus. Le récap de
   séance les met APRÈS — une échéance datée passe avant une attente vague — et rien ne les séparait :
   la première puce démarrait sur la dernière ligne du calendrier, sans un pixel entre les deux.
   Même respiration, même filet, dans les deux sens. La seconde règle est un filet : depuis le 30/08
   les puces portent toujours leur intitulé « Autres », donc aucune ne suit le tableau directement —
   mais un rapport plus ancien, ou une rubrique sans intitulé, ne doit pas revenir se coller. */
.fxdr-callike + .arlib-rsubsection { margin-top: 20px; padding-top: 16px; border-top: 1px solid var(--hud-line, #1a1a1e); }
.fxdr-callike + .arlib-rbullet    { margin-top: 16px; }
/* Ligne « À surveiller » cliquable → Décryptage DTP (même geste que l'onglet Calendrier). */
.fxdr-cal-clic { cursor: pointer; }
.fxdr-cal-clic:hover { background: rgba(227,178,58,.05); }
.fxdr-cal-chev { color: #6b7280; margin-left: 8px; font-size: 12px; transition: transform .15s ease; display: inline-block; }
.fxdr-cal-clic.open .fxdr-cal-chev { transform: rotate(90deg); color: #e3b23a; }
.fxdr-cal-detail > td { padding: 0 0 12px; background: var(--bg2); }
.fxdr-cal-detail .cal-kb { margin: 0; }
.fxdr-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(360px, 1fr)); gap: 12px; }
.fxdr-card {
  background: var(--bg2); border: 1px solid #1f1f24; border-left: 3px solid rgba(227,178,58,.6);
  border-radius: 4px; padding: 14px 16px;
}
.fxdr-card-title { font-size: 13px; font-weight: var(--fw-semibold); color: #f3f3f5; margin-bottom: 6px; line-height: 1.4; }
.fxdr-card-text { font-size: 12px; color: #b6b6bd; line-height: 1.65; }
.fxdr-card-text + .fxdr-grp-title { margin-top: 14px; }
/* Regional Analysis — cartes pays + sous-sections groupées */
.fxdr-region-head { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.fxdr-region-name { font-size: 14px; font-weight: var(--fw-bold); color: #f3f3f5; }
.fxdr-ccy {
  font-family: 'JetBrains Mono', monospace; font-size: 10px; color: #a2a2aa;
  background: #1a1a1f; border: 1px solid var(--border); border-radius: 4px; padding: 1.5px 6px;
}
.fxdr-grp-title {
  font-size: 10px; font-weight: var(--fw-bold); text-transform: uppercase; letter-spacing: .06em;
  color: #7d7d86; margin: 13px 0 7px;
}
.fxdr-sub { border-left: 2px solid rgba(227,178,58,.6); padding: 1px 0 1px 11px; margin-bottom: 9px; }
.fxdr-sub-h { font-size: 12px; font-weight: var(--fw-semibold); color: #dcdce0; margin-bottom: 2px; }
.fxdr-sub-t { font-size: 12px; color: #a6a6ad; line-height: 1.6; }
/* Central Bank Focus / Analyst Comments / Corporate News — variantes de carte */
.fxdr-cb { background: rgba(255,179,0,.06); border-left-color: var(--neutral); }
.fxdr-comment { border-left-color: #3a6df0; }
.fxdr-corp-head { display: flex; align-items: center; gap: 8px; margin-bottom: 6px; }
.fxdr-corp-head .fxdr-card-title { margin-bottom: 0; }
.fxdr-ticker {
  font-family: 'JetBrains Mono', monospace; font-size: 10px; font-weight: var(--fw-semibold); color: #e3b23a;
  background: rgba(227,178,58,.12); border: 1px solid rgba(227,178,58,.3); border-radius: 4px; padding: 1.5px 6px;
}
/* Tables (Key Economic Data + Looking Ahead) */
.fxdr-tablewrap { overflow-x: auto; border: 1px solid #1f1f24; border-radius: 4px; }
.fxdr-table { width: 100%; border-collapse: collapse; font-size: 12px; }
.fxdr-table thead th {
  position: sticky; top: 0; background: var(--bg); color: #8a8a90;
  font-size: 10px; font-weight: var(--fw-bold); text-transform: uppercase; letter-spacing: .05em;
  text-align: left; padding: 8px 11px; border-bottom: 1px solid #1f1f24; white-space: nowrap;
}
.fxdr-table th.num, .fxdr-table td.num { text-align: right; }
.fxdr-table td { padding: 7px 11px; color: #dcdce0; border-bottom: 1px solid var(--bg2); vertical-align: top; }
.fxdr-table tbody tr:hover { background: var(--row-hover); }
.fxdr-table td.fxdr-rel { font-weight: var(--fw-semibold); color: #f3f3f5; }
.fxdr-table td.fxdr-per, .fxdr-table td.dim { color: #85858c; }
/* « À surveiller » façon CALENDRIER : réutilise cal-table, cal-day-sep, classes cth et points d'impact
   du vrai calendrier. (Piège vécu : « cth-* / » écrit avec l'étoile-slash fermait ce commentaire.) */
.fxdr-callike { border: 1px solid var(--bg2); border-radius: 6px; overflow: hidden; margin-top: 2px; }
.fxdr-callike .fxdr-tablewrap { border: none; border-radius: 0; }   /* le cadre est porté par .fxdr-callike (sinon double bordure) ; le wrap ne garde que le défilement horizontal des 10 colonnes */
.fxdr-callike .cal-table { width: 100%; border-collapse: collapse; }
.fxdr-callike .cal-row td { padding: 8px 11px; border-bottom: 1px solid #131316; font-size: 12.5px; color: #dcdce0; }
.fxdr-callike tbody tr:last-child td { border-bottom: none; }
.fxdr-cal-cat { color: #85858c; font-size: 11px; }
/* Devise de chaque donnée éco (Récap Quotidien / FX) : code mono or, colonne étroite */
.fxdr-table td.fxdr-ccy { font-family: var(--font-mono, ui-monospace, monospace); font-weight: var(--fw-semibold); color: #e3b23a; white-space: nowrap; width: 1%; letter-spacing: .02em; }
/* Devise en tête de puce éco (déplié dans le fil news) : petit badge or */
.dtpd-eco-ccy { display: inline-block; font-family: var(--font-mono, ui-monospace, monospace); font-size: 10.5px; font-weight: 700; color: #e3b23a; background: rgba(227,178,58,.12); border: 1px solid rgba(227,178,58,.28); border-radius: 3px; padding: 0 4px; margin-right: 4px; letter-spacing: .02em; vertical-align: middle; }
/* « Point Marché · Ouverture US » (DTP Daily) — listes à puces + paragraphes (réutilise .fxdr-section / .fxdr-exec / .fxdr-table) */
.dtpd-bullets { margin: 4px 0 18px; padding-left: 18px; list-style: disc; }
.dtpd-bullets li { font-size: 12px; color: #b6b6bd; line-height: 1.6; margin-bottom: 8px; }
.dtpd-bullets li::marker { color: rgba(227,178,58,.7); }
.dtpd-bullets li strong { color: #f3f3f5; font-weight: var(--fw-semibold); }
.dtpd-paras { margin: 4px 0 18px; }
.dtpd-paras p { font-size: 13px; color: #cfcfd5; line-height: 1.7; margin: 0 0 10px; }
.dtpd-paras p:last-child { margin: 0; }
.dtpd-paras p strong { color: #f3f3f5; font-weight: var(--fw-semibold); }

/* (Section « Commentaires marquants » retirée le 25/08 : ses règles partaient avec elle.) */
.dtpd-lead { font-size: 14px; font-weight: var(--fw-semibold); color: #e8e8ec; line-height: 1.5; margin: 2px 0 18px; padding-left: 11px; border-left: 2px solid rgba(227,178,58,.55); }
.fxdr-table td.fxdr-cat { font-weight: var(--fw-semibold); color: #cfcfd4; white-space: nowrap; }
.fxdr-table .bias-badge { display: inline-block; padding: 1px 8px; border-radius: 4px; font-size: 10px; font-weight: var(--fw-bold); }
@media (max-width: 720px) { .fxdr-grid { grid-template-columns: 1fr; } }

/* ── Full post (news Info panel) ── */
.fpost-wrap { padding: 2px 0; }
.fpost-label {
  display: block;
  font-size: 9px;
  font-family: var(--font-mono);
  font-weight: var(--fw-bold);
  color: #444;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  margin-bottom: 9px;
}
.fpost-body {
  font-size: 11.5px;
  color: #aaa;
  line-height: 1.72;
  font-family: var(--font-ui);
}
.fpost-para {
  margin-bottom: 9px;
  padding-left: 10px;
  border-left: 2px solid var(--border);
}
.fpost-para:last-child { margin-bottom: 0; }

/* ═══════════════ RISK SENTIMENT POPUP ═══════════════ */
.risk-popup-overlay {
  position: fixed;
  inset: 0;
  z-index: 500;
  background: transparent;
}
.risk-popup-overlay.hidden { display: none; }

.risk-popup {
  position: absolute;
  top: calc(var(--topbar-h) + 4px);
  left: 50%;
  transform: translateX(-50%);
  width: 340px;
  max-width: calc(var(--vpw) - 16px);
  max-height: calc(var(--vph) - 80px);
  overflow-y: auto;
  background: var(--bg);
  border: 1px solid #232326;
  border-radius: 4px;
  box-shadow: 0 16px 48px rgba(0,0,0,0.8), 0 0 0 1px rgba(255,255,255,0.03);
  z-index: 501;
}

.risk-popup-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border-bottom: 1px solid #1a1a1a;
  background: var(--bg);
}
.rp-arrow { font-size: 15px; }
.risk-popup-header.risk-off .rp-arrow { color: #ef4444; }
.risk-popup-header.risk-on  .rp-arrow { color: #22c55e; }
.risk-popup-header.neutral  .rp-arrow { color: var(--neutral); }
.rp-label {
  flex: 1;
  font-family: var(--font-ui);
  font-weight: var(--fw-semibold);
  font-size: 15px;
  letter-spacing: 0;
  text-transform: none;
  color: #f2f3f5;
}
.rp-close {
  background: none; border: none; color: #444;
  font-size: 16px; cursor: pointer; line-height: 1; padding: 0 2px;
}
.rp-close:hover { color: #aaa; }

.risk-popup-body { padding: 0 14px 14px; }

/* ── Gauge ── */
.rp-gauge-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 16px 0 4px;
  border-bottom: 1px solid var(--bg2);
  margin-bottom: 12px;
  position: relative;
}
.rp-gauge-svg {
  width: 182px;               /* arc très légèrement réduit → laisse de la place au bouton */
  height: 109px;
}
.rp-gauge-lbl {
  margin-top: 8px;
  font-family: var(--font-mono);
  font-size: 14px;          /* bouton un peu plus grand → bien lisible sous la jauge */
  font-weight: var(--fw-bold);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 9px 22px;
  border-radius: 4px;
  border: 1.5px solid transparent;
  background: transparent;
}
.rp-gauge-lbl--risk-on  { color: #2ee06a; border-color: rgba(34,197,94,0.6);  background: rgba(34,197,94,0.14);  box-shadow: 0 0 14px rgba(34,197,94,0.18);  }
.rp-gauge-lbl--risk-off { color: #ff5a66; border-color: rgba(239,68,68,0.6);  background: rgba(239,68,68,0.14);  box-shadow: 0 0 14px rgba(239,68,68,0.18);  }
.rp-gauge-lbl--neutral  { color: #ffb02e; border-color: rgba(255,179,0,0.6); background: rgba(255,179,0,0.14); box-shadow: 0 0 14px rgba(255,179,0,0.16); }

/* Bande sentiment (● LABEL : phrase) — pleine largeur, colorée selon le risque */
.rp-band { display: flex; align-items: flex-start; gap: 8px; padding: 10px 16px; font-size: 12px; line-height: 1.45; }
.rp-band-dot { width: 6px; height: 6px; border-radius: 50%; margin-top: 6px; flex-shrink: 0; }
.rp-band-txt { flex: 1; min-width: 0; }
.rp-band strong { font-weight: var(--fw-bold); letter-spacing: 0.02em; }
/* couleurs calquées sur l'image : fond très sombre teinté, label vif, phrase plus mate */
.rp-band.risk-off { background: rgba(239,68,68,0.20); background: color-mix(in oklab, #ef4444 20%, transparent); border: 1px solid rgba(239,68,68,0.42); border-color: color-mix(in oklab, #ef4444 42%, transparent); color: #e8978d; }
.rp-band.risk-off strong   { color: #ef4444; }
.rp-band.risk-off .rp-band-dot { background: #ef4444; }
.rp-band.risk-on  { background: rgba(34,197,94,0.10); background: color-mix(in oklab, #22c55e 10%, transparent); border: 1px solid rgba(34,197,94,0.22); border-color: color-mix(in oklab, #22c55e 24%, transparent); color: #84c69d; }
.rp-band.risk-on strong    { color: #22c55e; }
.rp-band.risk-on .rp-band-dot { background: #22c55e; }
.rp-band.neutral  { background: rgba(255,179,0,0.10); background: color-mix(in oklab, var(--neutral) 10%, transparent); border: 1px solid rgba(255,179,0,0.24); border-color: color-mix(in oklab, var(--neutral) 28%, transparent); color: var(--neutral); }
.rp-band.neutral strong    { color: var(--neutral); }
.rp-band.neutral .rp-band-dot { background: var(--neutral); }

/* Gauge wrap accent border-top by sentiment */
.rp-gauge-wrap--risk-on::after  { content:''; position:absolute; top:0; left:0; right:0; height:2px; background:linear-gradient(90deg,transparent,#22c55e,transparent); }
.rp-gauge-wrap--risk-off::after { content:''; position:absolute; top:0; left:0; right:0; height:2px; background:linear-gradient(90deg,transparent,#ef4444,transparent); }
.rp-gauge-wrap--neutral::after  { content:''; position:absolute; top:0; left:0; right:0; height:2px; background:linear-gradient(90deg,transparent,var(--neutral),transparent); }

.rp-desc {
  font-size: 12px; color: #9aa3b2; line-height: 1.45; margin: 8px 0 4px;
}
.rp-divider {
  height: 1px; background: #2a2a2a; margin: 6px 0;
}
.rp-section-label {
  font-family: var(--font-mono); font-size: 8.5px; color: #8a93a0;
  letter-spacing: 0.1em; margin-bottom: 6px; text-transform: uppercase;
}
.rp-assets { display: flex; flex-direction: column; gap: 3px; }
.rp-asset-row {
  display: flex; align-items: center; gap: 8px;
  font-family: var(--font-mono); font-size: 11.5px;
}
.rp-asset-arrow { font-size: 12px; width: 14px; flex-shrink: 0; }
.rp-asset-name  { flex: 1; color: #c4ccd8; font-size: 11px; }
.rp-asset-chg   { font-weight: var(--fw-bold); font-size: var(--fs-title); }
.rp-asset-chg.pos { color: #34d399; }
.rp-asset-chg.neg { color: #f87171; }
.rp-updated { font-size: 9.5px; color: #6b7280; font-family: var(--font-mono); margin-top: 4px; }

/* Sentiment colors per label */
.risk-popup-header.risk-on    { border-left: 3px solid #22c55e; }
.risk-popup-header.risk-off   { border-left: 3px solid #ef4444; }
.risk-popup-header.neutral    { border-left: 3px solid var(--neutral); }
.rp-label.risk-on    { color: #22c55e; }
.rp-label.risk-off   { color: #ef4444; }
.rp-label.neutral    { color: var(--neutral); }

/* Topbar sentiment live colors */
/* Fond teinté pour rendre le bouton risk bien visible (comme DTP) */
/* Couleurs exactes DataTradingPro : bg 12% · bordure 35% · texte plein */
.topbar-sentiment.risk-on  { color: rgb(34,197,94);  border-color: rgba(34,197,94,0.35);  background: rgba(34,197,94,0.12); }
.topbar-sentiment.risk-off { color: rgb(239,68,68);  border-color: rgba(239,68,68,0.35);  background: rgba(239,68,68,0.12); }
.topbar-sentiment.neutral  { color: rgb(255,179,0); border-color: rgba(255,179,0,0.35); background: rgba(255,179,0,0.12); }

/* ═══════════════ RISK GAUGE (in RISK tab) ═══════════════ */
.risk-widget-container {
  flex: 1; min-height: 0; display: flex; flex-direction: column; overflow: hidden;
}
/* Bande sentiment (façon image) : ● LABEL: phrase — fond teinté, label vif, phrase mate */
.risk-ticker {
  display: flex; align-items: flex-start; gap: 7px;
  padding: 7px 13px; font-size: 11px; line-height: 1.4; flex-shrink: 0;
}
.risk-ticker-dot { width: 6px; height: 6px; border-radius: 50%; margin-top: 6px; flex-shrink: 0; }
.risk-ticker-txt { flex: 1; min-width: 0; }
.risk-ticker strong { font-weight: var(--fw-bold); letter-spacing: 0.02em; }
/* Fonds DataTradingPro : color-mix(in oklab, <couleur> 10%, transparent) — fallback rgba d'abord */
.risk-ticker.risk-off { background: #1f1416; border: 1px solid rgba(239,68,68,0.22); color: #d99a92; }
.risk-ticker.risk-off strong { color: #ef4444; }  .risk-ticker.risk-off .risk-ticker-dot { background: #ef4444; }
.risk-ticker.risk-on  { background: #131d17; border: 1px solid rgba(34,197,94,0.20); color: #84c69d; }
.risk-ticker.risk-on strong { color: #22c55e; }  .risk-ticker.risk-on .risk-ticker-dot { background: #22c55e; }
.risk-ticker.neutral  { background: var(--bg2); border: 1px solid rgba(255,179,0,0.20); color: var(--neutral); }
.risk-ticker.neutral strong { color: var(--neutral); }  .risk-ticker.neutral .risk-ticker-dot { background: var(--neutral); }

/* ── Risk Sentiment History (barres quotidiennes risk-on/off) ── */
#rtab-risk #risk-widget { flex: 1 1 auto; min-height: 280px; }   /* jauge AGRANDIE : grandit pour remplir → plus grande que la bande */
.rsh-header { margin-top: 4px; }

.rsh-status {
  display: flex; align-items: center; gap: 8px; padding: 7px 11px; margin: 5px 10px 4px;
  border: 1px solid var(--hud-line, var(--border)); border-radius: 4px; background: #101013;
  font-size: 11px; line-height: 1.35; flex-shrink: 0;
}
.rsh-status .rsh-dot { width: 9px; height: 9px; border-radius: 50%; flex: 0 0 auto; box-shadow: 0 0 0 3px rgba(255,255,255,0.03); }
.rsh-status .rsh-label { font-weight: var(--fw-bold); letter-spacing: 0.3px; white-space: nowrap; }
.rsh-status .rsh-desc { color: #9ca3af; font-size: 10px; flex: 1; min-width: 0; }
.rsh-status.risk-on  { background: #131d17; border-color: rgba(34,197,94,0.25); }
.rsh-status.risk-on  .rsh-dot { background: #22c55e; }  .rsh-status.risk-on  .rsh-label { color: #22c55e; }
.rsh-status.risk-off { background: #1f1416; border-color: rgba(239,68,68,0.25); }
.rsh-status.risk-off .rsh-dot { background: #ef4444; }  .rsh-status.risk-off .rsh-label { color: #ef4444; }
.rsh-status.neutral  { background: var(--bg2); border-color: rgba(255,179,0,0.25); }
.rsh-status.neutral  .rsh-dot { background: var(--neutral); }  .rsh-status.neutral  .rsh-label { color: var(--neutral); }
.rsh-chart { flex: 0 1 210px; min-height: 160px; width: 100%; border-top: 1px solid var(--hud-line, var(--border)); margin-top: 8px; }   /* bande RÉDUITE (hauteur modérée) → la jauge reste plus grande */

/* Jauge Risk — lecture (score + badge) CENTRÉE sous l'arc */
.risk-gauge-stage { position: relative; flex: 1; min-height: 0; width: 100%; }
#risk-gauge-div { position: absolute; inset: 0; }
.risk-readout {
  position: absolute; left: 50%; bottom: 5%;
  transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 15px;   /* score / badge bien espacés */
  text-align: center; pointer-events: none; z-index: 5;
}
.risk-readout-score {
  font-size: 34px; font-weight: var(--fw-bold); line-height: 1; letter-spacing: -0.01em;
  color: #f5f6f7; font-family: 'Inter', var(--font-ui), sans-serif;
}
.risk-readout-badge {
  font-size: 13px; font-weight: var(--fw-bold); letter-spacing: 2px;
  padding: 8px 20px; border-radius: 4px; border: 1px solid;
  background: rgba(18, 21, 28, 0.92); white-space: nowrap;
}
.risk-readout-badge.risk-on  { color: #22c55e; border-color: rgba(34,197,94,0.45);  background: rgba(14,30,20,0.95); background: color-mix(in oklab, #22c55e 14%, #0c0e13); }
.risk-readout-badge.risk-off { color: #ef4444; border-color: rgba(239,68,68,0.45);  background: rgba(40,16,16,0.95); background: color-mix(in oklab, #ef4444 16%, #0c0e13); }   /* même rouge que la bande/topbar */
.risk-readout-badge.neutral  { color: var(--neutral); border-color: rgba(255,179,0,0.45); background: rgba(38,24,12,0.95); background: color-mix(in oklab, var(--neutral) 14%, #0c0e13); }

/* ═══════════════ STRENGTH CHARTS — double panneau 50/50 ═══════════════ */
.strength-charts-row {
  flex: 1; min-height: 0; display: flex; flex-direction: row; overflow: hidden;
  background: var(--bg);
}
/* Chaque panneau (gauche TD / droite TW) = 50% */
.strength-pane {
  flex: 1 1 50%;
  min-width: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.strength-pane + .strength-pane { border-left: 1px solid var(--border); }
/* Sur écran étroit/laptop → empilement vertical : panel-right = 50% du viewport par défaut,
   donc côte à côte chaque courbe ne fait que ~287-345px de large sous 1380px (8 lignes devises
   amCharts illisibles, notamment 1366×768). Empilés, chacun prend toute la largeur du panneau. */
@media (max-width: 1380px) {
  .strength-charts-row { flex-direction: column; }
  .strength-pane + .strength-pane { border-left: none; border-top: 1px solid var(--border); }
}
.strength-chart-col {
  flex: 1; min-width: 0; display: flex; flex-direction: column;
  background: var(--bg); border: 1px solid var(--border); border-radius: 3px;
  overflow: hidden;
}
/* Bandeau du panneau Force des Devises : hauteur, fond, filet et marges viennent de .chart-header
   (le bandeau de la Carte des sessions, posé sur l element). Il n avait aucun filet bas et un fond
   different des autres panneaux — c est ce qui le faisait sortir du lot. */
.strength-tf-bar { display: flex; align-items: center; gap: 4px; flex-shrink: 0; }
.stf-btn {
  height: 28px; padding: 0 8px; font-size: 11px; font-weight: var(--fw-medium); letter-spacing: 0;
  font-family: var(--font-ui); background: none;
  border: 1px solid transparent; color: var(--text3);
  display: inline-flex; align-items: center; justify-content: center;
  cursor: pointer; border-radius: 4px; transition: color .15s, background-color .15s, border-color .15s;
}
.stf-btn:hover { color: var(--orange); background: var(--orange-bg); }   /* or DTP */
.stf-btn--active {   /* or DTP : fond + texte + bordure or (charte) */
  background: var(--orange-bg); border-color: rgba(227,178,58,0.30); color: var(--orange);
}
/* .strength-chart-label est un .chart-header-title : sa typographie vient de la. */
.strength-chart-label { margin-right: 4px; white-space: nowrap; }
.strength-updated-inner {
  font-size: 9px; color: var(--text4); font-family: var(--font-mono);
}

/* Legend row */
.strength-legend-bar {
  display: flex; flex-wrap: wrap; gap: 2px 14px; flex-shrink: 0;
  padding: 3px 10px 4px; border-bottom: 1px solid var(--border);
  background: var(--bg2);
}
.sli {
  display: inline-flex; align-items: center; gap: 5px;
  font-size: 10px; font-weight: var(--fw-medium); color: var(--text3);
  font-family: var(--font-mono); letter-spacing: 0.3px;
  white-space: nowrap;
}
.sli-line {
  display: inline-block; width: 16px; height: 2px; border-radius: 1px; flex-shrink: 0;
}

/* Toggle chips */
.sli--toggle {
  cursor: pointer; user-select: none;
  padding: 1px 6px 1px 4px; border-radius: 3px;
  border: 1px solid transparent;
  transition: opacity 0.15s, border-color 0.15s;
  color: var(--text3);
}
.sli--toggle:hover { color: var(--text); }
.sli--toggle.sli--on { color: var(--text); border-color: var(--border2); }
.sli--toggle:not(.sli--on) { opacity: 0.35; border-color: transparent; }
.sli-dot {
  display: inline-block; width: 7px; height: 7px;
  border-radius: 50%; flex-shrink: 0;
}

/* Separator between view toggle and TF buttons */
.stf-sep {
  display: inline-block; width: 1px; height: 12px;
  background: var(--border2); margin: 0 3px; flex-shrink: 0; align-self: center;
}

/* ─── Currency Strength — RANK view ─────────── */
.cs-rank-list {
  display: flex; flex-direction: column; gap: 6px;
  padding: 14px 16px; overflow-y: auto; height: 100%;
}
.cs-rank-item {
  display: grid;
  grid-template-columns: 16px 36px 1fr 50px;
  align-items: center; gap: 8px; height: 26px;
}
.cs-rank-num {
  font-size: 9px; color: var(--text4); font-family: var(--font-mono);
  text-align: right; flex-shrink: 0;
}
.cs-rank-ccy {
  font-size: 12px; font-weight: var(--fw-bold); font-family: var(--font-mono);
  letter-spacing: 0.5px; flex-shrink: 0;
}
.cs-rank-bar-wrap {
  height: 14px; background: var(--bg3); border-radius: 2px;
  overflow: hidden; position: relative;
}
.cs-rank-bar {
  height: 100%; border-radius: 2px;
  transition: width 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}
.cs-rank-val {
  font-size: 10px; font-family: var(--font-mono);
  font-weight: var(--fw-semibold); text-align: right; flex-shrink: 0;
}
.cs-rank-val--pos { color: var(--green); }
.cs-rank-val--neg { color: var(--red); }

/* ═══════════════ COT PANEL ═══════════════ */
.cot-header-bar {
  display: flex;
  align-items: center;
  gap: 3px;
  padding: 5px 10px 4px;
  background: var(--head-bg);
  flex-shrink: 0;
}
.cot-header-label {
  font-size: 11px;
  font-weight: var(--fw-semibold);
  color: var(--text);
  font-family: var(--font-mono);   /* même police que "Session Map" */
  letter-spacing: 0.04em;
}
.cot-tf-btn {
  padding: 1px 8px;
  font-size: 10px;
  font-weight: var(--fw-semibold);
  background: none;
  border: 1px solid var(--border2);
  color: var(--text3);
  border-radius: 2px;
  cursor: pointer;
  font-family: var(--font-mono);
  transition: color 0.12s, border-color 0.12s;
}
.cot-tf-btn:hover { color: var(--text); }
.cot-tf-btn--active { border-color: var(--orange); color: var(--orange); background: none; }

.cot-date-label {
  font-size: 9px;
  color: var(--text4);
  font-family: var(--font-mono);
}
.cot-type-bar {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 3px 8px 4px;
  border-bottom: 1px solid var(--border);
  background: var(--bg2);
  flex-shrink: 0;
}
.cot-type-btn {
  padding: 1px 7px;
  font-size: 9px;
  font-weight: var(--fw-semibold);
  letter-spacing: 0.3px;
  font-family: var(--font-mono);
  background: none;
  border: 1px solid transparent;
  color: var(--text3);
  cursor: pointer;
  border-radius: 2px;
  transition: color 0.12s, border-color 0.12s;
  white-space: nowrap;
}
.cot-type-btn:hover { color: var(--text); }
.cot-type-btn--active { border-color: var(--orange); color: var(--orange); }

.cot-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  /* Hauteur de rangée MINIMALE (208px) pour que chaque carte ait la place d'afficher
     en-tête + légende + donut + stats sans s'écraser. Si tout ne tient pas (ex. 2 colonnes
     × 4 rangées dans un panneau court), le panneau DÉFILE au lieu d'écraser/chevaucher. */
  grid-auto-rows: minmax(228px, 1fr);
  overflow-y: auto;
  gap: 1px;
  background: var(--bg);              /* même fond que les autres panneaux (au lieu du gris var(--border)) */
  flex: 1;
  min-height: 0;
  width: 100%;
  height: 100%;
  padding: 0;
}

/* (ancienne .cot-cell — donut centre, align-items:center, space-between — SUPPRIMEE 04/08 :
   ses align-items et justify-content survivaient a la nouvelle regle, qui ne les redeclare pas,
   et rabougrissaient la barre de repartition a la largeur de son contenu.) */

/* ── En-tête de carte (drapeau + ccy | type) ── */
.cot-card-head {
  display: flex; align-items: center; justify-content: space-between;
  width: 100%; gap: 6px;
}
.cot-head-left { display: flex; align-items: center; gap: 6px; }
.cot-head-left .meter-flag-img { height: 10px; width: 14px; }
.cot-head-ccy { font-size: 12px; font-weight: var(--fw-bold); color: #e2e8f0; font-family: var(--font-ui); }
.cot-head-type {
  font-size: 9px; color: var(--text); font-family: var(--font-ui);
  background: #15151a; border: 1px solid var(--border); border-radius: 3px;
  padding: 2px 6px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 60%;
}

/* ── Légende Court / Long ── */
.cot-legend { display: flex; gap: 14px; align-items: center; }
.cot-leg { display: flex; align-items: center; gap: 5px; font-size: 9px; color: #94a3b8; font-family: var(--font-ui); }
.cot-dot { width: 8px; height: 8px; border-radius: 2px; display: inline-block; }
.cot-dot--s { background: #f43f5e; }
.cot-dot--l { background: #10b981; }

/* ── Jauge + labels flottants ── */
.cot-gauge-wrap {
  position: relative; display: flex; align-items: center; justify-content: center;
  width: 100%; flex: 1; min-height: 0; padding: 4px 0;
}
/* Donut borné À LA FOIS en largeur (62% de la cellule) ET en hauteur (100% de sa case) :
   il rétrécit avec sa case quand la cellule est courte (responsive), ratio préservé,
   au lieu de déborder et de chevaucher le badge / la légende. */
.cot-donut { display: block; width: auto; height: auto; max-width: 62%; max-height: 100%; }
.cot-float {
  position: absolute; font-size: 10px; font-weight: var(--fw-bold);
  font-family: var(--font-mono); white-space: nowrap;
}
.cot-float--short { top: 6px; right: 8%; color: #f43f5e; }
.cot-float--long  { bottom: 6px; left: 8%; color: #10b981; }

/* ── Tableau de stats 3 colonnes ── */
.cot-stats {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px;
  width: 100%; padding-top: 8px; border-top: 1px solid var(--bg2);
}
.cot-stat { display: flex; flex-direction: column; align-items: center; gap: 2px; text-align: center; }
.cot-stat-lbl { font-size: 8px; color: var(--text); font-family: var(--font-ui); line-height: 1.2; }
.cot-stat-val { font-size: 13px; font-weight: var(--fw-bold); font-family: var(--font-mono); }
.cot-stat-pct { font-size: 9px; color: #94a3b8; font-family: var(--font-mono); }
.cot-red   { color: #f43f5e; }
.cot-green { color: #10b981; }


/* ═══════════════ DMX (Community Outlook) ═══════════════ */
.dmx-header-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 12px 6px;
  border-bottom: 1px solid var(--border);
  background: var(--head-bg);
  flex-shrink: 0;
}

/* ══ ALIGNEMENT AU PIXEL DES TITRES DES PANNEAUX DE DROITE (demande user 27/07 « fais pareil pour ces
   widgets ») — même méthode que les vues du haut. NORME = `.chart-header` (28px, padding 0 10px, fond
   --head-bg, filet bas). Mesuré avant : 5 hauteurs de barre (25/28/37/38/44px), x à 960 ET 962 (padding
   12px de DMX/Saisonnalité), et FORCE sur un fond --bg2 au lieu de --head-bg.
   `.stf-btn` faisait 28px = toute la hauteur de la barre → ramené à 24px (même gabarit que .season-cfg-btn). */
.cot-header-bar, .dmx-header-bar, .strength-tf-bar {
  height: 28px;
  padding: 0 10px;
  background: var(--head-bg);
  border-bottom: 1px solid var(--border);
}
.strength-tf-bar .stf-btn { height: 24px; }
/* Le <select> natif de tri DMX est masqué au profit du composant `.dtpsel` (30px de haut par défaut) :
   dans une barre de 28px il débordait de 1px en haut/bas → on le compacte au même gabarit que les
   autres contrôles de barre. (Le select natif garde son display:none, cf. .dtpsel-native.) */
.dmx-header-bar .dtpsel-btn { padding-top: 3px; padding-bottom: 3px; font-size: 11px; }
.dmx-header-title {
  font-size: 11px;
  font-weight: var(--fw-semibold);
  color: var(--text);
  font-family: var(--font-mono);      /* cohérence : même police mono que les autres en-têtes */
  letter-spacing: 0.04em;
  flex-shrink: 0;
}
.dmx-header-sep {
  color: var(--text4);
  font-size: 11px;
  flex-shrink: 0;
  margin: 0 2px;
}
.dmx-header-period {
  font-size: 10px;
  color: var(--orange);
  font-family: var(--font-mono);
  font-weight: var(--fw-semibold);
  flex-shrink: 0;
  letter-spacing: 0.03em;
}
.dmx-header-period::before { content: '['; }
.dmx-header-period::after  { content: ']'; }
.dmx-tf-group {
  display: flex;
  align-items: center;
  gap: 2px;
  flex-shrink: 0;
}
.dmx-tf-btn {
  padding: 2px 9px;
  font-size: 10px;
  font-weight: var(--fw-semibold);
  letter-spacing: 0.3px;
  font-family: var(--font-mono);
  background: none;
  border: 1px solid transparent;
  color: var(--text3);
  cursor: pointer;
  border-radius: 3px;
  transition: color 0.12s, border-color 0.12s, background 0.12s;
}
.dmx-tf-btn:hover { color: var(--text); border-color: var(--border2); }
.dmx-tf-btn--active {
  border-color: var(--orange);
  color: var(--orange);
  background: rgba(227,178,58,0.08);
}

.dmx-sort-select {
  /* Le menu natif s'ouvre à la largeur de l'élément : sans borne, une carte étroite coupait les
     libellés. Bornes + libellés courts = toujours lisible, quelle que soit la taille du widget. */
  max-width: 100%;   /* jamais plus large que sa carte */
  min-width: 0;
  text-overflow: ellipsis;
  background: var(--bg3);
  border: 1px solid var(--border2);
  color: var(--text3);
  font-size: 10px;
  font-family: var(--font-mono);
  padding: 2px 5px;
  border-radius: 3px;
  cursor: pointer;
  outline: none;
}
.dmx-sort-select:focus { border-color: var(--orange); }

.dmx-legend-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 14px;
  border-bottom: 1px solid var(--border);
  flex-shrink: 0;
  background: var(--bg2);
}
.dmx-legend-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  flex-shrink: 0;
}
.dmx-legend-long-dot  { background: #1ec898; }
.dmx-legend-short-dot { background: #ff4d6e; margin-left: 8px; }
.dmx-legend-text {
  color: var(--text2);
  font-size: 11px;
  font-family: var(--font-ui);
}

.dmx-table-wrap {
  flex: 1;
  overflow-y: auto;
}

/* ── SEASONALITY — table de performance mensuelle par année (façon pro) ── */
.season-pair-badge { font-family: var(--font-mono); font-size: 11px; font-weight: var(--fw-bold); color: #e3b23a; letter-spacing: .03em; margin-left: 6px; }
.season-table-wrap { flex: 1; overflow: auto; display: flex; }

/* ── Bouton engrenage Seasonality + tooltip « Settings » ── */
/* Ce bouton est un .wdg-ico (celui des cartes de Mon Desk) : taille, couleur, absence de cadre et
   survol dore viennent de la. Il etait en 24x24 avec une bordure qui s allumait — une boite pleine
   au milieu d un panneau, la ou tout le reste est plat. On ne garde ici que le positionnement,
   necessaire a son infobulle. */
.season-cfg-btn { position: relative; margin-left: 8px; }
.season-cfg-btn[data-tip]::after { content: attr(data-tip); position: absolute; top: calc(100% + 7px); right: 0; white-space: nowrap; background: #1b1b1f; color: var(--text); border: 1px solid #2a2a31; border-radius: 4px; padding: 4px 9px; font-size: 11px; font-weight: var(--fw-medium); box-shadow: 0 6px 18px rgba(0,0,0,.5); opacity: 0; transform: translateY(-3px); pointer-events: none; transition: opacity .12s, transform .12s; z-index: 6000; }
.season-cfg-btn[data-tip]:hover::after { opacity: 1; transform: translateY(0); }

/* ── Panneau « Seasonality Performance Table Settings » — volet latéral DROITE (comme les autres volets du desk) ── */
.sea-cfg-overlay { position: fixed; inset: 0; z-index: 5500; background: rgba(0,0,0,.5); backdrop-filter: blur(3px); }
.sea-cfg-modal { position: absolute; top: var(--topbar-h, 44px); right: 0; left: auto; bottom: 0; width: 380px; max-width: 92vw; background: var(--bg); border-left: 1px solid #1f1f24; box-shadow: -8px 0 40px rgba(0,0,0,.55); display: flex; flex-direction: column; }
.sea-cfg-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 14px 16px; border-bottom: 1px solid var(--hud-line, var(--bg2)); }
.sea-cfg-ttl { display: inline-flex; align-items: center; gap: 7px; font-size: 13px; font-weight: var(--fw-semibold); color: var(--text); }
.sea-cfg-x { background: none; border: none; color: #6a6a6f; font-size: 14px; cursor: pointer; padding: 4px 6px; border-radius: 4px; }
.sea-cfg-x:hover { color: var(--text); background: rgba(255,255,255,.06); }
.sea-cfg-body { flex: 1; min-height: 0; padding: 14px 16px; overflow-y: auto; }
.sea-cfg-lbl { font-size: 11px; font-weight: var(--fw-bold); letter-spacing: .04em; color: #8a8a90; text-transform: uppercase; margin: 4px 0 8px; }
.sea-cfg-tabs { display: flex; flex-direction: column; gap: 6px; margin-bottom: 18px; }
.sea-cfg-tab { text-align: left; padding: 10px 14px; background: var(--bg2); border: 1px solid #1f1f24; border-radius: 4px; color: var(--text2, #c4c4c8); font-size: 13px; cursor: pointer; transition: .12s; }
.sea-cfg-tab:hover { border-color: rgba(227,178,58,.4); }
.sea-cfg-tab--on { background: rgba(227,178,58,.12); border-color: rgba(227,178,58,.6); color: #fff; font-weight: var(--fw-semibold); }
.sea-cfg-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.sea-cfg-sym { display: flex; align-items: center; gap: 7px; padding: 9px 11px; background: var(--bg2); border: 1px solid #1f1f24; border-radius: 4px; color: var(--text); font-size: 12px; cursor: pointer; transition: .12s; text-align: left; }
.sea-cfg-sym:hover { border-color: var(--border2); background: var(--row-hover); }
.sea-cfg-sym--on { border-color: #e3b23a; background: rgba(227,178,58,.12); }
.sea-cfg-sym-lbl { flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sea-cfg-chk { color: #e3b23a; font-weight: var(--fw-bold); }
.sea-flag { width: 16px; height: 16px; border-radius: 50%; object-fit: cover; }
.sea-flag--2 { margin-left: -8px; }
.sea-cfg-foot { padding: 12px 16px; border-top: 1px solid var(--hud-line, var(--bg2)); }
.sea-cfg-cancel { width: 100%; padding: 10px; background: var(--bg2); border: 1px solid #2a2a31; border-radius: 4px; color: var(--text); font-size: 13px; font-weight: var(--fw-semibold); cursor: pointer; }
.sea-cfg-cancel:hover { background: #1d1d22; }
.season-table { width: 100%; height: 100%; border-collapse: collapse; table-layout: fixed; font-family: var(--font-mono); }   /* height:100% → la table REMPLIT tout le panneau (façon Session Map), rangées étirées, responsive */
.season-th { font-size: 10px; font-weight: var(--fw-bold); color: var(--text2); text-align: center; padding: 5px 2px; border-bottom: 1px solid var(--border); background: var(--head-bg); position: sticky; top: 0; z-index: 1; }
.season-th--m { width: 40px; }
.season-th--avg { color: #cbd2dc; border-left: 1px solid var(--border); }
.season-month { font-size: 10px; font-weight: var(--fw-bold); color: #aeb6c2; text-align: left; padding: 0 6px; background: var(--bg2); border-bottom: 1px solid var(--bg2); }
.season-td { font-size: 10px; font-weight: var(--fw-semibold); color: #f4f6f9; text-align: center; padding: 5px 1px; border-bottom: 1px solid rgba(0,0,0,.35); border-right: 1px solid rgba(0,0,0,.25); white-space: nowrap; }
.season-td--na { background: var(--bg) !important; color: #3a3a42; }
.season-td--avg { border-left: 1px solid var(--border); font-weight: var(--fw-bold); }
.season-arrow { font-size: 8px; opacity: .85; margin-right: 1px; }

.dmx-loading {
  padding: 28px 16px;
  text-align: center;
  color: var(--text4);
  font-size: 11px;
  font-family: var(--font-mono);
}

/* (legacy rows — kept for compat) */
.dmx-header-row { display: none; }
.dmx-list { display: flex; flex-direction: column; }
.dmx-row {
  display: flex; align-items: center; gap: 7px;
  padding: 9px 10px; border-bottom: var(--row-sep);
  transition: background 0.16s;
}
.dmx-row:hover { background: var(--row-hover); }
.dmx-row:last-child { border-bottom: none; }
.dmx-sym {
  font-family: var(--font-mono); font-size: 11px; font-weight: var(--fw-semibold);
  color: var(--text); letter-spacing: 0.02em; width: 68px;
  flex-shrink: 0;
}

.dmx-num-s {
  color: #f43f5e;
  font-size: 9px;
  font-weight: var(--fw-semibold);
  font-family: var(--font-mono);
  width: 34px;
  text-align: right;
  flex-shrink: 0;
}
.dmx-num-l {
  color: #10b981;
  font-size: 9px;
  font-weight: var(--fw-semibold);
  font-family: var(--font-mono);
  width: 34px;
  text-align: left;
  flex-shrink: 0;
}

.dmx-bar-col {
  flex: 1;
  display: flex;
  align-items: center;
  min-width: 0;
}
.dmx-bar {
  flex: 1;
  height: 7px;
  border-radius: 3px;
  background: var(--bg4);
  overflow: hidden;
  position: relative;
}
.dmx-bar-s {
  position: absolute;
  left: 0; top: 0; height: 100%;
  background: #f43f5e;
}
.dmx-bar-l {
  position: absolute;
  right: 0; top: 0; height: 100%;
  background: #10b981;
}

.dmx-badge {
  font-size: 8px;
  font-weight: var(--fw-bold);
  padding: 2px 5px;
  border-radius: 2px;
  letter-spacing: 0.06em;
  flex-shrink: 0;
  width: 32px;
  text-align: center;
  font-family: var(--font-mono);
}
.dmx-badge--long  { color: #10b981; background: rgba(16,185,129,0.12); }
.dmx-badge--short { color: #f43f5e; background: rgba(244,63,94,0.12); }

.dmx-empty {
  padding: 40px 20px;
  text-align: center;
  color: var(--text4);
  font-size: 11px;
}



/* ─── DMX v2 rows — matches Myfxbook-style horizontal bar design ─ */
.dmx2-list {
  display: flex;
  flex-direction: column;
}

.dmx2-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 3px 12px;
  border-bottom: 1px solid rgba(255,255,255,0.04);
  transition: background 0.16s;
}
.dmx2-row:hover { background: rgba(255,255,255,0.025); }
.dmx2-row:last-child { border-bottom: none; }

.dmx2-sym {
  font-family: var(--font-mono);
  font-size: 11.5px;
  font-weight: var(--fw-semibold);
  color: #eceef2;
  width: 62px;
  flex-shrink: 0;
  letter-spacing: 0.02em;
}

.dmx2-bar {
  flex: 1;
  height: 20px;                /* barres plus fines (moins "grosses") */
  display: flex;
  border-radius: 3px;
  overflow: hidden;
  min-width: 0;
  background: rgba(255,255,255,0.05);
}

/* Long segment — vert la référence exact (couleurs récupérées de la référence) */
.dmx2-bar-long {
  height: 100%;
  background: rgb(0, 230, 118);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  white-space: nowrap;
  flex-shrink: 0;
  min-width: 0;
}

/* Short segment — rouge la référence exact (couleurs récupérées de la référence) */
.dmx2-bar-short {
  height: 100%;
  background: rgb(255, 61, 0);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  white-space: nowrap;
  flex-shrink: 0;
  min-width: 0;
}

/* Percentage label inside the bar */
.dmx2-pct {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: var(--fw-bold);
  color: rgba(255,255,255,0.92);
  text-shadow: 0 1px 2px rgba(0,0,0,0.3);
  pointer-events: none;
  padding: 0 5px;
}

/* ─── Economic Calendar ──────────────────────────────────────────────────── */

#view-calendar {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  flex: 1;
  min-height: 0;
}

/* ═══════════════ ECONOMIC CALENDAR ═══════════════ */

.cal-panel {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  font-family: var(--font-mono);
  background: #080808;
}

/* Toolbar — 2 rows */
.cal-toolbar {
  display: flex;
  flex-direction: column;
  border-bottom: 1px solid #1a1a1a;
  flex-shrink: 0;
  background: var(--bg);
}

/* Row 1: Title + icons */
/* Hauteur, fond, filet et marges viennent de .chart-header (posée sur l'élément) : la seule chose
   propre à ce bandeau est de répartir titre et flèches de navigation aux deux bouts. */
.cal-title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
}
.cal-title-block { flex: 1; }
.cal-title-icons {
  display: flex;
  align-items: center;
  gap: 2px;
  flex-shrink: 0;
}
.cal-title-icon {
  width: 22px;
  height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  color: #3a3a3a;
  cursor: pointer;
  border-radius: 3px;
  transition: color 0.12s, background 0.12s;
  user-select: none;
}
.cal-title-icon:hover { color: #888; background: var(--bg2); }

/* Row 2: Filters + Search + LIVE pushed right */
.cal-filter-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 14px 7px;
  flex-wrap: nowrap;
}

/* Impact filter buttons */
.cal-impact-filter {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* Impact filter buttons — all use the same orange scheme */
.cal-imp-btn {
  padding: 4px 16px;
  font-size: 11px;
  font-weight: var(--fw-bold);
  font-family: var(--font-ui);
  background: transparent;
  border: 1px solid rgba(227,178,58,0.45);
  color: var(--orange);
  border-radius: 3px;
  cursor: pointer;
  letter-spacing: 0.04em;
  transition: background var(--t-fast) var(--ease), border-color var(--t-fast) var(--ease), color var(--t-fast) var(--ease), transform var(--t-fast) var(--ease);
  white-space: nowrap;
}
.cal-imp-btn:hover {
  background: rgba(227,178,58,0.10);
  border-color: rgba(227,178,58,0.7);
}

/* Active state — subtle orange tint */
.cal-imp-btn--active {
  background: rgba(227,178,58,0.18) !important;
  border-color: var(--orange) !important;
  color: var(--orange) !important;
}

/* High / Med / Low inherit the same orange style — no per-level overrides */
.cal-imp-btn--high,
.cal-imp-btn--med,
.cal-imp-btn--low { /* same as base */ }

/* Search */
.cal-search-wrap {
  display: flex;
  align-items: center;
  background: var(--bg2);            /* var(--bg2) — un cran plus clair que le fond (était #111, invisible) */
  border: 1px solid #2c2d34;         /* bordure un cran plus lisible (était #222) */
  border-radius: 3px;
  padding: 4px 10px;
  gap: 6px;
  flex: 1;
  max-width: 340px;
}
.cal-search-icon {
  font-size: 13px;
  color: var(--text3);               /* loupe lisible (était #444) */
  flex-shrink: 0;
  line-height: 1;
}
.cal-search-input {
  background: none;
  border: none;
  outline: none;
  color: var(--text);
  font-size: 11px;
  font-family: var(--font-ui);
  width: 100%;
}
.cal-search-input::placeholder { color: var(--text3); }   /* « Rechercher des événements… » lisible (était #383838, quasi noir) */

/* Title block */
.cal-title-block {
  display: flex;
  align-items: center;
  gap: 0;
  flex-shrink: 0;
  white-space: nowrap;
}
.cal-title {
  font-size: 11.5px;
  font-weight: var(--fw-semibold);
  color: var(--text);
  font-family: var(--tight);
  text-transform: uppercase;             /* meme design que les autres titres d'onglet (chart-header-title) */
  letter-spacing: 0.08em;
}
/* (puce or du titre calendrier retiree a la demande — meme traitement applique au titre Liste FX) */
.cal-title-sep { color: #333; font-size: 11px; margin: 0 4px; }
.cal-title-bracket { color: var(--orange); font-size: 11px; font-family: var(--font-mono); }
.cal-daterange {
  font-size: 11px;
  color: var(--orange);
  font-family: var(--font-mono);
  font-weight: var(--fw-semibold);
}
/* Flèches de navigation historique du calendrier (‹ ›) — jusqu'à 3 mois en arrière */
/* ⚠️ Ces fleches n avaient AUCUNE regle mobile : mesurees a 14 x 11,7 px a l ecran, soit moins de
   la moitie du seuil tactile. Elles commandent pourtant les trois mois d historique du calendrier.
   36 px CSS = 32,4 px reels une fois le zoom global applique. La barre a la place : sa rangee de
   titre occupe 318 px sur 320 disponibles, et la plage de dates reste vide tant que le JS n a pas
   ecrit dedans. */
@media (hover: none), (pointer: coarse), (max-width: 768px) {
  .cal-range-arrow {
    display: inline-flex; align-items: center; justify-content: center;
    min-width: 36px; min-height: 36px; padding: 0 8px; font-size: 16px;
  }
  .cal-title-block { gap: 2px; }
}
.cal-range-arrow {
  background: none; border: none; margin: 0; padding: 0 5px;
  color: var(--orange); font-family: var(--font-mono); font-size: 13px; font-weight: var(--fw-bold);
  line-height: 1; cursor: pointer; opacity: 0.9;
  transition: opacity .15s ease, transform .1s ease; user-select: none;
}
.cal-range-arrow:hover:not(:disabled)  { opacity: 1; transform: scale(1.18); }
.cal-range-arrow:active:not(:disabled) { transform: scale(0.94); }
.cal-range-arrow:disabled { opacity: 0.22; cursor: default; }

.cal-live-badge {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 9px;
  font-weight: var(--fw-bold);
  color: var(--green);
  font-family: var(--font-mono);
  letter-spacing: 0.08em;
  white-space: nowrap;
  flex-shrink: 0;
  background: rgba(46,204,113,0.08);
  border: 1px solid rgba(46,204,113,0.25);
  padding: 3px 9px;
  border-radius: 2px;
}

.cal-live-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--green);
  flex-shrink: 0;
  animation: calLivePulse 1.6s ease-in-out infinite;
}

@keyframes calLivePulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50%       { opacity: 0.35; transform: scale(0.7); }
}

/* Table wrapper */
.cal-table-wrap {
  flex: 1;
  overflow-y: auto;
  overflow-x: auto;
  background: #090909;
}

.cal-loading, .cal-empty {
  padding: 40px 20px;
  text-align: center;
  color: #444;
  font-size: 11px;
  font-family: var(--font-mono);
}

/* Table — haute densité, lignes monoblocs, jamais d'arrondi */
.cal-table {
  width: 100%;
  border-collapse: collapse;
  border-radius: 0;
  font-size: 11px;
}

/* ── Lignes calendrier cliquables ── */
.cal-row--click { cursor: pointer; }
.cal-row--click:hover { background: var(--row-hover); }

/* ── Panneau détail événement (Specs + History) ── */
.cal-detail-overlay {
  position: fixed; inset: 0; z-index: 9000;
  background: rgba(0,0,0,0.62); backdrop-filter: blur(2px);
  display: none; align-items: flex-start; justify-content: center;
  padding: 60px 16px; overflow-y: auto;
}
.cal-detail-overlay.visible { display: flex; }
.cal-detail-card {
  width: 100%; max-width: 620px; background: var(--bg);
  border: 1px solid var(--border); border-radius: 4px; overflow: hidden;
  box-shadow: 0 18px 60px rgba(0,0,0,0.6); animation: calDetailIn .16s ease-out;
}
@keyframes calDetailIn { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; transform: none; } }
.cal-detail-head {
  display: flex; align-items: flex-start; justify-content: space-between;
  gap: 12px; padding: 16px 18px 12px; border-bottom: 1px solid #1d1d22;
}
.cal-detail-titlewrap { display: flex; align-items: center; gap: 10px; }
.cal-detail-flag img { width: 22px; border-radius: 2px; vertical-align: middle; }
.cal-detail-title { font-size: 15px; font-weight: var(--fw-bold); color: #fff; line-height: 1.25; }
.cal-detail-sub { font-size: 11px; color: #9aa0a6; font-family: var(--font-mono); margin-top: 3px; }
.cal-detail-close { font-size: 22px; line-height: 1; color: #777; cursor: pointer; padding: 0 4px; }
.cal-detail-close:hover { color: #fff; }
/* Compacté 17/07 (demande user « moins gros, cohérent ») : boîtes discrètes alignées sur la densité HUD */
.cal-detail-vals { display: flex; gap: 8px; padding: 10px 18px 2px; }
.cdv { flex: 1; background: var(--bg2); border: 1px solid #1f1f24; border-radius: 4px; padding: 5px 8px; text-align: center; }
.cdv-lbl { display: block; font-size: 8.5px; letter-spacing: 0.08em; text-transform: uppercase; color: #8a9097; margin-bottom: 3px; font-family: var(--font-mono); }
.cdv .cv-actual, .cdv .cv-forecast, .cdv .cv-prev { font-size: 12.5px; font-weight: var(--fw-bold); }
.cdv .cv-empty { font-size: 11px; }
.cal-detail-body { padding: 6px 18px 20px; }
.cal-detail-section { font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase; color: #e3b23a; font-weight: var(--fw-bold); margin: 16px 0 8px; font-family: var(--font-mono); }
.cal-specs-table, .cal-hist-table { width: 100%; border-collapse: collapse; font-size: 12px; }
.cal-specs-table td { padding: 7px 8px; border-bottom: 1px solid var(--border); vertical-align: top; color: #e8eaed; }
.cal-spec-lbl { color: #9aa0a6; width: 34%; white-space: nowrap; font-family: var(--font-mono); font-size: 11px; }
.cal-hist-table th { text-align: left; padding: 6px 8px; font-size: 9px; letter-spacing: 0.06em; text-transform: uppercase; color: #8a9097; border-bottom: 1px solid var(--border); font-family: var(--font-mono); }
.cal-hist-table td { padding: 7px 8px; border-bottom: 1px solid var(--border); color: #e8eaed; font-family: var(--font-mono); }
.cal-hist-table th:not(:first-child), .cal-hist-table td:not(:first-child) { text-align: right; }
.cal-detail-empty { color: #8a9097; font-size: 12px; padding: 18px 0; text-align: center; }
/* Décryptage DTP en bas du panneau Info d'une news (plus de pill dédiée dans le fil, 17/07) :
   filet de séparation discret sous les puces, puis le bloc .cal-kb standard. */
.news-eco-slot { margin-top: 11px; padding-top: 10px; border-top: 1px solid var(--hud-line, var(--bg2)); }
/* ── Décryptage DTP du déroulé calendrier (pédagogie éco + banque centrale, 16/07) ── */
.cal-kb { margin: 2px 0 10px; }
.cal-kb-row { display: flex; gap: 12px; padding: 7px 0; border-bottom: 1px solid var(--hud-line, var(--bg2)); font-size: 12px; line-height: 1.55; }
.cal-kb-row:last-child { border-bottom: none; }
.cal-kb-lbl { flex: 0 0 148px; color: #8a9097; font-size: 10.5px; font-weight: 600; letter-spacing: .05em; text-transform: uppercase; padding-top: 1px; }
.cal-kb-val { flex: 1; color: #dcdce0; min-width: 0; }
.cal-kb-cat { display: inline-block; font-size: 10px; font-weight: 700; color: #e3b23a; background: rgba(227,178,58,.10); border: 1px solid rgba(227,178,58,.25); border-radius: 3px; padding: 0 5px; margin-right: 6px; letter-spacing: .04em; text-transform: uppercase; vertical-align: middle; }
.cal-kb-tone { display: inline-block; font-size: 10.5px; font-weight: 700; border: 1px solid; border-radius: 3px; padding: 0 5px; margin-right: 6px; letter-spacing: .04em; text-transform: uppercase; vertical-align: middle; }
.cal-kb-quote { color: #b8bcc4; font-style: italic; margin: 2px 0; }
.cal-kb-quote::before { content: '« '; color: #6f6f79; }
.cal-kb-quote::after  { content: ' »'; color: #6f6f79; }   /* guillemets hors texte → la traduction FR en place ne les mange pas */
.cal-kb-sub { color: #8a9097; font-size: 11px; margin-top: 2px; }
/* Une idée par ligne dans la colonne de droite : le pricing, puis la lecture du ton. */
.cal-kb-line { display: block; }
.cal-kb-line + .cal-kb-line { margin-top: 3px; }
/* CAUSE → CONSÉQUENCE : une par ligne, flèches alignées en colonne. La condition se balaie
   verticalement, la conséquence se lit en face — on ne relit pas une phrase pour la retrouver. */
.cal-flux { display: grid; grid-template-columns: minmax(0, max-content) auto minmax(0, 1fr); column-gap: 9px; row-gap: 5px; margin-top: 6px; align-items: baseline; }
.cal-flux-a { color: var(--text2, #b7bac2); }
.cal-flux-x { color: var(--orange); font-weight: 700; }
.cal-flux-b { color: var(--text); }
/* Écran étroit : la grille à 3 colonnes écraserait les deux textes. On empile, et la conséquence
   se repère à son filet or plutôt qu'à une flèche. */
@media (max-width: 900px) {
  .cal-flux { grid-template-columns: minmax(0, 1fr); row-gap: 0; }
  .cal-flux-x { display: none; }
  .cal-flux-a { margin-top: 4px; }
  .cal-flux-b { padding-left: 9px; border-left: 2px solid var(--orange); margin: 2px 0 4px; }
}
/* Téléphone : la colonne de libellés fige 148 px, soit la moitié de l'écran — le texte se lisait
   en colonnes de trois mots. Le libellé passe AU-DESSUS de sa valeur, qui récupère toute la largeur. */
@media (max-width: 640px) {
  .cal-kb-row { flex-direction: column; gap: 2px; }
  .cal-kb-lbl { flex: none; padding-top: 0; }
}
/* Extrait du discours : 1 propos par ligne = tag signal (hawkish/dovish/neutre) + citation VO + attribution/date */
.cal-kb-qline { margin: 5px 0; line-height: 1.5; }
.cal-kb-qtone { display: inline-block; font-size: 9px; font-weight: 700; border: 1px solid; border-radius: 3px; padding: 0 4px; margin-right: 6px; letter-spacing: .03em; text-transform: uppercase; vertical-align: middle; }
.cal-kb-qwho { color: #7f858e; font-size: 10.5px; font-style: normal; white-space: nowrap; }
.cal-kb-muted { color: #8a9097; }
/* Chip « Clé » (23/07) : discours de tête de BC / audition / minutes — repérable d'un coup d'œil dans la liste */
.cal-key-chip { display: inline-block; margin-left: 6px; padding: 0 5px; font-size: 9px; font-weight: 700; letter-spacing: .05em; text-transform: uppercase; color: #e3b23a; border: 1px solid rgba(227,178,58,.38); border-radius: 3px; vertical-align: middle; line-height: 1.5; }

/* Fiche événement — « Historique des publications » : mini-barres réel vs prévu (~6 mois), ancien → récent */
.cal-hist-sub { font-weight: 400; text-transform: none; letter-spacing: 0; color: #8b93a1; font-size: 10px; }
/* Les colonnes se PARTAGENT la largeur (flex: 1) au lieu de se tasser à gauche : le bloc occupe
   enfin toute la fiche. min-width garde une colonne lisible quand l'historique est long — au-delà,
   le défilement horizontal reprend la main. */
.cal-hist-row { display: flex; align-items: flex-end; gap: 0; padding: 14px 4px 4px; overflow-x: auto; }
.cal-hist-col { flex: 1 1 0; min-width: 60px; text-align: center; padding: 0 0 5px; border-radius: 5px; transition: background .12s ease; }
.cal-hist-col:hover { background: rgba(255,255,255,.03); }
.cal-hist-barwrap { position: relative; height: 96px; display: flex; align-items: flex-end; justify-content: center; border-bottom: 1px solid var(--border2); }
/* Trame éteinte derrière chaque barre (charte DTP) : la colonne existe visuellement même quand
   la valeur est basse — on ne lit jamais un « vide ». */
.cal-hist-barwrap::before { content: ''; position: absolute; bottom: 0; left: 50%; transform: translateX(-50%); width: 62%; max-width: 32px; height: 100%; background: var(--hud-line); opacity: .5; border-radius: 3px 3px 0 0; }
.cal-hist-bar { position: relative; width: 62%; max-width: 32px; border-radius: 3px 3px 0 0; background: linear-gradient(180deg, #9aa2b0, #565b66); min-height: 5px; box-shadow: inset 0 1px 0 rgba(255,255,255,.22); }
.cal-hist-bar.g { background: linear-gradient(180deg, #00e676, #049e57); box-shadow: inset 0 1px 0 rgba(255,255,255,.28); }
.cal-hist-bar.r { background: linear-gradient(180deg, #ff3d00, #b52c00); box-shadow: inset 0 1px 0 rgba(255,255,255,.28); }
/* Dernière publication = la plus récente : liseré or + date en or, elle se repère d'un coup d'œil. */
.cal-hist-col.last .cal-hist-bar { box-shadow: 0 0 0 1px rgba(227,178,58,.5); }
.cal-hist-col.last .cal-hist-date { color: var(--orange); font-weight: 700; }
.cal-hist-val { margin-top: 7px; font-size: 12.5px; font-weight: 700; color: var(--text); font-variant-numeric: tabular-nums; }
.cal-hist-val.g { color: #2ae389; }
.cal-hist-val.r { color: #ff7259; }
.cal-hist-prev { font-size: 10.5px; color: var(--text3); margin-top: 1px; }
.cal-hist-date { font-size: 10px; color: var(--text3); margin-top: 3px; letter-spacing: .02em; }

/* ── Déroulé INLINE d'un événement (accordéon sous la ligne — remplace la modale) ── */
.cal-detail-row > td { padding: 0; background: var(--bg); border-bottom: 1px solid #1d1d22; }
.cal-detail-inline { border-left: 2px solid var(--orange); overflow-x: auto; animation: calDetailIn .16s ease-out; }
.cal-detail-inline-head { display: flex; align-items: center; gap: 10px; padding: 14px 18px 2px; }
.cal-detail-row:hover > td { background: var(--bg); }   /* le déroulé n'a pas l'effet hover des lignes */

.cal-table thead th {
  position: sticky;
  top: 0;
  /* z-index 4 > bandeau de jour (3) : le bandeau sticky glisse SOUS l'en-tete au lieu de manger
     son bas (2,9 px rognes, mesure au banc) ; couvre aussi le lisere or de .cal-row--next (z 1). */
  z-index: 4;
  background: var(--head-bg);             /* en-tete sticky unifie avec les autres tables (etait #080808 noir/gras/blanc) */
  color: var(--text2);
  font-size: 11px;
  font-weight: var(--fw-semibold);
  font-family: var(--font-ui);
  letter-spacing: 0.04em;          /* resserre les libelles (demande "colle les") */
  text-transform: uppercase;
  /* line-height FIXE : la hauteur de l'en-tete devient deterministe (8+14+7+1 = 30 px) ; le `top`
     du bandeau de jour sticky se cale dessus au pixel, quelle que soit la police chargee. */
  line-height: 14px;
  padding: 8px 8px 7px;            /* horizontal aligne sur le corps (.cal-row td 9px 8px) -> colonnes alignees */
  border-bottom: 1px solid var(--border);
  text-align: left;
  white-space: nowrap;
}
.cal-table thead th.cth-val  { text-align: right; }
.cal-table thead th.cth-flag { text-align: center; }

/* Column widths */
/* Gouttiere de 18 px A GAUCHE (th ET td) : le chevron y vit en ABSOLU, donc l'en-tete « Heure » et
   les chiffres commencent au meme x ; avant, le chevron en flux decalait les chiffres de ~10,7 px
   par rapport au libelle (mesure au banc). Largeur 56 : 50 + les 10 px de gouttiere ajoutes. */
.cth-time   { width: 56px; padding-left: 18px !important; }
.cth-flag   { width: 34px; text-align: center !important; padding-left: 2px !important; padding-right: 2px !important; }
.cal-flag-wrap {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  overflow: hidden;
  vertical-align: middle;
  flex-shrink: 0;
  border: 1px solid rgba(255,255,255,0.13);
  box-shadow: 0 1px 4px rgba(0,0,0,0.55), inset 0 0 0 1px rgba(0,0,0,0.18);
}
.cal-flag-img { width: 28px; height: 28px; object-fit: cover; display: block; }
.cth-curr   { width: 36px; }
.cth-imp    { width: 56px; text-align: center !important; }
.cth-event  { min-width: 140px; }
.cth-val    { width: 62px; text-align: right !important; }
/* Mobile/tablette : on masque HAUT et BAS, non fournies par la source (toujours « - ») →
   calendrier plus étroit et lisible, moins de scroll horizontal.
   ⚠️ PAR CLASSE, JAMAIS par nth-child : le masquage par POSITION cachait PRÉVISION dès que le
   réglage Haut/Bas retirait une colonne du DOM (mesuré au banc, 17/08), et il amputait aussi la
   vue symbole (8 colonnes, sans Haut/Bas) de sa colonne 7. La classe suit la donnée, pas le rang. */
@media (max-width: 768px) {
  .cal-table .cth-val--haut, .cal-table .cth-val--bas { display: none; }
  /* « Semaine à Venir » : le calendrier doublé (#wa-cal-body) force min-width:760px (scroll horizontal
     dans le panneau étroit du DESKTOP) → sur MOBILE ça déborde l'écran (colonne ÉVÉNEMENT coupée +
     scroll horizontal page). On retire le min-width sur mobile : le calendrier doublé suit alors le
     MÊME responsive que le calendrier principal (colonnes masquées + largeurs compactes) et tient dans la largeur. */
  #wa-cal-body .cal-table { min-width: 0 !important; }
}
/* Telephone : table calendrier ETROITE (tient dans ~390px). On garde Heure/Pays/Devise/Impact/
   Evenement/Reel et on masque PREVISION (col 8) + PRECEDENT (col 10) -> dispos dans le detail au tap
   (comme HIGH/LOW). Colonnes + paddings compactes pour laisser de la place au nom de l'evenement. */
@media (max-width: 480px) {
  /* CALENDRIER ENTIER À L'ÉCRAN (demande user 15/07) : plus de scroll horizontal — toutes les colonnes utiles
     (Heure/Devise/Impact/Événement/Réel/Prévision/Précédent) tiennent dans ~375px. Pour y arriver : drapeau
     masqué (le code devise suffit) + HIGH/LOW déjà masqués (fourchette secondaire) + colonnes/paddings compacts. */
  #cal-table-wrap .cal-table { min-width: 0; width: 100%; table-layout: fixed; }   /* fixed = les largeurs de colonnes s'imposent au contenu → jamais plus large que l'écran */
  #cal-table-wrap { overflow-x: hidden; }   /* pas de scroll fantôme : la table est déjà calée à 100% */
  .cal-table thead th { overflow: hidden; text-overflow: ellipsis; }   /* « PRÉVISION »/« PRÉCÉDENT » clippés proprement dans leurs 46px */
  /* Colonnes masquées (drapeau, HAUT, BAS ; par CLASSE, le nth-child cachait Prévision quand le
     réglage retirait Haut du DOM) : en layout FIXE, display:none laisse la colonne réserver
     sa part (quirk moteur → ÉVÉNEMENT écrasé). On les rend LARGEUR ZÉRO à la place (invisibles, 0px). */
  .cal-table .cth-flag,
  .cal-table .cth-val--haut,
  .cal-table .cth-val--bas {
    display: table-cell !important; width: 0 !important; max-width: 0 !important;
    padding: 0 !important; font-size: 0 !important; overflow: hidden !important; border: 0 !important;
  }
  #cal-table-wrap .cal-chv { display: none; }   /* chevron › : place gagnée pour l'heure */
  .cth-time { width: 44px !important; font-size: 10px !important; }
  .cth-curr { width: 36px !important; }
  .cth-imp  { width: 34px !important; }
  .cth-val  { width: 46px !important; font-size: 10px !important; }
  .cth-event { min-width: 0 !important; width: auto !important; }
  .cal-table thead th, .cal-row td { padding-left: 4px !important; padding-right: 4px !important; }
  .cal-row td.cth-event { white-space: normal; font-size: 11px; line-height: 1.32; }
}

/* Day separator */
.cal-day-sep {
  position: sticky;
  /* SCELLÉ PAR CONSTRUCTION, pas au pixel près (retour user 18/08, capture : un jour restait ouvert
     entre l'en-tête et le bandeau, les lignes défilaient en transparence dans l'interstice). Caler
     le bandeau à hauteur-du-thead-moins-1 supposait une hauteur EXACTE partout ; or le zoom global
     0.9 du desk arrondit différemment selon l'écran, et 1 px de marge ne pardonne rien. Le bandeau
     rentre désormais de 4 px SOUS l'en-tête, qui est opaque et gagne au z-index (4 > 3) : tout
     arrondi dans cette marge se cache sous l'en-tête au lieu d'ouvrir un jour. Son texte, centré
     dans ~28 px, garde ~8 px d'air au-dessus : rien n'est rogné. */
  top: 26px;
  z-index: 3;
}
/* Divider de jour : bande sombre OPAQUE (couvre les lignes au scroll), texte gris discret.
   #1b1d23 : l'ancien #15161a ne se detachait du fond #090909 que de ~13 niveaux RVB, la bande ne
   se reperait qu'a sa hauteur. ~18-20 niveaux d'ecart : la borne du jour se voit en balayage
   vertical, sans devenir une barre claire qui casserait la densite. */
.cal-day-sep td {
  background: #1b1d23;
  color: #f1f5f9;
  font-size: 11px;
  font-weight: var(--fw-bold);
  font-family: var(--font-ui);
  letter-spacing: 0.03em;
  padding: 6px 14px 5px;
  border-top: 1px solid #050505;
  border-bottom: 1px solid #050505;
  box-shadow: 0 1px 0 rgba(0,0,0,0.6);
}
/* Thème clair : la règle était keyée sur body.theme-light, une classe que plus rien ne pose
   (mécanisme doublon retiré le 18/08) : elle était MORTE en prod, et le bandeau restait une bande
   sombre #1b1d23 à texte quasi blanc au milieu d'un calendrier éclairci. Re-keyée sur le vrai
   sélecteur du thème, et complétée : fond en-tête clair, encre, filets du thème. Sans effet en
   sombre (attribut absent). */
html[data-theme="light"] .cal-day-sep td {
  background: var(--head-bg);
  color: var(--text);
  border-top-color: var(--border);
  border-bottom-color: var(--border);
  box-shadow: 0 1px 0 rgba(0, 0, 0, 0.08);
}

/* Event rows — bloc compact, séparateur 1px, aucun arrondi */
.cal-row {
  border-bottom: var(--row-sep);   /* filet subtil unifie sur la ligne de news */
  border-radius: 0;
  transition: background 0.15s;
  cursor: default;
}
.cal-row:hover { background: var(--row-hover); }   /* hover sobre neutre unifie sur la ligne de news */

.cal-row td {
  padding: 9px 8px;
  vertical-align: middle;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  border-radius: 0;
  border-right: none;   /* filets verticaux retires : look "ligne de news" (separation horizontale seule) */
  font-size: 11px;
  color: #e8e8ea;   /* texte calendrier en blanc (look pro) */
}
.cal-row td:last-child, .cal-table thead th:last-child { border-right: none; }
.cal-table thead th { border-right: none; }

/* Chevron : en ABSOLU dans la gouttiere gauche de la cellule Heure (position:relative sur le td).
   En flux, il decalait les chiffres de ~10,7 px par rapport au libelle « Heure » de l'en-tete,
   seule colonne desalignee de la table (mesure au banc). Absolu : les chiffres commencent au
   padding-left du td, identique a celui du th. */
.cal-row td.cth-chv { padding: 0 0 0 10px; text-align: center; }
.cal-chv {
  position: absolute;
  left: 7px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 8px;
  color: #333;
  line-height: 1;
  transition: transform 0.15s, color 0.15s;
  cursor: default;
  user-select: none;
}
.cal-row:hover .cal-chv { color: #555; }
/* translateY conserve dans la rotation : sans lui, le chevron deplie sauterait hors du centrage vertical */
.cal-row--expanded .cal-chv { transform: translateY(-50%) rotate(90deg); color: var(--orange); }
.cal-row--next .cal-chv { color: var(--orange) !important; }

/* Expand panel */
.cal-expand-row td {
  padding: 0;
  border-top: var(--row-card-bd);
  border-bottom: var(--row-card-bd);
  background: var(--row-card-bg);
}
.cal-expand-body {
  padding: 8px 12px 10px 40px;
  font-size: 10px;
  color: var(--row-detail-fg);
  font-family: var(--font-mono);
  line-height: 1.7;
}

/* Event name */
.cal-row td.cth-event {
  white-space: normal;
  color: #ffffff;
  font-size: 12px;
  font-weight: var(--fw-semibold);
  font-family: var(--font-ui);
  line-height: 1.35;
  padding-right: 16px;
}

/* Time : EN BLANC (26/08, demande utilisateur capture à l'appui « met les heures en blancs »).
   L'heure était en gris moyen (var(--text2)) par un arbitrage antérieur : elle est un REPÈRE, le
   libellé de l'événement porte l'information, et au même blanc l'oeil n'avait aucune raison de lire
   l'événement d'abord. La hiérarchie ne repose donc plus sur la couleur mais sur ce qui la portait
   déjà : la POLICE (chiffres monospacés contre texte proportionnel), la TAILLE (11 px contre 12,5)
   et la GRAISSE (medium contre semi-bold du libellé). Une colonne de chiffres alignés se balaie de
   toute façon comme une colonne, pas comme du texte.
   L'événement EN COURS garde son heure OR et grasse (.cal-row--next, plus bas) : ce repère-là doit
   se distinguer des autres, et il le peut encore puisque les autres ne sont plus grises mais
   blanches — l'or reste le seul accent de la colonne. */
.cal-row td.cth-time {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: var(--fw-medium);
  color: #ffffff;
  position: relative;
  letter-spacing: 0.02em;
}

/* Flag */
.cal-row td.cth-flag { text-align: center; line-height: 1; }

/* Currency */
.cal-row td.cth-curr {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: var(--fw-bold);
  color: #ffffff;
  white-space: nowrap;
}

/* Impact = Dot Matrix ●●● : les 3 points sont TOUJOURS rendus, les inactifs estompés (opacité variable) */
.cal-row td.cth-imp { text-align: center; white-space: nowrap; }
.ci-high, .ci-med, .ci-low { font-size: 10px; letter-spacing: 2.5px; }
.ci-high    { color: #ef4444; }   /* High  → ●●● pleins */
.ci-med     { color: var(--neutral); }   /* Med   → ●● pleins + 1 estompé */
.ci-low     { color: #4ade80; }   /* Low   → ● plein + 2 estompés */
.ci-dot-off { opacity: 0.2; }     /* points inactifs de la matrice */

/* Value columns */
.cal-row td.cth-val { text-align: right; font-family: var(--font-mono); font-size: 11px; }
.cv-num      { color: #e8e8ea; }
.cv-forecast { color: #e8e8ea; }
.cv-prev     { color: #e8e8ea; }
.cv-empty    { color: #6b7280; }
.cv-actual   { font-weight: var(--fw-bold); color: var(--st-flat); }   /* pas de prévision → blanc, on ne juge pas */
.cv-pos      { color: var(--st-pos) !important; }            /* Deviation > forecast : vert fluo */
.cv-neg      { color: var(--st-neg) !important; }            /* Deviation < forecast : rouge écarlate */
/* CONFORME AU CONSENSUS : le chiffre est tombé PILE sur la prévision. TROIS COULEURS ET PAS UNE DE
   PLUS (arbitrage user 12/08 : « blanc = neutre, vert positif, rouge négatif, juste ces 3 ») —
   l'ambre essayé un moment ajoutait un quatrième signal à lire dans une colonne qui doit se
   parcourir d'un coup d'œil. Le neutre reste donc blanc, comme l'absence de référence.
   La classe est conservée : elle distingue les deux cas dans le DOM (« sorti au consensus » vs
   « pas de prévision »), ce qui reste utile aux composants qui voudraient les traiter à part. */
.cv-neu      { color: var(--st-flat) !important; }
/* Éclair « sous l'estimation basse (LOW) » : à GAUCHE du réel, hérite de la COULEUR DU RÉSULTAT
   (vert/rouge/blanc du span parent via currentColor) + halo assorti très léger (demande user) */
.cv-bolt     { display: inline-block; margin-right: 4px; vertical-align: -2px; filter: drop-shadow(0 0 2px currentColor); }

/* Lightning bolt on actual values that beat/miss */
.cv-bolt {
  font-size: 9px;
  margin-right: 2px;
  opacity: 0.85;
  vertical-align: middle;
}

/* Row state variants */
.cal-row--next {
  background: rgba(227,178,58,0.05);
  outline: 1px solid rgba(227,178,58,0.6);
  outline-offset: -1px;
  position: relative;
  z-index: 1;
}
.cal-row--next td { border-top: 1px solid rgba(227,178,58,0.5); border-bottom: 1px solid rgba(227,178,58,0.5); }
.cal-row--next td.cth-time { color: var(--orange) !important; font-weight: var(--fw-bold); }
.cal-row--next:hover { background: var(--row-hover); }
/* Le PASSÉ reste en retrait, mais en BLANC ÉTEINT et non plus en gris teinté : « met les heures en
   blancs » vaut pour toute la colonne, y compris les publications déjà tombées. Le retrait se joue
   désormais sur l'opacité seule — même teinte que les autres heures, simplement moins présente —
   là où var(--text3) introduisait une nuance bleutée différente du reste de la colonne. */
.cal-row--past td.cth-time { color: rgba(255, 255, 255, 0.5); }
/* Devise TOUJOURS blanche (look pro) — l'impact est déjà indiqué par les points colorés de la colonne IMP. */
.cal-row--high td.cth-curr { color: #ffffff; font-weight: var(--fw-bold); }
.cal-row--med  td.cth-curr { color: #ffffff; }

/* Current-time bar inside time cell */
.cal-now-bar {
  display: inline-block;
  width: 2px;
  height: 10px;
  background: var(--orange);
  border-radius: 1px;
  margin-right: 4px;
  vertical-align: middle;
}



