}
.pd-plan-name {
  font-size: 13px;
  font-weight: var(--fw-semibold);
  color: #e8e8e8;
  font-family: 'Inter', sans-serif;
  display: flex;
  align-items: center;
  gap: 7px;
}
.pd-plan-active-badge {
  font-size: 10px;
  font-weight: var(--fw-semibold);
  color: #2ecc71;
  border: 1px solid #2ecc71;
  border-radius: 4px;
  padding: 1px 6px;
  font-family: 'Inter', sans-serif;
}
.pd-plan-price {
  font-size: 14px;
  font-weight: var(--fw-bold);
  color: #e8e8e8;
  font-family: 'Inter', sans-serif;
}
.pd-plan-next {
  font-size: 11px;
  color: #666;
  font-family: 'Inter', sans-serif;
}
.pd-divider {
  height: 1px;
  background: #1a1a1a;
  margin: 12px 0;
}
.pd-renewal-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
}
.pd-renewal-label {
  font-size: 12px;
  color: #e8e8e8;
  font-family: 'Inter', sans-serif;
}
/* Toggle switch */
.pd-toggle {
  width: 36px;
  height: 20px;
  background: #2a2a2a;
  border-radius: 4px;
  position: relative;
  cursor: pointer;
  transition: background 0.2s;
  flex-shrink: 0;
}
.pd-toggle.on { background: #2ecc71; }
.pd-toggle-thumb {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #e8e8e8;
  transition: left 0.2s;
}
.pd-toggle.on .pd-toggle-thumb { left: 19px; }
/* Ligne du verrou biométrique (panneau « Mot de passe et sécurité »), révélée par la coquille
   mobile seulement. Même grammaire que le reste du panneau : pas de cadre neuf, un simple filet. */
.pd-bio-row { display: flex; align-items: center; gap: 14px; padding: 10px 0 14px;
  border-bottom: 1px solid var(--hud-line, var(--border)); margin-bottom: 14px; }
.pd-bio-txt { min-width: 0; flex: 1 1 auto; }
.pd-bio-t { font-size: 12.5px; color: var(--text); line-height: 1.4; }
.pd-bio-h { font-size: 11px; color: var(--text3); line-height: 1.45; margin-top: 3px; }
.pd-invoices-title {
  font-size: 12px;
  font-weight: var(--fw-semibold);
  color: #e8e8e8;
  font-family: 'Inter', sans-serif;
  margin-bottom: 8px;
}
.pd-invoice-row {
  display: flex;
  align-items: center;
  gap: 10px;
  background: #111;
  border-bottom: 1px solid #1a1a1a;
  padding: 10px 14px;
}
.pd-invoice-icon { font-size: 16px; flex-shrink: 0; color: #888; }
.pd-invoice-info { flex: 1; min-width: 0; }
.pd-invoice-date { font-size: 12px; font-weight: var(--fw-semibold); color: #e8e8e8; font-family: 'Inter', sans-serif; }
.pd-invoice-ref  { font-size: 10px; color: #666; font-family: var(--font-mono); }
.pd-invoice-amount { font-size: 12px; color: #e8e8e8; font-family: 'Inter', sans-serif; flex-shrink: 0; }
.pd-invoice-dl { font-size: 14px; color: #555; cursor: pointer; flex-shrink: 0; margin-left: 8px; }
.pd-invoice-dl:hover { color: #e3b23a; }

/* ── Support section (encadrés épuré) ── */
.pd-support-link {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 13px;
  margin-bottom: 8px;
  border: 1px solid #1f1f26;
  border-radius: 4px;
  background: var(--bg2);
  color: #b5b5bd;
  font-size: 13px;
  text-decoration: none;
  font-family: 'Inter', sans-serif;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
}
.pd-support-link:last-child { margin-bottom: 0; }
.pd-support-link:hover { background: #16161b; border-color: #2a2a32; color: #f0f0f2; }
.pd-support-icon { display: inline-flex; align-items: center; justify-content: center; width: 20px; height: 20px; flex-shrink: 0; color: var(--text2); }
.pd-support-icon svg { width: 18px; height: 18px; }
.pd-support-link:hover .pd-support-icon { color: #e3b23a; }
.pd-support-text { flex: 1; }
.pd-support-ext { display: inline-flex; align-items: center; color: #5a5a62; flex-shrink: 0; }
.pd-support-ext svg { width: 15px; height: 15px; }

/* Placeholder text */
.pd-placeholder {
  font-size: 11px;
  color: #444;
  font-style: italic;
  font-family: 'Inter', sans-serif;
  padding: 4px 0 8px;
}

/* ── Footer (logout) : bande rouge PLEINE LARGEUR (demande user 03/08 « le rouge doit s'étendre sur
   tout le panneau ») — le padding du footer laissait une gouttière sombre autour de la rangée. ── */
.pd-footer {
  padding: 0;
  border-top: 1px solid #1e1e1e;
  flex-shrink: 0;
  background: var(--bg);
}
.pd-logout-btn {
  display: flex;
  align-items: center;
  justify-content: flex-start;       /* aligné à gauche (comme l'image) */
  gap: 11px;
  background: rgba(231, 76, 60, 0.08);
  border: none;
  border-radius: 0;
  color: #e74c3c;
  font-size: 13px;
  font-weight: var(--fw-semibold);
  font-family: 'Inter', sans-serif;
  padding: 13px 16px;
  cursor: pointer;
  width: 100%;
  transition: background 0.15s;
}
.pd-logout-btn:hover {
  background: rgba(231, 76, 60, 0.16);
}

/* ── Topbar avatar trigger button ── */
#topbar-avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: var(--bg3);
  border: 1px solid var(--border);
  color: #e8e8e8;
  font-size: 13px;
  font-weight: var(--fw-bold);
  font-family: 'Inter', sans-serif;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  position: relative;
  transition: border-color 0.15s, background 0.15s;
  flex-shrink: 0;
  margin-left: 2px;
  overflow: hidden;
}
#topbar-avatar:hover {
  border-color: #e3b23a;
  background: #252525;
}
#topbar-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 50%;
}
#topbar-avatar .pd-status-mini {
  position: absolute;
  bottom: 0px;
  right: 0px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #2ecc71;
  border: 1.5px solid #111;
}

/* ═══════════════════════════════════════════════════════
   NOTIFICATION PANEL  (prefix: np-)
═══════════════════════════════════════════════════════ */

/* Overlay (transparent — closes panel on outside click) */
.np-overlay {
  display: none;
  position: fixed;
  top: var(--topbar-h); left: 0; right: 0; bottom: 0;   /* sous la topbar → icônes cliquables */
  z-index: 1100;
  background: rgba(0,0,0,0.5); backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px);   /* rideau flouté comme les autres volets (fini le dashboard net derrière) */
}
.np-overlay.open { display: block; }

/* Panel */
.np-panel {
  position: fixed;
  top: var(--topbar-h);
  right: 0;
  width: 420px;
  max-width: var(--vpw);
  height: calc(var(--vph) - var(--topbar-h));
  background: #0f0f0f;
  border-left: 1px solid #1e1e1e;
  display: flex;
  flex-direction: column;
  z-index: 1101;
  transform: translateX(100%);
  transition: transform 0.22s cubic-bezier(.4,0,.2,1);
  overflow: hidden;
}
.np-panel.open { transform: translateX(0); }

/* Header */
.np-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  border-bottom: 1px solid #1a1a1a;
  flex-shrink: 0;
}
.np-title {
  font-size: 14px;
  font-weight: var(--fw-bold);
  color: #e8e8e8;
  flex: 1;
}
.np-main-toggle {
  padding: 2px 9px;
  border-radius: 3px;
  font-size: 10px;
  font-weight: var(--fw-bold);
  font-family: var(--font-mono);
  letter-spacing: 0.06em;
  cursor: pointer;
  transition: background 0.15s;
  background: #e3b23a;
  color: #000;
  user-select: none;
}
.np-main-toggle.off {
  background: #2a2a2a;
  color: #666;
}
.np-close-btn {
  background: none;
  border: none;
  color: #555;
  font-size: 18px;
  cursor: pointer;
  padding: 0 2px;
  line-height: 1;
  transition: color 0.12s;
}
.np-close-btn:hover { color: #e8e8e8; }

/* Settings row */
.np-settings-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-bottom: 1px solid #1a1a1a;
  flex-shrink: 0;
}
.np-select {
  background: #191919;
  border: 1px solid #2a2a2a;
  border-radius: 4px;
  color: #aaa;
  font-size: 11px;
  font-family: 'Inter', sans-serif;
  padding: 5px 8px;
  outline: none;
  cursor: pointer;
}
.np-select:focus { border-color: #e3b23a; }
/* Silence (Muet / notifs OFF) → type de son verrouillé : grisé + non cliquable */
.np-select:disabled, .np-select--locked {
  opacity: 0.4;
  cursor: not-allowed;
  color: #666;
}
.np-vol-btn {
  display: flex;
  align-items: center;
  gap: 5px;
  background: #191919;
  border: 1px solid #2a2a2a;
  border-radius: 4px;
  color: #aaa;
  font-size: 11px;
  font-family: 'Inter', sans-serif;
  padding: 5px 10px;
  cursor: pointer;
  transition: color 0.12s, border-color 0.12s;
  white-space: nowrap;
}
.np-vol-btn:hover { color: #e8e8e8; border-color: #3a3a3a; }
.np-push-group {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
}
.np-push-label {
  font-size: 11px;
  color: #888;
  white-space: nowrap;
}
.np-push-toggle {
  display: flex;
  align-items: center;
  gap: 4px;
  background: #e3b23a;
  border-radius: 12px;
  padding: 2px 8px 2px 4px;
  cursor: pointer;
  transition: background 0.15s;
  user-select: none;
}
.np-push-toggle.off { background: #2a2a2a; }
.np-push-thumb {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #fff;
  flex-shrink: 0;
}
.np-push-state {
  font-size: 10px;
  font-weight: var(--fw-bold);
  font-family: var(--font-mono);
  color: #000;
  letter-spacing: 0.04em;
}
.np-push-toggle.off .np-push-state { color: #666; }

/* Filter tabs bar */
/* Barre d'onglets des ALERTES — TOUS LES ONGLETS VISIBLES À L'OUVERTURE (demande user 12/08).
   Elle défilait horizontalement entre deux flèches ‹ ›, et les 6 onglets (Tout · News · Calendrier ·
   Analystes · Institutions · DTP) font ~440 px alors que le volet en fait 380-420 : « DTP » — donc les
   nouveautés du desk — restait hors champ, invisible tant qu'on ne devinait pas qu'il fallait faire
   défiler. On passe au RETOUR À LA LIGNE : la barre grandit d'une ligne au besoin, rien n'est caché,
   et les flèches disparaissent (elles n'ont plus rien à faire défiler). */
.np-tabs-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  border-bottom: 1px solid #1a1a1a;
  flex-shrink: 0;
  min-height: 36px;
  padding: 0 4px;
}
.np-tabs-scroll {
  flex: 1 1 auto;
  display: flex;
  flex-wrap: wrap;
  gap: 0;
  overflow: visible;
  scrollbar-width: none;
}
.np-tabs-scroll::-webkit-scrollbar { display: none; }
.np-tabs-scroll { scrollbar-width: none; }   /* volontairement masquée : la règle globale la ferait réapparaître */
.np-tab {
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  color: #555;
  font-size: 11px;
  font-family: 'Inter', sans-serif;
  font-weight: var(--fw-medium);
  padding: 0 9px;      /* resserré : 6 onglets tiennent en 2 lignes courtes, souvent en 1 sur large écran */
  height: 34px;
  cursor: pointer;
  white-space: nowrap;
  flex-shrink: 0;
  transition: color 0.12s, border-color 0.12s;
  margin-bottom: -1px;
}
.np-tab:hover { color: #aaa; }
.np-tab--active { color: #e3b23a; border-bottom-color: #e3b23a; }
.np-filter-btn {
  display: flex;
  align-items: center;
  gap: 4px;
  background: none;
  border: 1px solid #2a2a2a;
  border-radius: 3px;
  color: #555;
  font-size: 10px;
  font-family: 'Inter', sans-serif;
  padding: 3px 8px;
  cursor: pointer;
  flex-shrink: 0;
  margin-left: 4px;
  transition: color 0.12s;
}
.np-filter-btn:hover { color: var(--text2); }

/* Items list */
.np-list {
  flex: 1;
  overflow-y: auto;
  scrollbar-width: thin;
  /* barre : globale (elle etait en #222) */
}
.np-list::-webkit-scrollbar { width: 4px; }
.np-list::-webkit-scrollbar-thumb { background: #222; border-radius: 2px; }

.np-empty {
  padding: 40px 20px;
  text-align: center;
  color: #444;
  font-size: 12px;
}

.np-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 12px 16px;
  border-bottom: 1px solid rgba(255,255,255,0.04);
  cursor: pointer;
  transition: background 0.16s;
}
.np-item:hover { background: rgba(255,255,255,0.03); }
.np-item:last-child { border-bottom: none; }
/* ══ UNE ALERTE NON LUE SE VOIT SANS ÊTRE LUE (01/09, référence fournie) ═══════════════════════
   Le seul signe de non-lu était la teinte de la pastille de gravité, à gauche, de 22 px — invisible
   dans une liste de trente lignes. La référence marque la ligne elle-même : un liseré à gauche et un
   POINT en haut à droite, à l'endroit où l'œil arrive en fin de titre.
   Le point est ROUGE dans la référence ; il est OR chez nous, et c'est la charte qui tranche : le
   rouge dit le baissier et l'alerte, pas « pas encore ouvert ». L'or est la couleur d'attention du
   desk, et il reste distinct des états de marché. La ligne est en `position: relative` pour le
   porter — sans quoi le point se poserait par rapport au volet et flotterait n'importe où. */
.np-item { position: relative; }
.np-item--unread { background: rgba(227, 178, 58, .035); box-shadow: inset 2px 0 0 rgba(227, 178, 58, .45); }
.np-item--unread:hover { background: rgba(227, 178, 58, .06); }
.np-unread {
  position: absolute; top: 13px; right: 13px; width: 6px; height: 6px; border-radius: 50%;
  background: var(--orange, #e3b23a); box-shadow: 0 0 5px rgba(227, 178, 58, .5); pointer-events: none;
}
.np-item-headline { padding-right: 12px; }        /* le titre ne passe jamais sous le point */

/* ══ LES TROIS CHIFFRES D'UNE PUBLICATION, EN CELLULES (01/09, référence fournie) ══════════════
   Réel / Prévu / Précédent côte à côte, chacun sous son intitulé. La question posée par une alerte
   de calendrier — au-dessus ou en dessous du consensus ? — se lit alors sans lire de phrase.
   `minmax(0, 1fr)` et non `1fr` : une valeur longue (« 1818.0 ») élargirait sinon sa colonne et
   décalerait les trois cellules d'une ligne à l'autre, ce qui interdit la comparaison verticale
   entre deux alertes — précisément l'usage de cette liste. */
.np-abc {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 5px; margin: 5px 0 6px;
}
.np-abc-c {
  display: flex; flex-direction: column; gap: 2px; min-width: 0;
  padding: 4px 6px; border: 1px solid var(--hud-line, rgba(255, 255, 255, .07)); border-radius: 4px;
  background: rgba(255, 255, 255, .02);
}
.np-abc-c i {
  font-style: normal; font-size: 8px; font-weight: 700; letter-spacing: .07em;
  color: var(--text4, #5b616b); text-transform: uppercase;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.np-abc-c b {
  font-size: 11.5px; font-weight: 700; font-variant-numeric: tabular-nums; color: var(--text2, #c9cdd4);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.np-abc-c .cv-forecast, .np-abc-c .cv-prev { color: var(--text3, #8a8f98); }
html[data-theme="light"] .np-item--unread { background: rgba(184, 134, 11, .06); box-shadow: inset 2px 0 0 rgba(184, 134, 11, .5); }
html[data-theme="light"] .np-unread { background: var(--orange-dim, #b8860b); }
html[data-theme="light"] .np-abc-c { background: rgba(0, 0, 0, .02); }
.np-item.np-item--unread .np-icon { color: #e8e8e8; }

/* Left icon */
.np-icon {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 1px solid #2a2a2a;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin-top: 1px;
  color: #555;
  font-size: 11px;
}
.np-icon--high {
  border-color: rgba(227,178,58,0.4);
  color: #e3b23a;
}
.np-icon--breaking {
  border-color: rgba(231,76,60,0.4);
  color: #ef4444;
}

.np-item-body { flex: 1; min-width: 0; }
.np-item-headline {
  font-size: 11.5px;
  font-weight: var(--fw-semibold);
  color: #e8e8e8;
  line-height: 1.4;
  margin-bottom: 3px;
  /* 3 line clamp */
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.np-item-desc {
  font-size: 10px;
  color: #666;
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin-bottom: 4px;
}
.np-item-time {
  font-size: 10px;
  color: #444;
  font-family: var(--font-mono);
}
.np-item-meta { display: flex; align-items: center; gap: 8px; }
.np-origin {
  font-size: 9px;
  font-weight: var(--fw-bold);
  letter-spacing: .4px;
  text-transform: uppercase;
  padding: 2px 6px;
  border-radius: 4px;
  border: 1px solid transparent;
}
.np-origin--squawk  { color: #22c55e; background: rgba(34,197,94,.12);  border-color: rgba(34,197,94,.35); }
.np-origin--news    { color: #60a5fa; background: rgba(96,165,250,.12); border-color: rgba(96,165,250,.32); }
.np-origin--cal     { color: #e3b23a; background: rgba(227,178,58,.12); border-color: rgba(227,178,58,.32); }
.np-origin--risk    { color: #ef4444; background: rgba(239,68,68,.12);  border-color: rgba(239,68,68,.32); }
.np-origin--analyst { color: #a78bfa; background: rgba(167,139,250,.12);border-color: rgba(167,139,250,.32); }

/* Bell active state (couleur définie plus bas avec le trait vert) */
#np-bell-btn.np-bell--active { color: #fff; }

/* Topbar bell cursor */
#np-bell-btn { cursor: pointer; }

/* ═══════════════════════════════════════════════════════════
   RESPONSIVE — comprehensive overrides for all screen sizes
═══════════════════════════════════════════════════════════ */

/* ── Large laptop (≤1280px) ── */
@media (max-width: 1280px) {
  .views-col       { flex-basis: 55%; }
  .pd-drawer       { width: 420px; }
  .np-panel        { width: 380px; }
  .settings-panel  { width: 380px; }
}

/* ── Tablet landscape (≤1024px) — enhance existing ── */
@media (max-width: 1024px) {
  .views-col       { flex-basis: 52%; min-width: 340px; }
  .pd-drawer       { width: 380px; }
  .np-panel        { width: 360px; }
  .settings-panel  { width: 360px; }

  /* COT grid: 2 columns on tablet */
  .cot-grid        { grid-template-columns: repeat(2, 1fr); }

  /* DMX bars slightly smaller */
  .dmx2-sym        { width: 54px; font-size: 11px; }
  .dmx2-bar        { height: 18px; }
  .dmx2-pct        { font-size: 10px; }

  /* Strength chart toolbar compact */
  .strength-tf-bar { padding: 4px 8px; gap: 2px; }
  .stf-btn         { padding: 1px 5px; font-size: 9px; }
}

/* ── Tablet portrait (≤768px) — full responsive mode ── */
@media (max-width: 768px) {
  /* Drawers: full width (100% évite le débordement scrollbar) */
  .pd-drawer, .np-panel, .settings-panel, .settings-overlay {
    width: 100% !important;
    max-width: 100% !important;
  }
  .settings-overlay { justify-content: flex-start; }

  /* Topbar: compact, hide less critical elements */
  .topbar-username { display: none; }
  .topbar-logout-btn[id="topbar-admin-btn"] { display: none !important; }

  /* Clock items: touch-friendly sizing */
  .clock-item      { min-width: 130px; padding: 7px 10px; }
  .clock-time      { font-size: 21px; }
  .clock-gmt       { font-size: 8px; }
  .clock-wx-row, .clock-wind-row { font-size: 9px; }

  /* News items: full-width readable */
  .news-item       { --c-pad: 12px; --c-icon: 26px; --c-time: 52px; --c-cat: 112px; --c-arrow: 22px; padding: 9px var(--c-pad); }   /* colonnes mobiles → bleed gauche ET droit suivent --c-pad ; 9px = densite desktop */
  .news-time       { min-width: 38px; font-size: 10px; }
  .news-category-text { width: 80px; font-size: 10px; }
  .news-headline   { font-size: 12px; }

  /* Toolbar: wrap gracefully */
  .panel-toolbar   { flex-wrap: wrap; height: auto; min-height: var(--toolbar-h); padding: 4px 8px; }
  .toolbar-right   { border-left: none; padding: 0; }

  /* Right panel tabs: compact */
  .right-tab       { font-size: 9px; padding: 0 7px; }
  .right-tab-spacer { flex: 1; min-width: 0; }

  /* COT: 2 columns */
  .cot-grid        { grid-template-columns: repeat(2, 1fr); }
  .cot-type-btn    { font-size: 8px; padding: 1px 5px; }

  /* DMX */
  .dmx2-sym        { width: 50px; font-size: 10px; }
  .dmx2-bar        { height: 18px; }
  .dmx2-pct        { font-size: 10px; }
  .dmx-header-title { font-size: 10px; }

  /* Tags: wrap */
  .news-tags       { flex-wrap: wrap; gap: 3px; }
  .tag             { font-size: 10px; padding: 2px 7px; }

  /* Admin page: table scrollable */
  .table-wrap      { overflow-x: auto; }
  .users-table th, .users-table td { font-size: 11px; padding: 7px 8px; }
  .add-form        { flex-direction: column; }
  .add-form .form-field { min-width: unset; width: 100%; }
}

/* ── Mobile (≤480px) ── */
@media (max-width: 480px) {
  :root {
    --topbar-h: 42px;
    --navbar-h: 40px;   /* = min-height tactile des .nav-item → onglets non coupés (le --header-h est recalculé ligne ~8783) */
  }

  /* Layout : pleine hauteur — aligné sur le bloc mobile ≤768px (ligne ~3345). NE PAS remettre 65vh : ça créait une zone morte sous le flux + double scroll. */
  .views-col       { height: calc(var(--vph) - var(--header-h)); min-height: 0; }
  .panel-news      { height: 100%; min-height: 0; }

  /* Topbar: minimal */
  .topbar          { padding: 0 8px; gap: 6px; }
  .topbar-icon     { width: 34px; height: 34px; }   /* cible tactile : ne pas redescendre sous ~34px (le bloc ligne ~3355 fait foi) */
  .topbar-symbol-search { display: none; }
  #topbar-avatar   { width: 26px; height: 26px; font-size: 11px; }

  /* Clocks: compact horizontal scroll */
  .clock-item      { min-width: 120px; padding: 6px 9px; }
  .clock-time      { font-size: 19px; }
  .clock-city-label { font-size: 10px; }
  .clock-wx-row, .clock-wind-row { display: none; } /* hide weather on very small screens */

  /* Profile drawer: full screen */
  .pd-drawer       { top: var(--topbar-h); height: calc(var(--vph) - var(--topbar-h)); }   /* règle projet : volet SOUS la topbar, jamais top:0 */
  .pd-header       { padding: 14px 14px; }
  .pd-section-trigger { height: 46px; }

  /* Notification panel: sous la topbar */
  .np-panel        { top: var(--topbar-h); height: calc(var(--vph) - var(--topbar-h)); }
  .np-title        { font-size: 13px; }

  /* News: simplify */
  .news-category-text  { display: none; }
  .news-time           { min-width: 34px; }
  .news-headline       { font-size: 11.5px; }

  /* Tags: minimal */
  .tag             { font-size: 9px; padding: 2px 6px; }

  /* COT: single column */
  .cot-grid        { grid-template-columns: 1fr; }

  /* DMX: compact */
  .dmx2-row        { padding: 3px 8px; }
  .dmx2-sym        { width: 46px; font-size: 10px; }
  .dmx2-bar        { height: 17px; }

  /* Toolbar search: full width */
  .toolbar-search  { width: 100%; }

  /* Strength chart: smaller */
  .stf-btn         { padding: 1px 4px; font-size: 9px; }
  .strength-chart-label { display: none; }

  /* Right panel tabs: smaller */
  .right-tab       { font-size: 10px; padding: 0 7px; letter-spacing: 0; }   /* lisible : la barre scrolle horizontalement, pas besoin d'écraser la police */

  /* METER : 8 colonnes compactes pour tenir/rester lisible sur petit écran */
  .meter-grid      { gap: 4px; padding: 8px 8px 12px; }
  .meter-col-head  { gap: 3px; font-size: 9px; padding-bottom: 6px; }
  .meter-flag-img  { height: 8px; width: 12px; }
  .meter-col-val   { font-size: 9px; padding-top: 5px; }
  .meter-brick     { min-height: 4px; }
}

/* ── Very small phones (≤390px) ── */
@media (max-width: 390px) {
  .clock-item      { min-width: 105px; }

  /* METER : ticker seul (le drapeau prend trop de place à 8 colonnes) */
  .meter-grid      { gap: 3px; padding: 6px 6px 10px; }
  .meter-col-head .meter-flag-img { display: none; }
  .meter-col-head  { font-size: 9px; }
  .meter-col-val   { font-size: 8px; }
  .clock-time      { font-size: 17px; letter-spacing: -0.03em; }

  .news-time       { display: none; }
  .news-item       { padding: 8px; }
  .news-headline   { font-size: 11px; }

  .right-tab       { font-size: 9px; padding: 0 6px; }

  /* Hide non-essential topbar icons on very small screens */
  .topbar-icon--notif { width: 22px; height: 22px; font-size: 12px; }
}

/* ── Touch improvements (all touch devices) ── */
@media (hover: none) and (pointer: coarse) {
  /* Larger tap targets */
  .nav-item        { min-height: 40px; display: flex; align-items: center; }
  .right-tab       { min-height: 30px; display: flex; align-items: center; }
  .pd-section-trigger { min-height: 48px; }
  .np-tab          { min-height: 36px; }
  .news-item       { min-height: 44px; }

  /* Remove hover effects that don't work on touch */
  .news-item:hover { background: inherit; }
  .clock-item:hover { background: inherit; }

  /* iOS : tout champ saisissable doit faire ≥16px sinon Safari ZOOME automatiquement
     au focus (et casse la mise en page). On force 16px sur les champs texte tactiles. */
  input[type="text"], input[type="email"], input[type="password"], input[type="search"],
  input:not([type]), textarea, select { font-size: 16px; }
}

/* ═══════════════════════════════════════════════════════════════
   Bank Research — Document Reader (PDF-like)
═══════════════════════════════════════════════════════════════ */

/* Loading state */
.br-doc-loading {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #888;
  font-size: 13px;
  padding: 40px 20px;
  justify-content: center;
}
.br-doc-spinner {
  width: 16px;
  height: 16px;
  border: 2px solid #333;
  border-top-color: var(--orange);
  border-radius: 50%;
  animation: br-spin 0.8s linear infinite;
  flex-shrink: 0;
}
@keyframes br-spin { to { transform: rotate(360deg); } }

/* Document wrapper — occupe tout l'espace disponible du reader */
.br-document {
  background: var(--bg2);            /* dark DTP (miroir de l'Analyst Viewer .arlib-rcontent) */
  color: #cfcfd4;
  width: 100%;
  max-width: 100%;        /* ← suppression de la limite 760px */
  margin: 0;
  padding: 40px 56px;
  min-height: 100%;
  font-family: 'Georgia', 'Times New Roman', serif;
  font-size: 15px;
  line-height: 1.7;
  box-sizing: border-box;
}

/* ── Header ING Think (logo + tagline) ── */
.br-ing-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}
.br-ing-logo svg text { line-height: 1; }
/* Logo DTP (rapports non-ING : ActionForex/FXStreet/agrégateurs) */
.br-dtp-logo { font-family: 'Arial Black', Arial, sans-serif; font-size: 22px; font-weight: 900; color: #e3b23a; letter-spacing: 0.02em; }
/* Vrai logo de la banque (image) dans l'en-tête du rapport — repli wordmark si indispo */
.br-bank-logo-wrap { display: inline-flex; align-items: center; }
.br-bank-logo { height: 24px; max-width: 104px; object-fit: contain; object-position: left center; vertical-align: middle; }
.br-ing-tagline {
  font-family: 'Arial', sans-serif;
  font-size: 13px;
  font-weight: var(--fw-bold);
  color: #e6e6ea;
  letter-spacing: 0.01em;
}
.br-ing-divider {
  width: 100%;
  height: 2px;
  background: var(--border);
  margin: 12px 0 20px;
}

/* ── Meta bar ── */
.br-ing-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 16px;
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  color: #888;
}
.br-ing-sep  { color: #44444c; }
.br-ing-date { color: #888; }
.br-ing-type { color: #888; }
.br-ing-country {
  margin-left: auto;
  font-size: 11px;
  font-weight: var(--fw-bold);
  letter-spacing: 0.1em;
  color: var(--orange-dim);
  text-transform: uppercase;
}

/* ── Lead paragraph / intro ── */
.br-ing-lead {
  font-size: 17px;
  font-weight: 400;
  color: #b9b9c2;
  line-height: 1.55;
  margin-bottom: 24px;
  font-style: italic;
  border-left: 3px solid var(--orange-dim);
  padding-left: 16px;
}

/* Document title */
.br-doc-title {
  font-family: 'Inter', 'Arial', sans-serif;
  font-size: 28px;
  font-weight: var(--fw-bold);
  color: #f2f2f4;
  line-height: 1.25;
  margin-bottom: 14px;
}

/* Horizontal divider under title */
.br-doc-divider {
  width: 100%;
  height: 1.5px;
  background: var(--border);
  margin: 14px 0;
}

/* Date */
.br-doc-date {
  font-family: 'Inter', sans-serif;
  font-size: 13px;
  color: #9a9aa2;
  margin-bottom: 8px;
}

/* Subtitle / intro */
.br-doc-subtitle {
  font-size: 17px;
  color: #b9b9c2;
  font-weight: var(--fw-medium);
  margin-bottom: 24px;
  line-height: 1.5;
}

/* Article body — reset to document style */
.br-doc-body {
  margin-top: 28px;
  color: #cfcfd4;
  overflow-wrap: anywhere;        /* coupe les mots/URLs trop longs → pas de débordement */
}
/* Tableaux : largeur contenue + scroll interne si vraiment large (jamais de débordement page) */
.br-doc-body table {
  width: 100%; max-width: 100%; border-collapse: collapse;
  display: block; overflow-x: auto; font-size: 12px; margin: 16px 0;
}
.br-doc-body th, .br-doc-body td { border: 1px solid var(--border); padding: 6px 9px; text-align: left; }
.br-doc-body th { background: var(--border); font-weight: var(--fw-bold); color: #e6e6ea; }
/* Images dans le body */
.br-doc-body img {
  max-width: 100%;
  height: auto;
  display: block;
  margin: 20px 0;
  border-radius: 4px;
}
.br-doc-body figure {
  margin: 20px 0;
}
.br-doc-body figcaption {
  font-size: 12px;
  color: #888;
  margin-top: 6px;
  font-style: italic;
  font-family: 'Inter', sans-serif;
}
.br-doc-body h1, .br-doc-body h2, .br-doc-body h3 {
  font-family: 'Inter', 'Arial', sans-serif;
  font-weight: var(--fw-bold);
  color: #f2f2f4;
  margin: 28px 0 12px;
  line-height: 1.3;
}
.br-doc-body h2 { font-size: 18px; }
.br-doc-body h3 { font-size: 15px; }
.br-doc-body p  {
  margin: 0 0 14px;
  color: #cfcfd4;
}
.br-doc-body strong, .br-doc-body b {
  font-weight: var(--fw-bold);
  color: #f2f2f4;
}

/* ── Rendu DTP : contenu structuré IA (source='ai') → titres de section ORANGE ──
   Scopé aux <strong> DIRECTS de .br-structured (jamais le gras inline d'un article brut). */
.br-doc-body.br-structured > strong {
  display: block;
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: var(--fw-bold);
  color: #e3b23a;                 /* orange signature (titres orange, façon Analyst Viewer) */
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin: 24px 0 9px;
  padding-top: 15px;
  border-top: 1px solid var(--border);
}
.br-doc-body.br-structured > strong:first-child {
  margin-top: 2px;
  padding-top: 0;
  border-top: none;
}
.br-doc-body a {
  color: var(--orange);
  text-decoration: underline;
}
.br-doc-body ul, .br-doc-body ol {
  padding-left: 20px;
  margin: 0 0 14px;
}
.br-doc-body li { margin-bottom: 6px; }
.br-doc-body blockquote {
  border-left: 3px solid var(--orange);
  margin: 16px 0;
  padding: 8px 16px;
  color: #b9b9c2;
  font-style: italic;
}
.br-doc-body table {
  width: 100%;
  border-collapse: collapse;
  margin: 16px 0;
  font-size: 13px;
}
.br-doc-body th {
  background: var(--border);
  padding: 8px 12px;
  text-align: left;
  font-weight: var(--fw-semibold);
  border: 1px solid var(--border);
}
.br-doc-body td {
  padding: 7px 12px;
  border: 1px solid var(--border);
}

/* Le pied de page d'un rapport d'institution et son bouton de sortie n'existaient que pour porter
   « Lire l'original → » vers le site de la banque (retire le 30/08). Plus aucun element ne les
   porte : on ne garde pas une regle qui ne peut plus s'appliquer, elle ferait croire au prochain
   lecteur qu'un pied de page existe encore. */

/* Placeholder — affiché quand aucun article n'est sélectionné */
.br-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  gap: 12px;
  color: #bbb;
  font-family: 'Inter', sans-serif;
  font-size: 13px;
  text-align: center;
  background: var(--bg, var(--bg));
  padding: 40px;
}
.br-placeholder svg { opacity: 0.25; }
.br-placeholder-label { opacity: 0.5; }

/* Empty state */
.br-document--empty {
  padding: 56px;
  text-align: center;
}
.br-no-content {
  color: #666;
  font-size: 14px;
  margin: 24px 0;
  font-family: 'Inter', sans-serif;
}

/* Zone de lecture — pleine largeur, scroll vertical */
#br-rcontent {
  background: #fff;      /* blanc puisque le document prend toute la place */
  padding: 0;
  overflow-y: auto;
  flex: 1;
  min-width: 0;
}

/* ═══════════════════════════════════════════════
   LIVE SQUAWK PANEL
═══════════════════════════════════════════════ */
.sqwk-overlay {
  /* démarre SOUS la topbar → les icônes (notif, profil) restent visibles ET cliquables */
  position: fixed; top: var(--topbar-h); left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.5); backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px);   /* rideau flouté comme les autres volets */
  opacity: 0; pointer-events: none; transition: opacity 0.22s; z-index: 1400;
}
.sqwk-overlay.open { opacity: 1; pointer-events: auto; }
.sqwk-panel {
  position: fixed; top: var(--topbar-h); right: 0; height: calc(var(--vph) - var(--topbar-h));
  width: 360px; max-width: 92vw;
  background: var(--bg); border-left: 1px solid var(--border);
  display: flex; flex-direction: column; z-index: 1401;
  transform: translateX(100%); transition: transform 0.26s ease;
  box-shadow: -10px 0 40px rgba(0,0,0,0.5);
}
.sqwk-panel.open { transform: translateX(0); }
.sqwk-header {
  display: flex; align-items: center; gap: 12px;
  padding: 16px 16px 14px; border-bottom: 1px solid var(--border); flex-shrink: 0;
}
.sqwk-title { white-space: nowrap; }   /* titre sur une seule ligne (plus aéré) */
/* Sous-barre dédiée : "Connexion automatique" + toggle → ne compresse plus le titre */
.sqwk-subbar {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 12px 16px; border-bottom: 1px solid var(--border); flex-shrink: 0;
  background: rgba(255,255,255,0.015);
}
.sqwk-subbar .sqwk-auto-lbl { font-size: 12px; color: var(--text2); }
.sqwk-play {
  width: 30px; height: 30px; flex-shrink: 0; border-radius: 50%;
  border: 1.5px solid #2ecc71; background: rgba(46,204,113,0.10); color: #2ecc71;
  font-size: 11px; cursor: pointer; display: flex; align-items: center; justify-content: center;
}
.sqwk-head-text { flex: 1; min-width: 0; }
.sqwk-title { font-size: 13px; font-weight: var(--fw-bold); color: #fff; }
.sqwk-status { font-size: 11px; color: #9ca3af; display: flex; align-items: center; gap: 5px; margin-top: 2px; }
.sqwk-dot { width: 6px; height: 6px; border-radius: 50%; background: #ef4444; display: inline-block; }
.sqwk-dot--live { background: #2ecc71; box-shadow: 0 0 6px rgba(46,204,113,0.7); }
.sqwk-auto { display: flex; flex-direction: column; align-items: flex-end; gap: 3px; }
.sqwk-auto-lbl { font-size: 9px; color: #6b7280; white-space: nowrap; }
.sqwk-toggle {
  width: 42px; height: 20px; border-radius: 11px; background: var(--border); cursor: pointer;
  position: relative; transition: background 0.15s;
}
.sqwk-toggle::after {
  content: ''; position: absolute; top: 2px; left: 2px; width: 16px; height: 16px;
  border-radius: 50%; background: #fff; transition: left 0.15s;
}
.sqwk-toggle.on { background: #e3b23a; }
.sqwk-toggle.on::after { left: 24px; }
.sqwk-toggle-state {
  position: absolute; top: 50%; transform: translateY(-50%); font-size: 8px; font-weight: var(--fw-bold);
  color: #fff; left: 6px; font-family: var(--font-mono);
}
.sqwk-toggle.on .sqwk-toggle-state { left: auto; right: 7px; color: var(--bg); }
.sqwk-close { background: none; border: none; color: #6b7280; font-size: 20px; cursor: pointer; line-height: 1; padding: 0 2px; }
.sqwk-close:hover { color: #fff; }
.sqwk-list { flex: 1; overflow-y: auto; }
.sqwk-empty { padding: 40px 18px; text-align: center; color: #555; font-size: 12px; }
.sqwk-row {
  display: flex; gap: 12px; align-items: flex-start;
  padding: 14px 16px; border-bottom: 1px solid rgba(23,23,23,0.6);
}
.sqwk-time {
  flex-shrink: 0; width: 64px; padding-top: 1px;
  color: #6b7280; font-family: var(--font-mono); font-size: 12px;
}
.sqwk-text { color: #d4d4d8; font-size: 13px; font-weight: 400; line-height: 1.6; word-break: break-word; }
.sqwk-footer { padding: 10px 14px; border-top: 1px solid var(--border); text-align: center; font-size: 10px; color: #555; flex-shrink: 0; }
.topbar-icon--active { color: #e3b23a !important; }

/* Volet ouvert (MESSAGERIE ou NOTIFICATIONS) → icône claire + trait vert dessous,
   aligné sur le bas du topbar (comme DataTradingPro). Scopé chat + cloche uniquement :
   le squawk (#sqwk-btn) garde sa couleur rouge/vert et n'a pas de trait. */
#chat-btn.topbar-icon--active,
#np-bell-btn.np-bell--active { color: #fff !important; }
/* Barre d'état actif (base) sous l'icône du volet ouvert */
#chat-btn.topbar-icon--active::after,
#np-bell-btn.np-bell--active::after,
#sqwk-btn.topbar-icon--active::after,
#ai-btn.topbar-icon--active::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -11px;
  transform: translateX(-50%);
  width: 18px;
  height: 2px;
  border-radius: 2px;
  pointer-events: none;
}
/* Couleurs sémantiques de la barre active */
/* Trait VERT pour les 4 icônes de volet (AI, Squawk, Notif, Messages) — uniforme */
#chat-btn.topbar-icon--active::after,
#np-bell-btn.np-bell--active::after,
#ai-btn.topbar-icon--active::after,
#sqwk-btn.topbar-icon--active::after { background: #22c55e; box-shadow: 0 0 7px rgba(34,197,94,0.55); }
@media (max-width: 480px) { .sqwk-panel { width: 100%; max-width: 100%; } }
.sqwk-audio { background: none; border: none; font-size: 15px; cursor: pointer; padding: 0 2px; line-height: 1; opacity: 0.9; }
.sqwk-audio--off { opacity: 0.4; filter: grayscale(1); }

/* Icône Squawk (topbar) : VERTE quand le flux est actif, ROUGE quand désactivé (off).
   Placé après .topbar-icon--active pour gagner la précédence (état = info principale). */
.topbar-icon--sqwk { color: #ef4444 !important; }            /* désactivé → rouge */
.topbar-icon--sqwk.sqwk-on { color: #22c55e !important; }     /* actif (auto OU live) → vert */

/* Squawk — état connecté : bouton STOP rouge */
.sqwk-play--live { border-color: #ef4444 !important; background: rgba(239,68,68,0.12) !important; color: #ef4444 !important; font-size: 12px; border-radius: 4px !important; }
/* Bandeau vert "Flux en direct connecté" */
.sqwk-live-note {
  display: flex; align-items: flex-start; gap: 8px;
  padding: 10px 14px; border-bottom: 1px solid var(--border);
  background: rgba(34,197,94,0.07); color: #4ade80;
  font-size: var(--fs-title); line-height: 1.5;
}
.sqwk-live-note.hidden { display: none; }
.sqwk-note-dot { width: 7px; height: 7px; border-radius: 50%; background: #22c55e; margin-top: 4px; flex-shrink: 0; box-shadow: 0 0 6px rgba(34,197,94,0.8); }
/* Texte des news : blanc cassé légèrement bleuté (façon DataTradingPro) */
.sqwk-text { color: #c9d1de; }

/* ═══════════════════════════════════════════════
   CHAT SUPPORT PANEL
═══════════════════════════════════════════════ */
.chat-overlay { position: fixed; top: var(--topbar-h); left:0; right:0; bottom:0; background: rgba(0,0,0,0.5); backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px); opacity:0; pointer-events:none; transition: opacity .22s; z-index: 1400; }   /* rideau flouté comme le volet IA → le dashboard ne transparaît plus net derrière */
.chat-overlay.open { opacity:1; pointer-events:auto; }
.chat-panel {
  position: fixed; top: var(--topbar-h); right: 0; height: calc(var(--vph) - var(--topbar-h));
  width: 420px; max-width: 94vw; background: var(--head-bg); border-left: 1px solid var(--border);
  display: flex; flex-direction: column; z-index: 1401;
  transform: translateX(100%); transition: transform .26s ease; box-shadow: -10px 0 40px rgba(0,0,0,0.5);
}
.chat-panel.open { transform: translateX(0); }
.chat-header { display:flex; align-items:center; gap: var(--sp-2); padding: var(--sp-3) var(--sp-4); border-bottom:1px solid var(--border); flex-shrink:0; background:#16171d; }   /* header un peu plus clair → l'avatar ressort */
.chat-support-av { width:42px; height:42px; border-radius:50%; background:#e7e9ee; color:var(--bg); font-weight:var(--fw-bold); font-size:13px; display:flex; align-items:center; justify-content:center; flex-shrink:0; overflow:hidden; box-shadow:0 0 0 2px rgba(255,255,255,.30); }   /* fond clair + anneau clair pour bien voir la photo */
/* CADRAGE DE LA PHOTO SUPPORT SUR LE VISAGE (26/08, demande utilisateur : « centre bien la bulle
   sur la personne »). La photo du desk est un plan LARGE : bureau, écrans, logo mural. Un simple
   `object-fit: cover` dans une pastille de 26 px centre au milieu du cadre — donc sur le torse, avec
   la tête coupée en haut. Et comme l'image est plus large que haute, `object-position` seul ne peut
   rien y faire : le recadrage de `cover` est HORIZONTAL, l'axe vertical est déjà entier.
   On serre donc autour du visage : `transform-origin` le désigne, `scale` s'y approche. Les deux
   valeurs sont des variables — un remplacement de photo se recadre en changeant deux nombres, à un
   seul endroit, sans toucher au JS.
   Une photo DÉJÀ CARRÉE et cadrée sur le visage (le mieux) se contente de `--sup-av-zoom: 1`. */
/* ZOOM À 1 (28/08). Ces variables serraient sur le visage d'une photo LARGE posée telle quelle.
   Depuis que la photo se recadre dans l'admin — cercle de placement, zoom, aperçu à la taille réelle
   — ce qui arrive ici est DÉJÀ un carré cadré sur le visage : re-zoomer par-dessus le grossirait une
   seconde fois et couperait le menton. Les variables restent : une photo posée autrement (fichier de
   marque déposé dans les assets) se recadre encore en changeant ces trois nombres, à un seul endroit. */
.chat-support-av, .chat-av { --sup-av-zoom: 1; --sup-av-x: 50%; --sup-av-y: 50%; }
.chat-support-av img, .chat-av img {
  width:100%; height:100%; object-fit:cover; border-radius:50%; display:block;
  transform: scale(var(--sup-av-zoom));
  transform-origin: var(--sup-av-x) var(--sup-av-y);
}
.chat-support-av.has-photo { background:#e7e9ee; }   /* fond clair derrière la photo support */
.chat-av.has-photo { background:#1a1c22; }
.chat-head-text { flex:1; min-width:0; }
.chat-head-name { font-size:13px; font-weight:var(--fw-bold); color:#fff; }
/* Pastille de statut À CÔTÉ DU NOM (conversation support) : vert = en ligne, gris = hors ligne */
.chat-name-dot { display:inline-block; width:8px; height:8px; border-radius:50%; margin-left:7px; vertical-align:middle; background:#5b6471; }
.chat-name-dot.is-online  { background:#22c55e; box-shadow:0 0 5px rgba(34,197,94,.6); }
.chat-name-dot.is-offline { background:#5b6471; box-shadow:none; }
.chat-head-sub { font-size:11px; color:#22c55e; margin-top:1px; }
/* Ligne dediee « Vous repondez en tant que support » (sous la presence, plus discrete) */
.chat-head-role2 { font-size:10.5px; color:var(--text3); margin-top:1px; line-height:1.2; }
.chat-close { background:none; border:none; color:#6b7280; font-size:20px; cursor:pointer; line-height:1; padding:0 2px; }
.chat-close:hover { color:#fff; }
.chat-back { background:none; border:none; color:#9aa4b2; font-size:24px; cursor:pointer; line-height:1; padding:0 4px 0 0; margin-right:2px; }
.chat-back:hover { color:#fff; }
.chat-head-sub { display:flex; align-items:center; min-width:0; }
.chat-presence { display:inline-block; width:7px; height:7px; border-radius:50%; background:#22c55e; margin-right:5px; box-shadow:0 0 0 2px rgba(34,197,94,.18); }
/* Badge présence de l'interlocuteur (en-tête conversation support) : point vert « En ligne » / gris « Hors ligne depuis X » */
.chat-head-dot { display:inline-block; width:8px; height:8px; border-radius:50%; margin-right:6px; flex-shrink:0; background:#5b6471; }
.chat-head-dot.is-online  { background:#22c55e; box-shadow:0 0 5px rgba(34,197,94,.6); }
.chat-head-dot.is-offline { background:#5b6471; box-shadow:none; }
.chat-head-st { white-space:nowrap; }
.chat-head-st.is-online  { color:#22c55e; }
.chat-head-st.is-offline { color:var(--text2); }
.chat-head-role { color:var(--text3); overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
/* Icônes pièces jointes + rendu images/fichiers */
.chat-attach { width:34px; height:38px; flex-shrink:0; border:none; background:none; color:var(--text2); cursor:pointer; display:flex; align-items:center; justify-content:center; border-radius:4px; }
.chat-attach:hover { color:#e2e8f0; background:rgba(255,255,255,.05); }
.chat-bubble--img { padding:4px !important; background:transparent !important; }
.chat-img { display:block; max-width:220px; max-height:240px; border-radius:10px; cursor:pointer; }
.chat-file { color:#8ab4f8; text-decoration:none; font-size:13px; }
.chat-file:hover { text-decoration:underline; }

/* ── Boîte de réception support (admin) ── */
.chat-thread { display:flex; align-items:center; gap:10px; padding:10px 8px; border-radius:4px; cursor:pointer; border:1px solid transparent; }
.chat-thread:hover { background:rgba(255,255,255,.04); border-color:rgba(255,255,255,.07); }
.chat-thread-av { width:34px; height:34px; border-radius:50%; background:#2a3340; color:#dfe6ef; font-weight:var(--fw-bold); font-size:13px; display:flex; align-items:center; justify-content:center; flex-shrink:0; }
.chat-thread-body { flex:1; min-width:0; }
.chat-thread-top { display:flex; align-items:center; gap:6px; }
.chat-thread-name { font-size:13px; font-weight:var(--fw-semibold); color:#e5e9ef; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.chat-thread-last { font-size:var(--fs-title); color:#7a8493; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.chat-thread-when { font-size:10px; color:#5b6471; flex-shrink:0; font-family:var(--font-mono); }
.chat-thread-badge { background:#ef4444; color:#fff; font-size:10px; font-weight:var(--fw-bold); border-radius:9px; padding:1px 6px; min-width:16px; text-align:center; }
.chat-thread--unread { background:rgba(227,178,58,.06); border-color:rgba(227,178,58,.18); }
.chat-thread--unread .chat-thread-name { color:#fff; }
.chat-thread--unread .chat-thread-last { color:#9aa4b2; }
/* Avatar rond avec point de présence (en ligne = vert, hors ligne = gris) */
.chat-thread-av { position:relative; }
.chat-presence-dot { position:absolute; right:-1px; bottom:-1px; width:11px; height:11px; border-radius:50%; background:#5b6471; border:2px solid var(--bg2); }
.chat-thread-av.is-online .chat-presence-dot { background:#22c55e; box-shadow:0 0 5px rgba(34,197,94,.6); }
/* Tag de rôle (admin / support) */
.chat-role-tag { font-size:9px; font-weight:var(--fw-bold); text-transform:uppercase; letter-spacing:.04em; color:#e3b23a; background:rgba(227,178,58,.14); border:1px solid rgba(227,178,58,.3); border-radius:4px; padding:1px 5px; flex-shrink:0; }
/* "Démarrer une conversation" (utilisateur sans message) */
.chat-thread-start { color:#6b7280; font-style:italic; }
/* Barre de recherche d'utilisateurs (inbox support) */
.chat-search-bar { display:flex; align-items:center; gap:8px; padding:8px 12px; border-bottom:1px solid var(--border); flex-shrink:0; }
.chat-search-ic { color:#6b7280; font-size:15px; flex-shrink:0; }
#chat-search-input { flex:1; background:var(--bg2); border:1px solid var(--border); border-radius:4px; padding:7px 11px; color:#e5e9ef; font-size:12px; outline:none; font-family:var(--font-ui); }
#chat-search-input:focus { border-color:rgba(227,178,58,.5); }
#chat-search-input::placeholder { color:#5b6471; }

.chat-list { flex:1; overflow-y:auto; overflow-x:hidden; overflow-anchor:none; padding:14px 14px 8px; display:flex; flex-direction:column; gap:10px; }   /* barre : globale (elle etait en #2a2f3a) */   /* overflow-anchor:none → le navigateur ne restaure pas tout seul la position (on la gère explicitement : entrée=haut, refresh=gardée) */
.chat-list::-webkit-scrollbar { width:7px; height:7px; }
.chat-list::-webkit-scrollbar-track { background:transparent; }
.chat-list::-webkit-scrollbar-thumb { background:#2a2f3a; border-radius:4px; border:2px solid transparent; background-clip:content-box; }
.chat-list::-webkit-scrollbar-thumb:hover { background:#3a4150; background-clip:content-box; }
.chat-thread-body { min-width:0; }
.chat-empty { margin:auto; text-align:center; color:#6b7280; font-size:13px; line-height:1.6; padding:30px 10px; }
.chat-date { display:flex; align-items:center; gap:10px; margin:16px 2px 8px; }
.chat-date::before, .chat-date::after { content:""; flex:1; height:1px; background:rgba(255,255,255,.07); }
.chat-date span { font-size:var(--fs-title); font-weight:var(--fw-semibold); color:#aeb6c2; letter-spacing:.2px; background:rgba(255,255,255,.05); border:1px solid rgba(255,255,255,.06); padding:3px 11px; border-radius:11px; white-space:nowrap; }
.chat-date span::first-letter { text-transform:uppercase; }
.chat-row { display:flex; align-items:flex-end; gap:8px; max-width:100%; }
.chat-row--me { justify-content:flex-end; }
.chat-av { width:26px; height:26px; border-radius:50%; background:#1f2a44; color:#8ab4f8; font-size:9px; font-weight:var(--fw-bold); display:flex; align-items:center; justify-content:center; flex-shrink:0; overflow:hidden; }
.chat-bubble { max-width:74%; padding:9px 12px; border-radius:12px; font-size:13px; line-height:1.5; position:relative; }
.chat-row--them .chat-bubble { background:#15161a; color:#e2e8f0; border-bottom-left-radius:4px; }   /* neutre HUD (fini le bleu) — cohérent avec le chat IA */
.chat-row--me   .chat-bubble { background:#1c1c1f; color:#e9eaed; border-bottom-right-radius:4px; }   /* même gris que la bulle user du chat IA */
.chat-text { white-space:pre-wrap; word-break:break-word; }
.chat-meta { font-size:10px; color:var(--text2); margin-top:4px; }
.chat-row--me .chat-meta { text-align:right; }

/* Indicateur « est en train d'écrire… » */
.chat-typing { display:flex; align-items:center; gap:7px; margin-top:2px; padding-left:4px; animation:chatTypingIn .2s ease; }
@keyframes chatTypingIn { from { opacity:0; transform:translateY(4px); } to { opacity:1; transform:none; } }
.chat-typing-text { font-size:var(--fs-title); color:#6b7280; font-style:italic; }
.chat-typing-dots { display:inline-flex; gap:3px; }
.chat-typing-dots i { width:4px; height:4px; border-radius:50%; background:#6b7280; display:inline-block; animation:chatDot 1.2s infinite ease-in-out; }
.chat-typing-dots i:nth-child(2) { animation-delay:.2s; }
.chat-typing-dots i:nth-child(3) { animation-delay:.4s; }
@keyframes chatDot { 0%,60%,100% { opacity:.3; transform:translateY(0); } 30% { opacity:1; transform:translateY(-3px); } }

/* ── Bulle + menu ⋯ + barre de réactions ── */
.chat-bubble-wrap { display:flex; flex-direction:column; max-width:84%; min-width:0; }
.chat-row--me   .chat-bubble-wrap { align-items:flex-end; }
.chat-row--them .chat-bubble-wrap { align-items:flex-start; }
.chat-bubble-wrap .chat-bubble { max-width:100%; }
.chat-bubble-row { display:flex; align-items:center; gap:4px; max-width:100%; min-width:0; }
.chat-row--me .chat-bubble-row { flex-direction:row-reverse; }   /* ⋯ à gauche de MA bulle */

/* Menu ⋯ (modifier / supprimer) — séparé des réactions */
.chat-msg-menu { position:relative; flex-shrink:0; }
.chat-menu-btn { background:none; border:none; cursor:pointer; color:#7a8493; font-size:17px; line-height:1; padding:2px 5px; border-radius:4px; opacity:0; transition:opacity .14s, background .12s, color .12s; }
.chat-row:hover .chat-menu-btn { opacity:.8; }
.chat-menu-btn:hover { opacity:1; color:#e8eaed; background:rgba(255,255,255,.08); }
/* Menu INLINE (sous le message) — jamais coupé par l'overflow, responsive */
.chat-menu-inline { display:flex; gap:6px; margin-top:5px; animation:chatTypingIn .14s ease; }
.chat-menu-inline button { display:flex; align-items:center; gap:6px; background:#1a1c22; border:1px solid #2a2f3a; border-radius:4px; cursor:pointer; color:#cdd3dc; font-size:12px; font-weight:var(--fw-semibold); font-family:var(--font-ui); padding:6px 12px; transition:background .12s, color .12s, border-color .12s; }
.chat-menu-inline button:hover { background:rgba(255,255,255,.06); color:#fff; }
.chat-menu-i-del:hover { background:rgba(239,68,68,.14); color:#ef4444; border-color:rgba(239,68,68,.4); }

/* Barre de réactions au-dessus du "Lu" : posées = toujours visibles ; vides = au survol (discret) */
/* Sélecteur flottant — SOUS la bulle, apparaît au survol de toute la ligne (stable, on a le temps de viser) */
/* Picker EN BAS de la bulle (jamais au-dessus) → ne déborde plus en haut sur la date du 1er message.
   Pour les messages reçus (.chat-row--them) il est ancré à GAUCHE, les pastilles posées étant en bas
   à DROITE → pas de chevauchement. */
.chat-react-picker { position:absolute; bottom:calc(100% + 3px); top:auto; z-index:6; display:flex; gap:1px; background:#15171d; border:1px solid #2a2f3a; border-radius:14px; padding:2px 4px; box-shadow:0 6px 18px rgba(0,0,0,.5); opacity:0; pointer-events:none; transform:translateY(4px); transition:opacity .16s ease, transform .16s ease; transition-delay:.04s; }   /* AU-DESSUS de la bulle (était dessous → sur le dernier message en bas il débordait du chat et chevauchait l'heure) */
.chat-row--them .chat-react-picker { left:6px; }
.chat-row--me   .chat-react-picker { right:6px; }
.chat-row:hover .chat-react-picker, .chat-react-picker:hover { opacity:1; pointer-events:auto; transform:translateY(0); transition-delay:0s; }
/* Taille alignée sur la pastille de réaction posée (compacte) */
.chat-react-picker button { background:none; border:none; cursor:pointer; font-size:13px; line-height:1; width:22px; height:22px; display:flex; align-items:center; justify-content:center; border-radius:50%; transition:transform .12s ease, background .12s ease; }
.chat-react-picker button:hover { transform:scale(1.15); background:rgba(255,255,255,.07); }
/* Pastilles posées (façon LinkedIn) — sous la bulle, alignées côté bulle */
/* Réactions POSÉES : ancrées en BAS À DROITE de la bulle (débord façon Messenger), jamais au-dessus */
.chat-reactions { position:absolute; bottom:-10px; right:14px; z-index:10; display:flex; gap:4px; flex-wrap:wrap; }
.chat-reactions:empty { display:none; }
/* Quand une bulle a des réactions, on pousse l'heure plus bas pour qu'elle ne chevauche pas les emojis */
.chat-bubble-wrap:has(.chat-reactions:not(:empty)) .chat-meta { margin-top:14px; }
.chat-reaction-pill { display:inline-flex; align-items:center; gap:3px; background:#1a1d25; border:1px solid #2a2f3a; border-radius:13px; padding:1px 8px; font-size:13px; line-height:1.5; cursor:pointer; transition:border-color .12s, background .12s; }
.chat-reaction-pill:hover { border-color:#3a4150; }
.chat-reaction-pill.mine { background:rgba(227,178,58,.16); border-color:rgba(227,178,58,.55); }
.chat-reaction-pill .n { font-size:11px; font-weight:var(--fw-bold); color:#cdd3dc; font-family:var(--font-mono); }
.chat-reaction-pill.mine .n { color:#e3b23a; }
/* Icônes de réaction façon LinkedIn : badge rond plat + glyphe blanc (bleu J'aime, rouge Cœur) */
.react-ic { display:inline-flex; align-items:center; justify-content:center; width:16px; height:16px; flex-shrink:0; }
.react-ic svg { width:14px; height:14px; display:block; }
/* Icônes PLATES colorées — plus de disque/cercle autour de la réaction */
.react-ic--like svg path { fill:#e3b23a; }   /* pouce orange signature DTP */
.react-ic--love svg path { fill:#ef4444; }   /* coeur rouge du site */
.chat-retry-btn { background:none; border:none; color:#e3b23a; cursor:pointer; font:inherit; text-decoration:underline; padding:0; }
.chat-reaction-pill { gap:4px; }   /* badge + compteur bien espacés */

/* Confirmation de suppression INLINE — juste les options, compacte (sans phrase) */
.chat-del-confirm { display:flex; align-items:center; gap:6px; margin-top:4px; animation:chatTypingIn .15s ease; }
.chat-del-confirm button { border:none; border-radius:7px; padding:4px 13px; font-size:11px; font-weight:var(--fw-semibold); cursor:pointer; font-family:var(--font-ui); }
.chat-del-yes { background:rgba(239,68,68,.16); color:#ef4444; }
.chat-del-yes:hover { background:rgba(239,68,68,.3); }
.chat-del-no { background:#1a1c22; color:#9aa4b2; border:1px solid #262b36; }
.chat-del-no:hover { color:#e8eaed; }

/* Édition INLINE — responsive et épurée */
.chat-edit-box { margin-top:6px; width:100%; max-width:min(340px, 78vw); }
.chat-edit-input { width:100%; min-height:40px; resize:vertical; background:#0d0f13; border:1px solid #2a2f3a; border-radius:9px; padding:8px 11px; color:#e8eaed; font-size:13px; line-height:1.45; font-family:var(--font-ui); outline:none; box-sizing:border-box; }
.chat-edit-input:focus { border-color:rgba(227,178,58,.55); }
.chat-edit-btns { display:flex; gap:7px; margin-top:6px; }
.chat-edit-btns button { border:none; border-radius:7px; padding:6px 14px; font-size:12px; font-weight:var(--fw-semibold); cursor:pointer; font-family:var(--font-ui); transition:background .12s, color .12s; }
.chat-edit-save { background:#e3b23a; color:var(--bg); }
.chat-edit-save:hover { background:#f0c44a; }
.chat-edit-cancel { background:#1a1c22; color:#9aa4b2; }
.chat-edit-cancel:hover { color:#e8eaed; }

/* ── Aperçu d'images avant envoi (jusqu'à 5, alignées, croix pour retirer) ── */
.chat-pending { display:none; flex-shrink:0; padding:9px 12px; border-top:1px solid var(--border); background:#0c0e12; }
.chat-pending.visible { display:block; animation:chatTypingIn .18s ease; }
.chat-pending-card { display:flex; flex-direction:column; gap:8px; }
.chat-pending-thumbs { display:flex; gap:8px; flex-wrap:wrap; }
.chat-pending-item { position:relative; width:54px; height:54px; flex-shrink:0; }
.chat-pending-item img { width:100%; height:100%; object-fit:cover; border-radius:4px; border:1px solid #262b36; }
.chat-pending-x { position:absolute; top:-6px; right:-6px; width:18px; height:18px; border-radius:50%; border:none; background:#15171d; color:#cdd3dc; font-size:13px; line-height:1; cursor:pointer; display:flex; align-items:center; justify-content:center; box-shadow:0 1px 4px rgba(0,0,0,.55); transition:background .12s, color .12s; }
.chat-pending-x:hover { background:#ef4444; color:#fff; }
.chat-pending-foot { display:flex; align-items:center; justify-content:flex-end; gap:10px; }
.chat-pending-count { font-size:var(--fs-title); color:#7a8493; }
.chat-pending-btns { display:flex; gap:6px; flex-shrink:0; }
.chat-pending-cancel, .chat-pending-send { border:none; border-radius:7px; padding:7px 13px; font-size:12px; font-weight:var(--fw-semibold); cursor:pointer; font-family:var(--font-ui); transition:background .12s, color .12s; }
.chat-pending-cancel { background:#1a1c22; color:#9aa4b2; border:1px solid #262b36; }
.chat-pending-cancel:hover { color:#e8eaed; border-color:#3a4150; }
.chat-pending-send { background:#e3b23a; color:var(--bg); }
.chat-pending-send:hover { background:#f0c44a; }

/* ── Compteur d'utilisateurs en ligne (à droite de la recherche) ── */
.chat-online-count { align-items:center; gap:5px; flex-shrink:0; padding:3px 9px; border-radius:20px; background:rgba(34,197,94,.1); border:1px solid rgba(34,197,94,.28); color:#22c55e; font-size:var(--fs-title); font-weight:var(--fw-bold); font-family:var(--font-mono); }
.chat-online-dot { width:7px; height:7px; border-radius:50%; background:#22c55e; box-shadow:0 0 5px rgba(34,197,94,.6); flex-shrink:0; }

/* ── Lightbox image (dans le panneau chat — clic sur le fond pour revenir) ── */
.chat-lightbox { position:absolute; inset:0; z-index:60; display:none; align-items:center; justify-content:center; background:rgba(0,0,0,.85); backdrop-filter:blur(3px); cursor:zoom-out; padding:24px; }
.chat-lightbox.visible { display:flex; animation:chatTypingIn .15s ease; }
.chat-lightbox img { max-width:100%; max-height:100%; border-radius:10px; box-shadow:0 14px 54px rgba(0,0,0,.65); cursor:default; }

.chat-input-bar { display:flex; align-items:flex-end; gap: var(--sp-2); padding: var(--sp-2) var(--sp-3) var(--sp-1); border-top:1px solid var(--border); flex-shrink:0; }
.chat-input { flex:1; resize:none; background:var(--bg2); border:1px solid var(--border); border-radius:var(--r-2); padding:9px 12px; color:var(--text); font-size:13px; font-family:var(--font-ui); outline:none; max-height:90px; }
.chat-input::placeholder { color:#6b7280; }
.chat-input:focus { border-color:var(--orange); box-shadow:0 0 0 2px rgba(227,178,58,0.16); }
.chat-send { width:38px; height:38px; flex-shrink:0; border:none; border-radius:4px; background:#e3b23a; color:var(--bg); cursor:pointer; display:flex; align-items:center; justify-content:center; }
.chat-send:hover { filter:brightness(1.08); }
.chat-hint { padding:2px 14px 10px; font-size:10px; color:#5b6471; flex-shrink:0; }
@media (max-width:480px){ .chat-panel { width:100%; max-width:100%; } }

/* ═══ FX LIST — Overview table ═══════════════════════════════════ */
.fxl-wrap { display: flex; flex-direction: column; flex: 1 1 auto; height: 100%; width: 100%; min-width: 0; background: var(--bg1); position: relative; border-radius: 0; box-shadow: var(--panel-depth); }
/* Loader centré dans la zone VISIBLE (overlay, pas dans la table large 1240px) */
.fxl-loader { position: absolute; inset: var(--toolbar-h) 0 0 0; display: flex; align-items: center; justify-content: center; background: var(--bg1); z-index: 5; }
/* Apparence héritée de .chart-header ; ici on ne garde que la répartition et le non-rétrécissement. */
.fxl-toolbar { display: flex; align-items: center; justify-content: space-between; flex: 0 0 auto; }
/* .fxl-title est un .chart-header-title : sa typographie vient de là. */
.fxl-title-sep, .fxl-title-tag { color: var(--orange); font-weight: var(--fw-bold); }   /* séparateur | et [Forex] en or vif */
.fxl-toolbar-right { display: flex; align-items: center; gap: 10px; }
.fxl-updated { font-size: 10px; color: var(--text3); font-family: var(--font-mono); }
.fxl-refresh {
  background: var(--bg3); border: 1px solid var(--border2); color: var(--text2);
  border-radius: var(--radius); width: 24px; height: 24px; cursor: pointer; font-size: 13px; line-height: 1;
}
.fxl-refresh:hover { color: var(--orange); border-color: var(--orange-dim); }

.fxl-table-scroll { flex: 1 1 auto; min-width: 0; overflow: auto; position: relative; }
/* Scrollbars fines & minimalistes (gauche/droite + haut/bas) */
/* .fxl-table-scroll : barre globale (elle etait en #2c2c33). */
.fxl-table-scroll::-webkit-scrollbar { width: 8px; height: 8px; }
.fxl-table-scroll::-webkit-scrollbar-track { background: transparent; }
.fxl-table-scroll::-webkit-scrollbar-thumb { background: #2c2c33; border-radius: 4px; border: 2px solid transparent; background-clip: content-box; }
.fxl-table-scroll::-webkit-scrollbar-thumb:hover { background: #3d3d46; background-clip: content-box; }
.fxl-table-scroll::-webkit-scrollbar-corner { background: transparent; }
.fxl-table { width: 100%; min-width: 1240px; border-collapse: collapse; font-family: var(--font-mono); font-size: 11px; }

.fxl-th {
  position: sticky; top: 0; z-index: 2; background: var(--head-bg);
  color: var(--text); font-weight: var(--fw-semibold); font-size: 11px; letter-spacing: var(--ls-caps); text-transform: uppercase;
  padding: 9px 12px; border-bottom: 1px solid var(--hud-line); border-right: none; white-space: nowrap;
}
.fxl-th:last-child, .fxl-td:last-child { border-right: none; }
/* Freeze the Symbol column while scrolling horizontally */
.fxl-th--left { left: 0; z-index: 3; text-align: left; background: var(--head-bg); }
.fxl-td--left { position: sticky; left: 0; z-index: 1; background: var(--bg1); }
.fxl-th--right { text-align: right; }
.fxl-th--center { text-align: center; }
.fxl-th--sortable { cursor: pointer; user-select: none; }
.fxl-th--sortable:hover { color: var(--orange, #e3b23a); }
.fxl-sort { color: #565b63; margin-left: 4px; font-size: 9px; }
.fxl-sort.active { color: var(--orange); }

.fxl-row { border-bottom: var(--row-sep); transition: background var(--t-fast) ease; }   /* filet subtil unifie ; transition douce pour la surbrillance active */
.fxl-row.active { background: rgba(227,178,58,0.06); }    /* pas de hover:bg → scan stable ; surbrillance SEULEMENT si actif */
.fxl-td { padding: var(--sp-15) var(--sp-3); white-space: nowrap; vertical-align: middle; color: var(--text); border-right: none; border-radius: 0; }
.fxl-td--right { text-align: right; }
.fxl-td--center { text-align: center; }
.fxl-td--heat { padding: 0; }   /* la cellule heatmap remplit tout l'espace (couleur edge-to-edge) */

.fxl-sym { display: flex; align-items: center; gap: 8px; }
.fxl-flag { width: 16px; height: 16px; border-radius: 50%; object-fit: cover; flex: 0 0 auto; box-shadow: 0 0 0 1px rgba(255,255,255,0.08); }   /* drapeau rond w-4 h-4 */
.fxl-flag--ph { background: var(--bg4); display: inline-block; }
.fxl-sym-txt { font-weight: var(--fw-semibold); color: var(--text); font-size: 12px; letter-spacing: .02em; }   /* paire en capitales, blanc cassé */

.fxl-last { display: flex; align-items: center; justify-content: center; }
.fxl-spark { display: block; }

/* CHANGE % — texte simple, sans fond (N/A gris foncé si absent) */
.fxl-na  { color: var(--text4); font-weight: var(--fw-medium); }
.fxl-chg { font-size: 11px; font-weight: var(--fw-semibold); }
.fxl-chg--pos { color: #00cc99; }
.fxl-chg--neg { color: #ff3d00; }

/* Heatmap Cell (1M/3M/12M) : bloc plein edge-to-edge, sans arrondi (fond rgba inline ∝ |%|) */
.fxl-pct { display: block; box-sizing: border-box; text-align: right; padding: 8px 12px; border-radius: 0; font-family: var(--font-mono); font-size: 11px; font-weight: var(--fw-bold); }
.fxl-pct--pos { color: #00e676; }   /* vert charte sur fond vert sombre */
.fxl-pct--neg { color: #ff3d00; }   /* rouge charte sur fond rouge sombre */

/* PATTERN — micro-matrice de carrés (allumés blanc / éteints gris très sombre) */
.fxl-pat { display: inline-flex; gap: 3px; align-items: center; justify-content: center; }
.fxl-pat-sq { width: 5px; height: 5px; border-radius: 1px; background: var(--bg2); box-shadow: inset 0 0 0 1px var(--bg2); }
.fxl-pat-sq.on { background: #eef0f3; box-shadow: 0 0 3px rgba(255,255,255,0.45); }

/* STRENGTH — vumètre horizontal ultra-fin (2px), remplissage depuis la gauche, turquoise / fuchsia */
.fxl-str { display: flex; justify-content: flex-start; align-items: center; padding: 0 4px; }
.fxl-str-track { position: relative; width: 100%; max-width: 130px; height: 2px; background: var(--bg2); border-radius: 0; overflow: hidden; }
.fxl-str-bar { position: absolute; top: 0; left: 0; height: 100%; border-radius: 0; }
.fxl-str-bar--pos { background: #00cc99; }
.fxl-str-bar--neg { background: #ff3d00; }

.fxl-dmx { display: block; margin: 0 auto; }

/* Micro-badges FUND./RESEARCH/BIAS — bords à peine adoucis (3px), codes couleurs sémantiques discrets */
.fxl-badge {
  display: inline-block; min-width: 64px; padding: 4px 10px; border-radius: var(--r-2);
  font-size: 11px; font-weight: var(--fw-semibold); text-align: center; letter-spacing: .01em;
}
.fxl-badge--bull { color: #00e676; background: #0d2a1d; }   /* BUY sur vert foncé mat */
.fxl-badge--neut { color: #ffb300; background: #221d12; }   /* NEUTRE (charte) sur anthracite brun */
.fxl-badge--na   { color: #5c5c66; background: #131316; }   /* donnée MANQUANTE (« — ») ≠ Neutre : gris éteint, honnête */
.fxl-badge--bear { color: #ff3d00; background: #2a1512; }   /* SELL sur marron brique */

.fxl-msg { text-align: center; color: var(--text3); padding: 30px; }

/* (Élasticité par container-query retirée : provoquait l'effondrement de .fxl-wrap.
   La table large défile horizontalement quand le volet est étroit — comportement sûr.) */

/* ════════════════════ MACRO AI ASSISTANT (chat IA) ════════════════════ */
/* Rideau flouté : commence SOUS la topbar (icônes d'onglets restent nettes & cliquables) ;
   floute + assombrit le dashboard derrière, sans recouvrir la navbar. */
.ai-backdrop { position: fixed; inset: var(--topbar-h) 0 0 0; background: rgba(0,0,0,0.5); backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px); z-index: 1399; opacity: 0; pointer-events: none; transition: opacity .22s; }
.ai-backdrop.open { opacity: 1; pointer-events: auto; }
.ai-panel {
  position: fixed; top: var(--topbar-h); right: 0; height: calc(var(--vph) - var(--topbar-h)); width: 430px; max-width: var(--vpw);
  background: var(--bg); z-index: 1401; display: flex; flex-direction: column;   /* sous la navbar → icônes d'onglets toujours cliquables */
  transform: translateX(100%); transition: transform .24s cubic-bezier(.2,.8,.2,1);
  border-left: 1px solid var(--border); border-radius: 0;
}
/* ── TAUX — taux directeurs des banques centrales (admin) ──────────────── */
.panel-taux { padding: 0; display: flex; flex-direction: column; width: 100%; height: 100%; flex: 1 1 auto; min-width: 0; }
.panel-taux .panel-header { flex: 0 0 auto; }
/* Légende du code couleur (Hausse / Maintien / Baisse) + rappel « estimation maison » */
.taux-legend { display: inline-flex; align-items: center; gap: 13px; margin-left: 14px; font-size: 10px; color: var(--text2); white-space: nowrap; }
.taux-legend .tlg { display: inline-flex; align-items: center; gap: 5px; }
.taux-legend .tlg i { width: 8px; height: 8px; border-radius: 2px; flex: 0 0 auto; }
.taux-legend .tlg i.g { background: #00e676; }
.taux-legend .tlg i.n { background: #abb4c3; }
.taux-legend .tlg i.r { background: #ff3d00; }
.taux-legend .tlg-note { color: var(--text3); font-style: italic; padding-left: 11px; border-left: 1px solid var(--border); }
@media (max-width: 1240px) { .taux-legend .tlg-note { display: none; } }
@media (max-width: 980px)  { .taux-legend { display: none; } }
.taux-wrap { overflow-x: auto; }
.taux-table { width: 100%; border-collapse: collapse; font-size: 12px; }
.taux-table thead th { position: sticky; top: 0; background: var(--head-bg); color: var(--text2); font-weight: var(--fw-semibold); text-align: left; padding: var(--sp-15) var(--sp-4); border-bottom: 1px solid var(--border); font-size: 10px; text-transform: uppercase; letter-spacing: .05em; white-space: nowrap; z-index: 1; }
.taux-table tbody td { padding: var(--sp-15) var(--sp-4); border-bottom: var(--row-sep); vertical-align: middle; }
.taux-table tbody tr:hover { background: var(--row-hover); }   /* hover sobre neutre unifie sur la ligne de news */
.taux-bank { display: flex; align-items: center; gap: 10px; min-width: 190px; }
.taux-flag { width: 26px; height: 20px; object-fit: cover; border-radius: 3px; flex: 0 0 auto; border: 1px solid var(--border); }
.taux-bank span { display: flex; flex-direction: column; line-height: 1.25; }
.taux-bank b { color: #f0f0f2; font-weight: var(--fw-bold); font-size: 13px; }
.taux-bank i { color: #6f6f78; font-style: normal; font-size: 11px; }
.taux-rate { font-family: var(--mono, ui-monospace, monospace); font-weight: var(--fw-bold); color: #f0f0f2; font-size: 14px; white-space: nowrap; }
.taux-last { font-family: var(--mono, ui-monospace, monospace); white-space: nowrap; font-size: 12px; }
.taux-last i { display: block; color: #6f6f78; font-style: normal; font-size: 10px; margin-top: 1px; }
.taux-next { font-family: var(--mono, ui-monospace, monospace); color: #cfcfd4; white-space: nowrap; }
.taux-badge { display: inline-flex; align-items: center; gap: 5px; padding: 3px 9px; border-radius: 4px; font-weight: var(--fw-bold); font-size: var(--fs-title); white-space: nowrap; border: 1px solid transparent; }
.taux-badge.g { color: #00e676; background: rgba(0,230,118,.1); border-color: rgba(0,230,118,.28); }
.taux-badge.r { color: #ff3d00; background: rgba(255,61,0,.12); border-color: rgba(255,61,0,.3); }
.taux-badge.n { color: #ffb300; background: rgba(255,179,0,.1); border-color: rgba(255,179,0,.28); }
.taux-last.g { color: #00e676; }
.taux-last.r { color: #ff3d00; }
.taux-last.n { color: #9a9aa2; }
.taux-bias { color: #a6a6ad; max-width: 380px; font-size: 12px; line-height: 1.45; }
.taux-loading, .taux-empty { display: flex; flex-direction: column; align-items: center; justify-content: center; min-height: 60vh; text-align: center; color: var(--text3); }   /* spinner CENTRÉ dans le panneau (était collé en haut) */
/* ── TAUX : grille 4 colonnes haute densité (cartes "Interest Rate Probability", estimation maison) ── */
/* REFONTE TAUX (demande user « mieux, compréhensible, bien lisible ») : fini le monobloc 4×2 étiré qui créait
   un GRAND VIDE dans chaque carte (cellules étirées à la hauteur de l'écran, .rtc-dist absorbait tout l'espace).
   → cartes LARGES (≥560px, 2-3 colonnes selon l'écran) à HAUTEUR NATURELLE + scroll : tableaux lisibles, zéro vide. */
/* 8 banques → rangées TOUJOURS pleines (demande user « les 4 alignés ») : uniquement 4 / 2 / 1 colonnes
   (3 ne divise jamais 8 → rangée orpheline). 4-up ≥1680px avec compaction lisible ; 2-up intermédiaire (cartes
   larges ≥560px) ; 1 colonne mobile. */
/* Rangées ÉTIRÉES à la page (demande user « exploite toute la page, vide en bas ») : minmax(max-content,1fr)
   → jamais moins que le contenu, et tout surplus de hauteur est partagé entre les rangées. La hauteur gagnée
   est absorbée par le TABLEAU DES RÉUNIONS de chaque carte (flex-basis 168px + grow, cf. .rtc-tblwrap) :
   grand écran = plus de dates de réunion visibles, zéro vide. */
.taux-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); grid-auto-rows: minmax(max-content, 1fr); gap: 10px; padding: 10px; overflow-y: auto; align-content: stretch; flex: 1 1 auto; min-height: 0; }
@media (max-width: 1679px) { .taux-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 1149px) { .taux-grid { grid-template-columns: 1fr; } }
/* Compaction 4-up (cartes ~400-470px) : tout reste lisible — libellés/valeurs/tableau resserrés d'un cran */
@media (min-width: 1680px) {
  .rtc-m { padding: 5px 7px 20px; min-height: 58px; }
  .rtc-k { font-size: 9.5px; }
  .rtc-v { font-size: 11px; }
  .rtc-tbl { font-size: 10.5px; }
  .rtc-tbl th { font-size: 9.5px; padding: var(--sp-1) 4px; }
  .rtc-tbl td { padding: var(--sp-05) 4px; }
  .rtc-pill { min-width: 56px; padding: 2px 4px; font-size: 9.5px; }
  .rtc-base { min-width: 34px; padding: 2px 5px; }
  .rtc-bp { width: 46px; }
  .rtc-axis { padding: 2px 53px 0 39px; }
}
/* ── Carte « Interest Rate Probability » — clone fidèle haute densité (angles carrés, terminologie EN) ── */
.rtc { background: var(--bg); border: 1px solid var(--border); border-radius: var(--radius); box-shadow: var(--panel-depth); display: flex; flex-direction: column; overflow: hidden; min-height: 0; transition: border-color var(--t-fast) ease; }
.rtc:hover { border-color: rgba(227,178,58,0.20); }
.rtc-head { display: flex; align-items: center; gap: 8px; min-height: 31px; padding: 0 10px; background: var(--head-bg); border-bottom: 1px solid var(--border); flex: 0 0 auto; }
.rtc-flag { width: 17px; height: 17px; object-fit: cover; border-radius: 50%; border: 1px solid var(--border); flex: 0 0 auto; }
.rtc-bank { font-size: 12px; font-weight: var(--fw-bold); color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
/* ── Bandeau 5 métriques (Next Move · Probability · Expected Δ · Current Rate · Meeting Date)
      avec sparkline ultra-fine EN FOND bas-droite de cellule (clone pro) ── */
/* Bandeau 5 métriques (clone pro) : chaque cellule bordée porte SA mini-courbe décorative
   calée bas-droite DERRIÈRE le texte (z-0), libellé pouvant passer sur 2 lignes. */
.rtc-metrics { display: grid; grid-template-columns: repeat(5, 1fr); border-bottom: 1px solid var(--bg2); flex: 0 0 auto; }
.rtc-m { position: relative; overflow: hidden; display: flex; flex-direction: column; gap: 3px; padding: 6px 9px 28px; border-right: 1px solid var(--bg2); min-width: 0; min-height: 70px; justify-content: flex-start; }   /* padding-bas 22→28 = bande sparkline agrandie (23/08), le texte ne passe toujours pas dessus */
.rtc-m:last-child { border-right: 0; }
.rtc-k { position: relative; z-index: 1; font-size: 10px; letter-spacing: .02em; color: #aab3bf; line-height: 1.25; }   /* libellés éclaircis + agrandis (lisibilité) */
.rtc-v { position: relative; z-index: 1; font-size: var(--fs-title); font-weight: var(--fw-bold); color: var(--text); font-family: var(--mono, ui-monospace, monospace); white-space: nowrap; }
.rtc-v.g { color: #00e676; } .rtc-v.r { color: #ff3d00; } .rtc-v.n { color: var(--text2); } .rtc-v.w { color: var(--text); }
.rtc-prob { color: var(--orange); }   /* Probability = or (clone pro text-primary) */
/* La courbe COMBLE le bas de la cellule : étirée sur toute la largeur (preserveAspectRatio none), ~45% de hauteur */
.rtc-msp { position: absolute; left: 5px; right: 5px; bottom: 3px; width: auto; height: 22px; max-height: 22px; z-index: 0; opacity: .95; pointer-events: none; }   /* 15→22px + opacité .8→.95 (23/08, demande user : courbes quasi invisibles — le viewBox 28 écrasé à 15px rendait un trait de ~0,8px) */
/* ── Scenario Distribution : OCCUPE l'espace libre entre métriques et tableau (plus de vide noir),
      contenu centré verticalement, barres épaisses rounded-sm, % à droite de la barre ── */
.rtc-dist { display: flex; flex-direction: column; gap: 6px; padding: 9px 10px 8px; flex: 0 0 auto; }   /* COLLÉE sous les métriques (l'ancien flex:1 + centré créait le grand vide) */
.rtc-dist-h { font-size: 10px; letter-spacing: var(--ls-caps); text-transform: uppercase; color: var(--text2); margin-bottom: 2px; font-weight: var(--fw-semibold); }
.rtc-bar { display: flex; align-items: center; gap: 7px; font-size: 11px; }
.rtc-bl { width: 32px; color: var(--text2); flex: 0 0 auto; }
.rtc-track { flex: 1; height: 20px; background: rgba(255,255,255,0.03); border-radius: 2px; }
.rtc-track i { display: block; height: 100%; border-radius: 2px; transition: width .4s; min-width: 2px; }
.rtc-track i.n { background: #abb4c3; } .rtc-track i.g { background: rgba(0,230,118,.85); } .rtc-track i.r { background: rgba(255,61,0,.82); }
.rtc-bp { width: 52px; text-align: left; color: var(--text); font-family: var(--mono, ui-monospace, monospace); font-weight: var(--fw-semibold); font-size: 11px; flex: 0 0 auto; }
.rtc-axis { display: flex; justify-content: space-between; padding: 2px 59px 0 39px; }
.rtc-axis span { font-size: 8px; color: var(--text3); font-family: var(--mono, ui-monospace, monospace); }
/* ── Tableau des réunions : AGRANDI + zone SCROLLABLE (~3 lignes visibles, en-tête collant 2 lignes,
      colonnes date/jours bien séparées — clone pro) ── */
.rtc-tblwrap { margin-top: 0; flex: 1 1 168px; min-height: 0; overflow-y: auto; border-top: 1px solid var(--border); }   /* grandit avec la carte étirée → plus de réunions visibles, zéro vide */   /* ~5 réunions visibles, hauteur naturelle (plus d'étirement) */
.rtc-tbl { width: 100%; border-collapse: collapse; font-size: 11px; font-family: var(--mono, ui-monospace, monospace); }
.rtc-tbl th { position: sticky; top: 0; z-index: 2; background: var(--head-bg); color: var(--text2); font-weight: var(--fw-semibold); text-align: center; padding: var(--sp-1) var(--sp-15); border-bottom: 1px solid var(--border); font-size: 10px; line-height: 1.2; }
.rtc-tbl th:first-child { text-align: left; padding-left: 9px; }
.rtc-tbl td { padding: var(--sp-05) var(--sp-15); border-bottom: var(--row-sep); text-align: center; color: var(--text); white-space: nowrap; }
.rtc-tbl tr:last-child td { border-bottom: 0; }
.rtc-tbl td:first-child { text-align: left; color: var(--text); padding-left: 9px; padding-right: 10px; }
.rtc-tbl tbody tr { transition: background var(--t-fast) ease; }
.rtc-tbl tbody tr:hover { background: var(--row-hover); }
.rtc-day { color: var(--text2); }
/* Pilules Implied Δ (fond plein vert/rouge foncé, texte centré) + badge Base Case (gris sombre / vert sombre) */
.rtc-pill { display: inline-block; font-size: 10px; font-weight: var(--fw-semibold); padding: 2px 7px; border-radius: 3px; border: 1px solid; white-space: nowrap; min-width: 66px; text-align: center; font-family: var(--mono, ui-monospace, monospace); }
.rtc-base { display: inline-block; font-size: 9px; font-weight: var(--fw-bold); padding: 2px 8px; border-radius: 3px; border: 1px solid; min-width: 40px; text-align: center; }
.rtc-pill.g, .rtc-base.g { background: rgba(0,230,118,.15);  color: #00e676; border-color: rgba(0,230,118,.5); }
.rtc-pill.r, .rtc-base.r { background: rgba(255,61,0,.15);   color: #ff3d00; border-color: rgba(255,61,0,.5); }
.rtc-pill.n             { background: rgba(171,180,195,.13); color: #abb4c3; border-color: rgba(171,180,195,.4); }
.rtc-base.n             { background: var(--bg5); color: #abb4c3; border-color: #34383f; }
/* .rtc-move : conservé pour le badge sentiment du panneau COT (sym-cot-sent), plus utilisé par les cartes TAUX */
.rtc-move { margin-left: auto; font-size: 10px; font-weight: var(--fw-bold); padding: 2px 8px; border-radius: 4px; white-space: nowrap; border: 1px solid; }
.rtc-move.g { background: rgba(0,230,118,.14); color: #00e676; border-color: rgba(0,230,118,.5); }
.rtc-move.r { background: rgba(255,61,0,.14); color: #ff3d00; border-color: rgba(255,61,0,.5); }
.rtc-move.n { background: rgba(171,180,195,.12); color: #abb4c3; border-color: rgba(171,180,195,.4); }
/* ── Onglets : réorganisation par glisser (appui maintenu) ── */
.nav-reordering { cursor: grabbing !important; user-select: none; }
.nav-reordering .nav-item { transition: transform .12s ease; }
.nav-item--dragging { background: rgba(227,178,58,.2); outline: 1px solid #e3b23a; border-radius: 4px; cursor: grabbing; transform: translateY(-2px); box-shadow: 0 6px 16px -6px rgba(0,0,0,.6); position: relative; z-index: 5; }

.ai-panel.open { transform: translateX(0); }
/* En-tête */
.ai-header { display: flex; align-items: center; justify-content: space-between; padding: var(--sp-3) var(--sp-4); border-bottom: 1px solid var(--bg2); flex: 0 0 auto; }
.ai-header-left { display: flex; align-items: center; gap: 10px; min-width: 0; }
.ai-head-ic {
  width: 30px; height: 30px; flex: 0 0 auto; border-radius: 4px 8px 8px 2px;
  background: rgba(0,230,118,0.14); border: 1px solid rgba(0,230,118,0.42); color: #00e676;
  font-weight: var(--fw-bold); font-size: 11px; display: flex; align-items: center; justify-content: center; font-family: var(--font-ui);
}
.ai-head-title { font-size: 13px; font-weight: var(--fw-semibold); color: #e9eaed; line-height: 1.2; }
.ai-head-status { display: flex; align-items: center; gap: 5px; font-size: 11px; color: #00e676; margin-top: 2px; }
.ai-status-dot { width: 6px; height: 6px; border-radius: 50%; background: #00e676; box-shadow: 0 0 5px rgba(0,230,118,0.8); }
.ai-header-right { display: flex; align-items: center; gap: 2px; }
.ai-hdr-btn { width: 28px; height: 28px; display: flex; align-items: center; justify-content: center; background: none; border: none; color: #6b7280; cursor: pointer; border-radius: 4px; transition: color .12s, background .12s; }
.ai-hdr-btn:hover { color: #e4e6ea; background: rgba(255,255,255,0.05); }
/* Bandeau de confirmation rouge */
.ai-clear-banner { display: none; align-items: center; justify-content: space-between; gap: 10px; padding: 10px 14px; background: #e03e3e; color: #fff; flex: 0 0 auto; animation: aiBannerIn .18s ease-out; }
.ai-clear-banner.show { display: flex; }
.ai-clear-txt { font-size: 13px; font-weight: var(--fw-semibold); }
.ai-clear-check { opacity: .92; margin-right: 2px; }
.ai-clear-actions { display: flex; align-items: center; gap: 8px; flex: 0 0 auto; }
.ai-clear-yes { background: #fff; color: #171717; padding: 2px 9px; border: none; border-radius: 3px; font-size: 12px; font-weight: var(--fw-bold); cursor: pointer; }
.ai-clear-cancel { background: none; border: none; color: #fff; font-size: 14px; cursor: pointer; opacity: .9; line-height: 1; padding: 2px; }
.ai-clear-cancel:hover { opacity: 1; }
@keyframes aiBannerIn { from { transform: translateY(-100%); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
/* Fil de messages */
.ai-messages { flex: 1 1 auto; min-height: 0; overflow-y: auto; padding: var(--sp-4); display: flex; flex-direction: column; gap: var(--sp-4); }
.ai-day-sep { display: flex; align-items: center; gap: 12px; color: #6b7280; font-size: 11px; }
.ai-day-sep::before, .ai-day-sep::after { content: ''; flex: 1; height: 1px; background: var(--bg2); }
/* Message utilisateur (droite) */
.ai-row--user { display: flex; flex-direction: column; align-items: flex-end; }
.ai-bubble-user { background: #1c1c1f; color: #e9eaed; padding: 9px 12px; border-radius: 4px; font-size: 13px; line-height: 1.5; max-width: 82%; word-wrap: break-word; }
.ai-time { font-size: 10px; color: #6b7280; margin-top: 4px; }
/* Message IA (gauche, sans fond) */
.ai-row--ai { display: flex; gap: 10px; align-items: flex-start; }
.ai-chip { width: 28px; height: 28px; flex: 0 0 auto; display: flex; align-items: center; justify-content: center; }
.ai-chip-img { width: 26px; height: 26px; object-fit: contain; display: block; }
.ai-ai-body { flex: 1; min-width: 0; }
.ai-ai-text { color: #d7dade; font-size: 13px; line-height: 1.62; word-wrap: break-word; }
.ai-ai-text strong { color: #fff; font-weight: var(--fw-bold); }
/* Accordéon des sources */
.ai-sources { margin-top: 9px; }
.ai-sources-head { display: inline-flex; align-items: center; gap: 6px; color: #e3b23a; font-size: 12px; font-weight: var(--fw-medium); cursor: pointer; user-select: none; }
.ai-sources-arrow { display: inline-block; font-size: 11px; transition: transform .18s ease; }
.ai-sources.open .ai-sources-arrow { transform: rotate(90deg); }
.ai-sources-list { display: none; margin-top: 9px; padding-left: 3px; flex-direction: column; gap: 9px; }
.ai-sources.open .ai-sources-list { display: flex; }
.ai-source { display: flex; gap: 9px; align-items: flex-start; }
.ai-source-dot { width: 5px; height: 5px; border-radius: 50%; background: #cfd3da; margin-top: 5px; flex: 0 0 auto; }
.ai-source-name { font-size: 12px; color: #d7dade; line-height: 1.3; }
.ai-source-date { font-size: 11px; color: #8a8f98; margin-top: 1px; }
/* « L'IA écrit… » : 3 points gris discrets qui rebondissent (pendant le calcul, avant le 1er chunk) */
.ai-thinking { display: inline-flex; gap: 4px; align-items: center; padding: 5px 0; }
.ai-thinking span { width: 6px; height: 6px; border-radius: 50%; background: #8a8f98; animation: aiBounce 1.2s infinite ease-in-out; }
.ai-thinking span:nth-child(2) { animation-delay: .16s; }
.ai-thinking span:nth-child(3) { animation-delay: .32s; }
@keyframes aiBounce { 0%,80%,100% { opacity: .35; transform: translateY(0); } 40% { opacity: 1; transform: translateY(-4px); } }
/* Barre d'input — ligne supérieure discrète, icônes pièce jointe, textarea, envoi orange plein */
.ai-inputbar { display: flex; align-items: flex-end; gap: 12px; padding: 10px 12px 4px; flex: 0 0 auto; border-top: 1px solid rgba(20,20,22,0.6); }
.ai-file-hidden { display: none; }
.ai-attach { flex: 0 0 auto; width: 24px; height: 36px; display: flex; align-items: center; justify-content: center; background: none; border: none; color: #6b7280; cursor: pointer; transition: color .12s; padding: 0; }
.ai-attach:hover { color: #d4d4d8; }
.ai-input {
  flex: 1; min-width: 0; resize: none; overflow-y: auto; max-height: 120px;
  background: #1c1c1f; border: 1px solid var(--border); border-radius: 4px; color: #e9eaed;
  font-size: 13px; line-height: 1.45; padding: 9px 12px; outline: none; font-family: var(--font-ui);
}
.ai-input::placeholder { color: #71757d; font-size: 13px; }
.ai-input:focus { border-color: #3a3a40; }
.ai-send {
  width: 36px; height: 36px; flex: 0 0 auto; display: flex; align-items: center; justify-content: center;
  background: #e3b23a; border: none; color: #fff; border-radius: 4px; cursor: pointer; transition: background .12s;
}
.ai-send:hover { background: var(--orange-dim); }
.ai-inputhint { font-size: 11px; font-weight: var(--fw-medium); color: #6b7280; padding: 6px 12px 0 50px; flex: 0 0 auto; }
.ai-legal { text-align: center; font-size: 11px; color: #6b7280; padding: 6px 12px 12px; flex: 0 0 auto; }
@media (max-width: 480px) { .ai-panel { width: 100%; border-left: none; } .ai-inputhint { padding-left: 12px; text-align: center; } }
/* iOS : la barre home (safe area) ne recouvre plus la zone de saisie / pied des volets (requiert viewport-fit=cover) */
@media (hover: none) and (pointer: coarse) {
  .ai-legal    { padding-bottom: calc(12px + env(safe-area-inset-bottom, 0px)); }
  .chat-hint   { padding-bottom: calc(10px + env(safe-area-inset-bottom, 0px)); }
  .sqwk-footer { padding-bottom: calc(10px + env(safe-area-inset-bottom, 0px)); }
  /* ANTI-ZOOM iOS : Safari zoome au focus dès qu'un champ a une police < 16px. On force 16px sur TOUS les champs
     de saisie tactile (chat support, IA, recherche symbole, recherche users, journal…) → plus de zoom parasite,
     la conversation reste à l'échelle. Le rendu visuel du texte tapé est à peine plus grand, c'est voulu. */
  .chat-input, #chat-search-input, .ai-input, #topbar-symbol-input, .wdg-lib-search,
  input[type="text"], input[type="search"], input[type="email"], input[type="number"],
  input[type="password"], input[type="url"], input[type="tel"], textarea, select { font-size: 16px !important; }
  .ai-input::placeholder { font-size: 16px; }
}

/* ═══════════════ CORRECTIFS RESPONSIVE (tablette / téléphone) ═══════════════ */
/* Tablette ≤ 1024px : la barre de redimensionnement est masquée (drag off), les volets
   latéraux (chat/notif/réglages/AI) prennent toute la largeur, World Clock plus compact. */
@media (max-width: 1024px) {
  .ai-panel { width: 100%; border-left: none; }
  .clocks-bar { flex-wrap: wrap; }
}
/* Tablette ≤ 768px : les volets latéraux passent en pleine largeur (au lieu de 420-440px
   qui mangeaient la moitié de l'écran), et les grandes tables s'assouplissent. */
@media (max-width: 768px) {
  .chat-panel, .np-panel, .settings-panel, .ai-panel, .sqwk-panel { width: 100% !important; max-width: 100% !important; border-left: none; }
  /* CLAVIER VIRTUEL : quand il s'ouvre, on rétrécit le volet de SA hauteur (--kb, posée en JS via visualViewport)
     → la zone de saisie remonte JUSTE au-dessus du clavier et la CONVERSATION reste visible au-dessus (demande user).
     Sans ça, l'input passait sous le clavier et iOS faisait défiler toute la page (en-tête + fil masqués). */
  .chat-panel, .ai-panel, .np-panel, .settings-panel, .sqwk-panel {
    height: calc(var(--vph) - var(--topbar-h) - var(--kb, 0px)) !important;
    transition: transform .24s ease, height .18s ease;
  }
  .fxl-table { min-width: 760px; font-size: 11px; }   /* 10 → 11 (audit 22/08) : l'échelle était INVERSÉE — 10px entre 481 et 768 mais 11px sous 480 ; le scroll horizontal absorbe déjà le surplus */
  /* Inertie tactile sur tous les conteneurs de tables larges (FX LIST / CALENDAR / BANK / Week Ahead) */
  .fxl-table-scroll, .cal-table-wrap, .bank-table-wrap, #wa-cal-body { -webkit-overflow-scrolling: touch; }
  .am-chart, .am-chart--donut { height: 200px; }
  .topbar { gap: 6px; }
}
/* Téléphone ≤ 480px : topbar désencombrée + tables compactes + vignettes plus petites. */
@media (max-width: 480px) {
  .topbar { padding: 0 10px; gap: 4px; }
  .topbar-symbol-search { display: none; }
  .topbar-ai-btn { height: 24px; padding: 0 8px; font-size: 10px; }   /* AI reste accessible (chat fonctionnel) */
  .fxl-table { min-width: 640px; font-size: 11px; }   /* ≥11px : chiffres lisibles au doigt, le scroll horizontal absorbe le surplus */
  .cth-event { min-width: 108px; font-size: 10px; }
  .news-category-text { width: 62px; font-size: 10px; }
  .news-item { --c-pad: 10px; --c-icon: 24px; --c-time: 50px; --c-cat: 96px; --c-arrow: 18px; }   /* colonnes mobiles → bleed auto-calculé */
  .news-time { min-width: 30px; }
  .chat-pending-item { width: 46px; height: 46px; }
  .chat-edit-box { max-width: 88vw; }
  .adm-tabs { overflow-x: auto; }                /* onglets admin scrollables si trop étroits */
  .ai-bubble-user { max-width: 88%; }
}

/* ═══════════ CORRECTIFS RESPONSIVE (audit) — Smart Bias mobile + bank + header ═══════════ */
@media (max-width: 768px) {
  /* Smart Bias — matrice 8 devises : vrai scroll horizontal au lieu d'un écrasement illisible */
  .sbm-grid { min-width: 620px; }
  .sbm-grid th.sbm-ind, .sbm-grid td.sbm-ind { width: 120px; }
  .sbm-grid-wrap { -webkit-overflow-scrolling: touch; }
  /* Smart Bias — panneau détail : empilé en 1 colonne (splitter retiré, inutilisable au doigt) */
  .sbs-body  { flex-direction: column; height: auto; }
  .sbs-left  { flex-basis: auto !important; width: 100%; max-height: 280px; }
  .sbs-right { width: 100%; }
  .sbs-split { display: none; }
  .sbs-badge   { flex: 0 0 auto; width: auto; min-width: 56px; max-width: 60%; font-size: 10px; padding: 3px 8px; overflow: hidden; text-overflow: ellipsis; }   /* « Very Bullish » : le badge s'ADAPTE au texte (plus jamais de débordement du rectangle vert) */
  .sbs-row-lbl { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }   /* le libellé rétrécit pour laisser la place au badge */
  /* Bank — détail déplié : 3 colonnes → 1 colonne */
  .bank-detail { grid-template-columns: 1fr; gap: 12px; padding: 12px 14px 14px 20px; }
  /* Bank — cellules compactées sur mobile : moins de scroll horizontal, lisibilité conservée (12px) */
  .bank-table { font-size: 12px; }
  .bank-table thead th { padding: 9px 10px; }
  .bank-row td { padding: 8px 10px; }
}
@media (max-width: 1100px) {
  /* Topbar — sentiment centré (absolu) : compacté pour ne pas chevaucher les icônes (769–1100px) */
  .topbar-sentiment { font-size: 10px; padding: 0 8px; }
}
@media (max-width: 480px) {
  /* Hauteur de header recalculée (désync corrigée) */
  :root { --header-h: calc(var(--topbar-h) + var(--navbar-h)); }
}


/* ── Dropdown custom DTP (remplace les <select> natifs : panneau sombre arrondi, ✓ orange — fini le surlignage bleu de l'OS) ── */
.dtpsel-native{display:none!important}
.dtpsel{position:relative;display:inline-flex;vertical-align:middle}
.dtpsel-btn{display:flex;align-items:center;gap:7px;background:var(--bg2);border:1px solid var(--border);border-radius:var(--r-2);padding:6px 28px 6px 10px;font-size:12px;color:var(--text);cursor:pointer;outline:none;position:relative;white-space:nowrap;transition:border-color var(--t-fast) var(--ease);line-height:1.3}
.dtpsel-btn:hover{border-color:var(--border2)}
.dtpsel.open .dtpsel-btn{border-color:var(--orange,#e3b23a)}
.dtpsel-lbl{display:inline-flex;align-items:center;gap:7px}
.dtpsel-caret{position:absolute;right:9px;top:50%;transform:translateY(-50%);transition:transform var(--t-med) var(--ease);color:#8a8a92;pointer-events:none;line-height:0}
.dtpsel.open .dtpsel-caret{transform:translateY(-50%) rotate(180deg)}
.dtpsel-panel{background:var(--bg2);border:1px solid var(--border);border-radius:var(--r-2);padding:5px;box-shadow:0 18px 44px -14px rgba(0,0,0,.55);z-index:99999;max-height:300px;overflow-y:auto}
.dtpsel-item{display:flex;align-items:center;gap:8px;padding:7px 26px 7px 10px;border-radius:var(--r-2);font-size:12px;color:var(--text2);cursor:pointer;white-space:nowrap;position:relative;transition:background var(--t-fast) var(--ease)}
.dtpsel-item:hover{background:var(--row-hover);color:var(--text)}
.dtpsel-item.sel{background:rgba(227,178,58,.13);color:#e3b23a}            /* item sélectionné → TEXTE orange + coche orange (uniforme partout) */
/* Filtres Analyst/Institution : largeurs la référence portées sur le dropdown dtpsel + bouton pleine largeur */
.arlib-filters .dtpsel, .br-filters .dtpsel { display:flex; }
.arlib-filters .dtpsel-btn, .br-filters .dtpsel-btn { width:100%; }
#arlib-type + .dtpsel { width:160px; }  #arlib-cat + .dtpsel { width:192px; }
#br-type + .dtpsel { width:160px; }  #br-source + .dtpsel { width:192px; }  #br-inst + .dtpsel { width:256px; }
.dtpsel-item.sel::after{content:"\2713";position:absolute;right:9px;color:var(--orange,#e3b23a);font-weight:var(--fw-bold);font-size:11px}
.dtpsel-flag{width:20px;height:13px;border-radius:2px;overflow:hidden;box-shadow:0 0 0 1px rgba(255,255,255,.14);flex-shrink:0;display:inline-flex}
.dtpsel-flag svg{width:100%;height:100%;display:block}


/* ── Barre recherche symbole — design la référence : bord + ring orange au focus, coins arrondis ── */
/* UN SEUL rectangle : l'input n'a AUCUNE bordure/fond/coin propre → fini le « rectangle dans le
   rectangle ». Le placeholder s'affiche directement dans le grand champ. La bordure ACTIVE orange
   est portée par le GRAND conteneur (.topbar-symbol-search) au focus, pas par l'input. */
#topbar-symbol-input{border:none;border-radius:0;outline:none;background:none;box-shadow:none;transition:none;-webkit-appearance:none;appearance:none}
#topbar-symbol-input:focus,#topbar-symbol-input:focus-visible{border:none;outline:none;box-shadow:none}
#topbar-symbol-input::placeholder{color:#7a7a82}
.topbar-symbol-search{transition:border-color var(--t-fast) var(--ease),box-shadow var(--t-fast) var(--ease)}
.topbar-symbol-search:focus-within{border-color:rgba(227,178,58,.62);box-shadow:none}   /* focus = UNE bordure OR nette, SANS halo (le glow se faisait clipper par les toolbars -> liseré cassé sous la case, bug signalé) ; l'input interne reste nu, cf. exemptions fin de fichier */

/* ═══════════ JOURNAL DE TRADING (vue plein écran + bouton topbar façon pro) ═══════════ */
.topbar-icon--desk { margin-right: 10px; flex-shrink: 0; }   /* même marge que Journal/Calc → écart RÉEL égal entre les 3 icônes (gap 10 + margin 10 partout ; avant : desk→journal = gap seul) */
.topbar-icon--journal { margin-right: 10px; flex-shrink: 0; }
.topbar-icon--active, .topbar-icon--active:hover { color: var(--orange); background: rgba(227,178,58,0.10); }
.panel-journal { display: flex; flex-direction: column; height: 100%; min-height: 0; flex: 1 1 auto; width: 100%; min-width: 0; }
.jr-stats { display: flex; flex-wrap: wrap; gap: 16px 22px; padding: 9px 14px; border-bottom: 1px solid var(--border); flex: 0 0 auto; }
.jr-stat i { font-style: normal; font-size: 9px; text-transform: uppercase; letter-spacing: 0.05em; color: var(--text3); display: block; }
.jr-stat b { font-family: var(--font-mono); font-size: 14px; font-weight: var(--fw-bold); color: var(--text); }
.jr-form { display: flex; flex-wrap: wrap; gap: 6px; padding: 9px 14px; border-bottom: 1px solid var(--border); flex: 0 0 auto; align-items: center; }
.jr-form input, .jr-form select { height: 27px; padding: 0 8px; background: var(--bg2); border: 1px solid var(--border); border-radius: 4px; color: var(--text); font-size: var(--fs-title); font-family: var(--font-ui); }
.jr-form input:focus, .jr-form select:focus { outline: none; border-color: var(--orange); }
#jr-pair  { width: 118px; } #jr-dir { width: 70px; } #jr-lots { width: 64px; }
#jr-entry { width: 86px; } #jr-exit { width: 150px; } #jr-pl { width: 110px; }
#jr-note  { flex: 1 1 180px; min-width: 140px; }
.jr-btn { height: 27px; padding: 0 12px; border: 1px solid var(--border); border-radius: 4px; background: var(--bg3); color: var(--text2); font-size: var(--fs-title); cursor: pointer; }
.jr-btn:hover { color: var(--text); border-color: var(--border2); }
.jr-btn--add { background: rgba(227,178,58,0.14); border-color: rgba(227,178,58,0.45); color: var(--orange); font-weight: var(--fw-bold); }
.jr-btn--add:hover { background: rgba(227,178,58,0.22); color: #ffb45e; }
.jr-table-wrap { flex: 1; min-height: 0; overflow: auto; -webkit-overflow-scrolling: touch; }
.jr-table { width: 100%; border-collapse: collapse; min-width: 760px; }
.jr-table thead th { position: sticky; top: 0; z-index: 2; background: var(--bg1); text-align: left; padding: 8px 10px; font-size: 9px; font-weight: var(--fw-bold); text-transform: uppercase; letter-spacing: 0.05em; color: var(--text3); border-bottom: 1px solid var(--border); white-space: nowrap; }
.jr-table td { padding: 7px 10px; font-size: var(--fs-title); color: var(--text2); border-bottom: 1px solid #141417; vertical-align: middle; }
.jr-table tbody tr:hover td { background: var(--bg2); }
.jr-mono { font-family: var(--font-mono); white-space: nowrap; }
.jr-pair { font-weight: var(--fw-bold); color: var(--text); white-space: nowrap; }
.jr-dir { font-size: 10px; font-weight: var(--fw-bold); letter-spacing: 0.04em; padding: 1px 7px; border-radius: 3px; border: 1px solid; }
.jr-buy  { color: #00e676; background: rgba(0,230,118,0.12); border-color: rgba(0,230,118,0.35); }
.jr-sell { color: #ff3d00; background: rgba(255,61,0,0.12);  border-color: rgba(255,61,0,0.35); }
.jr-pos { color: #00e676; } .jr-neg { color: #ff4d2e; }
.jr-open { font-size: 9px; font-weight: var(--fw-bold); letter-spacing: 0.05em; color: var(--amber, #ffb300); background: rgba(255,179,0,0.10); border: 1px solid rgba(255,179,0,0.32); padding: 1px 6px; border-radius: 3px; }
.jr-note { max-width: 320px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.jr-actions { white-space: nowrap; text-align: right; }
.jr-act { background: none; border: 1px solid transparent; border-radius: 4px; color: var(--text3); font-size: 12px; cursor: pointer; padding: 2px 7px; }
.jr-act:hover { color: var(--text); background: var(--bg3); }
.jr-act--del:hover { color: #ff4d2e; }
.jr-act--confirm { color: #ff4d2e; border-color: rgba(255,61,0,0.45); background: rgba(255,61,0,0.10); font-size: 10px; font-weight: var(--fw-bold); }
.jr-empty { text-align: center; vertical-align: middle; height: 240px; padding: 28px 16px !important; color: var(--text3); }
@media (max-width: 768px) {
  .jr-form input, .jr-form select { height: 32px; }
  .jr-btn { height: 32px; }
  .jr-stats { gap: 12px 16px; }
  .topbar-icon--journal { margin-right: 6px; }
  .topbar-icon--desk { margin-right: 6px; }
}

/* Journal — bouton Importer (Excel/CSV/Notion) */
.jr-form-sep { width: 1px; align-self: center; height: 20px; background: var(--border); margin: 0 4px; }
.jr-btn--import { border-color: var(--border2); color: var(--text2); }
.jr-btn--import:hover { color: var(--text); border-color: var(--orange); background: rgba(227,178,58,0.08); }

/* ════════ Journal — onglets Trade Log / Dashboard ════════ */
.jr-tabs { display: flex; gap: 2px; margin-left: 16px; }
.jr-tab { background: none; border: none; border-bottom: 2px solid transparent; color: var(--text3); font-size: 12px; font-weight: var(--fw-semibold); padding: 6px 12px; cursor: pointer; transition: color var(--t-fast) var(--ease), border-color var(--t-fast) var(--ease); }
.jr-tab:hover { color: var(--text); }
.jr-tab--active { color: var(--orange); border-bottom-color: var(--orange); }

/* ════════ Journal — TRADE LOG : toolbar + grille éditable façon Notion (HUD pro) ════════ */
#jr-log-view { display: flex; flex-direction: column; min-height: 0; flex: 1 1 auto; }
/* Barre de FILTRES / recherche / tri de la grille Trades (24/07) */
.jr-filters { display: flex; align-items: center; flex-wrap: wrap; gap: 7px; padding: 8px 14px; border-bottom: 1px solid var(--border); flex: 0 0 auto; }
.jr-filters:empty { display: none; }
.jr-flt-ic { display: inline-flex; color: var(--text3); margin-right: -2px; }
.jr-flt-search { height: 28px; min-width: 190px; flex: 1 1 190px; max-width: 320px; padding: 0 10px; background: var(--bg2); border: 1px solid var(--border); border-radius: 4px; color: var(--text); font-size: var(--fs-title); font-family: var(--font-ui); }
.jr-flt-search::placeholder { color: var(--text3); }
.jr-flt-search:focus, .jr-flt-sel:focus { outline: none; border-color: rgba(227,178,58,0.5); }
.jr-flt-sel { height: 28px; padding: 0 8px; background: var(--bg3); border: 1px solid var(--border); border-radius: 4px; color: var(--text2); font-size: var(--fs-title); font-family: var(--font-ui); cursor: pointer; max-width: 168px; }
.jr-flt-sel:hover { border-color: var(--border2); color: var(--text); }
.jr-flt-clear { height: 28px; padding: 0 11px; background: transparent; border: 1px solid var(--border); border-radius: 4px; color: var(--text3); font-size: var(--fs-title); font-family: var(--font-ui); cursor: pointer; }
.jr-flt-clear:hover { color: var(--orange); border-color: rgba(227,178,58,0.45); }
.jr-flt-clear[hidden] { display: none; }
.jr-flt-count { margin-left: auto; font-family: var(--font-mono); font-size: 11px; color: var(--text3); white-space: nowrap; }
.jr-flt-count--on { color: var(--orange); }
.jr-toolbar { display: flex; align-items: center; gap: 8px; padding: 8px 14px; border-bottom: 1px solid var(--border); flex: 0 0 auto; }
.jr-tb-btn { height: 28px; padding: 0 12px; border: 1px solid var(--border); border-radius: 4px; background: var(--bg3); color: var(--text2); font-size: var(--fs-title); font-family: var(--font-ui); cursor: pointer; transition: color var(--t-fast) var(--ease), background var(--t-fast) var(--ease), border-color var(--t-fast) var(--ease); white-space: nowrap; }
.jr-tb-btn:hover { color: var(--text); border-color: var(--border2); background: var(--bg2); }
.jr-tb-btn--add { background: rgba(227,178,58,0.14); border-color: rgba(227,178,58,0.42); color: var(--orange); font-weight: var(--fw-bold); }
.jr-tb-btn--add:hover { background: rgba(227,178,58,0.22); color: #ffb45e; border-color: rgba(227,178,58,0.6); }
.jr-tb-spacer { flex: 1; }
.jr-tb-mode { font-size: 10px; font-weight: var(--fw-bold); letter-spacing: .04em; text-transform: uppercase; color: var(--text3); padding: 3px 9px; border: 1px solid var(--border); border-radius: 20px; white-space: nowrap; }
.jr-tb-mode--perso { color: #00e676; border-color: rgba(0,230,118,0.35); background: rgba(0,230,118,0.08); }

.jr-grid-wrap { flex: 1; min-height: 0; overflow: auto; -webkit-overflow-scrolling: touch; }
.jr-grid { border-collapse: separate; border-spacing: 0; width: max-content; min-width: 100%; }
.jr-grid thead th { position: sticky; top: 0; z-index: 3; background: var(--head-bg); text-align: left; padding: 8px 11px; font-size: 9px; font-weight: var(--fw-bold); text-transform: uppercase; letter-spacing: .05em; color: var(--text3); border-bottom: 1px solid var(--border2); border-right: 1px solid var(--hud-line); white-space: nowrap; }
.jr-grid thead th.jr-th-act { border-right: none; min-width: 36px; }
.jr-grid thead th:first-child { left: 0; z-index: 5; }
.jr-grid td { border-bottom: 1px solid var(--hud-line); border-right: 1px solid var(--hud-line); vertical-align: middle; }
.jr-grid tbody tr:hover td { background: var(--row-hover); }
.jr-c { padding: 5px 9px; font-size: var(--fs-title); color: var(--text2); line-height: 1.35; cursor: pointer; max-width: 250px; }
.jr-c--multi, .jr-c--select { white-space: normal; }
.jr-grid td.jr-c:hover { background: #1d1f25; }
.jr-grid td.jr-c--title { position: sticky; left: 0; z-index: 2; background: var(--bg); }
.jr-grid tbody tr:hover td.jr-c--title { background: var(--row-hover); }
.jr-cv-title { font-weight: var(--fw-bold); color: var(--text); font-family: var(--font-mono); white-space: nowrap; }
.jr-cv-date { font-family: var(--font-mono); white-space: nowrap; color: var(--text2); }
.jr-cv-num { font-family: var(--font-mono); white-space: nowrap; }
.jr-ph { color: #44444c; font-style: normal; }
.jr-chip { display: inline-flex; align-items: center; gap: 4px; font-size: 10px; font-weight: var(--fw-semibold); line-height: 1.15; padding: 2px 8px; margin: 1px 3px 1px 0; border: 1px solid transparent; border-radius: 11px; white-space: nowrap; }
.jr-prog { display: flex; align-items: center; gap: 7px; min-width: 92px; }
.jr-prog-t { flex: 1; height: 5px; min-width: 38px; background: var(--border); border-radius: 3px; overflow: hidden; }
.jr-prog-t i { display: block; height: 100%; border-radius: 3px; }
.jr-prog-l { font-family: var(--font-mono); font-size: 10px; color: var(--text3); white-space: nowrap; }
.jr-ring { display: inline-flex; align-items: center; justify-content: center; position: relative; width: 26px; height: 26px; }
.jr-ring svg { width: 26px; height: 26px; }
.jr-ring b { position: absolute; font-family: var(--font-mono); font-size: 9px; font-weight: var(--fw-bold); color: var(--text); }
/* ── Sélection multiple façon Notion : colonne de cases à gauche + barre flottante ── */
.jr-th-sel, .jr-c-sel { width: 30px; min-width: 30px; padding: 0; text-align: center; vertical-align: middle; }
.jr-rowsel, .jr-selall { display: inline-block; width: 15px; height: 15px; border: 1.5px solid #3a3a42; border-radius: 4px; cursor: pointer; vertical-align: middle; transition: border-color var(--t-fast) var(--ease), background var(--t-fast) var(--ease); position: relative; }
.jr-c-sel .jr-rowsel { opacity: 0; }                                  /* visible au survol de la ligne (façon Notion) */
.jr-grid tbody tr:hover .jr-rowsel, .jr-rowsel--on { opacity: 1 !important; }
.jr-rowsel:hover, .jr-selall:hover { border-color: var(--orange); }
.jr-rowsel--on { background: var(--orange); border-color: var(--orange); }
.jr-rowsel--on::after { content: '✓'; position: absolute; inset: 0; color: var(--bg); font-size: 11px; font-weight: var(--fw-bold); line-height: 12px; text-align: center; }
.jr-grid tbody tr.jr-row--sel { background: rgba(227,178,58,0.07); }
#jr-selbar { position: fixed; left: 50%; bottom: 26px; transform: translateX(-50%); z-index: 4000; display: flex; align-items: center; gap: 12px; background: #16161a; border: 1px solid #2a2a31; border-radius: 4px; padding: 8px 10px 8px 14px; box-shadow: 0 8px 26px rgba(0,0,0,0.5); font-size: 12px; }
.jr-selbar-n { color: var(--text); font-weight: var(--fw-semibold); white-space: nowrap; }
.jr-selbar-del { background: rgba(255,61,0,0.12); border: 1px solid rgba(255,61,0,0.4); color: #ff5a36; border-radius: 4px; padding: 5px 12px; font-size: 12px; font-weight: var(--fw-bold); cursor: pointer; transition: background var(--t-fast) var(--ease), color var(--t-fast) var(--ease), border-color var(--t-fast) var(--ease); white-space: nowrap; }
.jr-selbar-del:hover { background: rgba(255,61,0,0.22); }
.jr-selbar-del--c { background: #ff3d00; border-color: #ff3d00; color: #fff; }
.jr-selbar-x { background: none; border: none; color: var(--text4); font-size: 13px; cursor: pointer; padding: 4px 6px; border-radius: 4px; }
.jr-selbar-x:hover { color: var(--text); background: rgba(255,255,255,0.06); }
.jr-c-act { padding: 4px; text-align: center; white-space: nowrap; }
.jr-rowdel { background: none; border: 1px solid transparent; border-radius: 4px; color: #45454d; font-size: 11px; cursor: pointer; padding: 3px 7px; opacity: 0; transition: opacity var(--t-fast) var(--ease), color var(--t-fast) var(--ease), background var(--t-fast) var(--ease); }
.jr-grid tbody tr:hover .jr-rowdel { opacity: 1; }
.jr-rowdel:hover { color: #ff4d2e; background: rgba(255,61,0,0.10); }
.jr-rowdel--c { opacity: 1; color: #ff4d2e; border-color: rgba(255,61,0,0.45); background: rgba(255,61,0,0.10); font-size: 10px; font-weight: var(--fw-bold); }
.jr-cell-input { width: 100%; min-width: 70px; height: 26px; padding: 0 7px; background: #1a1a1f; border: 1px solid var(--orange); border-radius: 4px; color: var(--text); font-size: var(--fs-title); font-family: var(--font-ui); box-shadow: 0 0 0 2px rgba(227,178,58,0.15); }
.jr-cell-input:focus { outline: none; }
/* Popover éditeur (select / multi) façon Notion */
.jr-pop { position: fixed; z-index: 9600; max-width: 340px; max-height: 340px; overflow-y: auto; background: #151519; border: 1px solid var(--border2); border-radius: 4px; box-shadow: 0 14px 34px rgba(0,0,0,0.6); padding: 6px; }   /* 9600 = au-dessus du volet détail (9401) pour que les éditeurs ouverts DANS le volet restent visibles */
.jr-pop-search { width: 100%; height: 28px; padding: 0 8px; margin-bottom: 5px; background: var(--bg2); border: 1px solid var(--border); border-radius: 4px; color: var(--text); font-size: var(--fs-title); font-family: var(--font-ui); }
.jr-pop-search:focus { outline: none; border-color: var(--orange); }
.jr-pop-chips { display: flex; flex-wrap: wrap; gap: 2px; padding: 2px 2px 6px; border-bottom: 1px solid var(--hud-line); margin-bottom: 6px; }
.jr-chip-x { cursor: pointer; opacity: .55; font-weight: var(--fw-bold); font-size: 12px; }
.jr-chip-x:hover { opacity: 1; }
.jr-pop-opts { display: flex; flex-direction: column; gap: 1px; }
.jr-pop-opt { display: flex; align-items: center; gap: 6px; text-align: left; background: none; border: none; border-radius: 4px; padding: 5px 7px; cursor: pointer; color: var(--text2); font-size: var(--fs-title); font-family: var(--font-ui); width: 100%; }
.jr-pop-opt:hover { background: rgba(255,255,255,0.05); }
.jr-pop-ck { margin-left: auto; color: var(--orange); font-weight: var(--fw-bold); }
.jr-pop-new { color: var(--orange); font-weight: var(--fw-semibold); }
.jr-pop-clear { color: var(--text3); }
/* Colonnes éditables : en-têtes cliquables (menu) + ajout de propriété */
.jr-th { cursor: pointer; user-select: none; }
.jr-th:hover { color: var(--text); background: #16161a; }
.jr-th-caret { opacity: 0; font-size: 8px; margin-left: 4px; color: var(--text3); transition: opacity var(--t-fast) var(--ease); }
.jr-th:hover .jr-th-caret { opacity: 1; }
.jr-th-addcol { cursor: pointer; color: var(--text3); font-size: 15px; font-weight: var(--fw-bold); text-align: center; min-width: 30px; background: var(--head-bg); }
.jr-th-addcol:hover { color: var(--orange); background: #16161a; }
/* Glisser-déposer des colonnes : état dragué + ligne d'insertion orange */
.jr-th[draggable="true"] { -webkit-user-drag: element; }
.jr-th--dragging { opacity: 0.4; background: var(--border) !important; }
.jr-th--drop-l { box-shadow: inset 3px 0 0 0 var(--orange); }
.jr-th--drop-r { box-shadow: inset -3px 0 0 0 var(--orange); }
.jr-cv-text { color: var(--text2); }
.jr-pop-ttl { font-size: 9px; font-weight: var(--fw-bold); text-transform: uppercase; letter-spacing: .05em; color: var(--text3); padding: 2px 6px 7px; }
.jr-nc-ic { display: inline-block; width: 16px; text-align: center; color: var(--text3); font-size: 11px; }
.jr-pop-del { color: #ff4d2e; }
.jr-pop-del:hover { background: rgba(255,61,0,0.10); }
.jr-prop-eye { display: inline-block; width: 14px; color: var(--orange); }
#jr-log-view.hidden, #jr-dashboard.hidden { display: none; }

/* ════════ Performance Dashboard (façon Performance Dashboard 3.0, identité HUD) ════════ */
.jrd { flex: 1; min-height: 0; overflow-y: auto; padding: 16px 18px; display: flex; flex-direction: column; gap: 20px; }
.jrd-sec { border: 1px solid var(--border); border-radius: 4px; padding: 14px 16px 16px; background: var(--bg); }
.jrd-sec-h { font-size: 11px; font-weight: var(--fw-bold); letter-spacing: .08em; color: var(--orange); text-transform: uppercase; margin-bottom: 14px; }
.jrd-rings { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 14px; }
.jrd-ring { display: flex; flex-direction: column; align-items: center; gap: 8px; padding: 4px 0; }
.jrd-ring-c { width: 98px; height: 98px; border-radius: 50%; border: 4px solid; display: flex; align-items: center; justify-content: center; background: var(--bg); padding: 0 4px; box-sizing: border-box; }
/* white-space:nowrap → la valeur (ex. "+12,3 k$") ne passe JAMAIS à la ligne dans l'anneau (le "$" ne saute plus) */
.jrd-ring-v { font-family: var(--font-mono); font-size: 17px; font-weight: var(--fw-bold); white-space: nowrap; line-height: 1; letter-spacing: -0.2px; }
.jrd-ring-l { font-size: 11px; color: var(--text2); font-weight: var(--fw-semibold); }
.jrd-ring-s { font-size: 10px; color: var(--text3); }
.jrd-row { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr); gap: 14px; margin-top: 14px; }
.jrd-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 14px; }
.jrd-card { background: var(--bg); border: 1px solid var(--border); border-radius: 4px; padding: 11px 13px; min-width: 0; }
.jrd-card-h { display: flex; align-items: center; font-size: var(--fs-title); font-weight: var(--fw-bold); color: var(--text); margin-bottom: 11px; }
.jrd-bars { display: flex; flex-direction: column; gap: 7px; }
.jrd-bar { display: grid; grid-template-columns: 92px 1fr 46px; align-items: center; gap: 8px; }
.jrd-bar-k { font-size: 11px; color: var(--text2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.jrd-bar-t { height: 8px; background: var(--bg2); border-radius: 4px; overflow: hidden; }
.jrd-bar-t i { display: block; height: 100%; border-radius: 4px; min-width: 2px; transition: width .3s; }
.jrd-bar-v { font-family: var(--font-mono); font-size: 11px; color: var(--text); text-align: right; }
.jrd-eq { width: 100%; height: 150px; display: block; }
.jrd-empty { color: var(--text3); font-size: 12px; padding: 14px 0; text-align: center; }
.jrd-empty-big { color: var(--text3); font-size: 13px; text-align: center; padding: 44px 16px; }
/* amCharts : courbe de performance + donut de répartition */
.jrd-row--charts { grid-template-columns: 224px minmax(0, 1fr); }
.jrd-card--donut, .jrd-card--eq { display: flex; flex-direction: column; }
.jr-chart-am { width: 100%; min-width: 0; }
.jr-chart-am--eq { height: 234px; }
.jr-chart-am--donut { height: 156px; }
.jrd-eqtoggle { margin-left: auto; display: inline-flex; gap: 3px; }
.jrd-eqtoggle button { background: var(--bg3); border: 1px solid var(--border); color: var(--text3); font-size: 9px; font-weight: var(--fw-semibold); padding: 2px 8px; border-radius: 4px; cursor: pointer; font-family: var(--font-ui); transition: background var(--t-fast) var(--ease), color var(--t-fast) var(--ease), border-color var(--t-fast) var(--ease); }
.jrd-eqtoggle button:hover { color: var(--text); border-color: var(--border2); }
.jrd-eqtoggle button.active { background: rgba(227,178,58,0.15); border-color: rgba(227,178,58,0.45); color: var(--orange); }
.jrd-legend { display: flex; flex-wrap: wrap; gap: 5px 12px; padding: 8px 2px 0; justify-content: center; }
.jrd-leg { font-size: 10px; color: #fff; font-weight: var(--fw-semibold); display: inline-flex; align-items: center; gap: 5px; }
.jrd-leg i { width: 9px; height: 9px; border-radius: 2px; display: inline-block; }
.jrd-leg b { color: #fff; font-family: var(--font-mono); font-weight: var(--fw-bold); }
@media (max-width: 760px) { .jrd-row, .jrd-row--charts { grid-template-columns: 1fr; } }

/* ════════ Volet détail d'un trade (façon page Notion) — ouvert via le bouton ⤢ OUVRIR d'une ligne ════════ */
/* Bouton OUVRIR : apparaît au survol de la ligne, ancré à droite de la cellule titre (déjà position:sticky) */
.jrd-open { position: absolute; top: 50%; right: 5px; transform: translateY(-50%); display: inline-flex; align-items: center; gap: 4px; opacity: 0; pointer-events: none; background: var(--border); border: 1px solid var(--border2); color: var(--text2); font-size: 8px; font-weight: var(--fw-bold); letter-spacing: .04em; padding: 2px 6px; border-radius: 4px; cursor: pointer; transition: opacity var(--t-fast) var(--ease), color var(--t-fast) var(--ease), background var(--t-fast) var(--ease); }
.jrd-open svg { display: block; }
.jr-grid tbody tr:hover .jrd-open { opacity: 1; pointer-events: auto; }
.jrd-open:hover { color: var(--orange); border-color: rgba(227,178,58,.45); background: #16161a; }

/* Rideau flouté sous la topbar (la topbar reste nette) */
#jrd-overlay { position: fixed; inset: var(--topbar-h) 0 0 0; z-index: 9400; background: rgba(6,6,8,.5); backdrop-filter: blur(5px); -webkit-backdrop-filter: blur(5px); opacity: 0; visibility: hidden; transition: opacity .18s; }
#jrd-overlay.show { opacity: 1; visibility: visible; }

/* Le volet : calé SOUS la topbar, glisse depuis la droite */
#jr-detail { position: fixed; top: var(--topbar-h); right: 0; bottom: 0; width: 560px; max-width: 96vw; z-index: 9401; background: var(--bg); border-left: 1px solid var(--border); box-shadow: -18px 0 40px rgba(0,0,0,.5); display: flex; flex-direction: column; transform: translateX(100%); transition: transform .22s cubic-bezier(.4,0,.2,1); }
#jr-detail.show { transform: translateX(0); }
.jrd-resize { position: absolute; left: -3px; top: 0; bottom: 0; width: 7px; cursor: col-resize; z-index: 5; }
.jrd-resize:hover, body.jrd-resizing .jrd-resize { box-shadow: inset 2px 0 0 0 var(--orange); }
body.jrd-resizing { cursor: col-resize; user-select: none; }
body.jrd-resizing #jr-detail { transition: none; }

.jrd-head { display: flex; align-items: center; gap: 4px; height: 42px; padding: 0 10px; border-bottom: 1px solid var(--hud-line); flex-shrink: 0; }
.jrd-ic { display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; background: none; border: none; border-radius: 4px; color: var(--text3); cursor: pointer; transition: .12s; }
.jrd-ic:hover { background: rgba(255,255,255,.06); color: var(--text); }
.jrd-head-lbl { font-size: 11px; color: var(--text3); font-weight: var(--fw-semibold); margin-left: 4px; }

.jrd-body { flex: 1; min-height: 0; overflow-y: auto; padding: 18px 22px 40px; }
.jrd-titlewrap { margin-bottom: 16px; }
.jrd-title { font-size: 23px; font-weight: var(--fw-bold); color: var(--text); cursor: text; padding: 2px 4px; margin: 0 -4px; border-radius: 4px; min-height: 30px; letter-spacing: -.01em; }
.jrd-title:hover { background: rgba(255,255,255,.04); }
.jrd-title-input { width: 100%; font-size: 23px; font-weight: var(--fw-bold); color: var(--text); background: var(--bg2); border: 1px solid var(--orange); border-radius: 4px; padding: 1px 4px; font-family: var(--font-ui); letter-spacing: -.01em; }
.jrd-title-input:focus { outline: none; }

/* Propriétés (clé à gauche, valeur cliquable à droite — éditeurs réutilisés de la grille) */
.jrd-props { display: flex; flex-direction: column; gap: 1px; margin-bottom: 22px; }
.jrd-prop { display: grid; grid-template-columns: 150px minmax(0,1fr); align-items: start; gap: 8px; min-height: 30px; }
.jrd-prop-k { display: flex; align-items: center; gap: 7px; font-size: 12px; color: var(--text3); padding-top: 6px; }
.jrd-prop-ic { display: inline-flex; align-items: center; justify-content: center; width: 15px; color: var(--text4); font-size: 11px; }
.jrd-prop-v { font-size: 12px; color: var(--text2); padding: 5px 6px; border-radius: 4px; cursor: pointer; min-height: 18px; display: flex; flex-wrap: wrap; align-items: center; gap: 2px; }
.jrd-prop-v:hover { background: rgba(255,255,255,.04); }
.jrd-prop-v--ro, .jrd-prop-v--ro:hover { cursor: default; background: none; }
.jrd-prop-v .jr-ph { color: var(--text4); font-style: normal; }
.jrd-prop-v .jr-cell-input { width: 100%; }

/* Sections narratives écrites (Fonda Bias, Technical, Entry, Management, Close, Erreur) */
.jrd-sections { display: flex; flex-direction: column; gap: 16px; border-top: 1px solid var(--hud-line); padding-top: 18px; }
.jrd-sect-h { font-size: 11px; font-weight: var(--fw-bold); letter-spacing: .07em; color: #e3b23a; text-transform: uppercase; margin-bottom: 6px; }
.jrd-sect-ta { width: 100%; min-height: 38px; resize: none; overflow: hidden; background: var(--bg); border: 1px solid var(--border); border-radius: 4px; padding: 8px 10px; color: var(--text2); font-size: 12px; line-height: 1.55; font-family: var(--font-ui); }
.jrd-sect-ta:hover { border-color: var(--border2); }
.jrd-sect-ta:focus { outline: none; border-color: var(--orange); box-shadow: 0 0 0 1.5px rgba(227,178,58,.25); background: var(--bg); }
.jrd-sect-ta::placeholder { color: var(--text4); }

/* Ligne « + Nouveau trade » sous la dernière ligne de la grille (façon Notion) */
.jr-addrow { cursor: pointer; }
.jr-addrow-cell { padding: 9px 12px !important; color: var(--text4); font-size: 12px; border-top: 1px solid var(--hud-line); transition: color .12s, background .12s; }
.jr-addrow:hover .jr-addrow-cell { color: var(--orange); background: rgba(227,178,58,.05); }
.jr-addrow-ic { display: inline-block; width: 14px; text-align: center; font-weight: var(--fw-bold); margin-right: 3px; }

/* 2 blocs images (captures de graphiques) sous les sections du volet détail */
.jrd-imgs { border-top: 1px solid var(--hud-line); padding-top: 18px; margin-top: 16px; }
.jrd-imgs-h { font-size: 11px; font-weight: var(--fw-bold); letter-spacing: .07em; color: #e3b23a; text-transform: uppercase; margin-bottom: 10px; }
.jrd-imgrow { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.jrd-imgblock { position: relative; aspect-ratio: 16 / 10; border: 1px dashed var(--border2); border-radius: 4px; background: var(--bg); overflow: hidden; cursor: pointer; display: flex; align-items: center; justify-content: center; transition: border-color .12s, background .12s; }
.jrd-imgblock:hover { border-color: var(--orange); background: rgba(227,178,58,.04); }
.jrd-imgblock--filled { border-style: solid; border-color: var(--border); cursor: zoom-in; }
.jrd-img-add { display: flex; flex-direction: column; align-items: center; gap: 5px; color: var(--text4); font-size: var(--fs-title); pointer-events: none; }
.jrd-img-ic { font-size: 22px; font-weight: 300; line-height: 1; color: var(--text3); }
.jrd-img { width: 100%; height: 100%; object-fit: contain; display: block; background: #050506; }
.jrd-img-del { position: absolute; top: 6px; right: 6px; width: 22px; height: 22px; border-radius: 4px; border: none; background: rgba(0,0,0,.62); color: #fff; font-size: 12px; line-height: 1; cursor: pointer; display: flex; align-items: center; justify-content: center; opacity: 0; transition: opacity .12s; }
.jrd-imgblock--filled:hover .jrd-img-del { opacity: 1; }
.jrd-lightbox { position: fixed; inset: 0; z-index: 9999; background: rgba(0,0,0,.88); display: flex; align-items: center; justify-content: center; padding: 24px; cursor: zoom-out; }
.jrd-lightbox img { max-width: 96%; max-height: 96%; object-fit: contain; border-radius: 4px; box-shadow: 0 8px 40px rgba(0,0,0,.6); }

@media (max-width: 768px) {
  #jr-detail { width: 100% !important; max-width: 100%; }
  .jrd-resize { display: none; }
  .jrd-prop { grid-template-columns: 116px minmax(0,1fr); }
}

/* ════════ Calculatrice de taille de position (icône topbar à côté du journal) ════════ */
.topbar-icon--calc { margin-right: 10px; flex-shrink: 0; }
.panel-calc { display: flex; flex-direction: column; height: 100%; min-height: 0; flex: 1 1 auto; width: 100%; min-width: 0; }
.calc-wrap { flex: 1; min-height: 0; overflow-y: auto; -webkit-overflow-scrolling: touch; display: grid; grid-template-columns: minmax(0, 320px) minmax(0, 1fr); gap: 0; }
.calc-form { display: flex; flex-direction: column; gap: 11px; padding: 16px 18px; border-right: 1px solid var(--border); }
.calc-field { display: flex; flex-direction: column; gap: 4px; }
.calc-field > span { font-size: 9px; text-transform: uppercase; letter-spacing: 0.05em; color: var(--text3); font-weight: var(--fw-bold); }
.calc-field input, .calc-field select { height: 32px; padding: 0 9px; background: var(--bg2); border: 1px solid var(--border); border-radius: 4px; color: var(--text); font-size: 12px; font-family: var(--font-mono); width: 100%; }
.calc-field input:focus, .calc-field select:focus { outline: none; border-color: var(--orange); box-shadow: 0 0 0 2px rgba(227,178,58,0.16); }
.calc-field input:hover, .calc-field select:hover { border-color: #2e2e34; }
/* Spinners natifs des champs nombre MASQUÉS (les flèches grises empilées cassaient le look HUD) */
.calc-field input[type=number] { -moz-appearance: textfield; appearance: textfield; }
.calc-field input[type=number]::-webkit-outer-spin-button,
.calc-field input[type=number]::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }
.calc-risk-row { display: flex; align-items: stretch; gap: 0; }
.calc-risk-row input { border-top-right-radius: 0; border-bottom-right-radius: 0; }
.calc-risk-unit { display: none; }
.calc-risk-mode { width: 40px; flex-shrink: 0; border: 1px solid var(--border); border-left: none; border-radius: 0 4px 4px 0; background: rgba(227,178,58,0.14); color: var(--orange); font-weight: var(--fw-bold); font-size: 13px; cursor: pointer; font-family: var(--font-mono); }

/* Paliers de risque (0,5 / 1 / 2 %) : trois clics remplacent une saisie, et c est le geste le
   plus frequent d une calculatrice de position. Le palier actif se voit, sinon on ne sait pas
   si le chiffre affiche vient d un clic ou d une frappe. Cibles de 30 px de haut : au-dessus du
   seuil tactile une fois le zoom global applique. */
.calc-presets { display: flex; gap: 5px; margin-top: 6px; }
.calc-preset {
  flex: 1 1 auto; min-height: 30px; padding: 0 8px;
  border: 1px solid var(--hud-line, var(--border)); border-radius: 4px;
  background: transparent; color: var(--txt-2, #8b93a1);
  font-family: var(--font-mono); font-size: 11.5px; font-weight: var(--fw-bold);
  cursor: pointer; transition: border-color .12s, color .12s, background .12s;
}
.calc-preset:hover { border-color: var(--orange); color: var(--txt-1, #e6e8eb); }
.calc-preset.est-actif { border-color: var(--orange); color: var(--orange); background: rgba(227,178,58,0.12); }
.calc-risk-mode:hover { background: rgba(227,178,58,0.24); color: #ffb45e; }
.calc-actions { display: flex; align-items: center; gap: 10px; margin-top: 4px; }
.calc-actions .jr-btn { height: 32px; }
.calc-rate-note { font-size: 9px; color: var(--text4); letter-spacing: 0.02em; }
.calc-results { padding: 16px 18px; display: flex; flex-direction: column; gap: 11px; min-width: 0; align-content: start; }
.calc-empty { color: var(--text3); font-size: 12px; padding: 22px 4px; text-align: center; border: 1px dashed var(--border); border-radius: 4px; }
.calc-card { background: var(--bg2); border: 1px solid var(--border); border-radius: 4px; padding: 11px 13px; display: flex; flex-direction: column; gap: 3px; min-width: 0; box-shadow: var(--panel-depth); }
.calc-card .calc-k { font-size: 9px; text-transform: uppercase; letter-spacing: 0.05em; color: var(--text3); font-weight: var(--fw-bold); }
.calc-card .calc-v { font-family: var(--font-mono); font-size: 16px; font-weight: var(--fw-bold); color: var(--text); font-variant-numeric: tabular-nums; }
.calc-card .calc-v em { font-style: normal; font-size: 11px; color: var(--text3); font-weight: var(--fw-semibold); }
.calc-card .calc-sub { font-size: 10px; color: var(--text3); font-family: var(--font-mono); font-variant-numeric: tabular-nums; }
.calc-card--hero { background: rgba(227,178,58,0.08); border-color: rgba(227,178,58,0.40); }
.calc-card--hero .calc-v { font-size: 30px; line-height: 1.15; letter-spacing: -0.01em; color: var(--orange); }
.calc-card--hero .calc-v em { color: rgba(227,178,58,0.7); font-size: 14px; }
.calc-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 11px; }
@media (max-width: 860px) {
  .calc-wrap { grid-template-columns: 1fr; }
  .calc-form { border-right: none; border-bottom: 1px solid var(--border); }
}
@media (max-width: 768px) { .topbar-icon--calc { margin-right: 6px; } }
/* ≤480px (téléphones) : topbar encore plus serrée mais TOUJOURS espacée — rien ne se touche */
@media (max-width: 480px) {
  .topbar-right { gap: 6px; padding-left: 8px; padding-right: 6px; }
  .topbar-icon { width: 28px; height: 28px; }
  .topbar-icon svg { width: 16px; height: 16px; }
  .topbar-icon--ai svg { width: 18px; height: 18px; }
  .topbar-sentiment { padding: 0 7px; font-size: 8px; height: 26px; }
  .topbar-icon--journal, .topbar-icon--calc { width: 28px; height: 28px; }
  .logo-text { font-size: 14px; }
}

/* ════════ Toast (fonctionnalité en développement / messages éphémères) ════════ */
#dtp-toast-host { position: fixed; left: 50%; bottom: 28px; transform: translateX(-50%); z-index: 4000; display: flex; flex-direction: column; gap: 8px; align-items: center; pointer-events: none; width: max-content; max-width: 92vw; }
.dtp-toast { display: flex; align-items: center; gap: 9px; background: #16161a; border: 1px solid var(--border2); border-radius: 4px; padding: 11px 16px; color: var(--text); font-size: 12px; line-height: 1.4; box-shadow: 0 8px 28px rgba(0,0,0,0.55); opacity: 0; transform: translateY(14px); transition: opacity 0.25s, transform 0.25s; max-width: 460px; }
.dtp-toast.show { opacity: 1; transform: translateY(0); }
.dtp-toast--dev { border-color: rgba(227,178,58,0.55); border-left: 3px solid var(--orange); }
.dtp-toast-ic { font-size: 15px; flex-shrink: 0; }

/* Bannière « Nouvelle version disponible » (détection de nouveau déploiement) */
.dtp-update-banner { position: fixed; left: 50%; bottom: 24px; transform: translateX(-50%) translateY(16px); z-index: 5000; display: flex; align-items: center; gap: 11px; background: #16161a; border: 1px solid rgba(227,178,58,0.55); border-left: 3px solid var(--orange); border-radius: 4px; padding: 10px 12px 10px 15px; color: var(--text); font-size: 12px; box-shadow: 0 10px 30px rgba(0,0,0,0.6); opacity: 0; transition: opacity .25s, transform .25s; }
.dtp-update-banner.show { opacity: 1; transform: translateX(-50%) translateY(0); }
.dtp-update-banner .dub-ic { font-size: 14px; flex-shrink: 0; }
.dtp-update-banner .dub-btn { background: var(--orange); color: #1a1205; border: none; border-radius: 4px; padding: 5px 13px; font-size: 12px; font-weight: var(--fw-bold); cursor: pointer; font-family: var(--font-ui); flex-shrink: 0; transition: filter var(--t-fast) var(--ease), transform var(--t-fast) var(--ease); }
.dtp-update-banner .dub-btn:hover { filter: brightness(1.08); }
.dtp-update-banner .dub-btn:active { transform: translateY(1px); }
.dtp-update-banner .dub-x { background: transparent; border: none; color: var(--text3); font-size: 16px; line-height: 1; cursor: pointer; padding: 2px 4px; flex-shrink: 0; transition: color var(--t-fast) var(--ease); }
.dtp-update-banner .dub-x:hover { color: var(--text); }
/* Variante APP INSTALLÉE : message sur 2 lignes (titre + détail), un cran plus large et présent. */
.dtp-update-banner--app { align-items: flex-start; max-width: min(92vw, 420px); padding: 13px 13px 13px 16px; }
.dtp-update-banner--app .dub-ic { font-size: 16px; margin-top: 1px; }
.dtp-update-banner--app .dub-body { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.dtp-update-banner--app .dub-title { font-size: 12.5px; font-weight: var(--fw-bold); color: var(--text); letter-spacing: -.005em; }
.dtp-update-banner--app .dub-txt { font-size: 11.5px; color: var(--text3); line-height: 1.5; }
.dtp-update-banner--app .dub-btn { align-self: center; }


/* ── Animation « nouvelle notif / message » (icônes topbar : sonnerie + glow + badge pop/ping) ── */
@keyframes tbBell { 0%,70%,100%{transform:rotate(0)} 74%{transform:rotate(14deg)} 78%{transform:rotate(-11deg)} 82%{transform:rotate(8deg)} 86%{transform:rotate(-5deg)} 90%{transform:rotate(2deg)} }
/* (tbGlow SUPPRIMÉE 05/08 — elle animait un `drop-shadow` en boucle infinie dès qu'il y avait du
   non-lu, donc la plupart du temps : un filtre se recalcule à chaque image, sur le fil principal,
   pour un simple halo. Remplacée plus bas par tbGlowSoft, qui anime une OPACITÉ — déléguée au
   compositeur, donc gratuite. Même rendu à l'œil.) */
@keyframes tbPop  { 0%{transform:scale(0)} 55%{transform:scale(1.3)} 100%{transform:scale(1)} }
@keyframes tbPing { 0%{box-shadow:0 0 0 0 rgba(255,60,60,.55)} 70%{box-shadow:0 0 0 6px rgba(255,60,60,0)} 100%{box-shadow:0 0 0 0 rgba(255,60,60,0)} }
.topbar-icon.tb-alert svg, .topbar-icon.tb-alert i { animation: tbBell 5s ease-in-out infinite; transform-origin: 50% 12%; }
#notif-badge, #chat-badge { animation: tbPop .45s cubic-bezier(.34,1.6,.5,1), tbPing 2.2s ease-out .6s infinite; }
@media (prefers-reduced-motion: reduce){ .topbar-icon.tb-alert svg, .topbar-icon.tb-alert i, #notif-badge, #chat-badge { animation: none !important; } }

/* Identite typo landing : titres Inter Tight */
.panel-title,.chart-header-title,.np-title,.sqwk-title,.ai-head-title,.sym-ptitle,.arlib-list-title,.wa-title,.wa3-ptitle,.br-list-title,.cot-header-label,.dmx-header-title,.sbs-risk-title,.wr-section-title,.ai-insights-title,.nav-item,.right-tab{font-family:var(--tight);}

/* Phase 4 polish subtil (additif facon landing) */
.sym-panel,.sym-bz-col,.ai-insights-card,.ai-ins-pair{transition:border-color .18s ease;}
.sym-panel:hover,.sym-bz-col:hover,.ai-insights-card:hover,.ai-ins-pair:hover{border-color:rgba(227,178,58,0.30);}
/* Override serif Fraunces des Notes d'Analystes SUPPRIMÉ (27/07) : c'était la seule vue en serif → cassait
   l'homogénéité. .arlib-list-title suit maintenant la règle canonique Inter Tight majuscules comme les autres. */

/* Phase 4 passe 3 - interactions premium facon landing (additif, sur) */
.sym-panel,.sym-bz-col,.ai-insights-card,.ai-ins-pair{transition:border-color .18s ease,transform .18s ease;}
.sym-panel:hover,.sym-bz-col:hover,.ai-insights-card:hover,.ai-ins-pair:hover{transform:translateY(-1px);}
input:focus,select:focus,textarea:focus{outline:none;box-shadow:0 0 0 3px rgba(227,178,58,0.14);}

/* Phase 4 passe 4 - cartes premium (radius 10px) + etats actifs or + hover renforce */
.sym-panel,.sym-bz-col,.clocks-panel,.sbs-panel,.dmx-panel{border-radius:var(--r-1);}
.sym-subtab--active,.nav-item.active,.nav-item--active{color:var(--orange);}
.sym-panel:hover,.sym-bz-col:hover,.ai-insights-card:hover,.ai-ins-pair:hover{transform:translateY(-2px);border-color:rgba(227,178,58,0.4);}

/* === Refonte Pass 3 - finition cartes + animation d entree (Minimal Epure) === */
.sym-panel,.sym-bz-col,.clocks-panel,.sbs-panel,.dmx-panel,.ai-insights-card,.bias-content,.arlib-list-view{border-radius:var(--r-1);}
.sym-panel,.sym-bz-col,.ai-insights-card,.ai-ins-pair,.clocks-panel,.sbs-panel,.dmx-panel{transition:border-color .18s ease,transform .18s ease,box-shadow .2s ease;}
.sym-panel:hover,.sym-bz-col:hover,.ai-insights-card:hover,.ai-ins-pair:hover{transform:translateY(-1px);border-color:rgba(227,178,58,0.26);box-shadow:0 10px 26px -16px rgba(0,0,0,0.65);}
@keyframes dtpEnter{from{opacity:0;transform:translateY(6px);}to{opacity:1;transform:none;}}
.main-layout{animation:dtpEnter .5s ease both;}

/* === Recal landing (Editorial Luxe) : titres serif Fraunces + wordmark or === */
.arlib-list-title,.br-list-title,.inst-title,.settings-title,.settings-section-title,.np-filter-title,.sbm-title,.sbs-narr-title,.prep-section-title,.prep-watchlist-title,.prep-risks-title,.prep-topbar-title,.wip-title{font-family:var(--tight),sans-serif !important;letter-spacing:-.005em;}
.sbs-narr-title{color:var(--text) !important;}   /* titre narratif en BLANC (demande) — fini l'or */
.logo-text{background:linear-gradient(100deg,#f0d27a,#cfa233 55%,#b8860b);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;}

/* === Dashboard Apercu - en-tetes de panneaux premium (Minimal Epure, structure inchangee) === */
.sym-phead{height:34px;padding:0 13px;border-bottom:1px solid var(--border,var(--border));background:linear-gradient(180deg,rgba(255,255,255,0.022),rgba(255,255,255,0));}
.sym-ptitle{font-size:var(--fs-title);font-weight:var(--fw-semibold);letter-spacing:var(--ls-caps);text-transform:uppercase;color:#d4d7dd;display:inline-flex;align-items:center;}
.sym-ptitle::before{content:'';display:inline-block;width:3px;height:.82em;border-radius:2px;background:var(--orange,#e3b23a);margin-right:8px;opacity:.85;flex:0 0 auto;}

/* === Polish apparence #2 : finition globale + profondeur des panneaux === */
::selection{background:rgba(227,178,58,0.26);color:#ffffff;}
::-webkit-scrollbar-thumb:hover{background:var(--orange-dim,#b8860b);}
.sym-panel{background:linear-gradient(180deg,#131419,#0e0f12);box-shadow:0 6px 18px -12px rgba(0,0,0,0.55);}

/* === Habillage institutionnel 'Verre brosse + filet or' (signature A) - panneaux widgets === */
/* Panneaux widgets PLATS institutionnels : fond var(--bg2), bordure fine var(--border), coins 4px (demande : data en avant, design s'efface) */
.sym-panel,.sym-bz-col,.sbs-panel,.inst-panel,.dmx-panel,.clocks-panel{background:var(--bg);border:1px solid var(--border);border-radius:4px;box-shadow:none;transition:border-color var(--t-fast) var(--ease);}   /* fond = celui du calendrier/panneau droit (var(--bg)) — demande : meme noir partout */
.sym-panel:hover,.sym-bz-col:hover,.sbs-panel:hover,.inst-panel:hover,.dmx-panel:hover,.clocks-panel:hover,.ai-insights-card:hover,.ai-ins-pair:hover{border-color:var(--border2);box-shadow:none;transform:none;}
.sym-ptitle,.panel-title,.chart-header-title,.sbs-head-title,.np-filter-title,.sbm-title,.inst-title{text-transform:uppercase;letter-spacing:.085em;font-weight:var(--fw-semibold);}
.panel-title::before,.chart-header-title::before,.sbs-head-title::before,.np-filter-title::before,.sbm-title::before,.inst-title::before{content:'';display:inline-block;width:3px;height:.82em;border-radius:2px;background:var(--orange,#e3b23a);margin-right:7px;vertical-align:-1px;opacity:.85;}
body{font-variant-numeric:tabular-nums;}

/* === Habillage institutionnel - lignes de listes (look 'releve bancaire') === */
.econ-group-row,.sym-bz-row,.wac-row,.prep-item,.prep-watchlist-row,.arl-row,.bank-row,.sbs-cdd-item,.news-item{transition:background .14s ease,box-shadow .14s ease;}
.econ-group-row:hover,.sym-bz-row:hover,.wac-row:hover,.prep-item:hover,.prep-watchlist-row:hover,.arl-row:not(.arl-row--weekly):hover,.bank-row:not(.bank-row--active):hover,.sbs-cdd-item:hover{background:var(--row-hover);}  /* hover sobre neutre unifie sur la ligne de news (fini le degrade or) */
.news-item:hover{box-shadow:inset 2px 0 0 rgba(227,178,58,.55);}

/* === Jauge de force LISSE + axe or === */
.meter-brick{border-bottom:0;}
.meter-brick--pos{background:rgba(0,230,118,.92);box-shadow:inset 0 0 7px rgba(0,230,118,.22);}
.meter-brick--neg{background:rgba(255,61,0,.92);box-shadow:inset 0 0 7px rgba(255,61,0,.2);}
.meter-half-top .meter-brick--pos[data-idx="0"]{box-shadow:inset 0 0 7px rgba(0,230,118,.22);}
.meter-half-bot .meter-brick--neg[data-idx="0"]{box-shadow:inset 0 0 7px rgba(255,61,0,.2);}
/* === Matrice Smart Bias en TUILES de marque === */
.sbm-grid{border-collapse:separate;border-spacing:3px;}
.sbm-grid th,.sbm-grid td{border:none;}
.sbm-cell{border-radius:5px;box-shadow:inset 0 1px 0 rgba(255,255,255,.06);}
.sbm-vbull{background:linear-gradient(180deg,#13a374,#0b7250);}
.sbm-bull{background:linear-gradient(180deg,#17b083,#0e8a62);}
.sbm-neut{background:linear-gradient(180deg,#454c5a,#363c47);}
.sbm-bear{background:linear-gradient(180deg,#e0524a,#b23128);}
.sbm-vbear{background:linear-gradient(180deg,#c23a30,#8f231c);}
.sbm-concl.sbm-vbull,.sbm-concl.sbm-bull{background:linear-gradient(180deg,#15b083,#0c7a56);}
.sbm-concl.sbm-bear,.sbm-concl.sbm-vbear{background:linear-gradient(180deg,#e0524a,#a82a22);}
.sbm-concl.sbm-neut{background:linear-gradient(180deg,#454c5a,#363c47);}

/* === Terminal dense (clair + sombre) : widgets CARRES + COLLES === */
.sym-panel,.sym-bz-col,.sbs-panel,.inst-panel,.dmx-panel,.clocks-panel,.ai-insights-card,.ai-ins-pair,.bias-content,.arlib-list-view,.br-reader-view,.notes-panel,.np-filter-panel,.panel,.panel-news,.settings-panel{border-radius:4px !important;}
.sym-panel,.sym-bz-col,.sbs-panel,.inst-panel,.dmx-panel,.clocks-panel{box-shadow:var(--panel-depth) !important;transform:none !important;}   /* LOT 8 : profondeur TRES legere (ombre douce + lisere haut) — a valider */
.sym-panel:hover,.sym-bz-col:hover,.sbs-panel:hover,.inst-panel:hover,.dmx-panel:hover,.clocks-panel:hover{transform:none !important;}
.sym-grid{padding:0 !important;grid-template-columns:var(--sym-col,1fr) 1px minmax(0,1fr) !important;grid-template-rows:var(--sym-row,1fr) 1px minmax(0,1fr) !important;}
.sbm-grid{border-collapse:collapse !important;border-spacing:0 !important;}
.sbm-grid th,.sbm-grid td{border:1px solid var(--border,var(--border)) !important;}
.sbm-cell{border-radius:0 !important;box-shadow:none !important;}
/* Accent OR de la ligne de conclusion (radar) — re-impose le bord gauche dore que la grille 1px ecrasait */
.sbm-overall .sbm-ind{border-left:3px solid var(--orange) !important;background:#1a1a1f !important;}

/* === Mode clair 'Solar' : cream chaud + texture pointillee + accent or chaud === */
body.theme-light{
  --bg:#f4f1ea; --bg1:#ffffff; --bg2:#faf8f2; --bg3:#efeae0; --bg4:#e8e2d4; --bg5:#ddd6c6;
  --border:#e7e1d3; --border2:#dad3c0; --border3:#cabfa8;
  --text:#241f17; --text2:#5c5347; --text3:#8a8170; --text4:#b3aa97;
  --orange:#b8860b; --orange-dim:#946c08;
  /* Remap des tokens de la refonte design en CLAIR (corrige filets/hover/cartes de lignes partout d'un coup) */
  --hud-line:rgba(0,0,0,0.10); --grid-line-v:rgba(0,0,0,0.06);
  --row-sep:1px solid rgba(0,0,0,0.07); --row-hover:#efeae0; --row-card-bg:#faf8f2; --row-card-bd:1px solid rgba(0,0,0,0.10); --row-detail-fg:#5c5347;
  --panel-depth:0 1px 2px rgba(60,45,15,0.07), inset 0 1px 0 rgba(255,255,255,0.6);
  background-image:radial-gradient(rgba(110,90,50,.06) 1px, transparent 1px);
  background-size:18px 18px;
}
body.theme-light .sym-panel,body.theme-light .sym-bz-col,body.theme-light .sbs-panel,body.theme-light .inst-panel,body.theme-light .dmx-panel,body.theme-light .clocks-panel{background:#ffffff !important;box-shadow:0 1px 0 rgba(184,134,11,.18),0 2px 8px -4px rgba(60,45,15,.08) !important;}

/* === Carte sessions Leaflet (satellite) - marqueurs villes === */
#am5-map .leaflet-container{background:#0b0c0f;font-family:var(--font-ui);outline:none;}
/* Terminateur jour/nuit : bord FLOUTÉ -> ombre crépusculaire douce/réaliste (au lieu d'un bord net) */
.lf-terminator{filter:blur(6px);}
#am5-map .leaflet-control-attribution{background:rgba(11,12,15,.6);color:#7e8189;font-size:9px;}
#am5-map .leaflet-control-attribution a{color:#9aa0ac;}
.lf-city-wrap{pointer-events:none;}
/* Badge session 2 lignes : [dot] HH:MM Ville / compte à rebours. Ouverte = allumé (bordure verte),
   imminente (<45 min) = dot/texte ambre, fermée = éteint. AUCUNE animation (les clignotements gênent). */
.lf-city{display:inline-flex;flex-direction:column;gap:2px;white-space:nowrap;transform:translate(-50%,-50%);background:rgba(13,14,17,.88);border:1px solid #2a2e37;border-radius:8px;padding:7px 14px 6px;font-family:var(--font-mono,monospace);font-size:12.5px;color:#e6e8ec;box-shadow:0 2px 10px rgba(0,0,0,.6);backdrop-filter:blur(3px);-webkit-backdrop-filter:blur(3px);}
.lf-city .lf-row{display:flex;align-items:center;gap:7px;}
.lf-city b{color:#e3b23a;font-weight:var(--fw-bold);}
.lf-city .lf-name{color:#aeb2bb;}
.lf-city .lf-dot{width:7px;height:7px;border-radius:50%;flex:0 0 auto;}
.lf-city .lf-sub{font-size:10.5px;letter-spacing:.02em;color:#8a8f98;padding-left:14px;}
/* OUVERTE : badge allumé — liseré + halo verts, ville en blanc, compte à rebours vert doux */
.lf-open{border-color:rgba(0,230,118,.5);background:rgba(9,19,14,.92);box-shadow:0 2px 12px rgba(0,0,0,.6),0 0 10px rgba(0,230,118,.14);}
.lf-open .lf-dot{background:#00e676;box-shadow:0 0 6px rgba(0,230,118,.8);}
.lf-open .lf-name{color:#eef1f5;}
.lf-open .lf-sub{color:rgba(0,230,118,.75);}
/* FERMÉE : badge éteint (plus discret qu'avant pour creuser l'écart avec les ouvertes) */
.lf-closed{opacity:.55;}
.lf-closed .lf-dot{background:#6b7280;}
/* OUVERTURE IMMINENTE (<45 min) : cue ambre discret, badge un peu moins éteint */
.lf-soon{opacity:.85;border-color:rgba(255,179,0,.4);}
.lf-soon .lf-dot{background:#ffb300;box-shadow:0 0 5px rgba(255,179,0,.6);}
.lf-soon .lf-sub{color:rgba(255,179,0,.8);}

/* === Popup sentiment : description structuree (verdict + lecture + pour trader) === */
.rp-d-lead{font-size:13px;font-weight:var(--fw-bold);color:#e9eaed;margin:0 0 10px;line-height:1.35;}
.rp-d-row{display:flex;gap:9px;align-items:baseline;margin:0 0 5px;}
.rp-d-k{flex:0 0 68px;font-size:8.5px;font-weight:var(--fw-bold);letter-spacing:.07em;text-transform:uppercase;color:#e3b23a;}
.rp-d-v{flex:1;font-size:11.5px;color:#aeb4bd;line-height:1.45;}

/* === Carte sessions : leger effet 3D (inclinaison perspective) === */
#am5-map{overflow:hidden;}   /* carte à PLAT : le transform 3D (perspective/rotateX) créait un artefact (trait noir) sur le rendu SVG Leaflet */
/* tilt 3D tres leger applique directement sur #am5-map ; clip assure par .right-tab-panel overflow:hidden */

/* === Widgets droits (COT/DMX/Saisonnalite) : en-tetes alignes sur l'identite desk (tick or + capitales) + boutons carres === */
.cot-header-label,.dmx-header-title{text-transform:uppercase;letter-spacing:.085em;font-weight:var(--fw-semibold);}
.cot-header-label::before,.dmx-header-title::before{content:'';display:inline-block;width:3px;height:.8em;border-radius:2px;background:var(--orange,#e3b23a);margin-right:7px;vertical-align:-1px;opacity:.85;}
.cot-type-btn,.dmx-tf-btn,.dmx-sort-select{border-radius:0 !important;}

/* === Polish panneau reglages - identite desk (or + carre + etats soignes) === */
.pd-section-icon-wrap{border-radius:2px !important;}
.pd-badge{border-radius:2px !important;}
.pd-section-trigger:hover .pd-section-icon-wrap,
.pd-section-trigger.pd-open .pd-section-icon-wrap{border-color:rgba(227,178,58,.5) !important;color:#e3b23a !important;background:rgba(227,178,58,.09) !important;}
.pd-section-trigger.pd-open{box-shadow:inset 3px 0 0 var(--orange,#e3b23a);background:rgba(227,178,58,.05) !important;}
.pd-section-trigger:hover{background:rgba(227,178,58,.04) !important;}
.pd-section-trigger.pd-open .pd-section-arrow{color:#e3b23a !important;}

/* Bouton AI topbar : icone + label IA (FR) / AI (EN via i18n) */
.topbar-icon--ai{width:auto !important;gap:5px;padding:0 9px;}
.ai-spark-txt{font-size:12px;font-weight:var(--fw-bold);color:#00e676;letter-spacing:.02em;line-height:1;}

/* Onglet nav actif : trait dore RESTAURE (demande utilisateur — souligne l'onglet actif facon CALENDRIER) */
.nav-item{position:relative;}
.nav-item--active:not(.nav-item--symbol),.nav-item.active:not(.nav-item--symbol){box-shadow:none !important;}
.nav-item--active:not(.nav-item--symbol)::after,.nav-item.active:not(.nav-item--symbol)::after{content:'' !important;position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--orange,#e3b23a) !important;border:0 !important;border-radius:2px 2px 0 0;transform-origin:center;animation:navUnderlineIn var(--t-med) var(--ease-out) both;}
@keyframes navUnderlineIn{from{transform:scaleX(0);opacity:.35;}to{transform:scaleX(1);opacity:1;}}
@media (prefers-reduced-motion: reduce){.nav-item--active:not(.nav-item--symbol)::after,.nav-item.active:not(.nav-item--symbol)::after{animation:none;}}

/* === Mode clair FULL WHITE — panneau droit (horloge, onglets, conteneurs graphiques) === */
body.theme-light .right-tab-panel,
body.theme-light .clocks-bar,
body.theme-light .amchart-container,
body.theme-light .strength-charts-row,
body.theme-light .right-panel-tabs,
body.theme-light .right-content,
body.theme-light .chart-header { background: var(--bg1) !important; }
body.theme-light .clock-item { background: #ffffff !important; }
body.theme-light .clock-time,
body.theme-light .clock-date,
body.theme-light .clock-city,
body.theme-light .clock-country,
body.theme-light .clock-meta,
body.theme-light .clock-tz,
body.theme-light .chart-header-title { color: var(--text) !important; }
body.theme-light .clock-gmt { color: var(--text2) !important; }

/* === (1) Onglet droit actif -> DORE (coherent avec la nav principale) === */
.right-tab--active{color:var(--orange,#e3b23a) !important;background:transparent !important;}
.right-tab--active::after{content:'';position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--orange,#e3b23a);border-radius:2px 2px 0 0;}   /* meme soulignement or que la nav principale */

/* ═══════════════════ ONGLETS — MODELE UNIFIE (coherence absolue, terminal institutionnel) ═══════════
   UN seul design pour TOUTES les barres d'onglets : nav principale (.nav-item), sous-onglets de widgets
   (.right-tab), micro-onglets de periodes (.stf-btn/.cot-type-btn/.dmx-tf-btn), sous-onglets symbole
   (.sym-subtab). MAJUSCULES + petit + letter-spacing. Inactif = gris discret, sans bordure. Hover = texte
   plus clair + tres leger fond translucide. Actif = BLANC PUR + gras + soulignement OR (l'or n'est PLUS
   sur le texte ni le fond d'un onglet, uniquement le marqueur inferieur). */
.nav-item, .right-tab, .stf-btn, .cot-type-btn, .dmx-tf-btn, .sym-subtab { text-transform: uppercase; letter-spacing: .06em; }
.stf-btn, .cot-type-btn, .dmx-tf-btn { position: relative; background: transparent !important; border: 0 !important; border-radius: 0 !important; color: var(--text3) !important; font-weight: var(--fw-semibold) !important; }
.stf-btn:not(.stf-btn--active):hover, .cot-type-btn:not(.cot-type-btn--active):hover, .dmx-tf-btn:not(.dmx-tf-btn--active):hover { color: var(--text2) !important; background: rgba(255,255,255,.045) !important; }
.right-tab--active, .stf-btn--active, .cot-type-btn--active, .dmx-tf-btn--active, .nav-item--active:not(.nav-item--symbol), .nav-item.active:not(.nav-item--symbol), .sym-subtab--active, .wdg-lay.on { color: var(--tab-on, #fff) !important; font-weight: var(--fw-bold) !important; background: transparent !important; }
/* --tab-on : le blanc pur des onglets actifs est illisible sur fond clair. Un seul token, donc les
   DEUX barres (desk et Mon Desk) et tous les onglets du produit basculent ensemble. */
:root { --tab-on: #fff; }
html[data-theme="light"] { --tab-on: #17181d; }
.stf-btn--active::after, .cot-type-btn--active::after, .dmx-tf-btn--active::after { content: ''; position: absolute; left: 0; right: 0; bottom: 0; height: 2px; background: var(--orange); border-radius: 2px 2px 0 0; }

/* EXTENSION — memes regles pour TOUS les autres onglets/sous-onglets/periodes du desk (Institutions,
   Journal, sections news, timeframes/types/indicateurs de graphiques). Les filtres semantiques
   (.cal-imp-btn = impact) et toggles (.sea-cfg-tab--on) sont volontairement exclus. */
.inst-tab, .jr-tab, .np-tab, .expand-tab, .tf-btn, .ct-btn, .cot-tf-btn, .ind-btn { text-transform: uppercase; letter-spacing: .06em; position: relative; background: transparent !important; border: 0 !important; border-radius: 0 !important; color: var(--text3) !important; font-weight: var(--fw-semibold) !important; }
.inst-tab:not(.inst-tab--active):hover, .jr-tab:not(.jr-tab--active):hover, .np-tab:not(.np-tab--active):hover, .expand-tab:not(.expand-tab--active):hover, .tf-btn:not(.tf-btn--active):hover, .ct-btn:not(.ct-btn--active):hover, .cot-tf-btn:not(.cot-tf-btn--active):hover, .ind-btn:not(.ind-btn--active):hover { color: var(--text2) !important; background: rgba(255,255,255,.045) !important; }
.inst-tab--active, .jr-tab--active, .np-tab--active, .expand-tab.expand-tab--active, .tf-btn--active, .ct-btn--active, .cot-tf-btn--active, .ind-btn--active { color: #fff !important; font-weight: var(--fw-bold) !important; background: transparent !important; }
.inst-tab--active::after, .jr-tab--active::after, .np-tab--active::after, .expand-tab.expand-tab--active::after, .tf-btn--active::after, .ct-btn--active::after, .cot-tf-btn--active::after, .ind-btn--active::after { content: ''; position: absolute; left: 0; right: 0; bottom: 0; height: 2px; background: var(--orange); border-radius: 2px 2px 0 0; }

/* === (2) Noms de widgets UNIFORMES (meme taille/police, MAJUSCULES) SANS tick dore a gauche === */
/* Extinction du repère doré d'avant-titre (19/08, demande user). `.wdg-title` y a été AJOUTÉ le
   02/09 : il manquait, et c'est par là que le trait est revenu sur les cartes du desk. */
.sym-ptitle::before,.panel-title::before,.chart-header-title::before,.sbs-head-title::before,.np-filter-title::before,.sbm-title::before,.inst-title::before,.cot-header-label::before,.dmx-header-title::before,.wdg-title::before{display:none !important;}
/* TITRES DE VUES — SOURCE DE VÉRITÉ UNIQUE (demande user 27/07 « cohérence et homogénéité, met partout
   pareil ») : TOUS les titres de vues du nav du haut partagent CETTE règle → Inter Tight, MAJUSCULES,
   11.5px, semibold, 0.08em. Ajoutés aux classes historiques : .cal-title/.fxl-title (déjà conformes, mis
   ici pour centraliser) + les ex-outliers .br-list-title (était mono/casse normale), .arlib-list-title
   (était serif Fraunces, cf. override supprimé), .wa-title/.wa3-ptitle (étaient mono). */
.sym-ptitle,.panel-title,.chart-header-title,.sbs-head-title,.np-filter-title,.sbm-title,.inst-title,.cot-header-label,.dmx-header-title,.cal-title,.fxl-title,.br-list-title,.arlib-list-title,.wa-title,.wa3-ptitle{font-size:var(--fs-title) !important;font-weight:var(--fw-semibold) !important;letter-spacing:var(--ls-caps) !important;text-transform:uppercase !important;}
/* Alignement COMPLET des titres restants (widgets + volets + bibliotheque serif) sur "Fil d'actualite en direct" */
.ai-insights-title,.wa-title,.arlib-list-title,.sqwk-title,.ai-head-title,.np-title,.wa3-ptitle{font-family:var(--tight) !important;font-size:var(--fs-title) !important;font-weight:var(--fw-semibold) !important;letter-spacing:var(--ls-caps) !important;text-transform:uppercase !important;}
.ai-insights-title::before,.wa-title::before,.arlib-list-title::before,.sqwk-title::before,.ai-head-title::before,.np-title::before{display:none !important;}

/* === (3) Premium "leger" — Eye Comfort / Command Center : glow accent discret + transitions fluides (150-200ms) === */
/* glow (halo) des onglets actifs RETIRE — plus net/institutionnel (couleur or + soulignement suffisent) */
.nav-item,.right-tab,.news-item,.topbar-icon,.cot-type-btn,.dmx-tf-btn,button{transition:color var(--t-fast) var(--ease),background-color var(--t-fast) var(--ease),box-shadow var(--t-fast) var(--ease),border-color var(--t-fast) var(--ease),transform var(--t-fast) var(--ease);}

/* === Premium "léger" dosé — Eye Comfort / Command Center (densité & flush conservés) === */
/* Profondeur douce + délimitation des cartes : fin filet clair en haut (pas de gaps entre panneaux collés) */
.panel,.right-tab-panel,.sym-panel,.sbs-panel,.inst-panel,.dmx-panel,.clocks-panel,.view-panel,.np-panel,.ai-panel,.sqwk-panel,.chat-panel{box-shadow:inset 0 1px 0 rgba(255,255,255,.04);}
/* Sheen "verre" très subtil sur les en-têtes de panneaux */
.panel-header,.chart-header,.sym-pheader,.sbs-head,.cot-header-bar,.dmx-header-bar,.ai-head{background-image:linear-gradient(180deg,rgba(255,255,255,.03),transparent 72%);}
/* Verre (flou léger) sur les surfaces FLOTTANTES uniquement : menus, dropdowns, toasts */
.sym-dd,.dtpsel-panel,.sbs-cdd-menu,.dtp-toast,.np-filter-menu{backdrop-filter:blur(9px) saturate(1.04);-webkit-backdrop-filter:blur(9px) saturate(1.04);}
/* Mode clair : filet sombre discret (au lieu du blanc) pour garder la délimitation */
body.theme-light .panel,body.theme-light .right-tab-panel,body.theme-light .sym-panel,body.theme-light .sbs-panel,body.theme-light .inst-panel,body.theme-light .dmx-panel,body.theme-light .clocks-panel,body.theme-light .view-panel{box-shadow:inset 0 1px 0 rgba(0,0,0,.04) !important;}

/* === Vert/rouge IDENTIQUES sur Barometre / COT / DMX -> standard de marque #00e676 / #ff3d00 === */
.cot-dot--l,.dmx-bar-l,.dmx-legend-long-dot{background:#00e676 !important;}
.cot-dot--s,.dmx-bar-s,.dmx-legend-short-dot{background:#ff3d00 !important;}

/* === News : refonte "flat" epuree (terminal pro) — texte medium, separateurs tres discrets, fond froid, alerte rouge legere === */
.news-item .news-headline { font-weight: 450 !important; }                                  /* texte medium/standard, plus de gras massif */
.news-item { border-bottom: 1px solid rgba(255,255,255,0.075) !important; background: #121317 !important; }  /* ⚠️ separateur RELEVE a 7,5% (21/08) : cette regle en !important ecrasait le token --row-sep et rendait le filet invisible (retour user « j ai pas l impression de le voir ») ; ~18 niveaux d ecart = visible mais sobre */
.news-item:hover { background: #16171c !important; }
.news-item--urgent, .news-item--breaking { background: rgba(255,61,0,0.085) !important; border-bottom: 1px solid rgba(255,61,0,0.10) !important; }  /* fond de BASE = ancienne teinte de survol (rouge deja bien visible au repos) */
.news-item--urgent:hover, .news-item--breaking:hover { background: rgba(255,61,0,0.13) !important; }  /* survol : rouge un cran + accentue par-dessus la base */

/* === Vert/rouge IDENTIQUES (complet COT/DMX -> standard de marque #00e676 / #ff3d00) === */
.cot-dot--l, .dmx-bar-l, .dmx-legend-long-dot { background: #00e676 !important; }
.cot-dot--s, .dmx-bar-s, .dmx-legend-short-dot { background: #ff3d00 !important; }
.cot-float--long, .cot-green { color: #00e676 !important; }
.cot-float--short, .cot-red { color: #ff3d00 !important; }

/* === Dates calendrier en FR : majuscule initiale du jour (jeudi -> Jeudi) === */
.cal-day-sep, .cal-day-sep td, .date-header, .wac-day { text-transform: capitalize !important; }

/* === Aucun trait or a gauche (barre hover/actif) — demande utilisateur === */
.pd-section-trigger.pd-open,
.econ-group-row:hover,.sym-bz-row:hover,.wac-row:hover,.prep-item:hover,.prep-watchlist-row:hover,.arl-row:not(.arl-row--weekly):hover,.bank-row:not(.bank-row--active):hover,.sbs-cdd-item:hover,
.news-item:hover { box-shadow: none !important; }

/* === Mode clair : panneau reglages (profil / Apparence / Abonnement…) FULL WHITE === */
body.theme-light .pd-drawer,
body.theme-light .pd-body,
body.theme-light .pd-section,
body.theme-light .pd-section-trigger,
