body.theme-light .meter-tip-name{color:#241f17;}
/* — Volet Biais (sbs) : en-tete + dropdowns sombres — */
body.theme-light .sbs-head{background:#f4f1ea !important;}
body.theme-light .sbs-head-title{color:#241f17;}
body.theme-light .sbs-dd,body.theme-light .sbs-cdd{background:#ffffff !important;color:#241f17;border-color:#dad3c0;}
body.theme-light .sbs-cdd-caret,body.theme-light .sbs-close{color:#8a8170;}
/* — Cartes/inputs sombres en dur eparses — */
body.theme-light .season-th,body.theme-light .season-month,body.theme-light .gew-key,body.theme-light .cdv,body.theme-light .br-ext-card,body.theme-light .chat-input,body.theme-light #chat-search-input{background:#faf8f2 !important;color:#241f17 !important;}
body.theme-light .rtc-tbl th{background:#f4f1ea;color:#241f17;}
body.theme-light .bank-detail-row td{background:#f7efe6 !important;}
/* — Bibliotheque Analyst : cartes lues + bordures sombres — */
body.theme-light .arlib-card--read{background:#efeae0 !important;border-color:#e7e1d3;}
body.theme-light .arlib-card--read:hover{background:#e8e2d4 !important;}
body.theme-light .arlib-back-btn:hover{background:#efeae0;color:#241f17;}

/* ═══ Indicateurs "live"/"Direct" : le POINT (.live-dot) est REACTIVE (juil. 2026, demande user)
   avec un pulse discret opacite seule (cf. keyframes pulse-green adoucis). Les libelles/badges texte
   (Direct / DIRECT / En direct / bandeau squawk) restent masques en attendant leur refonte. ═══ */
.live-label, .cal-live-badge, .wa3-live, .sqwk-live-note { display: none !important; }

/* ═══ Premium LOT 6 : focus CLAVIER accessible on-brand (anneau or net, sans outline natif) ═══
   N'apparait QU'au focus clavier (:focus-visible) — la souris n'affiche aucun anneau. */
button:focus-visible, a:focus-visible, input:focus-visible, textarea:focus-visible, select:focus-visible,
summary:focus-visible, [tabindex]:focus-visible, .nav-item:focus-visible, .right-tab:focus-visible,
.news-item:focus-visible, .cal-row:focus-visible, .stf-btn:focus-visible, .tag:focus-visible,
.cot-type-btn:focus-visible, .dtpsel-btn:focus-visible {
  outline: none !important;
  box-shadow: var(--focus-ring) !important;
}

/* ═══════════════ UX — micro-interactions & etats (Phase 1, additif, HUD dense) ═══════════════
   Feedback d'appui sur TOUS les boutons, boutons desactives assombris, focus clavier des controles
   <div>, hover de panel ravive (--border2 pointait sur --border = invisible), reduced-motion global.
   Zero impact layout — tout est additif. */

/* Feedback d'APPUI : le controle s'enfonce de 1px (transition transform deja fournie l.10048). */
.nav-item:active,.right-tab:active,.stf-btn:active,.cot-type-btn:active,.dmx-tf-btn:active,
.inst-tab:active,.jr-tab:active,.np-tab:active,.tf-btn:active,.ct-btn:active,.ind-btn:active,
.sym-subtab:active,.topbar-icon:active,.toolbar-select:active,.cal-imp-btn:active,.dtpsel-btn:active,
.load-more-btn:active,.br-back-btn:active,.arlib-back-btn:active,.pd-btn:active,.jr-btn:active,
.ai-send:active,.chat-send:active,button:active{transform:translateY(1px);}
button:disabled:active,button[disabled]:active{transform:none;}

/* Boutons DESACTIVES (JS pose disabled sur envoi/sauvegarde sans style aujourd'hui = manque visuel). */
button:disabled,button[disabled],.jr-btn:disabled,.pd-btn:disabled,.ai-send:disabled,
.chat-send:disabled,.load-more-btn:disabled,.dtpsel-btn:disabled{opacity:.45 !important;cursor:default !important;pointer-events:none;}

/* Focus CLAVIER on-brand pour les controles <div>/<span> oublies par la regle globale (l.10149). */
.topbar-icon:focus-visible,.toolbar-select:focus-visible,#section-filter-btn:focus-visible,.section-filter-btn:focus-visible{outline:none !important;box-shadow:var(--focus-ring) !important;}

/* Hover de PANEL ravive : filet or tres discret (avant : --border2 == --border = invisible). Pas de lift. */
.sym-panel:hover,.sym-bz-col:hover,.sbs-panel:hover,.inst-panel:hover,.dmx-panel:hover,.clocks-panel:hover{border-color:rgba(227,178,58,.20) !important;}

/* prefers-reduced-motion : coupe les mouvements residuels partout (couverture globale). */
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation-duration:.001ms !important;animation-iteration-count:1 !important;transition-duration:.001ms !important;scroll-behavior:auto !important;}
}

/* ═══════════════ Skeleton loaders — shimmer sombre PARTAGE (perception de vitesse) ═══════════════
   Base reutilisable .dtp-skel + templates par widget. Le shimmer se fige en reduced-motion (regle globale ci-dessus). */
@keyframes dtpSkelShimmer{from{background-position:200% 0;}to{background-position:-200% 0;}}
.dtp-skel{display:block;height:9px;border-radius:3px;background:linear-gradient(90deg,#141416 25%,#1e1e22 37%,#141416 63%);background-size:400% 100%;animation:dtpSkelShimmer 1.4s ease-in-out infinite;}
/* FX List : lignes squelette calees sur les colonnes (barre plus large a gauche = colonne SYMBOL) */
.fxl-skel-row .fxl-td{border-bottom:var(--row-sep);}
.fxl-skel-row .dtp-skel{width:58%;margin:0 auto;}
.fxl-skel-row .fxl-td--left .dtp-skel{margin-left:0;width:74%;}
.fxl-skel-row .fxl-td--right .dtp-skel{margin-left:auto;margin-right:0;}

/* ═══════════════ Graphes amCharts : reveal "premium" (jamais de courbes qui se construisent) ═══════════════
   .am-hold = la div amCharts se dessine en opacity:0 (cachee). .chart-skel = overlay OPAQUE shimmer par-dessus
   la zone (parent en position:relative) qui couvre le trace, puis disparait en fondu -> le graphe apparait fini. */
.am-hold{opacity:0 !important;}
/* overlay OPAQUE pose EN ENFANT du conteneur amCharts (couvre exactement le graphe) ; z-index 7 = au-dessus du grip de zoom (6) et du readout jauge (5) le temps du build */
.chart-skel{position:absolute;inset:0;z-index:7;background:var(--bg);overflow:hidden;opacity:1;transition:opacity .5s ease;pointer-events:none;border-radius:inherit;}
.chart-skel::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,transparent 20%,rgba(227,178,58,.045) 42%,rgba(255,255,255,.03) 50%,transparent 78%);background-size:300% 100%;animation:dtpSkelShimmer 1.5s ease-in-out infinite;}
.chart-skel--hide{opacity:0;}

/* ═══════════════ Skeletons des tableaux/listes (epousent la structure reelle -> zero reflow) ═══════════════ */
/* Table Banques : lignes squelette calees sur les 10 colonnes reelles */
.bank-skel-row td{border-bottom:var(--row-sep);}
.bank-skel-row .dtp-skel{width:62%;}
.bank-skel-row .bank-name .dtp-skel{width:82%;}
.bank-skel-row .bank-num .dtp-skel{width:70%;margin-left:auto;}
.bank-skel-row .bank-date .dtp-skel{width:56%;}
.bank-skel-row .bank-exp .dtp-skel,
.bank-skel-row .bank-chart-cell .dtp-skel{width:14px;margin:0 auto;}
/* Cartes TAUX : squelette cale sur .rtc (head + 5 metriques + 3 barres) */
.rtc-skel .rtc-head .dtp-skel{height:11px;}
.rtc-skel .rtc-m{gap:4px;}
.rtc-skel .rtc-dist{gap:8px;}
.rtc-skel .dtp-skel{opacity:.85;}
/* Matrice Radar de Biais : squelette cale sur la grille (en-tetes devises + cellules) */
.sbm-grid .sbm-ind .dtp-skel{width:70%;height:8px;}
.sbm-skel-cur{width:34px;height:8px;margin:0 auto;}
.sbm-skel-cell .dtp-skel{width:64%;height:8px;margin:0 auto;}
.sbm-skel-cell{background:transparent !important;}
/* Calendrier : lignes squelette calees sur les 10 colonnes .cal-table */
.cal-skel-row td{border-bottom:var(--row-sep,1px solid var(--border));}
.cal-skel-row .dtp-skel{width:62%;margin:0 auto;}
.cal-skel-row .cth-event .dtp-skel{width:88%;margin-left:0;}
.cal-skel-row .cth-time  .dtp-skel{width:70%;margin-left:0;}
.cal-skel-row .cth-curr  .dtp-skel{width:60%;}
.cal-skel-sep .dtp-skel{width:180px;height:8px;}
/* Semaine a Venir : placeholders cales sur .wa-wrap */
.wa-skel-wrap .wa-skel-head{width:190px;height:14px;}
.wa-skel-chart{position:relative;min-height:60px;}
.wa-skel-chart .dtp-skel{position:absolute;inset:6px;height:auto;border-radius:4px;}
.wa-skel-day .wa-node{display:flex;flex-direction:column;gap:4px;}
.wa-skel-dow{width:26px;height:8px;} .wa-skel-date{width:20px;height:11px;} .wa-skel-mon{width:26px;height:8px;}
.wa-skel-title{width:60%;height:11px;} .wa-skel-imp{width:74px;height:14px;border-radius:3px;}
.wa-skel-line{width:100%;height:8px;margin-top:6px;} .wa-skel-line--short{width:65%;}
/* Catalogues Analyste & Institution : lignes squelette calees sur .arlib-table */
.arl-skel-row td{border-bottom:var(--row-sep,1px solid var(--border));}
.arl-skel-bm{width:12px;height:13px;border-radius:2px;margin:0 auto;}
.arl-skel-row .arl-c-date .dtp-skel{width:56px;height:9px;}
.arl-skel-ico{width:13px;height:13px;border-radius:2px;flex:0 0 auto;}
.arl-skel-ttl{width:min(78%,420px);height:10px;}
.arl-skel-inst{width:20px;height:20px;border-radius:50%;margin-left:auto;}

/* ═══════════════ Responsive mobile — reader Institutions (PDF) + widget Force des Devises ═══════════════ */
@media (max-width: 768px){
  /* (A) Vue MARCHES / « Force des Devises » : le TITRE du widget doit rester visible — il etait ecrase
     par la barre de periodes. Titre prioritaire (ne se comprime pas) + la barre se comprime/scrolle. */
  .sym-phead{ min-height: 30px; gap: 6px; }
  .sym-ptitle{ flex: 0 0 auto; white-space: nowrap; overflow: visible; }
  #sym-strength-tf{ min-width: 0; overflow-x: auto; scrollbar-width: none; }
  #sym-strength-tf::-webkit-scrollbar{ display: none; }

  /* (B) Reader Institutions : le HTML d'article des banques (Nordea/HSBC…) a des largeurs/min-width FIXES
     qui forcaient .br-document plus large que l'ecran → centre = coupe GAUCHE ET DROITE. Correctif : on
     aligne a gauche (plus de margin:auto) + on RESET tout le contenu (min-width:0 + width:auto + float:none
     + position:static + marges 0 + tables en blocs) → flux 1 colonne qui tient dans l'ecran. */
  #br-rcontent, #arlib-rcontent, #br-reader-view{ max-width: var(--vpw) !important; overflow-x: hidden !important; }
  #br-rcontent .br-document{ max-width: 100% !important; width: auto !important; min-width: 0 !important; margin: 0 !important; box-sizing: border-box; }
  #br-rcontent .br-document > *, #br-rcontent .br-doc-body, #br-rcontent .br-doc-body *, #br-rcontent .br-ing-lead, #br-rcontent .br-ing-lead * {
    max-width: 100% !important; min-width: 0 !important; width: auto !important;
    float: none !important; position: static !important;
    margin-left: 0 !important; margin-right: 0 !important;
    white-space: normal !important;               /* nowrap → wrap : LE point qui manquait (titre/cellules Nordea restaient sur 1 ligne = debordement coupe a droite) */
    overflow-wrap: anywhere; word-break: break-word; box-sizing: border-box;
  }
  #br-rcontent .br-doc-body img{ height: auto !important; }
  #br-rcontent .br-doc-body table, #br-rcontent .br-doc-body thead, #br-rcontent .br-doc-body tbody, #br-rcontent .br-doc-body tr, #br-rcontent .br-doc-body td, #br-rcontent .br-doc-body th{ display: block !important; }
  .br-rcontent--pdf{ width: 100%; }
  .br-pdf-frame{ width: 100% !important; max-width: var(--vpw); }
  .br-pdf-canvaswrap{ width: 100%; max-width: var(--vpw); }
  .br-pdf-canvas{ width: 100% !important; height: auto !important; }
}

/* ═══════════════ UX Phase 2 — FINITION : timing & easing UNIFIES + micro-interactions (additif, reversible) ═══════════════
   On re-declare la transition des elements interactifs COMMUNS avec la MEME courbe (--ease) et la MEME
   cadence (--t-fast) + les proprietes EXACTES que leur survol change deja (jamais `all`, jamais le layout).
   Les animation: (shimmers/spinners/pop badges) ne sont PAS touchees. reduced-motion (regle globale) fige le tout.
   Zero couleur/position/taille modifiee — seule la MANIERE (fluidite/vitesse) du survol change. */

/* Micro-onglets de periodes jumeaux : MEME cadence (etaient .15s/.12s/.12s disparates) */
.stf-btn, .cot-type-btn, .dmx-tf-btn, .inst-tab, .jr-tab, .np-tab, .expand-tab, .tf-btn, .ct-btn, .cot-tf-btn, .ind-btn { transition: color var(--t-fast) var(--ease), background-color var(--t-fast) var(--ease), border-color var(--t-fast) var(--ease), transform var(--t-fast) var(--ease); }

/* Onglets nav : easing premium homogene */
.nav-item { transition: color var(--t-fast) var(--ease), background-color var(--t-fast) var(--ease), transform var(--t-fast) var(--ease); }

/* toolbar-select : le survol change AUSSI la couleur du texte (elle claquait) -> on l'anime + easing premium */
.toolbar-select { transition: background var(--t-fast) var(--ease), color var(--t-fast) var(--ease), transform var(--t-fast) var(--ease); }

/* Lignes de tables/listes : survol (fond + ombre eventuelle) sur la MEME courbe partout */
.news-item, .cal-row, .bank-row, .fxl-row, .arl-row { transition: background var(--t-fast) var(--ease), box-shadow var(--t-fast) var(--ease), transform var(--t-fast) var(--ease); }

/* .wa-card : survol aligne sur .arlib-card (micro-lift + accent or de MARQUE deja utilise + press), sans toucher la def d'origine */
.wa-card { transition: border-color var(--t-med) var(--ease), background var(--t-fast) var(--ease), transform var(--t-med) var(--ease), box-shadow var(--t-med) var(--ease); }
.wa-card:hover { transform: translateY(-1px); border-color: rgba(227,178,58,.26); box-shadow: 0 8px 20px -14px rgba(0,0,0,.7); }
.wa-card:active { transform: translateY(0); }

/* Press subtil (feedback d'appui) sur les surfaces cliquables qui n'en avaient pas — coherent avec la Phase 1 */
.sym-dd-row:active, .sbs-cdd-item:active, .pd-lang-opt:active, .sea-cfg-sym:active,
.bank-row:active, .cal-row--click:active, .arl-row:active { transform: translateY(.5px); }

/* ═══════════════ UX Phase 2B — micro-anim MAJ de donnees (additif, reduced-motion safe) ═══════════════
   Fondu d'arrivee UNIFORME des tableaux (aligne sur le reveal des graphes .chart-skel) au 1er remplacement
   du skeleton par les vraies donnees ; + flash DISCRET (halo de fond bref, aucune couleur de TEXTE touchee)
   sur une valeur qui se met a jour en place. Classes posees/retirees en JS. Figees en reduced-motion. */
@keyframes dtpDataIn { from { opacity: 0; transform: translateY(3px); } to { opacity: 1; transform: none; } }
.dtp-fade-in { animation: dtpDataIn var(--t-med) var(--ease-out) both; }
@keyframes dtpFlash   { 0% { background-color: rgba(227,178,58,.16); } 100% { background-color: transparent; } }
@keyframes dtpFlashUp { 0% { background-color: rgba(0,230,118,.16);  } 100% { background-color: transparent; } }
@keyframes dtpFlashDn { 0% { background-color: rgba(255,61,0,.16);   } 100% { background-color: transparent; } }
.dtp-flash    { animation: dtpFlash   .55s var(--ease) both; border-radius: 3px; will-change: background-color; }
.dtp-flash-up { animation: dtpFlashUp .55s var(--ease) both; border-radius: 3px; will-change: background-color; }
.dtp-flash-dn { animation: dtpFlashDn .55s var(--ease) both; border-radius: 3px; will-change: background-color; }
@media (prefers-reduced-motion: reduce) { .dtp-flash, .dtp-flash-up, .dtp-flash-dn { animation: none; } }

/* ═══ News rouges (urgent/breaking) : le ROUGE ne couvre que la LIGNE de titre — la DESCRIPTION dépliée
   repasse sur le fond neutre standard (#15161b, comme les news normales dépliées). Placé en FIN de
   fichier pour battre les règles hover « background:transparent !important » (l.~1336) qui laissaient
   transparaître le rouge du parent sous les puces. Les variantes :hover sont indispensables (même
   spécificité que les règles combattues → c'est l'ordre qui tranche). ═══ */
.news-item--urgent .news-description.visible,
.news-item--breaking .news-description.visible,
.news-item--urgent:hover .news-description.visible,
.news-item--breaking:hover .news-description.visible { background: #15161b !important; }
body.theme-light .news-item--urgent .news-description.visible,
body.theme-light .news-item--breaking .news-description.visible,
body.theme-light .news-item--urgent:hover .news-description.visible,
body.theme-light .news-item--breaking:hover .news-description.visible { background: #faf8f2 !important; }

/* ═══ Champs de recherche (symboles / news / événements / catalogues) — recette UNIFIÉE (demande user
   2026-07-02) : au focus, UNE seule bordure OR nette sur le CONTENEUR + léger halo flou. L'input
   INTERNE ne porte JAMAIS son propre anneau (l'anneau or global `input:focus-visible` l.~10149 dessinait
   un rectangle doré interne EN PLUS de la bordure → double contour moche). Exemptions en FIN de fichier
   (même !important que la règle globale → l'ordre tranche). ═══ */
.cal-search-wrap:focus-within,
.arlib-search-wrap:focus-within,
.br-search-wrap:focus-within { border-color: rgba(227,178,58,.62) !important; box-shadow: none; }   /* bordure or NETTE seule — le halo flou se faisait clipper par les toolbars (liseré doré cassé sous la case, bug signalé 2026-07-02) */
/* Recherche NEWS (toolbar, zone sans cadre) : soulignement or discret au focus (pas de rectangle) */
.toolbar-search:focus-within { border-color: rgba(227,178,58,.62); background: var(--bg2); box-shadow: none; }   /* contour or NET, FIXE et complet (bordure interne = jamais clippee) */
/* Inputs internes : aucun anneau propre — la bordure or vit UNIQUEMENT sur le conteneur */
#topbar-symbol-input:focus, #topbar-symbol-input:focus-visible,
.toolbar-search input:focus, .toolbar-search input:focus-visible,
.cal-search-input:focus, .cal-search-input:focus-visible,
.arlib-search-wrap input:focus, .arlib-search-wrap input:focus-visible,
.br-search-wrap input:focus, .br-search-wrap input:focus-visible { box-shadow: none !important; outline: none !important; }

/* ═══ Finition 5% (hiérarchie + micro-interactions) ═══
   1) Événements HIGH impact du calendrier : titre en GRAS plein + blanc pur. L'ancienne règle
      (semibold #e6e8ec) était une INVERSION mesurée au banc : le titre normal est DÉJÀ semibold
      blanc pur, donc l'événement à fort impact était le plus TERNE de la colonne. Le gras (700,
      même graisse que la devise des lignes high) le fait ressortir sans changer sa taille. */
.cal-row--high td.cth-event { font-weight: var(--fw-bold); color: #ffffff; }
/* 2) Sous-onglets news (Info/Analyse/Réaction) : sensation physique au clic (press discret). */
.tag--info:active, .tag--analyse:active, .tag--reaction:active { transform: translateY(1px) scale(.985); }
@media (prefers-reduced-motion: reduce) { .tag--info:active, .tag--analyse:active, .tag--reaction:active { transform: none; } }

/* ═══ Coherence : OMBRE UNIQUE de la famille des menus flottants (dropdowns) — .sym-dd (0 18px 50px -20px),
   .dtpsel-panel (0 18px 44px -14px), .sbs-cdd-menu (0 10px 28px /.65) et .pd-lang-menu (0 10px 28px /.55)
   portaient 4 recettes differentes pour le MEME role : une seule elevation (celle du selecteur premium
   .dtpsel-panel) = meme profondeur percue partout, facon design system. ═══ */
.sym-dd, .dtpsel-panel, .sbs-cdd-menu, .pd-lang-menu { box-shadow: 0 18px 44px -14px rgba(0,0,0,.55); }

/* ═══ Calculatrice de position — mise au niveau design system (ouverture abonnés).
   Placé en FIN de fichier pour primer sur le bloc premium !important (l.~9855+). ═══ */
/* Dropdowns custom (dtpsel) du formulaire : pleine largeur + même gabarit 32px que les inputs
   (sans ce correctif ils s'affichent en boutons rétrécis inline-flex, hors gabarit). */
.calc-field .dtpsel { display: flex; width: 100%; }
.calc-field .dtpsel-btn { width: 100%; height: 32px; padding-top: 0; padding-bottom: 0; align-items: center; }
/* Press physique du bouton % / montant (aligné sur le press global des boutons) */
.calc-risk-mode:active { transform: translateY(1px); }
@media (prefers-reduced-motion: reduce) { .calc-risk-mode:active { transform: none; } }
/* Bouton « Copier » du résultat héros : accent or discret, confirmation verte sémantique */
.calc-copy { align-self: flex-start; margin-top: 6px; height: 22px; padding: 0 9px; font-size: 10px; letter-spacing: .04em; text-transform: uppercase; background: transparent; border: 1px solid rgba(227,178,58,.45); border-radius: 4px; color: var(--orange); cursor: pointer; font-weight: var(--fw-bold); transition: background var(--t-fast) var(--ease), color var(--t-fast) var(--ease), border-color var(--t-fast) var(--ease); }
.calc-copy:hover { background: rgba(227,178,58,.14); }
.calc-copy.ok { border-color: rgba(0,230,118,.5); color: #00e676; background: rgba(0,230,118,.08); }
/* État vide / erreur : message + bouton Réessayer empilés proprement */
.calc-empty { display: flex; flex-direction: column; align-items: center; gap: 8px; }

/* ═══ JOURNAL (ouverture abonnés 24,99 €) — état vide premium + finitions design system ═══
   1) État vide accueillant du Trade Log (icône or métier, titre, 2 chemins : ajout / import Notion).
   2) Chiffres : tabular-nums partout + colonnes num/money alignées à droite (lecture verticale du P&L).
   3) Transitions résiduelles en dur (.12s/.18s) recalées sur la cadence canonique --t-fast/--t-med + --ease.
   Placé en FIN de fichier (comme les autres finitions) pour battre les règles d'origine à spécificité égale. */
.jr-empty-wrap { display: flex; flex-direction: column; align-items: center; gap: 9px; max-width: 480px; margin: 0 auto; }
.jr-empty-ic { width: 50px; height: 50px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: var(--orange); background: rgba(227,178,58,.08); border: 1px solid rgba(227,178,58,.22); margin-bottom: 2px; }
.jr-empty-title { font-size: 15px; font-weight: var(--fw-bold); color: var(--text); letter-spacing: -.01em; }
.jr-empty-sub { font-size: 12px; color: var(--text3); line-height: 1.55; }
.jr-empty-actions { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; margin-top: 7px; }
.jr-c--num, .jr-c--money { text-align: right; }
.jr-cv-num, .jr-stat b, .jrd-bar-v, .jrd-ring-v { font-variant-numeric: tabular-nums; }
/* Ligne sélectionnée + survol : garder la teinte or de sélection (le --row-hover opaque l'écraserait) */
.jr-grid tbody tr.jr-row--sel:hover td { background: rgba(227,178,58,.10); }
.jr-addrow-cell { transition: color var(--t-fast) var(--ease), background var(--t-fast) var(--ease); }
.jrd-ic { transition: color var(--t-fast) var(--ease), background var(--t-fast) var(--ease); }
#jrd-overlay { transition: opacity var(--t-med) var(--ease); }
.jrd-imgblock { transition: border-color var(--t-fast) var(--ease), background var(--t-fast) var(--ease); }
.jrd-img-del { transition: opacity var(--t-fast) var(--ease); }

/* ═══════════════ RECHERCHE DE SYMBOLE SUR MOBILE (demande user) ═══════════════
   La barre était masquée sur mobile (5 règles display:none plus haut — ce bloc, EN FIN de fichier,
   gagne la cascade). Repliée = case-icône 34px tapable dans la topbar ; au FOCUS (tap) elle se déplie
   en overlay pleine largeur sur la topbar (même input #topbar-symbol-input + même dropdown #sym-dd →
   zéro JS nouveau) ; au blur (choix d'un symbole / tap ailleurs) elle se replie seule. */
@media (max-width: 768px) {
  .topbar-symbol-search {
    display: flex;
    flex: 0 0 auto; width: 34px; min-width: 34px; max-width: 34px;
    padding: 0; margin: 0 4px; justify-content: center;
  }
  .topbar-symbol-search .search-icon { pointer-events: none; }
  /* input : couvre la case (tapable) mais invisible tant que replié ; 16px = pas de zoom auto iOS au focus */
  .topbar-symbol-search input { position: absolute; inset: 0; width: 100%; opacity: 0; padding: 0; font-size: 16px; }
  .topbar-symbol-search .breaking-news-flash { display: none !important; }   /* bandeau LIVE : jamais dans la case compacte */
  .topbar-symbol-search:focus-within {
    /* ⚠️ « 50 % » se calcule sur la boite de PADDING, qui inclut le retrait d encoche : sur un
       iPhone recent, le champ deplie se posait a 58 % de hauteur, a cheval sous la barre d etat.
       On recentre sur la bande de CONTENU. Hors iOS, env vaut 0 et l on retombe exactement sur
       « top: 50% » : aucun effet ailleurs. */
    position: absolute; left: 10px; right: 10px;
    top: calc(50% + env(safe-area-inset-top, 0px) / 2); transform: translateY(-50%);
    width: auto; max-width: none; height: 36px; margin: 0; padding: 0 12px;
    justify-content: flex-start; background: var(--bg2); z-index: 600;
    border-color: rgba(227,178,58,.62);
  }
  .topbar-symbol-search:focus-within input { position: static; inset: auto; opacity: 1; flex: 1; }
}

/* ═══════════════════════════════════════════════════════════════════════════════════
   MON DESK — système de widgets composable (BÊTA admin)
   Charte DTP : or #e3b23a, coins doux var(--radius), bordures fines var(--hud-line),
   hover doré sur les cartes. Densité HUD conservée.
   ═══════════════════════════════════════════════════════════════════════════════════ */

/* ══ TOKENS WIDGETS (Mon Desk) ══════════════════════════════════════════════════════════
   La valeur SOMBRE de chaque token est EXACTEMENT la couleur qui était écrite en dur : le desk
   sombre ne bouge pas. Les nuances séparées de moins de 2,0 ΔE (sous le seuil de perception)
   partagent un token ; au-delà elles en gardent un distinct — une première tentative les avait
   fusionnées trop largement et décalait certains gris de ΔE 10, nettement visible.
   La valeur CLAIRE est dérivée de la clarté L* : plus un texte est clair en sombre, plus il est
   foncé en clair (inversion), en restant dans l'échelle du thème clair déjà en place.
   L'or de marque et les couleurs d'état (vert/rouge) ne passent PAS par ici : charte immuable. ══ */
:root {
  --w-t1: #e8eaed;   /* + #e6e8ec */
  --w-t2: #cfd4dc;
  --w-t3: #c8ccd4;
  --w-t4: #c2c6d6;
  --w-t5: #b6bdc9;
  --w-t6: #b4b8bf;
  --w-t7: #9aa0aa;
  --w-t8: #8b93a1;
  --w-t9: #8b9099;   /* + #888d96 */
  --w-t10: #8a8a92;
  --w-t11: #7e8590;
  --w-t12: #6f7681;
  --w-t13: #6b7280;
  --w-t14: #5b5d66;
  --w-t15: #4c515b;   /* + #4c4f57 */
  --w-t16: #4a4a52;
  --w-t17: #3a3b40;
  --w-s1: #1a1b20;
  --w-s2: #14141a;   /* + #131317 */
  --w-s3: #131316;   /* + #111214 #101014 #101013 #0e0e11 */
  --w-s4: #0d0d10;   /* + #0b0c0f #0b0b0e */
  --w-f1: #3a3d44;
  --w-f2: #33343a;
  --w-f3: #17171b;
  --w-f4: #121215;
}
html[data-theme="light"] {
  --w-t1: #1b1b1d;
  --w-t2: #27282a;
  --w-t3: #2c2c2f;
  --w-t4: #303032;
  --w-t5: #363639;
  --w-t6: #393a3c;
  --w-t7: #4a4a4d;
  --w-t8: #545456;
  --w-t9: #565659;
  --w-t10: #5a5a5c;
  --w-t11: #5e5f61;
  --w-t12: #6a6a6d;
  --w-t13: #6d6e70;
  --w-t14: #7f7f81;
  --w-t15: #8a8a8d;
  --w-t16: #8f8f92;
  --w-t17: #9e9ea1;
  --w-s1: #fffef8;
  --w-s2: #f1efe9;
  --w-s3: #efede6;
  --w-s4: #e5e3dc;
  --w-f1: #c0beb8;
  --w-f2: #c6c4bd;
  --w-f3: #dfddd6;
  --w-f4: #e3e1db;
}

.wdg-beta {
  margin-left: 8px; padding: 1px 6px; border-radius: 3px; font-size: 9px; font-weight: 700;
  letter-spacing: .7px; color: var(--bg); background: var(--orange);
}
.wdg-btn {
  padding: 5px 11px; border-radius: var(--radius); font-size: 11px; font-weight: 600;
  cursor: pointer; background: var(--bg2); color: var(--w-t3);
  border: 1px solid var(--hud-line, var(--border)); transition: border-color .14s, color .14s;
}
.wdg-btn:hover { border-color: rgba(227,178,58,.55); color: var(--orange); }
.wdg-btn--gold { background: rgba(227,178,58,.11); border-color: rgba(227,178,58,.42); color: var(--orange); }
.wdg-btn--gold:hover { background: rgba(227,178,58,.2); border-color: var(--orange); }

/* Grille : 2 colonnes ; un widget en col:2 occupe toute la largeur.
   FLEX-WRAP et NON CSS Grid — choix mesuré, pas esthétique : avec `display:grid` + `grid-auto-rows:auto`,
   Chrome répartissait l'espace du panneau à ÉGALITÉ entre les rangées (754/3 = 251,3 px chacune) au lieu
   de les dimensionner sur le contenu. Résultat : des cartes de 251 px contenant un corps de 300 px, donc
   un graphe tronqué par `overflow:hidden` ET aucune barre de défilement (scrollHeight == clientHeight) →
   les widgets du bas devenaient inatteignables. `align-content:start` n'y changeait rien.
   `flex-wrap` + `align-content:flex-start` ne comprime jamais les lignes : la carte impose sa hauteur et
   c'est la grille qui défile. Vérifié : scrollHeight 1019 > clientHeight 802, hauteurs exactes.
   Les cartes d'une même ligne s'égalisent (align-items:stretch par défaut) → alignement propre. */
/* ── VRAIE GRILLE 12 COLONNES (refonte) : chaque widget occupe --gw colonnes (1→12 = 100 %) × --gh lignes.
   Densité automatique (grid-auto-flow dense) → AUCUN vide à droite, toute la largeur du Desk est utilisée.
   Responsive : 12 → 8 → 4 → 1 colonnes ; les spans se clampent tout seuls à la largeur dispo. */
/* HAUTEUR : les lignes s'ÉTIRENT pour remplir l'écran (demande user 26/07 « les widgets doivent couvrir
   le vide en bas »). `minmax(26px, 1fr)` = 26px est un PLANCHER, pas une taille : quand le desk tient dans
   la fenêtre, l'espace libre est réparti entre les lignes (les proportions entre widgets sont conservées) ;
   quand il déborde, chaque ligne retombe à 26px et la grille scrolle comme avant.
   ⚠️ La hauteur de ligne n'est donc plus constante → le snap du redimensionnement la MESURE (voir widgets.js). */
.wdg-grid {
  /* VUE D ENSEMBLE (demande user) : la disposition tient dans l ecran, on ne defile JAMAIS.
     Deux conditions, il faut les DEUX : overflow cache (plus de zone defilante) ET des rangees en
     minmax(0, 1fr) — le plancher de 26px empechait les rangees de descendre assez bas quand la
     disposition est chargee, donc le contenu debordait et la barre revenait. Les cartes ont deja
     overflow:hidden : leur contenu se clippe au lieu de pousser la grille. */
  flex: 1 1 auto; min-height: 0; overflow: hidden; padding: 12px;
  display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); grid-auto-rows: minmax(0, 1fr);
  grid-auto-flow: row dense; gap: var(--wdg-gap, 10px); align-content: stretch; position: relative;
}
/* Densité « Collés » (choix utilisateur, persisté) : widgets bord à bord — 1px de respiration, les bordures
   des cartes font la séparation. Le JS lit le gap RÉEL (getComputedStyle) → le snap du resize suit. */
/* Padding 0 en mode « Collés » (demande user 26/07 « le bas de page doit être comme ceci » en montrant le
   desk) : le desk classique colle ses panneaux aux bords de la fenêtre. Les 6px qui restaient créaient un
   liseré de fond tout autour, visible surtout en bas. Les bordures des cartes suffisent à séparer. */
.wdg-grid.wdg-gap-tight { --wdg-gap: 1px; padding: 0; }
.wdg-card {
  grid-column: span min(var(--gw, 6), 12); grid-row: span var(--gh, 12);
  position: relative; min-width: 0; overflow: hidden;
  display: flex; flex-direction: column;
  background: var(--bg); border: 1px solid var(--hud-line, var(--border)); border-radius: var(--radius);
  transition: border-color .16s, box-shadow .16s, transform .12s;
  animation: wdgCardIn .22s var(--ease, ease) both;           /* apparition légère */
}
.wdg-card:hover { border-color: rgba(227,178,58,.38); box-shadow: 0 4px 18px rgba(0,0,0,.35); }
.wdg-card.wdg-card--locked { border-color: rgba(227,178,58,.28); }
@keyframes wdgCardIn { from { opacity: 0; transform: translateY(6px) scale(.995); } to { opacity: 1; transform: none; } }
@keyframes wdgRefresh { 0% { box-shadow: 0 0 0 0 rgba(227,178,58,.5); } 100% { box-shadow: 0 0 0 3px rgba(227,178,58,0); } }
.wdg-card.wdg-refresh { animation: wdgRefresh .5s ease; }
@media (max-width: 1280px) { .wdg-grid { grid-template-columns: repeat(8, minmax(0, 1fr)); } }
@media (max-width: 900px)  { .wdg-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
@media (max-width: 560px)  { .wdg-grid { grid-template-columns: minmax(0, 1fr); } .wdg-card { grid-column: 1 / -1; } }

/* ── SPANS AU PRORATA DU NOMBRE DE COLONNES (tablette / petit portable) ────────────────────────
   La grille passe à 8 puis 4 colonnes, mais les cartes gardaient leur span calculé sur 12. Un widget
   demi-largeur (gw 6) réclamait alors 6 colonnes sur 4 : il prenait TOUTE la ligne, et la disposition
   s'empilait en une seule colonne dès 900px — précisément ce que le système de design refuse
   (« ça casse le côté professionnel »). On convertit le span au prorata : 6/12 reste une demi-largeur
   quel que soit le nombre de colonnes. En dessous de 560px la carte reste pleine largeur : un panneau
   d'application à ~170px de large ne serait plus lisible, la largeur prime là sur le nombre de colonnes.
   Protégé par @supports : round() est récent, les navigateurs qui ne l'ont pas gardent l'ancien calcul. */
@supports (width: round(1px, 1px)) {
  @media (max-width: 1280px) and (min-width: 901px) {
    .wdg-card { grid-column: span clamp(1, round(var(--gw, 6) * 8 / 12, 1), 8); }
  }
  @media (max-width: 900px) and (min-width: 561px) {
    .wdg-card { grid-column: span clamp(1, round(var(--gw, 6) * 4 / 12, 1), 4); }
  }
}

/* ── TÉLÉPHONE / TABLETTE : hauteur utile plutôt que vue d'ensemble ────────────────────────────
   Sur grand écran la disposition tient dans la page et ne défile jamais. Sur un téléphone, faire tenir
   trois panneaux dans 700px donne des tranches de 100px où aucun graphique n'est lisible. On garde donc
   les proportions choisies par l'utilisateur (les spans de lignes), mais avec un plancher par ligne et
   un plancher par carte ; la grille défile si la somme dépasse l'écran. */
@media (max-width: 900px) {
  .wdg-grid { overflow-y: auto; align-content: start; grid-auto-rows: minmax(14px, auto); }
  .wdg-card { min-height: 200px; }
}
@media (max-width: 560px) {
  .wdg-grid { grid-auto-rows: minmax(12px, auto); }
  /* 05/08 (constat user : « on ne peut pas bien scroller, les widgets sont trop courts »).
     220px laissaient ~150px de liste une fois l en-tete et la barre d outils deduits : trois
     lignes de news a peine, et un defilement qui bute aussitot. En colonne unique sur mobile,
     une carte plus haute ne coute rien a la mise en page — on defile de toute facon la page. */
  /* 05/08 — relevé à 420px (« agrandis les blocs pour empêcher les problèmes qu'on rencontre »).
     En colonne unique sur mobile, une carte haute ne coûte rien : on fait défiler la page de toute
     façon. C'est le MANQUE de hauteur qui produisait listes illisibles, graphiques écrasés et
     widgets réduits à une bande. */
  .wdg-card { min-height: 420px; }
  /* L'EXCEPTION pour les widgets dits « courts » est retirée : c'est précisément elle qui laissait
     l'Horloge mondiale en mince bande vide (capture user). Plancher plus bas qu'ailleurs, mais
     utilisable. */
  /* :not(.wdg-card--tabs) (25/08, audit) : via :has() DESCENDANT, cette exception attrapait aussi
     le PANNEAU À ONGLETS dès que son onglet RISQUE était monté, et son 0,2,0 battait le plancher
     460px des cartes (spécificité 0,1,0) → la carte à onglets tombait à 320px sur téléphone. */
  .wdg-card:not(.wdg-card--tabs):has(.wdg-clockwrap), .wdg-card:not(.wdg-card--tabs):has(.risk-gauge-stage) { min-height: 320px; }
}
/* Plein écran : la carte recouvre toute la zone de travail (overlay), les autres sont figées derrière. */
.wdg-grid.wdg-fs-mode { overflow: hidden; }
.wdg-grid.wdg-fs-mode .wdg-card:not(.wdg-fs) { visibility: hidden; }
.wdg-card.wdg-fs { position: absolute; inset: 0; z-index: 40; border-radius: var(--radius); box-shadow: 0 10px 40px rgba(0,0,0,.6); }
/* BANDEAU ÉPURÉ (29/07) — il pesait autant que la donnée : 7 contrôles permanents sur 34 px de haut.
   Resserré à 26 px, et seules TROIS actions restent visibles en permanence (réglages · remplacer ·
   fermer). Les quatre secondaires n'apparaissent qu'au survol de la carte : la grille respire,
   la puissance reste à un geste. */
.wdg-head {
  flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between; gap: 6px;
  padding: 3px 6px 3px 8px; min-height: var(--navbar-h);   /* MÊME hauteur que la nav et que tous les bandeaux du desk */
  background: var(--head-bg); border-bottom: 1px solid var(--hud-line, var(--border));
}
.wdg-title {
  font-family: var(--tight, 'Inter Tight', sans-serif); font-size: var(--fs-title, 11.5px); font-weight: var(--fw-semibold, 600); color: var(--text, var(--w-t1));
  text-transform: uppercase; letter-spacing: var(--ls-caps, .08em); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}   /* en-tête façon panneaux du desk (Inter Tight capitales) — plus de serif dans le module widgets (cohérence police desk) */
.wdg-actions { display: flex; align-items: center; gap: 1px; flex: 0 0 auto; }
/* ══ CONTEXTE DE LA CARTE, À CÔTÉ DE SON TITRE (01/09, référence fournie) ══════════════════════
   « GRAPHIQUE [EUR/USD · 1 h] ». En or, parce que c'est la seule couleur de marque du desk et que
   ce badge doit se distinguer du titre sans le concurrencer : capitales grises pour le nom, or
   minuscule pour le contexte.
   ⚠️ C'est le badge qui se tronque en premier, jamais le titre : `flex: 0 1 auto` sur les deux, mais
   le titre garde la priorité par son ordre. Sur une carte trop étroite le contexte disparaît en
   ellipse et l'en-tête reste lisible — l'inverse aurait rendu deux cartes voisines indistinguables,
   ce que ce badge existe précisément pour éviter. `margin-right: auto` colle le badge au titre :
   sans lui, `justify-content: space-between` l'enverrait flotter au MILIEU de l'en-tête. */
.wdg-ctx {
  flex: 0 1 auto; min-width: 0; margin-right: auto;
  font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 10px; font-weight: 600;
  letter-spacing: .02em; color: var(--orange, #e3b23a);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.wdg-ctx::before { content: "["; opacity: .6; margin-right: 1px; }
.wdg-ctx::after { content: "]"; opacity: .6; margin-left: 1px; }
html[data-theme="light"] .wdg-ctx { color: var(--orange-dim, #b8860b); }
.wdg-ico {
  width: 18px; height: 18px; display: flex; align-items: center; justify-content: center;
  background: transparent; border: 0; border-radius: 3px; cursor: pointer;
  color: var(--w-t13); font-size: 11px; line-height: 1; transition: color .12s, background .12s;
}
.wdg-ico:hover { color: var(--orange); background: rgba(227,178,58,.1); }
.wdg-ico--x { font-size: 15px; }
.wdg-ico--x:hover { color: #ff3d00; background: rgba(255,61,0,.1); }
.wdg-ico svg { display: block; }

/* Panneaux overlay info / réglages (dropdown depuis l'en-tête, façon desk pro — organisation DTP) */
.wdg-pop {
  /* z-index 1200 : au-dessus des couches Leaflet de la carte des sessions (panes 400-700) et des
     tuiles amCharts — sinon les badges de ville se dessinent PAR-DESSUS le panneau de réglages.
     288px (était 268) : les jeux de puces longs (Tri du DMX) respirent au lieu de s'empiler serrés. */
  position: absolute; top: 33px; right: 8px; z-index: 1200;
  width: min(288px, calc(100% - 16px));
  background: var(--pop-bg, var(--w-s3)); border: 1px solid rgba(227,178,58,.32); border-radius: var(--radius);
  box-shadow: 0 12px 34px rgba(0,0,0,.55); padding: 12px 14px;
}
html[data-theme="light"] .wdg-pop { --pop-bg: #fbfbf7; }
.wdg-pop-d { color: var(--text2, var(--w-t3)); }
.wdg-pop[hidden] { display: none; }
.wdg-pop-t { font-family: 'Fraunces', Georgia, serif; font-size: 12px; color: var(--orange); margin-bottom: 4px; }
.wdg-pop-d { font-size: 11px; color: var(--w-t3); line-height: 1.5; }
.wdg-pop-m { font-size: 9px; color: var(--w-t13); margin-top: 7px; text-transform: uppercase; letter-spacing: .6px; }
.wdg-set-row { display: flex; align-items: center; gap: 10px; margin: 6px 0; }
/* LISIBILITÉ (demande user 03/08, capture du panneau DMX) : libellés en CAPITALES DISCRÈTES façon
   en-têtes de sections du desk — la colonne grise 10px se confondait avec les puces. */
.wdg-set-lbl {
  flex: 0 0 auto; width: 62px; font-size: 9px; line-height: 1.3;
  font-family: var(--tight, 'Inter Tight', sans-serif); font-weight: 700;
  letter-spacing: .08em; text-transform: uppercase; color: var(--text3, var(--w-t9));
}

/* RÉGLAGES DÉCLARATIFS (générés depuis le contrat du catalogue) — même grammaire que les
   incrémenteurs taille/hauteur juste au-dessus, séparés par un filet. */
.wdg-set-sep { height: 1px; margin: 10px 0 8px; background: var(--hud-line, var(--border)); }
.wdg-set-row:has(.wdg-set-chips) .wdg-set-lbl { align-self: flex-start; padding-top: 5px; }
.wdg-set-chips { display: flex; flex-wrap: wrap; gap: 5px; min-width: 0; }
/* Puces : un cran plus grandes et plus contrastées — 9,5px mono gris sur gris se lisait mal. */
.wdg-set-chip {
  padding: 4px 10px; font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 10.5px; font-weight: 600; letter-spacing: .02em;
  color: var(--text2, #c9cdd4); background: var(--bg2); border: 1px solid var(--hud-line, var(--border));
  border-radius: var(--pill, 999px); cursor: pointer; white-space: nowrap; transition: border-color .12s, color .12s, background .12s;
}
.wdg-set-chip:hover { border-color: rgba(227, 178, 58, .5); color: var(--text); }
.wdg-set-chip.on { color: #0c0c0e; background: var(--orange, #e3b23a); border-color: var(--orange, #e3b23a); font-weight: 600; }
html[data-theme="light"] .wdg-set-chip.on { color: #fff; }
/* Bascule oui/non : rail + pastille, dorée quand active. */
.wdg-set-sw {
  position: relative; width: 30px; height: 16px; padding: 0; flex: 0 0 auto; cursor: pointer;
  background: var(--bg2); border: 1px solid var(--hud-line, var(--border)); border-radius: 9px;
  transition: background .14s, border-color .14s;
}
.wdg-set-sw i {
  position: absolute; top: 2px; left: 2px; width: 10px; height: 10px; border-radius: 50%;
  background: var(--w-t12); transition: left .14s var(--ease, ease), background .14s;
}
.wdg-set-sw.on { background: rgba(227, 178, 58, .22); border-color: rgba(227, 178, 58, .6); }
.wdg-set-sw.on i { left: 16px; background: var(--orange, #e3b23a); }
@media (prefers-reduced-motion: reduce) { .wdg-set-sw i { transition: none; } }
.wdg-set-btns { display: flex; gap: 4px; flex-wrap: wrap; }
.wdg-chip {
  padding: 3px 8px; font-size: 10.5px; border-radius: 3px; cursor: pointer;
  background: var(--bg2); color: var(--text2, var(--w-t6)); border: 1px solid var(--hud-line, var(--border));
  transition: border-color .12s, color .12s, background .12s;
}
.wdg-chip:hover { border-color: rgba(227,178,58,.5); color: var(--orange); }
.wdg-chip.on { background: rgba(227,178,58,.14); border-color: var(--orange); color: var(--orange); }
/* Hauteur FIXE et base flex définie (`flex: 0 0 auto` + `height`) : le corps ne grandit ni ne
   rétrécit, il vaut exactement --wdg-h. C'est ce qui rend la hauteur de la carte prévisible. */
.wdg-body { flex: 1 1 auto; min-height: 0; overflow: auto; position: relative; }   /* remplit la cellule de grille (hauteur = --gh lignes) */

/* ── AGENCEMENT SMART (demande user : déplacer / agencer / redimensionner) ────────────────────────
   Poignée de DÉPLACEMENT (⠿) à gauche de l'en-tête → glisser-déposer pour réordonner ; indicateur de
   dépôt doré ; poignée de REDIMENSIONNEMENT en bas → glisser pour ajuster la hauteur. Identité DTP. */
.wdg-title { flex: 0 1 auto; min-width: 0; }
.wdg-grip {
  flex: 0 0 auto; width: 18px; height: 20px; display: flex; align-items: center; justify-content: center;
  margin: -2px 4px -2px -3px; padding: 0; background: transparent; border: 0; border-radius: 3px;
  color: var(--w-t15); cursor: grab; transition: color .12s, background .12s;
}
.wdg-grip:hover { color: var(--orange); background: rgba(227,178,58,.1); }
.wdg-grip:active { cursor: grabbing; }
.wdg-grip svg { display: block; }
.wdg-card.wdg-dragging { opacity: .45; border-color: var(--orange); }
/* La carte saisie porte la marque commune aux listes réordonnables (`.wdg-reord-src`) depuis que le
   déplacement passe par le pointeur : au doigt, il n'y a plus de fantôme dessiné par le navigateur,
   c'est la seule chose qui dise ce qu'on tient — et la carte est sous le pouce. */
.wdg-card.wdg-reord-src { opacity: .45; border-color: var(--orange); }
.wdg-card.wdg-drop-before { box-shadow: -3px 0 0 0 var(--orange); }
.wdg-card.wdg-drop-after  { box-shadow:  3px 0 0 0 var(--orange); }
.wdg-resize {
  position: absolute; right: 0; bottom: 0; width: 18px; height: 18px; z-index: 6;
  cursor: nwse-resize; touch-action: none;
}
.wdg-resize::after {
  content: ''; position: absolute; right: 3px; bottom: 3px; width: 8px; height: 8px;
  border-right: 2px solid var(--w-f1); border-bottom: 2px solid var(--w-f1); border-bottom-right-radius: 3px;
  transition: border-color .12s;
}
.wdg-card:hover .wdg-resize::after, .wdg-resize:hover::after { border-color: var(--orange); }
.wdg-card.wdg-card--locked .wdg-resize { display: none; }
/* Poignée de BORD DROIT : élargir/rétrécir au curseur (largeur seule), snap sur les colonnes */
/* ⚠️ ZONE DE PRISE ÉLARGIE (04/09, capture user : « c'est difficile d'attraper pour élargir »).
   Elle faisait 9 px — et depuis qu'elle se décale de 8 px pour libérer la barre de défilement, ces
   9 px sont coincés entre le contenu et la barre : une cible de la largeur d'un curseur, qu'il faut
   viser. On l'élargit à 14 px VERS L'INTÉRIEUR, et c'est le sens qui compte : le repère visuel est
   posé en `right: 2px` À L'INTÉRIEUR de la poignée, donc élargir déplace le bord GAUCHE et laisse le
   repère exactement où l'œil l'a appris. La cible grandit, rien ne bouge à l'écran. */
.wdg-resize-e {
  position: absolute; top: 34px; bottom: 22px; right: 0; width: 14px; z-index: 6;
  cursor: ew-resize; touch-action: none;
}
/* ⚠️ ELLE OCCUPAIT EXACTEMENT LA BARRE DE DÉFILEMENT (31/08 : « j'ai du mal à bien choper le
   scroller, mon curseur est sur l'élargissement du bloc »). Mesuré : la poignée tient les 9 px les
   plus à droite de la carte, la barre du corps les 8 px les plus à droite du même bord. Elles se
   recouvrent, et la poignée gagne — elle a un z-index et se pose par-dessus.
   La sortir de la carte est IMPOSSIBLE : `.wdg-card` est en `overflow: hidden`, elle y serait rognée
   donc inatteignable (vérifié avant d'essayer). On la décale vers l'INTÉRIEUR — mais seulement quand
   il y a une barre à protéger : une carte qui ne défile pas garde sa poignée au bord, là où la main
   la cherche. La classe est posée par widgets.js quand le pointeur entre dans la carte. */
.wdg-card--barre .wdg-resize-e { right: 8px; }
/* ⚠️ LE REPÈRE MONTRAIT 8,5 % DE CE QU'ON POUVAIT SAISIR (capture user : « ce curseur n'est pas
   précis je comprends pas »). MESURÉ sur une carte de 358 px : la zone qui change le curseur en ↔
   court sur 306 px de hauteur, le repère orange n'en dessinait que 26, CENTRÉS. Il restait donc
   140 px aveugles au-dessus et 140 px en dessous : on survolait le bord, le curseur annonçait
   « redimensionner », et la seule marque visible s'allumait jusqu'à cent quarante pixels plus loin.
   Rien n'était cassé — c'est ce qui rend le défaut déroutant : le geste MARCHE là où l'œil ne voit
   rien, et l'œil regarde une marque qui n'est pas là où est la main.
   LE REPÈRE ÉPOUSE DÉSORMAIS LA ZONE, exactement (`top: 0; bottom: 0` de la poignée) : ce qu'on
   voit est ce qu'on peut prendre. Deux intensités, parce que les deux moments n'ont pas le même
   sens — carte survolée : un rail discret qui dit que ce bord se tire ; poignée survolée, c'est-à-
   dire curseur ↔ affiché : le rail passe en or plein, sur toute sa hauteur, sous le pointeur.
   ⚠️ ET L'OPACITÉ DE SURVOL DE CARTE BAISSE DE .8 À .45, ce n'est pas un détail de goût : .8
   convenait à un trait de 26 px, il ferait d'un rail pleine hauteur une SECONDE BORDURE le long de
   la carte — on aurait remplacé un repère introuvable par un ornement permanent. La valeur est
   CHOISIE SUR RENDU, pas au jugé : les quatre paliers .30 / .45 / .60 / .80 ont été peints côte à
   côte dans le vrai Chromium. .30 disparaît (on perdrait l'indice que ce bord se tire), .80 fait la
   seconde bordure, .60 en approche. .45 se voit sans peser. */
.wdg-resize-e::after {
  content: ''; position: absolute; right: 2px; top: 0; bottom: 0;
  width: 3px; border-radius: 2px; background: var(--w-f1);
  opacity: 0; transition: opacity .14s, background .12s;
}
.wdg-card:hover .wdg-resize-e::after { opacity: .45; }
.wdg-resize-e:hover::after { background: var(--orange); opacity: 1; }
.wdg-card.wdg-card--locked .wdg-resize-e { display: none; }

/* ── EMPLACEMENT VIDE (création guidée par disposition) : carte pointillée « + Choisir un widget » ── */
.wdg-card--slot {
  border: 1px dashed rgba(227,178,58,.42); background: rgba(227,178,58,.03);
  align-items: center; justify-content: center;
}
.wdg-card--slot:hover { border-color: rgba(227,178,58,.7); box-shadow: none; }
.wdg-slot-add {
  display: flex; flex-direction: column; align-items: center; gap: 4px; margin: auto;
  background: none; border: none; cursor: pointer; color: #b8935a;
  font-size: 24px; line-height: 1; font-weight: 300; transition: color .14s;
}
.wdg-slot-add span { font-size: 11.5px; font-weight: 500; letter-spacing: .02em; }
.wdg-slot-add:hover { color: var(--orange); }
.wdg-slot-x {
  position: absolute; top: 5px; right: 8px; z-index: 5; background: none; border: none;
  color: var(--w-t14); cursor: pointer; font-size: 14px; line-height: 1; padding: 3px;
}
.wdg-slot-x:hover { color: #ef4444; }

/* Réglages en STEPPERS (largeur en colonnes / hauteur en lignes) */
.wdg-stepper { display: inline-flex; align-items: center; border: 1px solid var(--hud-line, var(--border)); border-radius: 5px; overflow: hidden; }
.wdg-step { width: 22px; height: 22px; display: flex; align-items: center; justify-content: center; background: var(--bg2); color: var(--text2, var(--w-t3)); border: 0; cursor: pointer; font-size: 15px; line-height: 1; transition: background .12s, color .12s; }
.wdg-step:hover { background: rgba(227,178,58,.16); color: var(--orange); }
.wdg-step-val { min-width: 46px; text-align: center; font-size: 11px; color: var(--text, var(--w-t1)); font-variant-numeric: tabular-nums; }

/* Header TERMINAL : actions discrètes, révélées au survol de la carte (icônes toujours accessibles au tactile) */
.wdg-actions { opacity: 0; transition: opacity .14s; }
.wdg-card:hover .wdg-actions, .wdg-card:focus-within .wdg-actions, .wdg-card.wdg-fs .wdg-actions { opacity: 1; }
@media (hover: none) { .wdg-actions { opacity: .75; } }
.wdg-ico.on { color: var(--orange); }

/* CAUSE RACINE du « vide à droite » : .view-panel est un flex ROW, mais le .panel des widgets n'avait pas flex:1
   → il se limitait à sa largeur intrinsèque (~1060px) au lieu de GROSSIR sur toute la largeur du Desk. Corrigé. */
#view-widgets { display: flex; }
#view-widgets > .panel { flex: 1 1 auto; min-width: 0; width: 100%; }

/* ── Barre Mon Desk : contrôles COMPACTS façon desk (demande user « les 2 boutons sont gros » —
     alignés sur les contrôles du desk type .sbs-cdd : 11px, fonds feutrés, or en accent, pas de pilule massive) ── */
#view-widgets .panel-header { padding: 0 12px 0 0; gap: 9px; height: var(--navbar-h, 40px); }   /* barre = MÊME hauteur que la navbar ET padding-left 0 comme .navbar → les onglets démarrent au MÊME x que › ACTUS (les items portent leur 14px) */
#view-widgets .panel-header-left { align-self: stretch; }   /* les onglets remplissent la hauteur → soulignement or FLUSH en bas (comme .nav-item) */
.wdg-btn {
  display: inline-flex; align-items: center; gap: 5px; height: 26px; padding: 0 11px; font-size: 11px; font-weight: 600;
  font-family: var(--tight, 'Inter Tight', sans-serif); letter-spacing: .01em;
  color: var(--w-t3); background: var(--w-s3); border: 1px solid var(--hud-line, var(--border)); border-radius: 4px;
  cursor: pointer; transition: color .14s, border-color .14s, background .14s, transform .1s;
}
.wdg-btn:hover { color: var(--orange); border-color: rgba(227,178,58,.5); background: rgba(227,178,58,.07); }
.wdg-btn:active { transform: translateY(1px); }
.wdg-btn--gold { color: var(--orange); background: transparent; border-color: rgba(227,178,58,.45); }
.wdg-btn--gold:hover { background: rgba(227,178,58,.12); border-color: var(--orange); box-shadow: none; }
/* Contrôle de DENSITÉ : GROUPE pilule propre — 2 segments (l'actif en or plein), sans libellé
   (retiré à la demande user ; le title du groupe explique au survol). */
.wdg-density {
  display: inline-flex; align-items: center; gap: 2px;
  border: 1px solid var(--hud-line, var(--border)); border-radius: 6px; background: var(--w-s3);
  padding: 3px;
}
.wdg-density .wdg-dens-b {
  border: none; background: transparent; height: 22px; padding: 0 10px;
  border-radius: 4px; box-shadow: none; color: var(--w-t7);
}
.wdg-density .wdg-dens-b:hover { color: var(--w-t1); background: var(--w-s1); transform: none; }
.wdg-density .wdg-dens-b.wdg-btn--on { color: var(--bg); background: var(--orange); font-weight: 700; }
.wdg-density .wdg-dens-b.wdg-btn--on:hover { background: #eec253; color: var(--bg); }
@media (max-width: 560px) { .wdg-density .wdg-dens-b { padding: 0 7px; font-size: 10px; } }
/* (Ancien style de pilule des onglets de layout retiré : la barre suit désormais la grammaire
   EXACTE de la nav du desk — voir .wdg-lay plus bas. Il était intégralement écrasé.) */
/* Renommage inline d'un onglet (double-clic) */
.wdg-lay-edit {
  width: 118px; padding: 1px 4px; font: inherit; font-size: 11.5px; color: var(--w-t1);
  background: var(--bg); border: 1px solid rgba(227,178,58,.55); border-radius: 3px; outline: none;
}
.wdg-lay:hover { color: var(--w-t1); background: rgba(255,255,255,0.035); }
.wdg-lay.on { color: var(--text, var(--w-t1)); background: transparent; border-color: transparent; }
.wdg-lay-star { color: var(--orange); }
.wdg-lay-add { color: var(--w-t13); padding: 5px 9px; }
.wdg-lay-add:hover { color: var(--orange); }
.wdg-beta { padding: 2px 7px; font-size: 9px; font-weight: 800; letter-spacing: .06em; color: var(--bg); background: var(--orange); border-radius: 4px; }
.wdg-card.wdg-resizing { border-color: var(--orange); }
.wdg-card.wdg-resizing .wdg-body { pointer-events: none; }        /* pas d'interaction chart pendant le resize */

/* ── Mode Mon Desk (RE-RÉVISÉ 23/07, demande user « enlève la barre de navigation, on crée notre propre
   dashboard personnalisable ») : la nav Actus/Calendrier… est MASQUÉE — Mon Desk est un espace autonome.
   Sortie = re-clic sur l'icône topbar Mon Desk (toggle) ; pas de bouton « ‹ Retour » (veto user). ── */
body.wdg-mode #topbar-nav { display: none; }

.wdg-empty, .wdg-load {
  display: flex; align-items: center; justify-content: center; height: 100%;
  font-size: var(--fs-body, 12px); color: var(--text3, var(--w-t9)); text-align: center; padding: 12px;
}
.wdg-blank {
  flex: 1 1 100%; display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 8px; padding: 60px 20px; border: 1px dashed var(--hud-line, var(--border)); border-radius: var(--radius);
}
.wdg-blank-t { font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 14px; font-weight: 700; color: var(--w-t1); }   /* police du DESK (cohérence, demande user 23/07 — plus de serif) */
.wdg-blank-s { font-size: 11px; color: var(--w-t13); margin-bottom: 6px; }

/* Widget calendrier : conteneur scrollable ; la TABLE réutilise les classes du desk (.cal-table /
   .cth-*) pour un rendu IDENTIQUE. On ne redéfinit donc AUCUN style de calendrier ici. */
/* Le widget Calendrier est un PANNEAU, pas une table nue : barre d'outils fixe en haut (filtres
   d'impact + recherche + pastille DIRECT, classes du desk) et table qui défile en dessous. */
.wdg-cal-panel { display: flex; flex-direction: column; height: 100%; min-height: 0; }
.wdg-cal-bar { flex: 0 0 auto; padding: 6px 10px 7px; border-bottom: 1px solid var(--border); background: var(--head-bg); }
.wdg-cal-bar .cal-imp-btn { padding: 4px 10px; }
.wdg-cal-bar .cal-search-wrap { flex: 1 1 auto; min-width: 0; }
/* Même fond que le conteneur du calendrier du desk (.cal-table-wrap, #090909) : sans lui la table
   se détachait du reste sur le fond de carte, et le widget « ne ressemblait pas » à l'onglet. */
.wdg-cal-wrap { flex: 1 1 auto; height: 100%; min-height: 0; overflow: auto; background: #090909; }

/* AJUSTEMENT À LA CARTE, SANS SEUIL D'ÉCRAN. Le fit-to-width du calendrier était enfermé dans
   @media (max-width: 560px) : il ne s'appliquait donc JAMAIS à une carte étroite sur grand écran.
   Or les largeurs déclarées des colonnes totalisent 502px (HIGH et LOW masquées) à 626px (toutes
   visibles), pour une carte demi-largeur de 369px sur tablette — 133 à 257px hors champ, et la
   colonne ÉVÉNEMENT, seule à identifier la ligne, partait la première. La carte est étroite quelle
   que soit la taille de l'écran : la règle ne doit donc dépendre que d'elle. */
/* Le mode « ajusté » (table-layout fixed) n'est actif QUE sur carte étroite — voir la requête de
   conteneur plus bas. Sur carte large, la table garde le layout AUTO du desk : mesuré, imposer fixed
   partout tronquait la colonne HEURE (« 03:… ») et les en-têtes (« HEU… ») même à 943 px, car les
   largeurs déclarées (50 px…) deviennent des plafonds au lieu de minima. */

/* …mais le fit seul ne suffit pas : à largeur fixe, les colonnes déclarées (50+34+36+56+5×62 = 486px)
   mangent tout et ÉVÉNEMENT — la seule à identifier la ligne — tombe à 0 px sur une carte de 371px
   (mesuré). Il faut donc RETIRER des colonnes quand la carte est étroite, et la carte peut l'être sur
   n'importe quelle taille d'écran : un seuil de viewport ne peut pas répondre à ça. On interroge donc
   le CONTENEUR. Portée volontairement limitée au panneau du calendrier : `container-type` ajoute du
   confinement de mise en page, on ne l'impose pas à toutes les cartes.
   Ordre de sacrifice : HIGH et LOW d'abord (la source ne les fournit pas, elles affichent « — »),
   puis le drapeau (le code devise porte déjà l'information).
   ÉVÉNEMENT reçoit une largeur EXPLICITE (le solde) : mesuré, une colonne laissée en `auto` dans une
   table `table-layout: fixed` ne récupère pas l'espace restant — 119 px sur 493 restaient inutilisés
   et la colonne tombait à 60 px. On calcule donc le solde à la main, colonnes masquées déduites. */
.wdg-cal-panel { container-type: inline-size; container-name: dtpcal; }
/* Ceinture ACCUEIL (23/08) : la zone qui héberge le calendrier devient AUSSI le conteneur — si un
   hôte montait la table sans .wdg-cal-panel, le kit adaptatif s'appliquerait quand même. */
.home-zone-body:has(.wdg-cal-wrap) { container-type: inline-size; container-name: dtpcal; }
/* 640 → 700 (23/08, capture user accueil : panneau ~660px JUSTE AU-DESSUS du seuil → 10 colonnes
   au chausse-pied, « 1.41… », « PRÉVISI » coupés. À 700 le kit couvre l'accueil ; les valeurs ne
   se tronquent JAMAIS, c'est l'intitulé d'événement qui cède). */
@container dtpcal (max-width: 700px) {
  .wdg-cal-wrap { overflow-x: hidden; }
  .wdg-cal-wrap .cal-table { table-layout: fixed; width: 100%; }
  .wdg-cal-wrap .cth-event { min-width: 0; }
  .wdg-cal-wrap .cal-table thead th { overflow: hidden; text-overflow: ellipsis; }
  /* Par CLASSE (plus par position) : avec la colonne Haut retirée du DOM par le réglage de carte,
     nth-child(7) masquait PRÉVISION et la colonne Bas s'affichait SOUS l'en-tête « PRÉV » : une
     donnée mensongère, mesurée au banc sur carte de 495 px (17/08). */
  .cal-table .cth-val--haut, .cal-table .cth-val--bas { display: none; }
  .cal-chv { display: none; }   /* ses ~12 px tronquaient l'heure (« 03:… ») dans la colonne serrée */
  /* Toutes les colonnes en POURCENTAGE, somme = 100. Ni les largeurs en pixels ni un calc() du solde
     ne fonctionnent ici : mesuré, la colonne restée en `auto` ne récupère pas l'espace libre (119 px
     inutilisés sur 493) et ÉVÉNEMENT retombait à 60 px. En pourcentages, la répartition est exacte. */
  .cth-time  { width: 11%; padding-left: 6px !important; }
  .cth-flag  { width: 7%; }
  .cth-curr  { width: 8.5%; }   /* 7,5 % tronquait « CNY » en « C… » sur une carte de 495 px (mesuré) */
  .cth-imp   { width: 9%; }
  .cth-event { width: 33%; }
  .cth-val   { width: 10.5%; }
  /* INTITULÉS ABRÉGÉS. Mesuré au banc : « Devise », « Prévision » et « Précédent » se coupent
     encore à 560 px de cadre (« PRÉ… ») — aucune taille de police ne les y fait tenir. On abrège
     franchement plutôt que de laisser l'ellipse manger le mot. Le `!important` est OBLIGATOIRE :
     .cth-time et .cth-val portent déjà font-size:10px !important plus haut dans la feuille.
     ⚠️ Abréviations par CLASSE cth-val--* : par nth-child, une colonne masquée par le réglage de
     carte décalait tous les intitulés d'un cran (« PRÉV » au-dessus de la colonne Bas, mesuré). */
  .wdg-cal-wrap .cal-table thead .cth-curr,
  .wdg-cal-wrap .cal-table thead .cth-flag,
  .wdg-cal-wrap .cal-table thead .cth-imp,
  .wdg-cal-wrap .cal-table thead .cth-val { font-size: 0 !important; letter-spacing: 0; }
  .wdg-cal-wrap .cal-table thead .cth-curr::after,
  .wdg-cal-wrap .cal-table thead .cth-imp::after,
  .wdg-cal-wrap .cal-table thead .cth-val::after { font-size: 9px; letter-spacing: .04em; }
  .wdg-cal-wrap .cal-table thead .cth-curr::after { content: 'DEV'; }
  /* Drapeau : PAS de ::after (l'icône ronde se suffit, et « PAYS » se clippait en « PA… », mesuré) */
  .wdg-cal-wrap .cal-table thead .cth-imp::after { content: 'IMP'; }   /* « IMPACT » se clippait en « IM… » */
  .wdg-cal-wrap .cal-table thead .cth-val--reel::after { content: 'RÉEL'; }
  .wdg-cal-wrap .cal-table thead .cth-val--haut::after { content: 'HAUT'; }
  .wdg-cal-wrap .cal-table thead .cth-val--prev::after { content: 'PRÉV'; }
  .wdg-cal-wrap .cal-table thead .cth-val--bas::after  { content: 'BAS'; }
  .wdg-cal-wrap .cal-table thead .cth-val--prec::after { content: 'PRÉC'; }
}
@container dtpcal (max-width: 470px) {
  .cal-table .cth-flag { display: none; }   /* drapeau (par classe, plus par rang) : le code devise suffit */
  .cth-time  { width: 13%; }
  .cth-curr  { width: 10%; }
  .cth-imp   { width: 11%; }
  .cth-event { width: 33%; }
  .cth-val   { width: 11%; font-size: 10px; }
  .cal-table thead th, .cal-row td { padding-left: 5px !important; padding-right: 5px !important; }
}
/* Re-keyé le 18/08 : body.theme-light n'est plus posé par personne (la règle était morte en prod,
   le widget calendrier restait une île #090909 sur desk clair). Même bascule que .cal-table-wrap. */
html[data-theme="light"] .wdg-cal-wrap { background: var(--bg2); }

/* Widgets réutilisant des rendus du desk : on les fait remplir le corps du widget (règles additives,
   scoping .wdg-body → aucun effet sur les onglets du desk). */
/* PLANCHER du Baromètre (02/08, capture user « c'est trop petit ») : chaque moitié de l'égaliseur
   exige 10 briques × (5 px + 1 px de bordure) = 60 px ; sur une carte basse, la pile n'avait que
   ~60 px pour LES DEUX moitiés → overflow:hidden tranchait la moitié basse (il n'en restait que les
   briques allumées) et les valeurs chiffrées disparaissaient. Le desk garantit cette hauteur par la
   taille de son panneau ; dans la carte, c'est le plancher qui la garantit — le corps (.wdg-body,
   overflow:auto) défile si la carte est plus basse, au lieu d'écraser l'égaliseur. */
.wdg-body .meter-grid { height: 100%; min-height: 240px; }
.wdg-body .wdg-cs-wrap { height: 100%; overflow: auto; }
.wdg-body .cs-rank-list { padding: 8px 12px; }

/* Widget « Graphique » : bougies du desk dans une carte. La barre (paire + unité de temps) est
   STRUCTURELLE — elle ne défile pas — et le graphe prend tout le reste : amCharts mesure son
   conteneur, donc il lui faut une hauteur réelle (min-height) et pas seulement flex:1, sinon une
   carte basse le réduit à 0 px et la toile reste blanche. */
.wdg-cdl { display: flex; flex-direction: column; height: 100%; min-height: 0; }
.wdg-cdl-bar {
  flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between; gap: 8px;
  padding: 5px 8px; border-bottom: 1px solid var(--hud-line, var(--border));
}
.wdg-cdl-sym {
  height: 24px; padding: 0 22px 0 8px; cursor: pointer;
  background: var(--bg1) url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 12 12' fill='none' stroke='%23e3b23a' stroke-width='1.6'><path d='M2.5 4.5L6 8l3.5-3.5'/></svg>") no-repeat right 6px center;
  -webkit-appearance: none; appearance: none;
  border: 1px solid var(--border); border-radius: var(--r-1, 4px);
  font-family: var(--mono, ui-monospace, monospace); font-size: var(--fs-2, 11px); font-weight: 600;
  color: var(--w-t1); letter-spacing: .02em;
}
.wdg-cdl-sym:hover, .wdg-cdl-sym:focus { border-color: var(--orange); color: var(--orange); outline: none; }
.wdg-cdl-tf { display: flex; gap: 3px; }
.wdg-cdl-tf .stf-btn { height: 22px; padding: 0 7px; font-size: 10px; }
.wdg-cdl-chart { flex: 1 1 auto; min-height: 180px; }
/* Sous ~360 px de large, la barre passe sur deux lignes plutôt que d'écraser le sélecteur. */
@media (max-width: 560px) {
  .wdg-cdl-bar { flex-wrap: wrap; row-gap: 5px; }
  .wdg-cdl-sym { flex: 1 1 100%; }
  .wdg-cdl-tf { width: 100%; justify-content: space-between; }
  .wdg-cdl-tf .stf-btn { flex: 1 1 0; padding: 0 4px; }
}

/* Widget fil de news : réutilise le rendu .news-item officiel du desk */
.wdg-news { display: flex; flex-direction: column; }
.wdg-news-row { padding: 5px 8px; font-size: 11px; color: var(--w-t3); border-bottom: var(--row-sep, 1px solid rgba(255,255,255,.028)); }

/* Bibliothèque : voile + panneau (aucune dialog native — charte DTP) */
.wdg-lib { position: absolute; inset: 0; z-index: 700; display: none; }
.wdg-lib.open { display: block; }
.wdg-lib-backdrop { position: absolute; inset: 0; background: rgba(6,6,8,.72); backdrop-filter: blur(6px); }
.wdg-lib-box {
  position: absolute; top: 0; left: 0; bottom: 0; transform: none;
  width: min(468px, 90%); max-height: none; display: flex; flex-direction: column;
  background: var(--bg); border: 0; border-right: 1px solid rgba(227,178,58,.3); border-radius: 0;
  box-shadow: 14px 0 44px rgba(0,0,0,.55);
  animation: wdgVoletG .18s ease-out;
  container-type: inline-size; container-name: dtpvolet;
}
@keyframes wdgVoletG { from { transform: translateX(-14px); opacity: 0; } to { transform: none; opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .wdg-lib-box { animation: none; } }
.wdg-lib-head {
  flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between;
  padding: 11px 14px; border-bottom: 1px solid var(--hud-line, var(--border));
}
.wdg-lib-title { font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 12.5px; font-weight: 700; text-transform: uppercase; letter-spacing: .05em; color: var(--orange); }   /* titre façon en-têtes de panneaux du desk */
.wdg-lib-x { background: transparent; border: 0; color: var(--w-t13); font-size: 18px; cursor: pointer; line-height: 1; }
.wdg-lib-x:hover { color: var(--w-t1); }
.wdg-lib-grid {
  flex: 1 1 auto; min-height: 0; overflow-y: auto; padding: 14px;
  display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 10px;
}
.wdg-lib-card {
  display: flex; flex-direction: column; gap: 3px; text-align: left; cursor: pointer;
  padding: 11px; background: var(--head-bg); border: 1px solid var(--hud-line, var(--border));
  border-radius: var(--radius); transition: border-color .14s, background .14s;
}
.wdg-lib-card:hover { border-color: rgba(227,178,58,.55); background: var(--w-s3); }
.wdg-lib-cat { font-size: 8.5px; font-weight: 700; letter-spacing: .8px; color: var(--orange); text-transform: uppercase; }
/* ⚠️ PLUS DE GRAS (04/09, demande user : « enlève le gras de ces descriptions de widgets, ça
   permettra de mieux lire »). Dans une galerie où CHAQUE carte porte un nom, tout mettre en gras
   revient à ne rien mettre en avant : la graisse ne hiérarchise plus, elle épaissit — et sur deux
   lignes, un nom long comme « Calendrier économique » devient un pavé. Le nom garde l'encre pleine,
   qui suffit à le distinguer de la description en dessous. */
.wdg-lib-name { font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 12.5px; font-weight: var(--fw-medium, 500); color: var(--text, var(--w-t1)); }   /* police du DESK (cohérence) */
.wdg-lib-desc { font-size: 11px; color: var(--text2, var(--w-t6)); line-height: 1.5; }
.wdg-lib-used { font-size: 9.5px; color: var(--w-t8); font-style: italic; flex: 0 0 auto; }

/* ── Bibliothèque v2 : sections par CATÉGORIE + cartes horizontales avec icône (refonte UX/UI) ── */
.wdg-lib-sec { grid-column: 1 / -1; margin: 6px 2px 0; font-size: 10px; font-weight: 700; letter-spacing: .07em; text-transform: uppercase; color: var(--orange); display: flex; align-items: baseline; gap: 8px; }
.wdg-lib-sub { font-weight: 500; letter-spacing: .02em; text-transform: none; color: var(--text3, var(--w-t9)); font-size: 10px; }
.wdg-lib-sec:first-child { margin-top: 0; }
.wdg-lib-row { grid-column: 1 / -1; display: grid; grid-template-columns: repeat(auto-fill, minmax(198px, 1fr)); gap: 8px; }
.wdg-lib-row .wdg-lib-card { flex-direction: row; align-items: center; gap: 11px; text-align: left; padding: 10px 12px; }
.wdg-lib-ico { flex: 0 0 auto; display: inline-flex; align-items: center; justify-content: center; width: 32px; height: 32px; border-radius: 6px; color: var(--orange); background: rgba(227,178,58,.09); border: 1px solid rgba(227,178,58,.22); }
.wdg-lib-main { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.wdg-lib-plus { flex: 0 0 auto; font-size: 15px; font-weight: 700; color: var(--w-t16); transition: color .12s; }
.wdg-lib-card:hover .wdg-lib-plus { color: var(--orange); }

/* ── Empty state : CENTRÉ dans la zone de travail (avant : coincé en haut-gauche de la grille 12 col) ── */
.wdg-blank { grid-column: 1 / -1; min-height: 58vh; }

/* ── Ligne « Sauvegarde auto du … + Restaurer » (gestionnaire Mes layouts) ── */
/* Trois jalons de sauvegarde au lieu d'un : la barre passe en `flex-start` + retour à la ligne, sinon
   `space-between` étalerait les boutons datés aux deux bouts de la largeur. */
.wdg-mgr-bak { flex: 1 1 100%; display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-start; gap: 8px; margin: 0 0 2px; padding: 8px 10px; background: var(--head-bg); border: 1px solid var(--hud-line, var(--border)); border-radius: 5px; }
.wdg-mgr-bak .wdg-btn { font-variant-numeric: tabular-nums; }
.wdg-mgr-bak-lbl { font-size: 11.5px; color: var(--text2, var(--w-t5)); }

/* ── Widget Calculatrice de position (autonome, volatile) ── */
.wdg-calc { display: flex; flex-direction: column; gap: 6px; padding: 11px 13px; height: 100%; overflow-y: auto; }
.wdg-calc-row { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.wdg-calc-lbl { font-size: 11.5px; color: var(--w-t5); }
.wdg-calc-in { display: inline-flex; align-items: center; gap: 5px; }
.wdg-calc-in input { width: 86px; padding: 4px 8px; font-size: 12px; color: var(--w-t1); text-align: right; background: var(--bg); border: 1px solid var(--hud-line, var(--border)); border-radius: 4px; outline: none; font-variant-numeric: tabular-nums; }
.wdg-calc-in input:focus { border-color: rgba(227,178,58,.55); }
.wdg-calc-in em { font-style: normal; font-size: 10.5px; color: var(--w-t8); min-width: 26px; }
.wdg-calc-out { display: flex; gap: 8px; margin-top: 4px; }
.wdg-calc-o { flex: 1; display: flex; flex-direction: column; gap: 2px; padding: 8px 10px; background: var(--w-s3); border: 1px solid var(--hud-line, var(--border)); border-radius: 5px; }
.wdg-calc-o span { font-size: 9.5px; text-transform: uppercase; letter-spacing: .05em; color: var(--w-t8); }
.wdg-calc-o b { font-size: 15px; color: var(--w-t1); font-variant-numeric: tabular-nums; }
.wdg-calc-o--main { border-color: rgba(227,178,58,.35); background: rgba(227,178,58,.07); }
.wdg-calc-o--main b { color: var(--orange); }
.wdg-calc-note { font-size: 10px; color: var(--w-t11); line-height: 1.45; }
.wdg-calc-open { background: none; border: 0; padding: 0; font-size: 10px; color: var(--orange); cursor: pointer; }
.wdg-calc-open:hover { text-decoration: underline; }

/* ── Widget Journal = le VRAI journal relocalisé dans le host (24/07) : remplit la carte, en-tête compacté
   (le titre est déjà dans l'en-tête du widget → on masque celui du panneau, on garde les onglets). ── */
.wdg-jr-host { padding: 0 !important; overflow: hidden; display: flex; }
.wdg-jr-host .panel-journal { height: 100%; min-height: 0; width: 100%; border: 0; background: transparent; }
.wdg-jr-host .panel-journal > .panel-header { padding-top: 4px; padding-bottom: 4px; }
.wdg-jr-host .panel-journal > .panel-header .panel-title { display: none; }   /* pas de doublon avec le titre du widget */

/* ── (Repli) Widget Journal réimplémenté — mêmes colonnes perso, mêmes cellules ── */
.wdg-jr { display: flex; flex-direction: column; height: 100%; min-height: 0; overflow: hidden; }
/* Tableau IDENTIQUE au desk (24/07) : toutes les colonnes perso du compte, scroll horizontal DANS le tableau
   (stats + courbe + onglets restent fixes) ; cellules = classes globales .jr-chip/.jr-cv-*/.jr-ring/.jr-prog. */
.wdg-jrt-scroll { flex: 1 1 auto; min-height: 0; overflow: auto; }
.wdg-jrt { border-collapse: collapse; width: max-content; min-width: 100%; font-size: 11.5px; }
.wdg-jrt-th { position: sticky; top: 0; z-index: 2; background: var(--w-s4); text-align: left; padding: 6px 10px; font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: .05em; color: var(--w-t7); border-bottom: 1px solid var(--hud-line, var(--border)); white-space: nowrap; }
.wdg-jrt-c { padding: 5px 10px; border-bottom: 1px solid var(--w-f4); vertical-align: middle; white-space: nowrap; }
.wdg-jrt-c.jr-c--multi { white-space: normal; }   /* chips multiples : peuvent s'empiler dans la largeur de colonne, comme le desk */
.wdg-jrt-c.jr-c--title { position: relative; padding-right: 62px; }   /* place pour le bouton OUVRIR absolu (comme le desk) */
.wdg-jrt-row { cursor: pointer; }
.wdg-jrt-row:hover { background: var(--w-s3); }
/* MODIFIER = bouton « OUVRIR » IDENTIQUE au vrai journal (.jrd-open, classe globale) : révélé au survol de la ligne (scope widget) */
.wdg-jrt-row:hover .jrd-open { opacity: 1; pointer-events: auto; }
@media (hover: none) { .wdg-jrt .jrd-open { opacity: 1; pointer-events: auto; } }
.wdg-jr-stats { display: flex; align-items: center; gap: 14px; padding: 8px 12px; border-bottom: 1px solid var(--hud-line, var(--border)); font-size: 11.5px; color: var(--w-t5); flex: 0 0 auto; flex-wrap: wrap; }
.wdg-jr-stats b { color: var(--w-t1); }
.wdg-jr-stats b.up { color: #2ae389; } .wdg-jr-stats b.down { color: #ff7259; }
.wdg-jr-openbtn { margin-left: auto; background: none; border: 0; padding: 0; font-size: 10.5px; font-weight: 600; color: var(--orange); cursor: pointer; }
.wdg-jr-openbtn:hover { text-decoration: underline; }
.wdg-jr-list { flex: 1 1 auto; min-height: 0; overflow-y: auto; }
/* Courbe de capital (comme le vrai Journal du desk) : bloc flexible entre les stats et le tableau */
.wdg-jr-chartwrap { flex: 0 1 auto; min-height: 118px; display: flex; flex-direction: column; padding: 6px 10px 2px; border-bottom: 1px solid var(--hud-line, var(--border)); }
.wdg-jr-chartlbl { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: .05em; color: var(--w-t7); }
.wdg-jr-chartlbl b { font-size: 12.5px; font-variant-numeric: tabular-nums; color: var(--w-t1); letter-spacing: 0; text-transform: none; }
.wdg-jr-chartlbl b.up { color: #2ae389; } .wdg-jr-chartlbl b.down { color: #ff7259; }
.wdg-jr-chart { flex: 1 1 auto; min-height: 92px; width: 100%; }
/* Onglets internes du widget Journal (Trades / Tableau de bord) + vues */
.wdg-jrtab { display: flex; gap: 2px; padding: 6px 10px 0; border-bottom: 1px solid var(--hud-line, var(--border)); flex: 0 0 auto; }
.wdg-jrtab button { background: none; border: none; border-bottom: 2px solid transparent; color: var(--w-t8); font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: .04em; padding: 6px 10px; cursor: pointer; }
.wdg-jrtab button:hover { color: var(--w-t2); }
.wdg-jrtab button.on { color: var(--orange); border-bottom-color: var(--orange); }
.wdg-jr-view { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; overflow: hidden; }
.wdg-jr-view[hidden] { display: none; }
.wdg-jr .wdg-jrtab + .wdg-jr-view { }
/* Bascule de courbe %/$PNL/R/$Capital */
.wdg-jr-eqtog { display: inline-flex; gap: 3px; margin-left: auto; }
.wdg-jr-eqtog button { background: var(--w-s3); border: 1px solid var(--hud-line, var(--border)); color: var(--w-t8); font-size: 9.5px; font-weight: 600; padding: 2px 7px; border-radius: 3px; cursor: pointer; letter-spacing: 0; text-transform: none; }
.wdg-jr-eqtog button:hover { color: var(--w-t2); border-color: var(--w-f2); }
.wdg-jr-eqtog button.on { color: var(--orange); border-color: rgba(227,178,58,.5); background: rgba(227,178,58,.10); }
.wdg-jr-eqval { font-size: 13px; font-weight: 700; color: var(--orange); font-variant-numeric: tabular-nums; letter-spacing: 0; text-transform: none; }

/* ── Tableau de bord du Journal : anneaux KPI + donut de répartition + métriques clés ── */
.wdg-jrd { flex: 1 1 auto; min-height: 0; overflow-y: auto; padding: 4px 12px 12px; }
.wdg-jrd-sec { font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: .06em; color: var(--orange); margin: 14px 0 8px; }
.wdg-jrk-row { display: flex; flex-wrap: wrap; gap: 12px 18px; justify-content: space-around; }
.wdg-jrk { display: flex; flex-direction: column; align-items: center; gap: 4px; min-width: 74px; }
.wdg-jrk-circ { width: 56px; height: 56px; border-radius: 50%; border: 2.5px solid; display: flex; align-items: center; justify-content: center; font-size: 14px; font-weight: 800; font-variant-numeric: tabular-nums; background: var(--bg); box-shadow: 0 0 12px -4px currentColor; }
.wdg-jrk-lbl { font-size: 10px; color: var(--w-t5); text-align: center; }
.wdg-jrk-sub { font-size: 8.5px; color: var(--w-t13); text-align: center; }
.wdg-jrd-donutwrap { display: flex; align-items: center; gap: 20px; padding: 4px 6px; }
.wdg-jrd-donut { position: relative; width: 118px; height: 118px; border-radius: 50%; flex: 0 0 auto; }
.wdg-jrd-donut::after { content: ''; position: absolute; inset: 26px; border-radius: 50%; background: var(--bg); }
.wdg-jrd-hole { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; z-index: 1; }
.wdg-jrd-hole b { font-size: 20px; font-weight: 800; color: var(--text); line-height: 1; }
.wdg-jrd-hole em { font-style: normal; font-size: 8.5px; text-transform: uppercase; letter-spacing: .08em; color: var(--w-t10); }
.wdg-jrd-legend { display: flex; flex-direction: column; gap: 5px; font-size: 11px; color: var(--w-t2); }
.wdg-jrd-legend span { display: inline-flex; align-items: center; gap: 6px; } .wdg-jrd-legend i { width: 9px; height: 9px; border-radius: 2px; } .wdg-jrd-legend b { color: #fff; margin-left: 2px; }

/* Barre d'actions du Journal (Nouveau trade / Ouvrir la page) + ligne cliquable */
.wdg-jr-tools { display: flex; align-items: center; gap: 8px; padding: 8px 12px; border-bottom: 1px solid var(--hud-line, var(--border)); flex: 0 0 auto; }
.wdg-jr-tools button { font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 11px; font-weight: 600; height: 26px; padding: 0 11px; border-radius: 4px; cursor: pointer; border: 1px solid; }
.wdg-jr-add { color: var(--bg); background: var(--orange); border-color: var(--orange); }
.wdg-jr-add:hover { background: var(--orange-dim, #cfa233); }
.wdg-jr-open { margin-left: auto; color: var(--w-t2); background: transparent; border-color: var(--hud-line, var(--border)); }
.wdg-jr-open:hover { color: var(--orange); border-color: rgba(227,178,58,.5); }
.wdg-jr-row { cursor: pointer; }
.wdg-jr-list .wdg-jr-row:hover { background: var(--w-s2); }
/* Formulaire d'ajout rapide inline */
.wdg-jr-qa { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; padding: 8px 12px; border-bottom: 1px solid var(--hud-line, var(--border)); background: var(--w-s3); flex: 0 0 auto; }
.wdg-jr-qa[hidden] { display: none; }
.wdg-jr-qa input, .wdg-jr-qa select { height: 28px; font-size: 12px; font-family: var(--font-ui); color: var(--w-t1); background: var(--bg2); border: 1px solid var(--hud-line, var(--border)); border-radius: 4px; padding: 0 8px; min-width: 0; }
.wdg-jr-qa input::placeholder { color: var(--w-t13); }
.wdg-jr-qa input:focus, .wdg-jr-qa select:focus { outline: none; border-color: rgba(227,178,58,.55); }
.wdg-jr-qa-pair { flex: 1 1 110px; } .wdg-jr-qa-pl { flex: 0 1 90px; } .wdg-jr-qa-dir, .wdg-jr-qa-res { flex: 0 1 auto; }
.wdg-jr-qa-save { height: 28px; padding: 0 12px; font-size: 11.5px; font-weight: 700; color: var(--bg); background: #00e676; border: none; border-radius: 4px; cursor: pointer; }
.wdg-jr-qa-save:hover { background: #0bd06f; } .wdg-jr-qa-save:disabled { opacity: .6; cursor: default; }
.wdg-jr-qa-cancel { height: 28px; width: 28px; color: var(--w-t8); background: transparent; border: 1px solid var(--hud-line, var(--border)); border-radius: 4px; cursor: pointer; font-size: 13px; }
.wdg-jr-qa-cancel:hover { color: #ff7259; border-color: rgba(255,61,0,.4); }
/* Bouton « Suppr. » (mode édition d'un trade) */
.wdg-jr-qa-del { height: 28px; padding: 0 10px; font-size: 11px; font-weight: 600; color: #ff7259; background: transparent; border: 1px solid rgba(255,61,0,.4); border-radius: 4px; cursor: pointer; }
.wdg-jr-qa-del:hover { background: rgba(255,61,0,.12); } .wdg-jr-qa-del[hidden] { display: none; } .wdg-jr-qa-del:disabled { opacity: .6; cursor: default; }
/* Crayon « modifier ce trade » : révélé au survol de la ligne, posé au bord droit (hors flux grille) */
.wdg-jr-row { position: relative; }
.wdg-jr-edit { position: absolute; right: 8px; top: 50%; transform: translateY(-50%); width: 24px; height: 22px; display: inline-flex; align-items: center; justify-content: center; color: var(--w-t8); background: var(--w-s2); border: 1px solid var(--hud-line, var(--border)); border-radius: 4px; cursor: pointer; opacity: 0; transition: opacity .1s, color .1s, border-color .1s; box-shadow: -10px 0 8px -4px var(--w-s3); }
.wdg-jr-row:hover .wdg-jr-edit { opacity: 1; }
.wdg-jr-edit:hover { color: var(--orange); border-color: rgba(227,178,58,.5); }
@media (hover: none) { .wdg-jr-edit { opacity: 1; box-shadow: none; background: transparent; border-color: transparent; } }   /* tactile : toujours visible (pas de survol) */

/* Gestionnaire : cadenas du desk par défaut (non supprimable) */
.wdg-mgr-lock { flex: 0 0 auto; width: 24px; height: 24px; display: inline-flex; align-items: center; justify-content: center; color: var(--w-t13); }

/* Badge NOUVEAU de l'icône Mon Desk : pastille or discrète, posée JUSTE AU-DESSUS de l'icône
   (ne recouvre pas le glyphe — demande user « ne masque pas l'icône ») ; pulse subtil ×3 puis statique. */
.wdg-new-badge { top: -6px; right: -6px; font-size: 6.5px; padding: 2px 4px; letter-spacing: 0.04em; }
.wdg-new-badge.pulse { animation: wdgNewPulse 1.5s ease-out 3; }
@keyframes wdgNewPulse { 0% { box-shadow: 0 0 0 1.5px var(--bg), 0 0 0 0 rgba(227,178,58,.55); } 60% { box-shadow: 0 0 0 1.5px var(--bg), 0 0 0 5px rgba(227,178,58,0); } 100% { box-shadow: 0 0 0 1.5px var(--bg), 0 0 0 0 rgba(227,178,58,0); } }
@media (prefers-reduced-motion: reduce) { .wdg-new-badge.pulse { animation: none; } }
/* En-tête de colonnes façon TABLE DU DESK (même grammaire que .macro-table th — cohérence, demande user 23/07) */
.wdg-jr-head { display: grid; grid-template-columns: minmax(62px, .8fr) minmax(70px, 1.1fr) minmax(54px, .7fr) minmax(56px, .8fr) minmax(64px, .8fr); gap: 8px; padding: 6px 12px; background: var(--w-s4); border-bottom: 1px solid var(--hud-line, var(--border)); font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: .05em; color: var(--w-t7); flex: 0 0 auto; }
.wdg-jr-head .r { text-align: right; }
.wdg-jr-row { display: grid; grid-template-columns: minmax(62px, .8fr) minmax(70px, 1.1fr) minmax(54px, .7fr) minmax(56px, .8fr) minmax(64px, .8fr); gap: 8px; align-items: center; padding: 6px 12px; border-bottom: 1px solid var(--w-f4); font-size: 11.5px; transition: background .1s; }
.wdg-jr-row:hover { background: var(--w-s3); }
.wdg-jr-date { color: var(--w-t8); font-variant-numeric: tabular-nums; white-space: nowrap; } .wdg-jr-pair { color: #e6e8ec; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; } .wdg-jr-side, .wdg-jr-restag { min-width: 0; }
.wdg-jr-res { text-align: right; font-variant-numeric: tabular-nums; font-weight: 600; color: var(--w-t5); white-space: nowrap; }
.wdg-jr-res.up { color: #2ae389; } .wdg-jr-res.down { color: #ff7259; }
/* Badges façon vrai Journal du desk (jr-dir/jr-chip) : ACHAT vert · VENTE rouge · TP vert · BE ambre · SL rouge */
.wdg-jr-tag { display: inline-block; font-size: 9.5px; font-weight: 700; letter-spacing: .04em; padding: 1px 7px; border-radius: 3px; border: 1px solid rgba(165,170,190,.30); color: var(--w-t4); background: rgba(165,170,190,.14); max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; vertical-align: middle; }
.wdg-jr-tag.buy, .wdg-jr-tag.tp { color: #00e676; background: rgba(0,230,118,.12); border-color: rgba(0,230,118,.35); }
.wdg-jr-tag.sell, .wdg-jr-tag.sl { color: #ff3d00; background: rgba(255,61,0,.12); border-color: rgba(255,61,0,.35); }
.wdg-jr-tag.be { color: #ffb300; background: rgba(255,179,0,.10); border-color: rgba(255,179,0,.32); }
.wdg-jr-ph { font-style: normal; color: var(--w-t14); }
.wdg-jr-empty { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; height: 100%; font-size: 11.5px; color: var(--w-t8); }

/* ── Widget Radar de Biais : réutilise le VRAI tableau du desk (.macro-table dans .macro-wrap, builder
   _sbRenderMacroTable) → rendu IDENTIQUE à l'onglet BIAIS. Ici on ne fait que le laisser remplir la carte
   et défiler (les styles de la table/tags viennent des classes desk globales .macro-* / .mt-*). ── */
.wdg-biaswrap { height: 100%; width: 100%; overflow: auto; }

/* ── Widget Taux directeurs : taux actuel + scénario de base de la prochaine réunion, par banque centrale ── */
.wdg-taux { height: 100%; overflow-y: auto; }
.wdg-taux-head, .wdg-taux-row { display: grid; grid-template-columns: minmax(84px, 1.2fr) 62px minmax(96px, 1fr) minmax(78px, .9fr); gap: 8px; align-items: center; padding: 6px 12px; }
.wdg-taux-head { position: sticky; top: 0; background: var(--w-s4); border-bottom: 1px solid var(--hud-line, var(--border)); font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: .05em; color: var(--w-t7); z-index: 1; }
.wdg-taux-head .r { text-align: right; }
.wdg-taux-row { border-bottom: 1px solid var(--w-f4); font-size: 11.5px; }
.wdg-taux-row:hover { background: var(--w-s3); }
.wdg-taux-bank { display: inline-flex; align-items: center; gap: 6px; color: var(--w-t1); min-width: 0; }
.wdg-taux-bank b { font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.wdg-taux-bank .cal-flag-img { width: 14px; height: 14px; border-radius: 50%; object-fit: cover; display: block; }
.wdg-taux-bank .cal-flag-wrap { display: inline-flex; flex: 0 0 auto; }
.wdg-taux-rate { font-variant-numeric: tabular-nums; color: var(--w-t1); font-weight: 600; white-space: nowrap; }
.wdg-taux-move { font-size: 10.5px; font-weight: 700; letter-spacing: .02em; padding: 1px 7px; border-radius: 3px; justify-self: start; white-space: nowrap; }
.wdg-taux-flat { background: rgba(107,114,128,.22); color: var(--w-t4); }
.wdg-taux-up { background: rgba(227,178,58,.16); color: var(--orange); }        /* Hausse = resserrement (or DTP) */
.wdg-taux-down { background: rgba(34,211,238,.16); color: #38bdf8; }      /* Baisse = assouplissement */
.wdg-taux-when { text-align: right; font-size: 10.5px; color: var(--w-t8); white-space: nowrap; }

/* ── Widgets « identiques au desk » (23/07) : fines surcouches de LAYOUT uniquement — le RENDU vient
   des classes desk réelles (.risk-*, .cot-*, .dmx-*, .season-*, .lf-*) réutilisées par les widgets ── */
/* Plancher hérité du desk (#rtab-risk #risk-widget : min-height 280px) : sans lui, sur une carte
   courte, le badge de lecture (APPÉTIT / FORTE AVERSION…) se posait SUR l'arc de la jauge et le
   débordait des deux côtés — mesuré : 15,7 px de l'arc passaient derrière le badge, et le badge était
   41 % plus large que la jauge entière. Le corps de carte défile (overflow auto) au lieu d'écraser. */
/* ⚠️ 280 -> 240 (29/08, capture user « on doit voir l integralite du texte en bas, les mois »).
   Le plancher de 280px venait de l onglet RISQUE du desk. Additionne au plancher de la bande
   d historique, il donnait un minimum de panneau que les cartes courtes ne pouvaient pas tenir :
   le panneau depassait, le corps defilait, et le bas de l histogramme — l axe des mois — passait
   sous le pli. VERIFIE au banc avec le VRAI amCharts (bundle npm) : les etiquettes de l axe sont
   TOUJOURS a l interieur de leur canevas, a ~2px du bas, de 103 a 170px de bande. Le graphique ne
   deborde donc pas : c est bien la place qui manque au panneau.
   240 laisse intacte la scene de la jauge (`.risk-gauge-stage`, plancher 190px) et le bandeau
   (~40px) : l arc et le badge ne bougent pas d un pixel, on ne retire que le mou. */
.wdg-riskwrap { height: 100%; min-height: 240px; }
.wdg-riskwrap .risk-gauge-stage { min-height: 190px; }
.wdg-riskgauge { position: absolute; inset: 0; }   /* même rôle que #risk-gauge-div (jauge du desk) */

/* ── Widgets COT / DMX / Saisonnalité : conteneurs (le rendu = classes desk .cot-* / .dmx-* / .season-*) ── */
.wdg-cotwrap, .wdg-dmxwrap, .wdg-seawrap { height: 100%; display: flex; flex-direction: column; min-height: 0; }
.wdg-cotwrap .cot-grid { flex: 1 1 auto; min-height: 0; }
/* Grille PAVANTE (04/08) : _cotFit() pose colonnes ET rangées en 1fr → les 8 cartes remplissent
   exactement le bloc. Plus d'orpheline seule en bas ni de zone morte à droite (l'ancien
   repeat(auto-fit, minmax(150px,1fr)) tombait sur 7 colonnes + 1). Le défilement ne revient que
   si le bloc est trop petit pour un rectangle lisible (classe --scroll posée par _cotFit). */
.cot-grid--fit { overflow: hidden; grid-auto-rows: auto; }
.cot-grid--fit.cot-grid--scroll { overflow-y: auto; }
/* Le badge de catégorie répétait la même valeur sur les 8 cartes en se tronquant
   (« Fonds à effet… ») : la catégorie vit dans les réglages, la carte n'a plus à la porter. */
/* Le donut restait figé à 96 px quelle que soit la carte (width/height auto + max-* qui ne font que
   rétrécir) → gros vides au-dessus et en dessous. Il occupe maintenant sa case, ratio préservé. */
/* 04/08 — « c'est trop gros ». Laisser le donut prendre 88 % de la carte remplissait le bloc mais
   donnait une infographie grand public, pas un terminal. La règle : la carte se remplit par
   l'INFORMATION (chiffres lisibles), pas en gonflant le cercle. Donut ramené à ~52 % / 132 px max,
   le reste de la hauteur va aux chiffres, qui grandissent. */
/* La légende Court/Long redit ce que les colonnes « Positions courtes / longues » disent déjà,
   en couleur : une ligne de gagnée pour les chiffres. */
.wdg-dmxwrap .dmx-table-wrap { flex: 1 1 auto; min-height: 0; overflow-y: auto; }
.wdg-seawrap .season-table-wrap { flex: 1 1 auto; min-height: 0; overflow: auto; }

/* ── Widget Sessions de marché : la VRAIE carte Leaflet du desk (classes .lf-* globales) ── */
.wdg-mapwrap { height: 100%; display: flex; flex-direction: column; min-height: 0; }
.wdg-map-sub { padding: 6px 12px; flex: 0 0 auto; font-size: 11px; }
.wdg-lfmap { position: relative; flex: 1 1 auto; min-height: 0; overflow: hidden; }
.wdg-lfmap .leaflet-container { background: var(--w-s4); font-family: var(--font-ui); outline: none; }

/* Widget Horloge mondiale : réutilise les .clock-item du desk (rendus par le VRAI renderClocks) ; on passe
   la barre en flex-wrap pour qu'elle remplisse n'importe quelle largeur de carte (5 sur une ligne en large,
   repli 2-3/ligne en étroit) — cellules internes strictement identiques au desk. */
/* CONTENEUR DE REQUÊTE EN HAUTEUR (03/08, capture user « l'heure est trop sur le texte ») : la cellule
   d'horloge du desk mesure ~120 px de contenu naturel ; dans une carte plus basse (Vue générale :
   bande de 4 rangées), le centrage + overflow:hidden ÉCRASAIENT les lignes — l'heure venait mordre
   sur « GMT ». La typo se resserre par PALIERS selon la hauteur RÉELLE du widget, et rien ne se
   chevauche plus à aucune hauteur (banc). container-type:size est sûr ici : height:100% est définie. */
.wdg-clockwrap { height: 100%; overflow-y: auto; min-height: 0; container-type: size; container-name: dtphorloge; }
.wdg-clocks-bar .clock-time { margin: 2px 0 3px; }              /* respiration de base heure ↔ GMT */
@container dtphorloge (max-height: 132px) {
  .clock-item { padding: 4px 11px; }
  .clock-top-row { margin-bottom: 1px; }
  .clock-wday, .clock-date { font-size: 10px; }
  .clock-time { font-size: 16px; margin: 1px 0 2px; }
  .clock-gmt { font-size: 9px; }
  .clock-city-label { font-size: 11px; }
  .clock-mid-row { margin-bottom: 2px; gap: 0; }
  .clock-country-row, .clock-sub-row { font-size: 9px; }
}
/* ⚠️ PALIER INTERMÉDIAIRE (02/09) — il manquait, et c'est par ce trou que le contenu débordait.
   Entre « compact » (≤132) et « sans météo » (≤96) il y avait un vide de 36 px : à ~108 px de
   cadre, le contenu compacté mesurait encore ~118 px. Mesuré au banc : 10 px hors cadre, donc le
   vent et le pays de chaque place inatteignables sans défiler. Ici la SECONDE sous-ligne (jour/nuit
   + vent) cède seule : c'est la moins chère des deux, la météo du dessus reste. */
@container dtphorloge (max-height: 112px) {
  .clock-sub-row + .clock-sub-row { display: none; }
  .clock-time { font-size: 15px; }
}
@container dtphorloge (max-height: 96px) {
  /* Très bas : la météo cède — l'heure, le fuseau et la ville priment. */
  .clock-sub-row { display: none; }
  .clock-time { font-size: 15px; }
}
/* Dernier palier : à ce point la carte n'est plus qu'une bande. On garde l'HEURE et la VILLE —
   c'est ce pour quoi on ouvre une horloge — et la date du haut cède à son tour. */
@container dtphorloge (max-height: 76px) {
  .clock-top-row { display: none; }
  .clock-item { padding: 3px 10px; }
  .clock-time { font-size: 14px; margin: 0 0 1px; }
  .clock-mid-row { margin-bottom: 0; }
}
/* Plancher absolu : à moins de 56 px de cadre il ne reste la place que pour DEUX informations. On
   garde l'heure et la ville — le fuseau se déduit de la ville, l'inverse est faux. En dessous, on
   ne compacte plus : ce serait rendre illisible ce qui doit rester lu. */
@container dtphorloge (max-height: 56px) {
  .clock-gmt { display: none; }
  .clock-item { padding: 2px 10px; }
  .clock-time { font-size: 13px; margin: 0; line-height: 1.15; }
}
/* IDENTIQUE AU DESK (demande user 26/07 « le widget doit remplir comme cette image ») : grille de colonnes
   ÉGALES qui occupe TOUTE la largeur et TOUTE la hauteur de la carte, villes collées et séparées par un
   simple filet vertical — plus de cartes détachées à coins arrondis avec des gouttières.
   `auto-fit` conserve l'adaptation du widget : 5 colonnes quand la place le permet, moins si la carte est
   étroite, mais TOUJOURS pleine largeur (les pistes vides sont supprimées, les items s'étirent). */
.wdg-clocks-bar {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(132px, 1fr));
  /* ⚠️ height:100% + align-content:stretch VERROUILLAIENT la grille à la hauteur du wrap : dès que
     auto-fit replie en ≥2 rangées (carte étroite, ou plus de 5 places choisies), chaque rangée
     recevait une FRACTION du wrap (~61px mesurés pour ~120px de contenu) et .clock-item
     { overflow:hidden } coupait GMT, ville, pays, météo — et le défilement du wrap (overflow-y:
     auto, jamais engagé : contenu = contenant) ne pouvait pas secourir. Le bloc ≤768 corrigeait
     ce cas depuis le 23/08 ; au-dessus de 768px il subsistait (REPRODUIT au banc : carte 300px,
     3 rangées, vent de la dernière ville inatteignable). Recette : hauteur de CONTENU avec
     plancher 136px par rangée (la cellule entière) et min-height:100% — quand tout tient, 1fr
     étire les rangées comme avant, à l'identique ; quand ça ne tient plus, la grille dépasse et
     le wrap défile enfin. Le bloc mobile ≤768, plus spécifique, reste maître sous 768px. */
  gap: 0; padding: 0; background: var(--bg1); height: auto; min-height: 100%; align-content: stretch;
  /* ⚠️ LE PLANCHER NE DOIT JAMAIS DÉPASSER LE CADRE (02/09, 3e signalement du même défaut : « on
     voit même pas toutes les informations de l'horloge mondiale »). Le widget a DEUX dispositifs
     d'adaptation, posés à des dates différentes, et ils se contredisaient : les requêtes de
     conteneur compactaient le contenu quand la carte devient basse, pendant que ce plancher restait
     bloqué à 136 px. Mesuré au banc sur une seule rangée de cinq places : cadre 88 px, rangée
     136 px — 38 px de contenu hors cadre, et le bas des horloges (pays, météo, vent) inatteignable
     autrement qu'en défilant.
     `min(136px, 100cqh)` réconcilie les deux : sur UNE rangée, le plancher s'aligne exactement sur
     la hauteur du cadre, donc rien ne dépasse et les paliers font leur travail ; sur PLUSIEURS
     rangées, il reprend ses 136 px et la grille déborde — c'est le défilement de dernier recours,
     celui qui a toujours été voulu. L'unité `cqh` est disponible ici parce que `.wdg-clockwrap` est
     déclaré `container-type: size`. */
  grid-auto-rows: minmax(min(136px, 100cqh), 1fr);
}
.wdg-clocks-bar .clock-item {
  flex: none; min-width: 0; background: transparent;
  border: 0; border-right: 1px solid var(--border); border-radius: 0;
  justify-content: center;                 /* le contenu se centre quand la ligne s'étire en hauteur */
}
.wdg-clocks-bar .clock-item:last-child { border-right: 0; }
.wdg-clocks-bar .clock-item--local { border: 0; border-right: 1px solid var(--border); }

/* ── Onglets de layouts (templates) dans l'en-tête ── */
.wdg-layouts { display: flex; align-items: stretch; height: 100%; gap: 0; overflow-x: auto; max-width: 52vw; }
.wdg-layouts::-webkit-scrollbar { height: 0; }                 /* pas de scrollbar visible sur la barre d'onglets */
.wdg-layouts { scrollbar-width: none; }   /* volontairement masquée : la règle globale la ferait réapparaître */
/* Onglets de templates = IDENTIQUES à la nav du desk (.nav-item) : plat, capitales, chevron ›, pleine hauteur,
   soulignement or ANIMÉ ::after quand actif (même mécanisme + même animation navUnderlineIn que .nav-item--active). */
/* Les onglets de Mon Desk SONT des .nav-item (voir renderBar) : police, taille, graisse,
   interlettrage, casse, marges, couleurs, survol et soulignement actif viennent tous de la nav du
   desk. On ne déclare ici QUE les deux ajouts propres à Mon Desk : l'espacement du chevron et de
   l'étoile, et la largeur maximale d'un nom (les layouts sont renommables, donc de longueur libre). */
/* background/appearance : les onglets de Mon Desk sont des <button>, la nav du desk non —
   sans ça le fond gris par défaut du navigateur apparaît au repos. Ce n'est pas une recopie de
   valeur de la nav, c'est la neutralisation d'un style d'agent utilisateur. */
.wdg-lay { gap: 5px; max-width: 190px; border: none; background: transparent; -webkit-appearance: none; appearance: none; }
/* Soulignement or de l'onglet actif : fourni par .nav-item--active::after (règle du desk).
   Le doublon qui vivait ici empilait DEUX traits — le soulignement paraissait plus épais que sur
   « › ACTUS ». Ne pas le réintroduire. */
.wdg-lay-chv { color: inherit; font-weight: 400; margin-right: 1px; }   /* › : même couleur que le libellé, comme la nav */
.wdg-lay.on .wdg-lay-chv { color: inherit; }                    /* › blanc quand actif (comme « › ACTUS »), pas d'or */
.wdg-lay-name { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.wdg-lay-star { color: var(--orange); font-size: 10px; line-height: 1; }
.wdg-lay-edit { font-family: var(--font-mono); font-size: 11px; text-transform: uppercase; letter-spacing: .06em; color: var(--w-t1); background: var(--bg2); border: 1px solid var(--orange); border-radius: 3px; padding: 2px 6px; max-width: 150px; }
.wdg-lay-add { color: var(--w-t13); font-size: 15px; font-weight: 700; height: 100%; padding: 0 12px; display: inline-flex; align-items: center; }
.wdg-lay-add:hover { color: var(--orange); }

/* ── Gestionnaire de layouts (overlay, réutilise .wdg-lib) ── */
/* Meme largeur que la bibliotheque : les deux onglets du panneau se remplacent en place, une
   largeur differente ferait sauter le volet a chaque bascule Layouts <-> Widgets. */
.wdg-mgr-box { width: min(468px, 90%); }
.wdg-mgr-list { flex: 1 1 auto; min-height: 0; overflow-y: auto; padding: 12px 14px; display: flex; flex-direction: column; gap: 6px; }
.wdg-mgr-row {
  display: flex; align-items: center; gap: 8px; padding: 6px 8px;
  background: var(--head-bg); border: 1px solid var(--hud-line, var(--border)); border-radius: var(--radius);
}
.wdg-mgr-row.on { border-color: rgba(227,178,58,.45); }
.wdg-mgr-star { flex: 0 0 auto; width: 22px; height: 22px; background: transparent; border: 0; cursor: pointer; color: var(--w-t17); font-size: 13px; border-radius: 3px; }
.wdg-mgr-star:hover { color: var(--orange); }
.wdg-mgr-star.on { color: var(--orange); }
.wdg-mgr-name {
  flex: 1 1 auto; min-width: 0; padding: 5px 8px; font-size: 12.5px; font-family: var(--tight, 'Inter Tight', sans-serif); font-weight: 600;
  color: var(--text, var(--w-t1)); background: var(--bg2); border: 1px solid transparent; border-radius: 3px;
}
.wdg-mgr-name:hover { border-color: var(--hud-line, var(--border)); }
.wdg-mgr-name:focus { outline: none; border-color: var(--orange); background: var(--bg); }
.wdg-mgr-count { flex: 0 0 auto; font-size: 10.5px; color: var(--text3, var(--w-t9)); font-variant-numeric: tabular-nums; white-space: nowrap; }
.wdg-mgr-open {
  flex: 0 0 auto; padding: 4px 10px; font-size: 10.5px; font-weight: 600; border-radius: 3px; cursor: pointer;
  background: rgba(227,178,58,.1); color: var(--orange); border: 1px solid rgba(227,178,58,.38);
}
.wdg-mgr-open:hover { background: rgba(227,178,58,.2); border-color: var(--orange); }
.wdg-mgr-del { flex: 0 0 auto; width: 24px; height: 24px; background: transparent; border: 0; cursor: pointer; color: var(--w-t13); font-size: 15px; border-radius: 3px; }
.wdg-mgr-del:hover { color: #ff3d00; background: rgba(255,61,0,.1); }
.wdg-mgr-del.confirm { width: auto; padding: 0 9px; font-size: 10.5px; font-weight: 700; color: #fff; background: #ff3d00; }
.wdg-mgr-new {
  margin-top: 2px; padding: 8px; font-size: 11.5px; font-weight: 600; border-radius: var(--radius); cursor: pointer;
  background: rgba(227,178,58,.11); color: var(--orange); border: 1px dashed rgba(227,178,58,.45);
}
.wdg-mgr-new:hover { background: rgba(227,178,58,.2); border-color: var(--orange); }
.wdg-mgr-full { padding: 8px; font-size: 10.5px; color: var(--w-t13); text-align: center; font-style: italic; }
.wdg-mgr-foot { flex: 0 0 auto; padding: 10px 14px; border-top: 1px solid var(--hud-line, var(--border)); display: flex; justify-content: flex-end; gap: 8px; flex-wrap: wrap; }

/* Recherche de la bibliothèque */
.wdg-lib-search-row { flex: 0 0 auto; padding: 10px 14px 0; }
.wdg-lib-search { width: 100%; height: 30px; padding: 0 11px; font-size: 12px; font-family: var(--tight, 'Inter Tight', sans-serif); color: var(--w-t1); background: var(--head-bg); border: 1px solid var(--hud-line, var(--border)); border-radius: var(--radius); }
.wdg-lib-search::placeholder { color: var(--w-t13); }
.wdg-lib-search:focus { outline: none; border-color: rgba(227,178,58,.55); }

/* Miniature d'agencement (gestionnaire + modèles prêts) : la grille 12 colonnes en réduction */
.wdg-thumb { flex: 0 0 auto; display: grid; grid-template-columns: repeat(12, 1fr); grid-auto-rows: 4px; gap: 1.5px; width: 52px; padding: 3px; background: var(--bg); border: 1px solid var(--w-s1); border-radius: 3px; }
/* Bloc = un widget. Teinte portée par --tc (famille du widget, posée en inline par _thumb) : la vignette
   se lit d'un coup d'œil (or = devises, bleu = macro, rouge = risque, violet = news, vert = outils). */
.wdg-thumb i {
  display: block; border-radius: 1px; min-height: 4px; overflow: hidden;
  background: color-mix(in srgb, var(--tc, #e3b23a) 26%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--tc, #e3b23a) 34%, transparent);
}
.wdg-mgr-row.on .wdg-thumb i { background: color-mix(in srgb, var(--tc, #e3b23a) 42%, transparent); }

/* Vignette LISIBLE (gestionnaire, modèles, accueil) : plus grande + micro-libellé du widget dans le bloc. */
.wdg-thumb--lbl { width: 88px; grid-auto-rows: 6px; gap: 2px; padding: 4px; }
.wdg-thumb--lbl i { display: flex; align-items: center; justify-content: center; }
.wdg-thumb--lbl b {
  font-family: var(--mono, ui-monospace, monospace); font-weight: 600; font-size: 5.5px; line-height: 1;
  letter-spacing: .04em; color: color-mix(in srgb, var(--tc, #e3b23a) 86%, #fff);
  max-width: 100%; overflow: hidden; text-overflow: clip; white-space: nowrap; padding: 0 1px;
}
.wdg-mgr-row .wdg-thumb--lbl { flex: 0 0 auto; }
.wdg-tpl-card .wdg-thumb--lbl, .wdg-dispo-card .wdg-thumb--lbl { width: 100%; }
/* Thème clair : mêmes teintes, fond de vignette clair (les blocs restent contrastés). */
html[data-theme="light"] .wdg-thumb--lbl b { color: color-mix(in srgb, var(--tc, #b8860b) 92%, #000); }

/* Galerie de MODÈLES dans la bibliothèque : vignette EN HAUT + nom CENTRÉ dessous (jamais à droite, demande user) */
.wdg-tpl-row { grid-column: 1 / -1; display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 10px; margin-bottom: 4px; }
.wdg-tpl-card {
  display: flex; flex-direction: column; align-items: center; gap: 7px; cursor: pointer; text-align: center;
  padding: 12px 10px; background: var(--head-bg); border: 1px solid var(--hud-line, var(--border)); border-radius: var(--radius);
  transition: border-color .14s, background .14s;
}
.wdg-tpl-card:hover:not(:disabled) { border-color: rgba(227,178,58,.55); background: var(--w-s3); }
.wdg-tpl-card:disabled { opacity: .45; cursor: not-allowed; }
.wdg-tpl-card .wdg-thumb { width: 100%; grid-auto-rows: 6px; padding: 5px; }
.wdg-tpl-name { font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 12.5px; font-weight: 700; color: var(--text, var(--w-t1)); }
.wdg-tpl-n { font-size: 10.5px; color: var(--text3, var(--w-t9)); }

/* Modèles prêts */
.wdg-mgr-row--preset { background: var(--w-s3); }
.wdg-mgr-pname { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 1px; font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 12px; font-weight: 600; color: var(--w-t1); }
.wdg-mgr-pname em { font-style: normal; font-size: 10px; font-weight: 400; color: var(--w-t11); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.wdg-mgr-open:disabled { opacity: .4; cursor: not-allowed; }
.wdg-mgr-note { padding: 6px 10px; font-size: 11px; color: #2ae389; }
/* Masquer / ré-ouvrir un layout (dossier) : ouvert = or, fermé = gris + badge « Fermé » ; l'onglet suit */
.wdg-mgr-eye {
  flex: 0 0 auto; display: inline-flex; align-items: center; justify-content: center;
  width: 26px; height: 26px; background: none; border: none; cursor: pointer;
  color: var(--w-t14); border-radius: 4px; transition: color .13s, background .13s;
}
.wdg-mgr-eye:hover { background: var(--w-s1); color: var(--w-t1); }
.wdg-mgr-eye.on { color: var(--orange); }
.wdg-mgr-closed {
  flex: 0 0 auto; font-size: 9px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase;
  color: var(--w-t8); background: var(--w-s1); border: 1px solid var(--hud-line, var(--border));
  padding: 2px 7px; border-radius: 3px;
}
/* Ancienne rangée du champ NOM, restée au-dessus des dispositions jusqu'au 17/08. Le nom (et
   désormais l'icône) se saisissent à l'écran suivant : cf. « ÉCRAN NOM + ICÔNE » en fin de feuille.
   La règle est conservée : rien ne la porte plus, mais une disposition exportée d'une version
   antérieure peut encore la traverser sans se déformer. */
.wdg-dispo-namerow { margin: 0 0 12px; }

/* Manquantes historiques : cadenas du desk protégé + ligne sauvegarde du pied de modale */
.wdg-mgr-lock { display: inline-flex; align-items: center; color: var(--w-t14); padding: 0 6px; }
.wdg-mgr-bak { display: flex; align-items: center; gap: 10px; margin-right: auto; }
.wdg-mgr-bak-lbl { font-size: 10.5px; color: var(--w-t11); }
/* Renvoi discret vers les modèles prêts (déplacés dans la bibliothèque pour ne pas brouiller la création) */
.wdg-mgr-tplhint { margin-top: 10px; font-size: 10.5px; color: var(--w-t11); line-height: 1.5; }
.wdg-mgr-tpllink { background: none; border: none; padding: 0; color: var(--orange); cursor: pointer; font-size: 10.5px; text-decoration: underline; text-underline-offset: 2px; }
.wdg-mgr-tpllink:hover { color: #f0c96a; }

/* ── CHOIX DE DISPOSITION (création guidée d'un layout, mini-schémas façon « Select Layout ») ── */
.wdg-dispo-head { display: flex; align-items: center; gap: 10px; margin-bottom: 12px; }
.wdg-dispo-t { font-size: 11.5px; color: var(--w-t1); font-weight: 700; letter-spacing: .05em; text-transform: uppercase; }
.wdg-dispo-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(112px, 1fr)); gap: 10px; }
.wdg-dispo-card {
  display: flex; flex-direction: column; align-items: center; gap: 7px; padding: 12px 8px;
  background: var(--w-s3); border: 1px solid var(--hud-line, var(--border)); border-radius: 6px; cursor: pointer;
  transition: border-color .15s, transform .12s;
}
.wdg-dispo-card:hover { border-color: rgba(227,178,58,.55); transform: translateY(-1px); }
.wdg-dispo-card .wdg-thumb { width: 100%; grid-auto-rows: 7px; }
.wdg-thumb--free { display: flex; align-items: center; justify-content: center; color: var(--w-t14); font-size: 17px; min-height: 30px; width: 100%; }
/* ── VIGNETTE « PLAN » (02/08) : blocs en POSITIONS EXACTES (pourcentages du placement 2D réel),
   plus de rangées arrondies — c'est ce qui désalignait les colonnes (« le bloc de gauche doit aller
   tout en bas »). Ratio figé ~2,15:1 : sur le desk, les rangées s'étirent pour remplir l'écran, donc
   TOUTES les dispositions ont le même cadre — la vignette aussi. L'enveloppe interne est nécessaire :
   un enfant absolu se place par rapport à la boîte de padding, le padding du cadre serait ignoré. */
/* HAUTEUR DE L'APERÇU — boîte de ratio, PAS `aspect-ratio` seul (correctif 12/08, bug user « on ne
   voit pas bien l'aperçu, c'est sur mobile »). Le plan est un conteneur VIDE : tous ses blocs sont en
   position absolue, donc sa hauteur ne vient QUE de la propriété de ratio. Si `aspect-ratio` n'est
   pas honoré — vieux WebKit mobile, ou l'un des cas connus où il se résout à 0 dans le contenu
   anonyme d'un <button> — la boîte tombe à 0 et la carte devient un rectangle noir, ce que montrait
   la capture. Le `padding-top` en pourcentage, lui, marche partout depuis toujours et se calcule sur
   la LARGEUR du parent : la hauteur est garantie même quand `aspect-ratio` est ignoré.
   `min-height` en plus : dernier filet, l'aperçu ne peut jamais devenir invisible. */
.wdg-thumb--plan { display: block; position: relative; padding: 0; min-height: 74px; }
.wdg-thumb--plan::before { content: ''; display: block; padding-top: 46.5%; }   /* 1 / 2.15 */
@supports (aspect-ratio: 1) {
  .wdg-thumb--plan { aspect-ratio: 2.15 / 1; }
  .wdg-thumb--plan::before { display: none; }
}
.wdg-tpl-card .wdg-thumb--plan { height: 76px; aspect-ratio: auto; min-height: 0; }   /* la carte modèle fige déjà sa hauteur */
.wdg-tpl-card .wdg-thumb--plan::before { display: none; }
.wdg-plan-in { position: absolute; inset: 3px; display: block; }
.wdg-thumb--lbl .wdg-plan-in { inset: 4px; }
.wdg-thumb--plan i {
  position: absolute; display: flex; align-items: center; justify-content: center;
  box-sizing: border-box; border: 1px solid var(--bg); min-height: 0;
}
.wdg-dispo-name { font-size: 11px; color: var(--text2, var(--w-t6)); text-align: center; }
.wdg-dispo-hint { margin-top: 12px; font-size: 10.5px; color: var(--w-t11); line-height: 1.5; }
/* Rangées GROUPÉES par nombre de panneaux (chiffre à gauche, façon « Select Layout ») */
.wdg-dispo-row { display: flex; align-items: flex-start; gap: 10px; margin-bottom: 10px; }
.wdg-dispo-num { flex: 0 0 auto; width: 20px; text-align: center; font-family: var(--mono, ui-monospace, monospace); font-size: 11px; color: var(--w-t11); padding-top: 16px; }
.wdg-dispo-cards { flex: 1; display: grid; grid-template-columns: repeat(auto-fill, minmax(100px, 1fr)); gap: 8px; }
.wdg-dispo-cards .wdg-dispo-card { padding: 9px 6px; gap: 6px; }

/* Modèles prêts : cartes ALIGNÉES (vignette à hauteur FIXE, dessin ancré en haut → noms au même niveau)
   + liste LISIBLE des widgets contenus (2 lignes max) */
.wdg-tpl-card .wdg-thumb { height: 76px; align-content: start; }
.wdg-tpl-list { font-size: 10.5px; color: var(--text2, var(--w-t6)); line-height: 1.45; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }

/* ── Widget « Panneau à onglets » : barre d'onglets grammaire NAV du desk, dans une carte ── */
.wdgt-host { display: flex; flex-direction: column; height: 100%; min-height: 0; }
.wdgt-bar { flex: 0 0 auto; display: flex; align-items: stretch; overflow-x: auto; background: var(--head-bg, var(--w-s3)); border-bottom: 1px solid var(--hud-line, var(--border)); min-height: 30px; scrollbar-width: none; }
.wdgt-bar::-webkit-scrollbar { height: 0; }
.wdgt-tab { position: relative; display: inline-flex; align-items: center; gap: 4px; padding: 0 11px; background: none; border: none; cursor: pointer; font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 10.5px; font-weight: var(--fw-semibold, 600); letter-spacing: .05em; text-transform: uppercase; color: var(--text3, var(--w-t13)); white-space: nowrap; transition: color .14s; }
.wdgt-chv { opacity: .8; }
.wdgt-tab:hover { color: var(--w-t1); }
/* Le liseré de l'onglet actif est ATTÉNUÉ (28/08, demande utilisateur : « réduis légèrement la
   clarté de ce trait doré »). Il tapait à l'or plein — la même encre que les titres de rubrique et
   les valeurs de marque — pour ne signaler qu'une position de navigation. On garde la teinte, on
   baisse la présence : l'onglet actif se lit toujours (encre blanche + graisse), le trait le
   confirme sans réclamer l'attention. C'est le dernier survivant du nettoyage des soulignements du
   21/08, qui avait retiré tous les autres. */
.wdgt-tab.on { color: var(--text); font-weight: var(--fw-bold, 700); box-shadow: inset 0 -2px 0 rgba(227, 178, 58, .55); }
/* (.wdgt-x supprimé 02/08 : la croix au survol détruisait un onglet par accident — le retrait et le
   renommage vivent dans les Réglages de la carte : .wdg-set-tabrow ci-dessous.) */
.wdg-set-tabs-t { font-size: 10px; letter-spacing: .07em; text-transform: uppercase; color: var(--text3, #8a8f98); font-weight: 700; margin: 2px 0 4px; }
.wdg-set-tabrow { gap: 8px; }
.wdg-set-tabin {
  flex: 1 1 auto; min-width: 0;
  background: var(--bg2); border: 1px solid var(--border); border-radius: 4px;
  color: var(--text); font-size: 11px; font-family: inherit; padding: 5px 8px;
}
.wdg-set-tabin:focus { border-color: rgba(227, 178, 58, .5); outline: none; }
.wdg-set-tabdel {
  flex: 0 0 auto; width: 24px; height: 24px;
  background: transparent; border: 1px solid var(--border); border-radius: 4px;
  color: var(--text3, #8a8f98); cursor: pointer; font-size: 13px; line-height: 1;
  transition: color .12s, border-color .12s;
}
.wdg-set-tabdel:hover { color: #ef4444; border-color: rgba(239, 68, 68, .5); }
.wdgt-add { flex: 0 0 auto; background: none; border: none; color: #8a7440; cursor: pointer; font-size: 14px; padding: 0 10px; }
.wdgt-add:hover { color: var(--orange); }
/* ⚠️ overflow-y:auto, PAS hidden (25/08, audit 38 widgets : un sous-widget à minima durs —
   jauge de risque 450px, grille du baromètre 240px… — était CLIPPÉ dans l'onglet sans aucun
   moyen d'accès : mesuré 158px inatteignables pour l'onglet RISQUE dans une carte de 360).
   Même doctrine que le .wdg-body des cartes simples, qui défile depuis toujours. */
.wdgt-body { flex: 1 1 auto; min-height: 0; position: relative; overflow-y: auto; overflow-x: hidden; display: flex; flex-direction: column; }
.wdgt-body > * { flex: 1 1 auto; min-height: 0; }

/* ── Force des Devises : DOUBLE panneau TD | TW (miroir de l'onglet › FORCE du desk) ── */
/* PANNEAU UNIQUE (01/08) : la barre de periodes en haut, le graphe prend le reste. Meme gabarit
   de barre que les en-tetes de panneau du desk, et les boutons reutilisent .stf-btn — pas un
   troisieme style de boutons dans le produit. */
.wdg-fx-solo { display: flex; flex-direction: column; height: 100%; min-height: 0; }
.wdg-fx-tfbar { display: flex; align-items: center; justify-content: flex-end; gap: 3px; flex: 0 0 auto; height: 24px; padding: 0 2px 4px; }
.wdg-fx-tfbar--head { height: auto; padding: 0; margin-left: auto; margin-right: 6px; }
.wdg-fx-tfbar--head .stf-btn { height: 18px; padding: 0 6px; font-size: 9.5px; }
.wdg-fx-tfbar .stf-btn { height: 20px; padding: 0 7px; font-size: 10px; }
/* (.wdg-fx-dual / .wdg-fx-pane / .wdg-fx-cap : double panneau retire, regles conservees sans effet.) */
.wdg-fx-dual { display: grid; grid-template-columns: 1fr 1fr; height: 100%; min-height: 0; }
.wdg-fx-pane { position: relative; min-width: 0; min-height: 0; display: flex; flex-direction: column; }
.wdg-fx-pane--l { border-right: 1px solid var(--hud-line, var(--w-f3)); }
.wdg-fx-cap { position: absolute; top: 4px; right: 8px; z-index: 2; font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 9.5px; font-weight: var(--fw-bold, 700); letter-spacing: .06em; color: var(--orange); opacity: .85; pointer-events: none; }
.wdg-fx-chart { flex: 1 1 auto; min-height: 0; width: 100%; }

/* ── BIBLIOTHÈQUE : cartes avec APERÇU visuel (vignette à gauche, nom + description à droite) ── */
.wdg-lib-card--prev { position: relative; align-items: center; gap: 10px; }
.wdg-lib-prev {
  display: block; height: 58px; background: var(--w-s4); border: 1px solid var(--w-f3); border-radius: 4px;
  overflow: hidden; pointer-events: none;
}
.wdg-lib-prev svg { width: 100%; height: 100%; display: block; }
.wdg-lib-card--prev .wdg-lib-plus, .wdg-lib-card--prev .wdg-lib-used { position: absolute; top: 8px; right: 8px; }

/* ── Overlay DÉTAIL MACRO d'une devise (widget Radar de Biais) : le vrai .mdet-panel du desk dans une boîte large ── */
.wdg-mdet-box { width: min(980px, 96%); max-height: 88%; overflow-y: auto; padding: 0; }
.wdg-mdet-box .mdet-panel { padding: 12px 14px; }

/* ── Panneau UNIFIÉ « Personnaliser » : onglets internes Widgets | Layouts (grammaire nav du desk :
   chevron ›, capitales, actif blanc/gras + soulignement OR flush sur la bordure de l'en-tête) ── */
.wdg-lib-head { padding: 0 14px; min-height: 42px; gap: 12px; }
.wdg-panel-tabs { display: flex; align-items: stretch; align-self: stretch; margin-right: auto; margin-left: 6px; }
.wdg-ptab {
  position: relative; display: inline-flex; align-items: center; padding: 0 12px;
  background: none; border: none; cursor: pointer;
  font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 11px; font-weight: var(--fw-semibold, 600);
  letter-spacing: .06em; text-transform: uppercase; color: var(--text3, var(--w-t13));
  transition: color .15s;
}
.wdg-ptab:hover { color: var(--w-t1); }
.wdg-ptab.on { color: var(--text); font-weight: var(--fw-bold, 700); }
.wdg-ptab.on::after { content: ''; position: absolute; left: 12px; right: 12px; bottom: -1px; height: 2px; background: var(--orange); }
@media (max-width: 560px) { .wdg-ptab { padding: 0 8px; font-size: 10px; } .wdg-lib-title { display: none; } }

/* ── Rangée d'outils de la bibliothèque : puces de catégories + réglage d'espacement (déplacé de la barre) ── */
.wdg-lib-tools {
  display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap;
  padding: 11px 14px 12px; border-bottom: 1px solid var(--hud-line, var(--border));   /* décollé de la recherche */
}
.wdg-lib-chips { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
/* Volet étroit : chaque bloc de réglages porte son intitulé, sinon deux rangées de boutons
   empilées se lisent comme une seule liste. */
.wdg-lib-grp { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
/* L'espacement du desk, déplacé de la bibliothèque au gestionnaire de layouts (09/09) : il se pose
   entre le sous-titre et la liste des dispositions, aligné sur elles, et séparé par le même filet
   que le reste du panneau. Il ne s'étire pas : c'est un réglage, pas une rubrique. */
.wdg-mgr-dens { align-items: flex-start; margin: 0 0 12px; padding: 0 0 12px;
  border-bottom: 1px solid var(--hud-line, var(--border)); }
.wdg-lib-lbl { font-size: 9px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase;
  color: var(--text3, var(--w-t9)); }
.wdg-lib-chips .wdg-chip { padding: 4px 11px; font-size: 10.5px; }
.wdg-lib-cnt { font-size: 10px; color: var(--text3, var(--w-t9)); margin-left: 5px; font-weight: 400; }
/* Seuil sur la largeur du VOLET : à 468 px les puces et le réglage d'espacement ne tiennent pas
   côte à côte. Un @media n'aurait jamais déclenché ici, la fenêtre restant large. */
@container dtpvolet (max-width: 640px) {
  .wdg-lib-tools { flex-direction: column; align-items: stretch; gap: 8px; }
  .wdg-lib-tools .wdg-density { align-self: flex-start; }
}

/* ── Écran guidé du desk VIDE : « Compose ton desk » (3 chemins : disposition · bibliothèque · modèles) ── */
.wdg-blank-actions { display: flex; gap: 8px; margin-top: 4px; }
.wdg-blank-sec {
  margin-top: 22px; font-size: 10px; letter-spacing: .08em; text-transform: uppercase; color: var(--w-t11); font-weight: 700;
}
.wdg-blank-tpls {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 210px)); gap: 12px;
  justify-content: center; margin-top: 10px; width: min(920px, 94%);
}

/* ── ASTUCE GESTES (1re visite, fermable — persistée par compte) ── */
.wdg-tip {
  grid-column: 1 / -1; grid-row: span 1;
  display: flex; align-items: center; gap: 9px; padding: 0 12px;
  background: rgba(227,178,58,.06); border: 1px solid rgba(227,178,58,.28); border-radius: var(--radius);
  font-size: 11px; color: #c9b078; line-height: 1.35; overflow: hidden;
}
.wdg-tip-ico { flex: 0 0 auto; font-size: 12px; }
.wdg-tip-txt { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.wdg-tip-txt b { color: var(--orange); font-weight: 600; }
.wdg-tip-x { flex: 0 0 auto; background: none; border: none; color: #8a7440; cursor: pointer; font-size: 14px; padding: 2px 4px; }
.wdg-tip-x:hover { color: var(--orange); }
@media (max-width: 900px) { .wdg-tip { grid-row: span 2; } .wdg-tip-txt { white-space: normal; } }

/* ── Feedback « ✓ Ajouté » sur la carte cliquée de la bibliothèque ── */
.wdg-lib-card--added { border-color: rgba(34,197,94,.65) !important; }
.wdg-lib-card--added::after {
  content: '✓ Ajouté'; position: absolute; top: 8px; left: 8px; z-index: 2;
  font-size: 9.5px; font-weight: 700; color: #22c55e; background: rgba(19,29,23,.95);
  border: 1px solid rgba(34,197,94,.4); padding: 2px 8px; border-radius: 3px;
  animation: wdgCardIn .18s ease both;
}

/* ── Réordonner les layouts (poignée ⠿ du gestionnaire) ── */
.wdg-mgr-grip {
  flex: 0 0 auto; background: none; border: none; color: var(--w-t15); cursor: grab;
  font-size: 13px; padding: 2px 2px; line-height: 1;
  /* ⚠️ `pan-y`, PAS `none` (29/08). `none` interdit au navigateur de défiler DÈS le premier pixel,
     y compris avant qu'un déplacement soit engagé — et les poignées forment une colonne quasi
     continue sur le bord gauche du volet : un pouce qui descend ce bord pour faire défiler la liste
     réordonnait un onglet à la place. Le défilement reste donc permis tant que rien n'est armé ;
     une fois l'appui long tenu, c'est un `touchmove` non passif qui le refuse (voir
     `_glisserPourReordonner`). C'est la seule construction qui laisse la zone servir aux deux. */
  touch-action: pan-y;
}
.wdg-mgr-grip:hover { color: var(--orange); }
.wdg-mgr-grip:active { cursor: grabbing; }
.wdg-mgr-row.wdg-drop-before { box-shadow: 0 -2px 0 0 var(--orange); }
.wdg-mgr-row.wdg-drop-after  { box-shadow: 0 2px 0 0 var(--orange); }

/* ── Réordonner les ONGLETS d'un panneau (même poignée ⠿, dans les Réglages de la carte) ──
   Le repère de dépôt reprend le trait or de _wireMgr : deux listes qui se réordonnent pareil
   doivent en avoir l'air. La poignée reste visible en permanence (et pas au seul survol) : dans un
   volet dense, une affordance qui n'apparaît qu'au survol ne se découvre pas. */
.wdg-set-tabgrip {
  flex: 0 0 auto; background: none; border: none; color: var(--w-t15, #6a6a72); cursor: grab;
  font-size: 13px; padding: 2px 1px; line-height: 1; margin-top: 5px;
  touch-action: pan-y;   /* même raison que .wdg-mgr-grip : le pouce doit pouvoir défiler ici */
  border-radius: 3px;
}
.wdg-set-tabgrip:hover { color: var(--orange); }
.wdg-set-tabgrip:active { cursor: grabbing; }
.wdg-set-tabgrip:focus-visible { outline: none; color: var(--orange); box-shadow: 0 0 0 1px rgba(227, 178, 58, .55); }
.wdg-set-tabrow.wdg-drop-before { box-shadow: 0 -2px 0 0 var(--orange); }
.wdg-set-tabrow.wdg-drop-after  { box-shadow: 0 2px 0 0 var(--orange); }
/* Le repère de dépôt vaut aussi pour les cartes du gestionnaire de desks : le sélecteur du code
   était resté sur `.wdg-mgr-row`, un nom que le rendu n'émet plus (cf. `_wireMgr`). */
.wdg-mgr-card.wdg-drop-before { box-shadow: 0 -2px 0 0 var(--orange); }
.wdg-mgr-card.wdg-drop-after  { box-shadow: 0 2px 0 0 var(--orange); }
/* CE QU'ON DÉPLACE SE VOIT. À la souris, le navigateur dessinait lui-même le fantôme du glisser
   HTML5 ; au pointeur, personne ne le fait — sans cette marque, on ne sait plus quelle ligne on
   tient, et c'est au doigt que ça manque le plus (la ligne est sous le pouce). */
.wdg-reord-src { opacity: .5; }

/* ── LA POIGNÉE, AU DOIGT ──────────────────────────────────────────────────────────────────────
   Mesurée à 15×17 px : c'est une cible qu'on rate. `pointer: coarse` vise le doigt sans toucher à
   la souris — on élargit la ZONE DE PRISE sans grossir le caractère, avec une marge négative pour
   que la ligne ne s'écarte pas d'autant. */
@media (pointer: coarse) {
  /* 44 px RÉELS, donc 49 déclarés : le zoom de page de 90 % mange un dixième de toute cible
     pensée en pixels CSS. La marge négative garde la ligne compacte — seule la zone de toucher
     grandit, le caractère ⠿ ne bouge pas. */
  .wdg-set-tabgrip, .wdg-mgr-grip {
    padding: 14px 16px; margin: -11px -14px; margin-top: -6px;
    -webkit-user-select: none; user-select: none; -webkit-touch-callout: none;
  }
  /* LA LIGNE AUSSI. La poignée ne peut pas être plus haute que ce qui l'entoure : mesurée à 33 px
     dans une ligne de 27, elle débordait déjà. Une ligne de 40 px donne au doigt une prise franche
     et ecarte les deux boutons voisins — la poignée et la croix de suppression étaient à 4 px l'une
     de l'autre, ce qui suffit pour supprimer un onglet en croyant le déplacer. */
  .wdg-set-tabrow { min-height: 49px; }
  .wdg-set-tabdel, .wdg-set-tabrow .wdg-tabic-cur {
    min-width: 34px; min-height: 34px; display: inline-flex; align-items: center; justify-content: center;
  }
}
.wdg-set-tabgrip, .wdg-mgr-grip { -webkit-user-select: none; user-select: none; }

/* Aperçu de carte : largeur FIXE (rangée homogène) + transition douce de densité de la grille */
.wdg-lib-card--prev .wdg-lib-prev { flex: 0 0 112px; height: 54px; }
.wdg-grid { transition: gap .25s ease, padding .25s ease; }
@media (max-width: 560px) { .wdg-resize-e { width: 18px; } }

/* Mobile : une seule colonne (le demi-largeur n'a plus de sens sous 900px) */
@media (max-width: 900px) {
  .wdg-grid { padding: 8px; --wdg-gap: 8px; }   /* via la variable → le mode « Collés » (spécificité supérieure) gagne toujours */
  .wdg-card, .wdg-card--full { flex-basis: 100%; }
  .wdg-layouts { max-width: 40vw; }
}

/* ════════════════════════════════════════════════════════════════════════════
   RESPONSIVE MOBILE — passe téléphone (≤560px) : 6 correctifs (captures user 24/07)
   1) badge NOUVEAU qui déborde du topbar   2) bouton « + Ajouter un widget » sur 2 lignes
   3) modale MES LAYOUTS trop grosse        4) barre de recherche BIBLIOTHÈQUE trop grosse
   5) tableau BIAIS coupé (tout voir)       6) cartes TAUX qui débordent horizontalement
   ════════════════════════════════════════════════════════════════════════════ */

/* Règles GLOBALES (pas seulement mobile) — sûres partout */
.wdg-btn { white-space: nowrap; }              /* (2) le libellé du bouton ne se casse JAMAIS en 2 lignes */
.rtc-tblwrap { overflow-x: auto; }             /* (6) le tableau des réunions défile au lieu d'être rogné */

@media (max-width: 560px) {

  /* (1) Badge « NOUVEAU » de l'icône Mon Desk : replié DANS le topbar (le topbar-center
         a overflow:hidden en mobile → un top trop négatif le rognait par le haut). */
  .wdg-new-badge { top: -3px; right: -3px; font-size: 6px; padding: 1.5px 3px; letter-spacing: .02em; }

  /* (2) Barre Mon Desk : les onglets sur leur ligne (défilable), les 2 boutons sur la ligne
         suivante — chacun tenant sur UNE ligne (nowrap ci-dessus). Fini « + Ajouter un\nwidget ». */
  #view-widgets .panel-header { flex-wrap: wrap; height: auto; min-height: 32px; row-gap: 7px; padding-bottom: 8px; }
  #view-widgets .panel-header-left { flex: 1 1 100%; min-width: 0; }
  #view-widgets .wdg-layouts { max-width: 100%; }
  #view-widgets .panel-header-controls { flex: 1 1 100%; justify-content: flex-start; }

  /* (3)+(4) Modales BIBLIOTHÈQUE / MES LAYOUTS : plus compactes (police, marges, cartes réduites). */
  .wdg-lib-box { width: 94%; max-height: none; }
  .wdg-lib-head { padding: 9px 12px; }
  .wdg-lib-title { font-size: 11.5px; }
  /* (4) barre de recherche : plus fine (mais reste confortable au doigt) + marges resserrées */
  .wdg-lib-search-row { padding: 9px 11px 0; }
  .wdg-lib-search { height: 34px; font-size: 12px; }
  .wdg-lib-grid { padding: 11px; gap: 8px; }
  .wdg-lib-row { grid-template-columns: 1fr; }                 /* cartes fonctions : 1 par ligne, pleine largeur */
  .wdg-lib-row .wdg-lib-card { padding: 9px 11px; gap: 9px; }
  .wdg-lib-ico { width: 28px; height: 28px; }
  .wdg-lib-name { font-size: 12px; }
  .wdg-lib-desc { font-size: 10px; }
  .wdg-lib-sec { font-size: 9.5px; margin-top: 4px; }
  /* (3) gestionnaire de layouts : lignes + vignettes + modèles resserrés */
  .wdg-mgr-list { padding: 10px 11px; gap: 5px; }
  .wdg-mgr-row { padding: 5px 7px; gap: 6px; }
  /* ⚠️ CETTE RÈGLE DOIT RESTER SCOPÉE AUX LIGNES (correctif 12/08, bug user « on ne voit pas bien
     l'aperçu, c'est sur mobile »). Écrite pour la PASTILLE d'une ligne de liste, elle ciblait
     `.wdg-thumb` tout court : elle rabotait donc AUSSI le plan pleine largeur des cartes « Mes
     desks ». Avec `aspect-ratio: 2.15/1`, 44 px de large = un aperçu de 44×20 px collé en haut à
     gauche d'une carte de 324 px — le reste vide. C'est exactement ce que montrait la capture. */
  .wdg-mgr-row .wdg-thumb { width: 44px; }
  .wdg-mgr-name, .wdg-mgr-pname { font-size: 11px; }
  .wdg-mgr-pname em { font-size: 9.5px; }
  .wdg-mgr-open { padding: 4px 8px; font-size: 10px; }
  .wdg-mgr-count { font-size: 9px; }
  .wdg-tpl-row { grid-template-columns: repeat(2, 1fr); gap: 8px; }
  .wdg-mgr-foot { padding: 9px 11px; gap: 6px; }
  .wdg-mgr-foot .wdg-btn { font-size: 10px; padding: 0 8px; height: 24px; }

  /* (5) Onglet BIAIS — tableau RADAR : compacté pour TOUT voir sur téléphone.
         Driver (6e col) déjà masqué ≤980px ; on masque en plus le chevron, on rétrécit police/tags,
         et le Biais peut passer sur 2 lignes → 6 colonnes tiennent sans coupe. */
  .macro-table { font-size: 11px; min-width: 0; }
  .macro-table th, .macro-table td { padding: 6px 5px; }
  .macro-table th { font-size: 9px; letter-spacing: .02em; white-space: normal; line-height: 1.2; }   /* en-têtes sur 2 lignes → « Politique monétaire » ne force plus une colonne à 110px */
  .macro-table th.mt-cur-h { width: auto; }
  .macro-table th.mt-x-h, .macro-table td.mt-x { display: none; }   /* chevron masqué (lignes toujours cliquables) */
  .mt-cur { font-size: 12px; gap: 5px; }
  .mt-cur .sbm-flag { width: 15px; height: 15px; }
  .mt-cell-tags { gap: 3px 4px; }
  .mt-tag { font-size: 9px; padding: 2px 6px; margin: 1px 3px 1px 0; letter-spacing: 0; }
  /* ⚠️ AUDIT 22/08 : nth-child(7) visait le Biais AVANT l'insertion de la colonne « Taux
     directeur » (20/08) — depuis, il visait le Taux et le Biais partait hors écran. Le renderer
     pose désormais .mt-bias-cell : insensible aux futures insertions de colonnes. */
  .macro-table .mt-bias-cell .mt-tag { white-space: normal; }
  /* La colonne Taux se compacte au même régime que le reste : 7 colonnes retiennent l'écran. */
  .macro-table td.mt-taux { padding: 6px 3px; }
  .macro-table .mt-taux-v { font-size: 9.5px; padding: 2px 4px; }
  /* Colonne « Devise » FIGÉE à gauche : à 375px la table tient sans scroll, mais sous ~360px
     un léger défilement horizontal peut subsister → la devise reste toujours visible (UX pro,
     jamais de contexte perdu). Fonds opaques pour couvrir le contenu qui défile dessous. */
  .macro-table th.mt-cur-h, .macro-table td.mt-cur { position: sticky; left: 0; z-index: 2; }
  .macro-table th.mt-cur-h { z-index: 3; }                        /* reste dans le coin haut-gauche (déjà sticky top) */
  .macro-table td.mt-cur { background: var(--bg); }
  .mt-row:hover td.mt-cur { background: #101014; }
  .mt-row--active td.mt-cur { background: #14140f; box-shadow: inset 3px 0 0 var(--orange, #e3b23a); }     /* Biais : autorise le retour à la ligne */

  /* (6) Onglet TAUX — cartes « Interest Rate Probability » : bandeau 5 métriques replié en 3+2
         (fini « +12,00 bp » et « 29/07/202 » rognés), tableau des réunions allégé (Scénario central masqué). */
  .rtc-metrics { display: flex; flex-wrap: wrap; }
  .rtc-m { flex: 1 1 30%; min-width: 30%; min-height: 46px; padding: 5px 7px 6px; border-bottom: 1px solid var(--bg2); }
  .rtc-m:nth-child(3), .rtc-m:last-child { border-right: 0; }
  .rtc-m:nth-child(n+4) { border-bottom: 0; }
  .rtc-k { font-size: 9px; }
  .rtc-v { font-size: 12px; }
  .rtc-tbl { font-size: 10px; }
  .rtc-tbl th:nth-child(7), .rtc-tbl td:nth-child(7) { display: none; }   /* « Scénario central » masqué */
  .rtc-pill { min-width: 54px; padding: 2px 5px; }
  .rtc-bp { width: 46px; }
  .rtc-axis { padding: 2px 53px 0 39px; }   /* aligné sur la géométrie réelle de la piste : gauche rtc-bl(32)+gap(7)=39, droite rtc-bp(46)+gap(7)=53 */
}

/* ════════════════════════════════════════════════════════════════════════════
   RESPONSIVE MOBILE — passe 2 (≤560px) : correctifs issus de l'audit multi-surfaces
   (en-têtes de panneaux, onglet BANQUES, lecteur INSTITUTIONS). Vérifiés au bench.
   ════════════════════════════════════════════════════════════════════════════ */
@media (max-width: 560px) {

  /* ── En-têtes de panneaux (TAUX, Banques, Marchés…) : titre long + contrôle de fraîcheur
        se chevauchaient dans la barre 32px fixe (ex. « Taux directeurs des banques centrales »
        + « Cotations à jour · HH:MM » ≈ 435px pour ~355px dispo). flex-wrap est AUTO-LIMITANT :
        seuls les en-têtes qui débordent passent sur 2 lignes ; les autres restent à 32px. ── */
  .panel-header { flex-wrap: wrap; height: auto; min-height: 32px; align-content: center; row-gap: 2px; }
  .panel-header-left { min-width: 0; }

  /* ── Onglet BANQUES : la colonne « Afficher le graphique » (en-tête nowrap ~150px pour une
        icône 16px) est la plus large et rallonge le scroll pour RIEN — sur mobile le graphe
        s'affiche déjà en permanence sous la table et un tap sur la ligne le sélectionne. On la masque. ── */
  .bank-table th.bank-chart-col-h,
  .bank-table td.bank-chart-cell { display: none; }
  /* Ligne détail dépliée (thèse) : épinglée à gauche + bornée à l'écran → le texte revient à la ligne
     dans la zone visible au lieu de s'étaler sur la largeur intrinsèque (~750px) de la table. */
  .bank-detail { position: sticky; left: 0; width: calc(var(--vpw) - 24px); max-width: calc(var(--vpw) - 24px); box-sizing: border-box; }

  /* ── INSTITUTIONS — lecteur : bandeau nav. Le titre du rapport (seul identifiant) était rogné à néant
        et « ‹ Retour à la liste » se cassait sur 2-3 lignes. On fait retomber le titre sur sa propre
        ligne pleine largeur et on empêche le Retour de se casser. ── */
  .br-rnav { flex-wrap: wrap; }
  .br-back-btn { flex-shrink: 0; white-space: nowrap; }
  .br-rnav-title { flex: 1 1 100%; order: 3; text-align: left; }
  /* Barre PDF (rendu canvas) : titre long tronqué proprement au lieu de wrapper et pousser le compteur */
  .br-pdf-bar-lbl:first-child { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .br-pdf-bar .br-pdf-bar-lbl + .br-pdf-bar-lbl { flex: 0 0 auto; }
}

/* ════════════════════════════════════════════════════════════════════════════
   RESPONSIVE MOBILE — passe 3 (≤560px) : audit 11 surfaces restantes, 11 constats
   CONFIRMÉS après vérification adversariale (6 réfutés écartés). Vérifiés au bench.
   ════════════════════════════════════════════════════════════════════════════ */
@media (max-width: 560px) {

  /* [HIGH] JOURNAL — barre d'outils : 4 boutons (dont « ↑ Importer (Notion / CSV) », « ↓ Exporter (CSV) »)
     + spacer flex:1 + badge de mode débordaient (Exporter/badge rognés). flex-wrap + spacer masqué → 2 rangées. */
  .jr-toolbar { flex-wrap: wrap; }
  .jr-tb-spacer { display: none; }

  /* [HIGH] CALENDRIER — en-tête (ligne 1) : titre MAJ + flèches ‹ › + plage de dates (nowrap) débordaient.
     La ligne grandit, le bloc titre s'enroule en interne (la plage passe sous le titre), les icônes restent à droite. */
  .cal-title-row { height: auto; min-height: 32px; padding: 4px 10px; }
  .cal-title-block { flex: 1 1 auto; min-width: 0; white-space: normal; flex-wrap: wrap; row-gap: 1px; }
  .cal-daterange { font-size: 10px; }

  /* [MEDIUM] CALENDRIER — barre de filtres (ligne 2) : impacts + recherche + badge DIRECT en nowrap débordaient.
     Les 4 boutons d'impact tiennent en ligne 1, la recherche passe pleine largeur en ligne 2. */
  .cal-filter-row { flex-wrap: wrap; gap: 6px; padding: 6px 10px 7px; }
  .cal-imp-btn { padding: 4px 11px; }
  .cal-search-wrap { flex: 1 1 100%; max-width: none; order: 3; }

  /* [LOW] CALENDRIER — décryptage : l'attribution de citation BC (« — Speaker · date ») en nowrap forçait
     un scroll horizontal du déroulé dans la colonne valeur étroite → on l'autorise à revenir à la ligne. */
  .cal-kb-qwho { white-space: normal; }

  /* [MEDIUM] ANALYSTES — bandeau du lecteur : le titre du rapport était écrasé/illisible. Même parade que le
     lecteur Institutions : le titre reprend une ligne pleine largeur, le bouton « ‹ Retour » reste intact. */
  .arlib-rnav { flex-wrap: wrap; height: auto; min-height: 44px; padding: 6px 12px; row-gap: 6px; }
  .arlib-rnav-title { flex: 1 1 100%; order: 3; text-align: left; }

  /* [MEDIUM] ACTUS — menu « Sections d'actualités » : son top figé (calc(--toolbar-h)+32px) pointait dans la
     barre repliée (2 lignes) et recouvrait la recherche → top:auto suit la hauteur réelle du bandeau. */
  .section-dropdown { top: auto; left: 8px; right: 8px; width: auto; }

  /* [LOW] SEMAINE À VENIR — bouton « Lire la suite » : zone d'appui ~20px < 34px → agrandie (look inchangé). */
  .wa-more { padding: 8px 0; min-height: 34px; align-items: center; }

  /* [MEDIUM] MON DESK — widget Calendrier : la table n'héritait pas du fit-to-width (table-layout:fixed est
     scopé #cal-table-wrap) → colonne drapeau réapparaît + scroll horizontal. On applique le fit dans le widget. */
  #view-widgets .wdg-cal-wrap .cal-table { table-layout: fixed; width: 100%; }
  #view-widgets .wdg-cal-wrap { overflow-x: hidden; }

  /* [LOW] MON DESK — widget Taux directeurs : grille 4 colonnes à mini figés (≈344px incompressible) débordait
     ~11px → minmax(0,…) compressibles + gaps/paddings resserrés. */
  .wdg-taux-head, .wdg-taux-row { grid-template-columns: minmax(0, 1.2fr) 50px minmax(0, 1.1fr) minmax(0, .8fr); gap: 6px; padding: 6px 9px; }
  .wdg-taux-head { font-size: 9px; letter-spacing: .03em; }

  /* [LOW] MON DESK — contrôles d'en-tête/redimension du widget sous la cible tactile 34px : zone de tap agrandie
     (les glyphes/SVG ne changent pas, densité visuelle intacte). */
  .wdg-ico { width: 30px; height: 28px; }
  .wdg-step { width: 30px; height: 28px; }
  .wdg-grip { width: 26px; height: 28px; }
  .wdg-resize { width: 26px; height: 26px; }

  /* [LOW] CALCULATRICE — bouton « Copier » (22px) sous la cible tactile → aligné sur la hauteur de contrôle desk. */
  .calc-copy { height: 30px; padding: 0 12px; }
}


/* ── FICHE ÉVÉNEMENT en thème clair ──────────────────────────────────────────────────────────
   Les couleurs de texte de la fiche (valeurs, citations, libellés) sont écrites en dur en blanc
   cassé : lisibles sur le fond sombre, quasi invisibles sur le papier clair. On les re-mappe ici
   sur les tokens, qui ont une valeur par thème. Rien n'est touché côté sombre. */
html[data-theme="light"] .cal-detail-title,
html[data-theme="light"] .cal-specs-table td,
html[data-theme="light"] .cal-hist-table td,
html[data-theme="light"] .cal-kb-val { color: var(--text); }
html[data-theme="light"] .cal-detail-sub,
html[data-theme="light"] .cal-spec-lbl,
html[data-theme="light"] .cal-hist-table th,
html[data-theme="light"] .cal-detail-empty,
html[data-theme="light"] .cal-kb-lbl,
html[data-theme="light"] .cal-kb-quote,
html[data-theme="light"] .cal-kb-sub,
html[data-theme="light"] .cal-kb-muted,
html[data-theme="light"] .cal-hist-sub { color: var(--text2); }
html[data-theme="light"] .cal-kb-qwho { color: var(--text2); }
/* L'or vif de marque tombe a 1,7:1 sur fond clair : on bascule sur l'or assombri du theme. */
html[data-theme="light"] .cal-detail-section,
html[data-theme="light"] .cal-kb-cat,
html[data-theme="light"] .cal-key-chip { color: var(--orange); }
html[data-theme="light"] .cal-kb-quote::before,
html[data-theme="light"] .cal-kb-quote::after { color: var(--text3); }

/* ═══════════════════════════════════════════════════════════════════════════════════════════════
   THÈME CLAIR (bêta) — activé par html[data-theme="light"] (sélecteur Apparence du profil).
   Philosophie : papier doux (pas de blanc pur en fond de page), panneaux blancs, or signature
   conservé, états de marché INCHANGÉS (charte immuable — leurs cellules portent leur propre fond).
   Les surfaces passent par les tokens (tokenisation 28/07) ; ce bloc ne fait que les re-mapper.
   Limite assumée v1 : les étiquettes amCharts et quelques encarts aux couleurs en dur restent
   pensés pour le sombre — itération vue par vue à venir.
   ═══════════════════════════════════════════════════════════════════════════════════════════════ */
html[data-theme="light"] {
  color-scheme: light;
  --orange:      #9b7409;   /* or LISIBLE sur clair (l'or vif #e3b23a manque de contraste en texte) — reste dans la famille charte b8860b */
  --bg:          #f2f2ee;   /* papier doux — pas de blanc pur en pleine page */
  --bg1:         #f2f2ee;
  --bg2:         #ffffff;   /* panneaux */
  --bg3:         #ffffff;
  --bg4:         #ffffff;
  --bg5:         #e6e6e0;
  --border:      #d9d9d2;
  --border2:     #d9d9d2;
  --border3:     #d9d9d2;
  --head-bg:     #eaeae4;   /* barres d'en-tête : un cran sous le panneau, comme en sombre */
  --text:        #17181d;
  --text2:       #474a54;
  --text3:       #6d707b;
  --text4:       #9a9ca6;
  --sb-thumb:       #cdcdc5;   /* barre de defilement sur papier clair */
  --sb-thumb-hover: #b4b4ab;
  --hud-line:      rgba(0, 0, 0, 0.09);
  --grid-line-v:   rgba(0, 0, 0, 0.055);
  --row-sep:       1px solid rgba(0, 0, 0, 0.08);   /* theme clair : releve avec le sombre (21/08) */
  --row-hover:     #ecece6;
  --st-flat:     #17181d;   /* valeur « égal/neutre » : blanc en sombre → encre en clair */
  --orange-bg:   rgba(184, 134, 11, 0.10);
}
html[data-theme="light"] body { background: var(--bg); color: var(--text); }
/* Scrollbars claires */
html[data-theme="light"] * { scrollbar-color: var(--sb-thumb) transparent; }   /* meme token que le sombre */
html[data-theme="light"] ::-webkit-scrollbar-thumb { background: #c3c3bc; background-clip: content-box; }
html[data-theme="light"] ::-webkit-scrollbar-thumb:hover { background: #a9a9a1; background-clip: content-box; }
/* Textes « blanc dur » les plus fréquents du chrome (titres, valeurs) → encre */
/* .wdg-lay rattaché ici : la barre d'onglets de Mon Desk doit suivre la nav du desk dans les DEUX
   thèmes. En la listant dans la même règle plutôt qu'en recopiant sa valeur, les deux barres ne
   peuvent plus diverger si cette règle évolue. */
html[data-theme="light"] .panel-title, html[data-theme="light"] .nav-item, html[data-theme="light"] .logo-text, html[data-theme="light"] .wdg-lay { color: var(--text); }
/* L'or vif #e3b23a manque de contraste sur fond clair pour du TEXTE fin → on garde l'or SOMBRE
   de la charte (#b8860b) pour les textes or, l'or vif reste pour les fonds/accents. */
html[data-theme="light"] a { color: #b8860b; }

/* Sélecteur Apparence (profil) — segmenté 3 positions, grammaire des pilules du desk */
.pd-theme-seg { display: flex; gap: 4px; margin: 0 0 14px; }
.pd-theme-seg button {
  flex: 1; padding: 7px 8px; background: var(--bg2); border: 1px solid var(--border);
  border-radius: var(--r-2); color: var(--text2); font-size: var(--fs-body); cursor: pointer;
  transition: border-color var(--t-fast) var(--ease), color var(--t-fast) var(--ease), background var(--t-fast) var(--ease);
}
.pd-theme-seg button small { font-size: var(--fs-micro); color: var(--orange); margin-left: 3px; }
.pd-theme-seg button:hover { border-color: rgba(227, 178, 58, 0.4); color: var(--text); }
.pd-theme-seg button.on { border-color: rgba(227, 178, 58, 0.6); background: var(--orange-bg); color: var(--text); font-weight: 600; }

/* ── Panneau à onglets SANS rangée de titre (demande user 28/07) : la barre d'onglets EST l'en-tête.
   Le bandeau standard (poignée + actions) se superpose à la barre : poignée à gauche, actions à
   droite au survol de la carte — une ligne de gagnée pour le contenu. ── */
.wdg-card--tabs > .wdg-head { position: absolute; top: 0; left: 0; right: 0; z-index: 6; min-height: 30px; background: transparent; border-bottom: 0; padding: 0 4px; pointer-events: none; }
.wdg-card--tabs > .wdg-head .wdg-title { display: none; }
.wdg-card--tabs > .wdg-head .wdg-grip, .wdg-card--tabs > .wdg-head .wdg-actions { pointer-events: auto; }
.wdg-card--tabs > .wdg-head .wdg-actions { background: var(--head-bg); border-radius: 3px; padding: 0 2px; opacity: 0; transition: opacity .14s var(--ease); }
.wdg-card--tabs:hover > .wdg-head .wdg-actions, .wdg-card--tabs > .wdg-head .wdg-actions:focus-within { opacity: 1; }
.wdg-card--tabs .wdgt-bar { padding-left: 26px; }
/* ⚠️ LE TRAIT DORÉ PASSAIT DERRIÈRE LES COMMANDES (04/09, capture user : « on dirait que c'est un
   bug, on voit le trait doré qui passer à travers »). Deux causes qui se cumulent, et aucune ne se
   voit en lisant une règle isolée :
     · sur une carte à onglets, l'en-tête est posé EN SURIMPRESSION de la barre d'onglets
       (`position: absolute`), et rien ne réservait la place des commandes : l'onglet actif pouvait
       donc s'étendre jusque sous elles, son liseré avec ;
     · la plaque de fond des commandes ne fait que la hauteur des icônes, centrée. Le liseré vit,
       lui, sur les 2 derniers pixels du bas — précisément la bande que la plaque ne couvre pas.
       Il ressortait donc DE PART ET D'AUTRE des icônes, ce qui se lit comme un trait qui les
       traverse.
   On corrige les deux : la barre réserve la largeur des commandes à TOUTES les tailles d'écran (la
   règle n'existait que pour le tactile), et la plaque prend toute la hauteur de l'en-tête, si bien
   qu'un onglet qu'on ferait défiler sous elle disparaît proprement derrière au lieu d'en dépasser. */
.wdg-card--tabs .wdgt-bar { padding-right: 96px; }
.wdg-card--tabs > .wdg-head .wdg-actions { align-self: stretch; display: flex; align-items: center; }
/* Champ de renommage inline (double-clic sur un onglet) */
.wdgt-edit { width: 92px; background: var(--bg); border: 1px solid rgba(227, 178, 58, .55); border-radius: 3px; color: var(--text); font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 10.5px; padding: 2px 5px; margin: 0 2px; text-transform: none; letter-spacing: normal; }
.wdgt-edit:focus { outline: none; box-shadow: var(--focus-ring); }

/* ── Bloc fantôme « Ajouter un widget » : remplit le RESTE de la rangée après le dernier widget.
   Discret (pointillés, texte éteint), doré au survol ; masqué en plein écran. ── */
.wdg-ghost {
  min-height: 72px;   /* placement (span colonnes/lignes) calculé par renderGrid — comble le trou réel */
  display: flex; align-items: center; justify-content: center; gap: 8px;
  background: transparent; border: 1px dashed rgba(255, 255, 255, 0.10); border-radius: var(--radius);
  color: var(--text3); cursor: pointer; font-family: var(--tight, 'Inter Tight', sans-serif);
  font-size: var(--fs-title, 11.5px); font-weight: var(--fw-semibold, 600); letter-spacing: .05em; text-transform: uppercase;
  transition: border-color .15s var(--ease), color .15s var(--ease), background .15s var(--ease);
}
.wdg-ghost:hover { border-color: rgba(227, 178, 58, .45); color: var(--orange); background: rgba(227, 178, 58, .04); }
.wdg-ghost-plus { font-size: 16px; font-weight: 700; line-height: 1; }
.wdg-grid.wdg-fs-mode .wdg-ghost { display: none; }
html[data-theme="light"] .wdg-ghost { border-color: rgba(0, 0, 0, 0.14); }

/* ── Bouton « Personnaliser » DISCRET (28/07) : pilule fine, or éteint, s'allume au survol ── */
/* « Personnaliser » : c'était une PASTILLE dorée cerclée — le seul élément qui trahissait
   immédiatement que la barre de Mon Desk n'est pas la nav du desk. On lui donne la grammaire d'un
   onglet de nav (même police, taille, graisse, interlettrage, casse, marges, hauteur pleine, aucun
   fond ni bordure), l'or n'apparaissant qu'au SURVOL. La barre se lit alors comme « › ACTUS … ». */
.wdg-btn-pers {
  display: inline-flex; align-items: center; gap: 5px; align-self: stretch;
  padding: 0 14px; background: transparent; border: 0; border-radius: 0; cursor: pointer;
  font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 11px; font-weight: var(--fw-semibold, 600);
  letter-spacing: .06em; text-transform: uppercase; color: var(--text3);   /* = .nav-item */
  transition: color .15s var(--ease), background .15s var(--ease);
}
.wdg-btn-pers:hover { color: var(--orange); background: rgba(255, 255, 255, 0.035); }
.wdg-btn-pers svg { opacity: .85; }

/* ═══ ESPACE D'ACCUEIL (« workstation ») — v1 admin, identité DTP ═══════════════════════════════ */
.home-overlay {
  position: fixed; left: 0; right: 0; top: var(--topbar-h, 54px); bottom: 0; z-index: 45;
  background:
    radial-gradient(1100px 420px at 12% -8%, rgba(227, 178, 58, 0.10), transparent 60%),
    radial-gradient(800px 340px at 95% 8%, rgba(184, 134, 11, 0.06), transparent 55%),
    var(--bg);
  overflow-y: auto; animation: dtpViewIn var(--t-med, .22s) var(--ease-out, ease) both;
}
/* PLEINE LARGEUR. Le bridage à 1180 px laissait deux bandes noires sur un écran large et rognait
   les deux TABLEAUX de l'accueil : le calendrier perdait 191 px (mesuré) et le Radar de Biais sa
   colonne CROISSANCE. Sans bride, chacun reçoit la place dont il a besoin.
   Le bas était à 60 px : sur un écran de 900 px, c'est un sixième du dépassement mesuré, pour du
   vide. 20 px suffisent à ne pas coller la dernière rangée au bord. */
.home-inner {
  max-width: none; margin: 0; padding: 20px 30px; position: relative;
  /* Colonne haute d'un écran : la grille (flex:1) absorbe la place restante et ses rangées la
     partagent. Plus aucune constante de « hors-widgets » à re-mesurer quand l'en-tête change. */
  height: calc(var(--vph) - var(--topbar-h, 54px));
  display: flex; flex-direction: column;
}
@supports (height: 100dvh) {
  .home-inner { height: calc(var(--vph) - var(--topbar-h, 54px)); }
}
.home-skip {
  position: absolute; top: 26px; right: 28px; padding: 5px 12px;
  background: transparent; border: 1px solid var(--hud-line, var(--border)); border-radius: var(--pill, 999px);
  color: var(--text3); font-family: var(--tight); font-size: 10.5px; letter-spacing: .05em; text-transform: uppercase; cursor: pointer;
  transition: color .15s var(--ease), border-color .15s var(--ease);
}
.home-skip:hover { color: var(--orange); border-color: rgba(227, 178, 58, .45); }
/* Identité à gauche, état des places à droite : une seule rangée d'en-tête. Sur écran étroit le
   bandeau repasse dessous plutôt que de se comprimer (flex-wrap + base de 420 px). */
.home-top { display: flex; align-items: flex-end; gap: 22px; flex-wrap: wrap; }
.home-top .home-hero { flex: 0 1 auto; min-width: 0; }
.home-top .home-strip { flex: 1 1 420px; margin-top: 0; }
.home-eyebrow { font-family: var(--tight); font-size: 9.5px; font-weight: 700; letter-spacing: .2em; text-transform: uppercase; color: var(--text3); margin-bottom: 6px; }
.home-title { font-family: var(--serif, Georgia, serif); font-size: 27px; font-weight: 600; letter-spacing: -.01em; color: var(--text); line-height: 1.15; }
.home-name { background: linear-gradient(100deg, #f0d27a, #cfa233 55%, #b8860b); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
.home-sub { margin-top: 4px; font-size: var(--fs-body); color: var(--text3); }
.home-cols { display: flex; gap: 26px; margin-top: 30px; align-items: flex-start; }
.home-col { flex: 1 1 auto; min-width: 0; }
.home-col--side { flex: 0 0 320px; }
.home-sec { font-family: var(--tight); font-size: var(--fs-title); font-weight: 700; letter-spacing: var(--ls-caps); text-transform: uppercase; color: var(--text2); margin: 0 0 7px; padding-left: 8px; border-left: 2px solid var(--orange); }
.home-sec-t { display: inline-flex; align-items: center; gap: 8px; min-width: 0; }
/* Période du graphe, dans le vocabulaire du desk (TD = séance en cours, TW = semaine) : un graphe
   de force ne veut rien dire sans sa fenêtre de temps. */
.home-tf {
  font-family: var(--font-mono); font-size: 8.5px; font-weight: 700; letter-spacing: .08em;
  color: var(--orange); background: var(--orange-bg); border: 1px solid rgba(227, 178, 58, .30);
  border-radius: 3px; padding: 1px 5px; line-height: 1.5;
}
.home-sec:first-child { margin-top: 0; }
/* CONTOUR DE LA PREMIÈRE CARTE. Avec `height` + `overflow-y:auto`, la grille devient un conteneur
   de défilement dont l'arête haute RASE la bordure de la première carte dès qu'il défile d'un pixel
   — c'est le « contour qui disparaît en haut, il passe sous le panneau ». `max-height` ne clippe que
   s'il y a réellement trop de cartes, et 1 px de marge intérieure éloigne la bordure de l'arête. */
.home-cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(152px, 1fr)); gap: 9px;
  flex: 1 1 auto; min-height: 0; overflow-y: auto; align-content: start; padding: 1px; }
.home-card {
  position: relative; display: flex; flex-direction: column; align-items: flex-start; gap: 4px; text-align: left;
  padding: 12px 12px 10px; min-height: 86px; background: var(--bg2); border: 1px solid var(--hud-line, var(--border));
  border-radius: var(--radius); cursor: pointer; color: var(--text);
  transition: border-color .15s var(--ease), transform .15s var(--ease), box-shadow .15s var(--ease);
}
.home-card:hover { border-color: rgba(227, 178, 58, .45); transform: translateY(-1px); box-shadow: 0 6px 22px rgba(0, 0, 0, .35); }
.home-card-fav { position: absolute; top: 10px; right: 12px; color: var(--orange); font-size: 12px; }
/* Vignette du desk en tête de carte : on reconnaît sa disposition avant même de lire le nom.
   BOÎTE À HAUTEUR FIXE — les layouts n'ont pas tous le même nombre de lignes ; sans ça les titres
   des cartes se décalent les uns par rapport aux autres. La vignette est centrée dans la boîte. */
.home-card-thumb {
  display: flex; align-items: center; align-self: stretch;
  width: 100%; max-width: 138px; height: 62px; margin-bottom: 6px; overflow: hidden;
}
.home-card-thumb .wdg-thumb { width: 100%; grid-auto-rows: 6px; }
.home-card:hover .wdg-thumb { border-color: rgba(227, 178, 58, .34); }
.home-card-name { font-family: var(--tight); font-size: 13px; font-weight: 700; letter-spacing: .01em; }
.home-card-meta { font-size: var(--fs-meta); color: var(--text3); }
.home-card-go { margin-top: auto; font-family: var(--tight); font-size: 10px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--orange-dim); transition: color .15s; }
.home-card:hover .home-card-go { color: var(--orange); }
.home-card--new { border-style: dashed; background: transparent; align-items: center; justify-content: center; text-align: center; color: var(--text3); }
.home-card--new:hover { color: var(--orange); }
.home-card-plus { font-size: 20px; font-weight: 700; line-height: 1; }
/* (.home-chips / .home-chip : « Accès rapide » retiré de l'accueil — la nav du desk est à un clic.
   Les règles restent inoffensives, aucun élément ne les porte plus.) */
.home-chips { display: flex; flex-wrap: wrap; gap: 7px; }
.home-chip {
  padding: 6px 12px; background: transparent; border: 1px solid var(--hud-line, var(--border)); border-radius: var(--r-2);
  color: var(--text2); font-family: var(--tight); font-size: 10.5px; font-weight: 600; letter-spacing: .05em; text-transform: uppercase; cursor: pointer;
  transition: color .14s var(--ease), border-color .14s var(--ease), background .14s var(--ease);
}
.home-chip:hover { color: var(--orange); border-color: rgba(227, 178, 58, .4); background: rgba(227, 178, 58, .05); }
.home-agenda { background: var(--bg2); border: 1px solid var(--hud-line, var(--border)); border-radius: var(--radius); padding: 13px 14px; }
.home-agenda-h { font-size: var(--fs-body); font-weight: 600; color: var(--text); line-height: 1.45; margin-bottom: 10px; }
.home-ev { display: flex; gap: 9px; align-items: baseline; padding: 5px 0; border-top: var(--row-sep, 1px solid rgba(255,255,255,.04)); }
.home-ev:first-of-type { border-top: 0; }
.home-ev-ccy { flex: 0 0 34px; font-family: var(--tight); font-size: 10px; font-weight: 700; letter-spacing: .06em; color: var(--orange-dim); }
.home-ev-t { font-size: var(--fs-body); color: var(--text2); line-height: 1.4; }
.home-ev-empty { font-size: var(--fs-body); color: var(--text3); }
@media (max-width: 860px) { .home-cols { flex-direction: column; } .home-col--side { flex: 1 1 auto; width: 100%; } .home-title { font-size: 24px; } }

/* Fantôme sur petits écrans : les colonnes passent à 8/4/1 → pleine largeur, bandeau modeste */
@media (max-width: 1280px) { .wdg-ghost { grid-column: 1 / -1 !important; grid-row: span 5 !important; } }

/* ═══ ÉTATS UNIFORMES DES WIDGETS (28/07) : chargement · vide · erreur ══════════════════════════
   Une seule grammaire pour tout le catalogue : icône discrète, message court, action facultative.
   L'erreur porte un « Réessayer » qui relance le widget concerné. */
.wdg-state {
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 9px;
  height: 100%; min-height: 80px; padding: 16px 14px; text-align: center; color: var(--text3);
}
.wdg-state svg { opacity: .5; flex: 0 0 auto; }
.wdg-state-t { font-size: var(--fs-body); line-height: 1.5; max-width: 34ch; }
.wdg-state--err { color: var(--text2); }
.wdg-state--err svg { color: var(--red); opacity: .8; }
.wdg-state-btn {
  padding: 4px 12px; background: transparent; border: 1px solid var(--hud-line, var(--border));
  border-radius: var(--pill, 999px); color: var(--text2); cursor: pointer;
  font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 10.5px; font-weight: 600;
  letter-spacing: .05em; text-transform: uppercase;
  transition: color .14s var(--ease), border-color .14s var(--ease), background .14s var(--ease);
}
.wdg-state-btn:hover { color: var(--orange); border-color: rgba(227, 178, 58, .45); background: rgba(227, 178, 58, .06); }
/* Squelette de chargement : barres pulsées — le widget « respire » au lieu d'afficher un texte figé */
.wdg-skel { display: flex; flex-direction: column; gap: 9px; padding: 14px 12px; }
.wdg-skel-l {
  height: 9px; border-radius: 3px;
  background: linear-gradient(90deg, rgba(255,255,255,.045) 25%, rgba(255,255,255,.085) 50%, rgba(255,255,255,.045) 75%);
  background-size: 220% 100%; animation: wdgSkel 1.25s var(--ease, ease) infinite;
}
@keyframes wdgSkel { 0% { background-position: 120% 0; } 100% { background-position: -120% 0; } }
html[data-theme="light"] .wdg-skel-l { background: linear-gradient(90deg, rgba(0,0,0,.045) 25%, rgba(0,0,0,.085) 50%, rgba(0,0,0,.045) 75%); background-size: 220% 100%; }
@media (prefers-reduced-motion: reduce) { .wdg-skel-l { animation: none; } }

/* Bandeau « Annuler » après un retrait de widget (7 s, volatil) */
.wdg-undo {
  position: fixed; left: 50%; bottom: 26px; transform: translateX(-50%); z-index: 90;
  display: flex; align-items: center; gap: 14px; padding: 9px 14px;
  background: var(--bg2); border: 1px solid rgba(227, 178, 58, .38); border-radius: var(--radius);
  box-shadow: 0 8px 28px rgba(0, 0, 0, .45); animation: wdgUndoIn .18s var(--ease-out, ease) both;
}
.wdg-undo-t { font-size: var(--fs-body); color: var(--text); }
.wdg-undo-b {
  background: transparent; border: 0; padding: 0; cursor: pointer; color: var(--orange);
  font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 11px; font-weight: 700;
  letter-spacing: .06em; text-transform: uppercase;
}
.wdg-undo-b:hover { text-decoration: underline; }
/* Variante ALERTE : le desk n'a pas pu être chargé, donc rien n'est enregistré. Rouge, persistant
   (pas de disparition automatique) — c'est un avertissement de perte de données, pas une info. */
.wdg-undo--warn { border-color: rgba(255, 61, 0, .5); }
.wdg-undo--warn span { font-size: var(--fs-body); color: var(--text); }
.wdg-undo--warn .wdg-undo-b { color: #ff3d00; }
@keyframes wdgUndoIn { from { opacity: 0; transform: translate(-50%, 10px); } to { opacity: 1; transform: translate(-50%, 0); } }
@media (max-width: 560px) { .wdg-undo { left: 12px; right: 12px; transform: none; justify-content: space-between; } @keyframes wdgUndoIn { from { opacity: 0; } to { opacity: 1; } } }

/* Bouton ARMÉ (2e clic = destruction) : rouge d'alerte, même grammaire que la confirmation de
   suppression d'un layout. Sert à « Réinitialiser tout » du gestionnaire. */
.wdg-btn--danger { color: #fff !important; background: #ff3d00 !important; border-color: #ff3d00 !important; }
.wdg-btn--danger:hover { background: #e63500 !important; }

/* ══ ESPACE DE TRAVAIL — état de séance, agenda, hiérarchie des devises ═══════════════════════════
   Identité DTP : rail or des titres, fond de panneau, filets fins, mono pour les chiffres.
   Le parti pris : de la DONNÉE, pas de la décoration — ce qu'on veut savoir avant d'ouvrir le desk. */
.home-strip {
  display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px;
  padding: 7px 12px; background: var(--bg2); border: 1px solid var(--hud-line, var(--border)); border-radius: var(--radius);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .022);
}
.home-sess { display: flex; align-items: center; gap: 7px; flex: 1 1 150px; min-width: 0; padding: 4px 2px; }
.home-sess-dot { flex: 0 0 auto; width: 6px; height: 6px; border-radius: 50%; background: var(--text4); }
.home-sess.is-open .home-sess-dot { background: #00e676; box-shadow: 0 0 0 3px rgba(0, 230, 118, .16); }
.home-sess-n {
  font-family: var(--tight); font-size: 11.5px; font-weight: 700; letter-spacing: .04em;
  text-transform: uppercase; color: var(--text3); white-space: nowrap;
}
.home-sess.is-open .home-sess-n { color: var(--text); }
.home-sess-t { font-size: 10.5px; color: var(--text3); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.home-sess.is-open .home-sess-t { color: var(--text3); }

.home-box { background: var(--bg2); border: 1px solid var(--hud-line, var(--border)); border-radius: var(--radius); padding: 4px 0; overflow: hidden; }
.home-empty { padding: 14px 12px; font-size: 11.5px; color: var(--text4); text-align: center; }

/* Agenda : l'heure en mono pour que la colonne s'aligne, la devise en pastille, le titre tronqué. */
.home-ev { display: flex; align-items: baseline; gap: 9px; padding: 7px 12px; border-bottom: 1px solid var(--hud-line, var(--border)); }
.home-ev:last-child { border-bottom: 0; }
.home-ev-h { flex: 0 0 auto; font-family: var(--mono, ui-monospace, monospace); font-size: 11px; color: var(--orange); font-variant-numeric: tabular-nums; }
.home-ev-ccy {
  flex: 0 0 auto; font-family: var(--mono, ui-monospace, monospace); font-size: 9.5px; font-weight: 700; letter-spacing: .05em;
  color: var(--text2); background: var(--bg5); border-radius: 3px; padding: 1px 5px;
}
.home-ev-t { flex: 1 1 auto; min-width: 0; font-size: 11.5px; color: var(--text2); line-height: 1.35;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }

/* Hiérarchie des devises : barre proportionnelle à la plus forte, vert en tête / rouge en queue. */
.home-fx { display: flex; align-items: center; gap: 9px; padding: 6px 12px; }
.home-fx-c { flex: 0 0 34px; font-family: var(--mono, ui-monospace, monospace); font-size: 11px; font-weight: 700; color: var(--text); }
.home-fx-bar { flex: 1 1 auto; height: 4px; background: var(--bg5); border-radius: 2px; overflow: hidden; }
.home-fx-bar i { display: block; height: 100%; border-radius: 2px; }
.home-fx.is-up   .home-fx-bar i { background: #00e676; }
.home-fx.is-down .home-fx-bar i { background: #ff3d00; }
.home-fx-v { flex: 0 0 auto; font-family: var(--mono, ui-monospace, monospace); font-size: 10.5px; font-variant-numeric: tabular-nums; color: var(--text3); }
.home-fx.is-up   .home-fx-v { color: #00e676; }
.home-fx.is-down .home-fx-v { color: #ff3d00; }
.home-fx-sep { height: 1px; margin: 5px 12px; background: var(--hud-line, var(--border)); }

/* Sur écran étroit la colonne latérale passe SOUS le contenu principal (jamais de colonne écrasée),
   et l'état de séance se met sur deux rangées plutôt que de tronquer ses libellés. */
@media (max-width: 900px) {
  .home-cols { flex-direction: column; gap: 4px; }
  .home-col--side { flex: 1 1 auto; width: 100%; }
  .home-sess { flex: 1 1 45%; }
}
/* L'or de marque en TEXTE sur papier clair ne tient que ~3:1 à 11 px — insuffisant pour une heure
   qu'on lit en diagonale. On l'assombrit UNIQUEMENT en thème clair : la couleur reste dans la
   famille de la charte, la lisibilité passe au-dessus du seuil. */
html[data-theme="light"] .home-ev-h { color: #7a5c07; }
/* Le vert et le rouge de la charte sont faits pour SIGNALER (fonds, barres, badges) — en TEXTE sur
   papier clair ils tombent à 1,7:1 et 3,5:1, illisibles. Les BARRES gardent donc les valeurs exactes
   de la charte ; seuls les CHIFFRES sont assombris, dans la même famille de teinte. */
html[data-theme="light"] .home-fx.is-up   .home-fx-v { color: #05713b; }
html[data-theme="light"] .home-fx.is-down .home-fx-v { color: #ab2708; }

/* ══ ESPACE DE TRAVAIL — GRILLE DE VRAIS WIDGETS ═════════════════════════════════════════════════
   Les panneaux ne sont pas des maquettes : ce sont les widgets du desk montés ici. Le cadre reste
   donc DISCRET (filet fin, en-tête d'une ligne) pour que la donnée porte l'écran, pas l'habillage. */
.home-grid {
  display: grid; grid-template-columns: repeat(12, 1fr); gap: 12px; margin-top: 12px;
  /* Les rangées se partagent la hauteur restante ; 180 px est le plancher en dessous duquel un
     graphique ne montre plus rien (et ce qui s'applique en une seule colonne, sur téléphone). */
  flex: 1 1 auto; align-items: stretch; grid-auto-rows: minmax(0, 1fr); min-height: 0;
}
/* Chaque zone porte son nombre de colonnes (--c) : la répartition suit ce que le widget doit
   MONTRER (un tableau à 7 piliers ne tient pas sur 4 colonnes) au lieu de classes figées. */
.home-zone { grid-column: span var(--c, 4); min-width: 0; min-height: 0; display: flex; flex-direction: column; }
.home-sec--w { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.home-zone-go {
  font-family: var(--tight); font-size: 10px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase;
  color: var(--text3); background: transparent; border: 0; padding: 0; cursor: pointer; transition: color .12s;
}
.home-zone-go:hover { color: var(--orange); }
/* Cadre du widget : hauteur EXPLICITE obligatoire — sans elle, amCharts et Leaflet mesurent 0 et
   rendent vide. Mais elle ne doit plus être FIGÉE : à 260/300 px, le contenu dépassait de 121 px
   sur un écran de 900 px (mesuré) et de plus de 250 px sur un portable 1366 × 768.
   On la déduit donc de la place réelle : (écran − topbar − le reste) ÷ nombre de rangées.
   · 240 px = tout ce qui n'est pas un widget (titre, sessions, en-têtes, accès rapide, marges,
     gouttières) — chiffre MESURÉ, pas estimé.
   · le clamp protège les deux extrêmes : jamais sous 158 px (un graphique n'y dirait plus rien),
     jamais au-delà de 300 px (au-delà, on gaspille l'écran sans rien montrer de plus). */
.home-zone-body {
  flex: 1 1 auto; min-height: 180px; overflow: hidden; position: relative;
  background: var(--bg2); border: 1px solid var(--hud-line, var(--border)); border-radius: var(--radius);
  /* Filet lumineux d'un pixel en haut : donne de l'assise au panneau sans ajouter de trait visible.
     Au survol, le liseré or de la charte — même langage que les cartes du desk. */
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .028);
  transition: border-color .16s var(--ease, ease);
}
.home-zone-body:hover { border-color: rgba(227, 178, 58, .26); }
.home-zone-body > * { height: 100%; }

/* Sous 1280 px, la rangée 1 à trois zones devient trop serrée : on la coupe en deux (desks + agenda
   large / news pleine largeur), ce qui fait TROIS rangées — la hauteur des cadres suit. */
/* Sous 1280 px, une rangée à trois zones devient trop serrée : deux par rangée. Les rangées
   continuent de se partager la hauteur restante — rien à recalculer. */
@media (max-width: 1280px) {
  .home-zone { grid-column: span 6; }
}
/* Une seule colonne : quatre widgets ne tiennent PAS dans un écran de téléphone, et les y forcer
   les réduirait à des timbres-poste illisibles. On assume le défilement — l'exigence est que rien
   ne soit ROGNÉ, pas que tout tienne dans un écran de 6 pouces. */
/* Une seule colonne : cinq zones ne tiennent PAS dans un écran de téléphone. Le plancher de 220 px
   prime, le défilement est assumé — l'exigence est que rien ne soit ROGNÉ. */
@media (max-width: 860px) {
  /* Hauteur figée + cinq zones = widgets écrasés. On rend la main au flux : la page défile. */
  .home-inner { height: auto; min-height: calc(var(--vph) - var(--topbar-h, 54px)); }
  .home-grid { grid-template-columns: 1fr; grid-auto-rows: minmax(220px, auto); }
  .home-zone { grid-column: 1 / -1; }
}



/* ══ BARRE D'ONGLETS DE MON DESK = LA NAV DU DESK, CADRE COMPRIS ══════════════════════════════════
   Les ITEMS étaient déjà alignés (même police, taille, graisse, marges, couleurs — cf. --tab-on).
   Restaient deux écarts de CADRE, mesurés : le bandeau faisait 32 px au lieu des 28 px de la nav
   (.navbar, hauteur --navbar-h) et retirait son premier onglet de 10 px, si bien que ni la ligne de
   base ni le soulignement or ne tombaient au même endroit que « › ACTUS ».
   On reprend donc la hauteur au TOKEN de la navbar plutôt qu'une valeur recopiée : si la nav change
   de gabarit, Mon Desk suit. Le retrait de droite est conservé (bouton Personnaliser). */
/* La barre de Mon Desk EST une .navbar (voir index.html) : hauteur, fond, bordure et alignement
   viennent de la nav du desk. On ne déclare ici que la répartition gauche/droite et l'étirement
   vertical des deux zones, pour que les onglets et « Personnaliser » occupent toute la hauteur. */
.wdg-bar { justify-content: space-between; padding-right: 10px; }
/* ⚠️ LA BARRE « MON DESK » SE REPLIE SUR TELEPHONE. Mesure : la moitie de la barre restait vide
   pendant que les onglets de disposition etaient coupes et que le « + » sortait de l'ecran — la
   place existait, elle etait juste du mauvais cote. En repliant, la rangee des dispositions
   recupere toute la largeur. On ne se sert PAS de :empty pour detecter le groupe de droite : il
   contient un commentaire HTML et des retours a la ligne, donc :empty ne matche jamais. */
@media (max-width: 560px) {
  #view-widgets .wdg-bar { flex-wrap: wrap; height: auto; min-height: var(--navbar-h, 40px); }
  #view-widgets .wdg-bar > .panel-header-left { flex: 1 1 100%; min-width: 0; }
  #view-widgets .wdg-bar > .panel-header-controls { flex: 0 0 auto; }
}
.wdg-bar > .panel-header-left, .wdg-bar > .panel-header-controls { align-self: stretch; align-items: stretch; }
/* min-width:0 comme la nav : sur un écran étroit, beaucoup de layouts doivent RÉTRACTER la zone
   d'onglets, pas repousser « Personnaliser » hors du bandeau. */
.wdg-bar > .panel-header-left { min-width: 0; overflow: hidden; }
.wdg-bar > .panel-header-controls { flex: 0 0 auto; }
#wdg-layouts { display: flex; align-items: stretch; }
/* Le conteneur de droite (.panel-header-controls) est centré verticalement et se dimensionne sur son
   contenu : « Personnaliser » ne pouvait donc pas s'étirer sur la hauteur du bandeau, et sa zone
   cliquable restait deux fois plus courte que celle d'un onglet. On étire le conteneur DANS la vue
   Mon Desk uniquement — ailleurs, .panel-header-controls porte des contrôles qui doivent rester centrés. */

/* ACTIONS DESCENDUES DU BANDEAU (29/07) — le bandeau portait SEPT icônes ; il n'en garde que trois
   (régler · remplacer · fermer). Les quatre autres vivent ici, dans le panneau de réglages, en
   boutons LIBELLÉS : on ne s'en sert pas tous les jours, une icône seule aurait juste déplacé le
   problème de lisibilité. Grille de 2 pour rester compact. */
.wdg-set-acts { display: grid; grid-template-columns: 1fr 1fr; gap: 4px; margin-top: 2px; }
.wdg-set-act {
  display: inline-flex; align-items: center; gap: 5px; padding: 5px 7px;
  font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 10.5px; font-weight: var(--fw-semibold, 600);
  color: var(--text2); background: var(--bg2); border: 1px solid var(--hud-line, var(--border));
  border-radius: 4px; cursor: pointer; white-space: nowrap;
  transition: color .12s, border-color .12s, background .12s;
}
.wdg-set-act:hover { color: var(--text); border-color: rgba(227, 178, 58, .5); background: rgba(227, 178, 58, .07); }
.wdg-set-act.on { color: var(--orange); border-color: rgba(227, 178, 58, .55); }
.wdg-set-act svg { flex: 0 0 auto; opacity: .85; }

/* ════════════════════════════════════════════════════════════════════════════
   RESPONSIVE DES WIDGETS — salve issue de l'audit multi-agents du 02/08
   (18 défauts confirmés après réfutation adversariale ; chaque règle cite sa
   mesure). Bloc en FIN de feuille : à spécificité égale, l'ordre source fait
   gagner ces correctifs sur les règles historiques qu'ils amendent.
   ════════════════════════════════════════════════════════════════════════════ */

/* ── FORCE DES DEVISES : la barre de périodes ne peut pas rétrécir (flex 0 0 auto) et, dans l'en-tête,
   elle écrasait le titre à 9 px sur téléphone et 0 px sur carte demi-largeur (mesuré). Sous 900px elle
   passe sur sa PROPRE ligne, pleine largeur — le titre respire, l'en-tête grandit de 13 px. */
@media (max-width: 900px) {
  .wdg-head:has(.wdg-fx-tfbar--head) { flex-wrap: wrap; padding-bottom: 5px; }
  .wdg-head .wdg-fx-tfbar--head { order: 3; flex: 1 1 100%; margin: 0; justify-content: flex-start; overflow-x: auto; }
}

/* ── BAROMÈTRE : compactions pilotées par la LARGEUR DE LA CARTE (conteneur .wdg-metre posé par le
   mount), plus par un seuil d'écran — mesuré au banc, les têtes se télescopaient et les badges se
   tronquaient aussi sur une carte étroite posée sur un GRAND écran. Sous ~430 px de carte, les
   colonnes font ≤ 42 px : le drapeau (14 px) et le plancher 42 px du badge ne tiennent plus — le code
   devise et le chiffre portent l'information, ils cèdent. */
/* width:100% OBLIGATOIRE : container-type:inline-size rend la largeur indépendante du contenu, et
   dans un parent flex l'enveloppe s'effondrait (colonnes mesurées à 15,7 px au banc). */
.wdg-metre { container-type: inline-size; container-name: dtpmetre; width: 100%; height: 100%; min-height: 0; }
.wdg-metre .meter-grid { height: 100%; min-height: 240px; }
@container dtpmetre (max-width: 430px) {
  .meter-col-head .meter-flag-img { display: none; }
  .meter-ticker { font-size: 9px; letter-spacing: .02em; }
  .meter-grid { gap: 4px; padding: 8px 8px 12px; }
  .meter-col-val .v { min-width: 0; padding: 2px 4px; font-size: 9px; }
}

/* ── RADAR DE BIAIS : deux règles du desk s'imposaient au widget — min-width 540px (≤980px de viewport)
   dans une carte de 369 px = 171 px hors champ garantis, et au-dessus de 980px la colonne Driver + le
   chevron + les paddings larges portaient le minimum réel à ~647 px pour 493 disponibles. La carte peut
   être étroite sur N'IMPORTE QUEL écran : on interroge donc le CONTENEUR, pas le viewport. */
#view-widgets .wdg-biaswrap { container-type: inline-size; container-name: dtpbias; }
#view-widgets .wdg-biaswrap .macro-table { min-width: 0; }
@container dtpbias (max-width: 700px) {
  /* Driver et chevron cèdent (le détail au clic les montre) ; en-têtes autorisés à passer sur 2 lignes. */
  .macro-table th:nth-child(6), .macro-table td:nth-child(6),
  .macro-table th.mt-x-h, .macro-table td.mt-x { display: none; }
  .macro-table th, .macro-table td { padding: 7px 6px; }
  .macro-table th { font-size: 9.5px; letter-spacing: .02em; white-space: normal; line-height: 1.25; }
  .macro-table th.mt-cur-h { width: 64px; }
  .mt-cur { font-size: 12px; gap: 5px; }
  .mt-tag { font-size: 10px; padding: 2px 6px; }
  /* Les tags étant incompressibles (nowrap), le contenu minimal reste ~500 px : sous ce seuil la table
     DÉFILE, mais la devise reste FIGÉE — on sait toujours quelle ligne on lit (parti du desk sur
     téléphone). Sans débordement, le sticky est inerte : on l'active donc dès le mode compact.
     Coin en-tête : sticky top (règle de base) ET left. */
  .macro-table td:first-child { position: sticky; left: 0; z-index: 2; background: var(--bg); }
  .macro-table th:first-child { position: sticky; left: 0; z-index: 3; }
}

/* ── TAUX DIRECTEURS : les minima de la grille (84+62+96+78 + gaps + padding = 368 px incompressibles)
   débordaient d'une carte de 357 px sur iPad mini (11 à 47 px selon l'écran). Bande tablette dédiée —
   bornée à 561px pour laisser la règle téléphone existante (≤560) faire foi en dessous. */
@media (min-width: 561px) and (max-width: 900px) {
  .wdg-taux-head, .wdg-taux-row { grid-template-columns: minmax(0, 1.2fr) 56px minmax(0, 1.1fr) minmax(0, .9fr); gap: 6px; padding: 6px 10px; }
}

/* ── SENTIMENT DE RISQUE : badge compact sur petit écran — à 13 px + interlettrage 2 px il était plus
   large que le diamètre entier de la jauge (175 px vs 124). Le plancher de la jauge est posé sur
   .wdg-riskwrap (voir plus haut) ; ici on ne réduit que le badge. */
@media (max-width: 900px) {
  #view-widgets .risk-readout-badge { font-size: 11px; letter-spacing: 1px; padding: 5px 12px; }
}

/* ── FIL D'ACTUALITÉ : entre 769 et 900px la carte est demi-largeur mais gardait le budget de colonnes
   DESKTOP (266 px figés : padding 36 + icône 32 + heure 58 + catégorie 112 + flèche 28) → 99 px pour le
   titre, 7 lignes, 202 px de haut pour UNE news (mesuré). Budget compact : 261 px de titre. Même parti
   que le desk à ≤480px, qui masque déjà la catégorie. */
@media (max-width: 900px) {
  .wdg-news .news-item { --c-pad: 10px; --c-icon: 22px; --c-time: 44px; --c-cat: 0px; --c-arrow: 18px; padding: 8px 10px; }
  .wdg-news .news-category-text { display: none; }
}

/* ── SESSIONS DE MARCHÉ : badges des villes de l'Est ancrés à droite (classe posée par cityHtml quand
   lon > 100°). Centré sur son point, le badge de Sydney sortait de 34 px du cadre à 493 px de large. */
.wdg-lfmap .lf-city--w { transform: translate(-92%, -50%); }

/* ── HORLOGE MONDIALE : en mode compact l'heure repassait à 21 px (règle tardive du desk) dans des
   colonnes de 132 px → 3 à 8 px coupés sur le code ville et l'icône jour/nuit (mesuré à 430, 600 et
   768 px). 15 px : plus aucun débordement sur toutes les largeurs testées. */
@media (max-width: 900px) {
  .wdg-clocks-bar .clock-time { font-size: 15px; }
}

/* ── JOURNAL : la barre d'outils (4 boutons nowrap + badge = 588 px incompressibles) débordait de
   246 px d'une carte de 342 px et était CLIPPÉE — « Exporter (CSV) » inatteignable. Le repli existait
   mais enfermé dans @media 560 : une carte peut être étroite sur tout écran → scopé au desk de
   widgets, sans seuil. Idem pour le tableau de bord : la colonne donut figée à 224 px écrasait la
   courbe de capital à 34 px de large — auto-fit retombe seul à 1 colonne sous ~460 px de conteneur. */
#view-widgets .jr-toolbar { flex-wrap: wrap; }
#view-widgets .jr-tb-spacer { display: none; }
#view-widgets .jrd-row { grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); }
#view-widgets .jrd-row--charts { grid-template-columns: repeat(auto-fit, minmax(224px, 1fr)); }

/* ── PANNEAU À ONGLETS, TACTILE : les 3 boutons d'en-tête restaient à opacité 0 (le révélateur est
   :hover, jamais déclenché au doigt) MAIS cliquables — un piège invisible de 92 px au-dessus de la
   barre d'onglets : un tap visant un onglet retirait le widget. Visibles sur tactile, et la barre
   d'onglets réserve leur place pour ne plus défiler dessous. (La croix de fermeture d'onglet a été
   supprimée partout depuis — le retrait passe par les Réglages de la carte, souris comme tactile.) */
@media (hover: none) {
  .wdg-card--tabs > .wdg-head .wdg-actions { opacity: .75; }
  .wdg-card--tabs .wdgt-bar { padding-right: 96px; }
}

/* ── FIL D'ACTUALITÉ (widget) : panneau du desk à l'identique — assemblage local uniquement, tout le
   reste (toolbar, dropdown, date-header, news-item) vient des classes globales du desk. */
.wdg-news-panel { display: flex; flex-direction: column; height: 100%; min-height: 0; position: relative; }
.wdg-news-panel .news-list { flex: 1 1 auto; min-height: 0; }
/* Le menu de sections du desk se cale sous SA toolbar via un décalage qui inclut le header du panneau
   (+32px) ; dans la carte il n'y a pas ce header → on le recale sous la toolbar réelle du widget. */
.wdg-news-panel .section-dropdown { top: var(--toolbar-h, 40px); }
/* Carte étroite : la recherche cède au lieu de pousser le compteur hors champ. */
.wdg-news-panel .toolbar-search { flex: 1 1 60px; min-width: 0; }

/* ── SENTIMENT DE RISQUE (widget) : jauge + bande d'historique, comme l'onglet RISQUE du desk. ── */
.wdg-riskpanel { display: flex; flex-direction: column; height: 100%; min-height: 0; }
/* ⚠️ BASE ZERO SUR LA JAUGE, ET C EST TOUT LE CORRECTIF (28/08). Elle etait `flex: 1 1 auto` avec
   `height: 100%` : sa base valait donc la hauteur ENTIERE du panneau, et l histogramme partait
   perdant dans le partage — quelle que soit la place, le surplus allait a la jauge, et le manque
   etait paye par la bande. `1 1 0` inverse l ordre : l histogramme prend ses 170px, la jauge REMPLIT
   ce qui reste. Et quand ce reste tombe sous son plancher de 280px, c est alors seulement que la
   bande cede, jusqu a 104px. Compression SEQUENTIELLE, obtenue sans requete de conteneur. */
.wdg-riskpanel .wdg-riskwrap { flex: 1 1 0; }
/* ⚠️ L HISTOGRAMME DOIT CEDER AVANT LE DEFILEMENT (28/08, capture user « on voit pas tout le bas »).
   Il etait `flex: 0 0 170px` — RIGIDE — face a une jauge plancher a 280px : 450px incompressibles.
   Mesure au banc : sous ~490px de carte, la bande debordait de 28 a 108px. Atteignable en faisant
   defiler le corps, certes, mais faire defiler un widget pour voir SON PROPRE graphique n est pas
   une lecture, c est un pis-aller — et l axe des dates comme le titre « Sentiment (%) » passaient
   sous le pli sans que rien ne le signale.
   `1 1 170px` : la bande garde 170px quand la place existe (rendu identique a avant, verifie au
   banc a 620, 560 et 500px) et se resserre jusqu a 104px quand elle manque — a cette hauteur les
   barres, la ligne de zero et l axe restent lisibles, c est le plancher utile mesure. Le plancher
   incompressible du panneau tombe ainsi de 450 a 384px. Le defilement du corps reste en dernier
   recours sous cette valeur : on comprime d abord, on ne coupe jamais. */
.wdg-riskpanel .rsh-chart { flex: 0 1 170px; min-height: 104px; }

/* ── WIDGETS « VUE DU DESK » (adoption du vrai panneau) : l'hôte donne au panneau la place entière
   de la carte ; les panneaux (.view-panel) portent déjà flex:1 + leurs propres scrolls internes. */
.wdg-vuehost { display: flex; flex-direction: column; height: 100%; min-height: 0; overflow: hidden; }
.wdg-vuehost > .view-panel { flex: 1 1 auto; min-width: 0; min-height: 0; width: 100%; }

/* ── VUES ADOPTÉES : lecture PLEINE LARGEUR dans la carte (03/08, capture user « trop d'écart sur les
   côtés »). La colonne de lecture des lecteurs Analystes/Institutions (~1040 px centrés) est pensée
   pour l'onglet plein écran ; dans une carte, ce centrage laissait deux gouttières noires. Dans une
   vue adoptée, le contenu prend l'espace de tous les côtés — padding fixe raisonnable, plus de calc
   centré. */
.wdg-vuehost .arlib-rcontent, .wdg-vuehost #br-rcontent { padding: 20px 26px 36px; }

/* Onglet Taux (vue adoptée) : mode « une seule banque » → la carte restante prend toute la largeur. */
.wdg-vuehost #taux-grid.rtc-solo { grid-template-columns: minmax(0, 1fr); }

/* ── VUES ADOPTÉES : contenu COLLÉ AUX BORDS de la carte (03/08, capture user « il faut qu'il prenne
   tout l'espace ») — les gouttières venaient du padding de page des vues, pensé pour l'onglet plein
   écran. Dans une carte, c'est la carte qui fait le cadre. ── */
.wdg-vuehost .taux-grid { padding: 0; gap: 8px; }
.wdg-vuehost .taux-grid .rtc { border-left: 0; border-right: 0; border-radius: 0; }   /* la carte du widget fait déjà le cadre latéral */

/* ════════════════════════════════════════════════════════════════════════════
   ESPACE DE TRAVAIL — PRISE DE POSTE « NIVEAU SUPÉRIEUR » (03/08, demande user)
   Synthèse des trois directions design (lumière · typographie · mouvement),
   identité 100 % DTP. Bloc en fin de feuille : il amende les règles de base.
   ════════════════════════════════════════════════════════════════════════════ */

/* ── SCÈNE : vignette sombre + trame terminal + aura d'or qui respire ── */
.home-overlay { isolation: isolate; }
.home-overlay::before {
  content: ''; position: absolute; inset: 0; z-index: -1; pointer-events: none;
  background:
    linear-gradient(0deg, rgba(0,0,0,.36), transparent 22%),
    radial-gradient(120% 90% at 50% 40%, transparent 58%, rgba(0,0,0,.34)),
    repeating-linear-gradient(0deg, rgba(255,255,255,.012) 0 1px, transparent 1px 3px);
}
.home-overlay::after {
  content: ''; position: absolute; z-index: -1; pointer-events: none;
  top: -180px; left: 4%; width: 900px; height: 480px;
  background: radial-gradient(closest-side, rgba(227,178,58,.075), transparent 70%);
  animation: homeAura 22s ease-in-out infinite alternate;
}
@keyframes homeAura { from { transform: translateX(0); } to { transform: translateX(64px); } }

/* ── HÉROS : kicker or à filet, Fraunces format affiche, prénom qui s'allume une fois ── */
.home-eyebrow {
  display: inline-flex; align-items: center; gap: 8px;
  color: var(--orange-dim, #b8860b); letter-spacing: .3em;
}
.home-eyebrow::before { content: ''; width: 18px; height: 1px; background: linear-gradient(90deg, var(--orange, #e3b23a), transparent); }
.home-title {
  font-size: 32px; font-weight: 500;
  font-variation-settings: 'opsz' 84;             /* Fraunces : coupe AFFICHE (empattements fins, contraste) */
}
.home-name {
  font-weight: 700;
  background-size: 220% 100%;
  animation: homeNameSweep 1.1s .25s ease-out both; /* un seul balayage, puis le rendu se fige */
  filter: drop-shadow(0 0 18px rgba(227,178,58,.28));
}
@keyframes homeNameSweep { from { background-position: 120% 0; } to { background-position: 0% 0; } }
.home-sub-date {
  font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 10px; font-weight: 700;
  letter-spacing: var(--ls-caps, .08em); text-transform: uppercase; color: var(--text3);
}
.home-sub-dot { color: var(--orange, #e3b23a); margin: 0 7px; }

/* ── SESSIONS : instrument de bord — hairlines, pouls radar, compte à rebours mono, jauge de séance ── */
.home-top .home-strip {
  background: linear-gradient(180deg, rgba(255,255,255,.02), transparent 55%), var(--bg2);
  border: 1px solid var(--hud-line, var(--border)); border-radius: var(--radius);
  padding: 7px 6px;
}
.home-sess { position: relative; padding: 4px 12px; }
.home-sess + .home-sess::before {
  content: ''; position: absolute; left: 0; top: 15%; bottom: 15%;
  width: 1px; background: var(--hud-line, var(--border));
}
.home-sess-main { display: flex; flex-direction: column; gap: 3px; min-width: 0; flex: 1; }
.home-sess-lig { display: flex; align-items: baseline; gap: 7px; min-width: 0; }
.home-sess-cd { font-family: var(--font-mono); font-weight: 600; font-variant-numeric: tabular-nums; color: var(--text2); }
.home-sess.is-open .home-sess-cd { color: var(--orange-dim, #b8860b); }
.home-sess.is-open .home-sess-dot { position: relative; }
.home-sess.is-open .home-sess-dot::after {
  content: ''; position: absolute; inset: -2px; border-radius: 50%;
  border: 1px solid rgba(0, 230, 118, .55);
  animation: homePing 2.6s ease-out infinite;
}
@keyframes homePing { 0% { transform: scale(.7); opacity: .9; } 70%, 100% { transform: scale(2.4); opacity: 0; } }
.home-sess-j { display: block; height: 2px; border-radius: 2px; background: rgba(255,255,255,.07); overflow: hidden; }
.home-sess-j i { display: block; height: 100%; border-radius: 2px; background: linear-gradient(90deg, rgba(0,230,118,.5), #00e676); transition: width .6s ease; }

/* ── EN-TÊTES DE SECTIONS : numérotés, rail or dégradé, filet fuyant, zone qui s'allume ── */
.home-grid { counter-reset: homesec; }
.home-sec { border-left: 0; padding-left: 12px; position: relative; }
.home-sec::before {
  content: ''; position: absolute; left: 0; top: 1px; bottom: 1px; width: 2px; border-radius: 2px;
  background: linear-gradient(180deg, var(--orange, #e3b23a), var(--orange-dim, #b8860b));
}
.home-sec--w { display: flex; align-items: center; gap: 10px; }
.home-sec-t::before {
  counter-increment: homesec; content: counter(homesec, decimal-leading-zero);
  font-family: var(--font-mono); font-size: 9px; font-weight: 600; letter-spacing: .06em;
  color: var(--orange-dim, #b8860b); opacity: .85;
}
.home-sec--w::after { content: ''; order: 2; flex: 1; height: 1px; background: linear-gradient(90deg, rgba(227,178,58,.28), transparent 82%); }
.home-sec--w .home-zone-go { order: 3; letter-spacing: var(--ls-caps, .08em); transition: color .15s, transform .15s; }
.home-zone:hover .home-sec-t { color: var(--text); }
.home-zone:hover .home-zone-go { color: var(--orange); transform: translateX(2px); }

/* Pastille « En direct » : l'écran est branché sur le marché, pas une page figée. */
.home-live {
  display: inline-flex; align-items: center; gap: 5px;
  font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 8.5px; font-weight: 700;
  letter-spacing: .09em; text-transform: uppercase; color: #27c07a;
}
.home-live i { width: 5px; height: 5px; border-radius: 50%; background: #00e676; animation: homeBreathe 2.4s ease-in-out infinite; }
@keyframes homeBreathe { 0%, 100% { opacity: 1; } 50% { opacity: .35; } }

/* ── PANNEAUX EN RELIEF : lumière du haut, ombre douce, liseré or d'arête qui s'allume ── */
.home-zone-body {
  position: relative;
  background: linear-gradient(180deg, rgba(255,255,255,.022), transparent 40%), var(--bg2);
  box-shadow: 0 14px 34px -22px rgba(0,0,0,.6);
}
.home-zone-body::before {
  content: ''; position: absolute; top: -1px; left: 10%; right: 10%; height: 1px; z-index: 1; pointer-events: none;
  background: linear-gradient(90deg, transparent, rgba(227,178,58,.34), transparent);
  opacity: .45; transition: opacity .2s ease;
}
.home-zone:hover .home-zone-body::before { opacity: 1; }
.home-zone:hover .home-zone-body { border-color: rgba(227,178,58,.34); }

/* ── CARTES « MES DESKS » : lestées, nom en Fraunces, presse tactile, flèche vivante ── */
.home-card {
  background: linear-gradient(180deg, rgba(255,255,255,.025), transparent 46%), var(--bg2);
  animation: homeIn .5s calc(.24s + var(--i, 0) * .06s) var(--ease-out, ease) both;
}
.home-card:hover {
  border-color: rgba(227,178,58,.5);
  box-shadow: 0 10px 26px -14px rgba(0,0,0,.55), 0 8px 22px -12px rgba(227,178,58,.18), inset 0 0 0 1px rgba(227,178,58,.12);
}
.home-card:active { transform: translateY(0) scale(.99); }
.home-card-name { font-family: var(--serif, 'Fraunces', Georgia, serif); font-size: 13.5px; font-weight: 600; letter-spacing: 0; }
.home-card--new .home-card-name { font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 11px; font-weight: 700; letter-spacing: var(--ls-caps, .08em); text-transform: uppercase; }
.home-card-go { letter-spacing: var(--ls-caps, .08em); transition: color .15s, transform .18s; }
.home-card:hover .home-card-go { transform: translateX(3px); }

/* ── CASCADE D'ALLUMAGE : héros → sessions → zones (l'ordre de lecture) ── */
@keyframes homeIn { from { opacity: 0; transform: translateY(7px); } to { opacity: 1; transform: none; } }
.home-top .home-hero { animation: homeIn .45s .04s var(--ease-out, ease) both; }
.home-top .home-strip { animation: homeIn .45s .12s var(--ease-out, ease) both; }
.home-grid > .home-zone:nth-child(1) { animation: homeIn .5s .18s var(--ease-out, ease) both; }
.home-grid > .home-zone:nth-child(2) { animation: homeIn .5s .24s var(--ease-out, ease) both; }
.home-grid > .home-zone:nth-child(3) { animation: homeIn .5s .30s var(--ease-out, ease) both; }
.home-grid > .home-zone:nth-child(4) { animation: homeIn .5s .36s var(--ease-out, ease) both; }
.home-grid > .home-zone:nth-child(5) { animation: homeIn .5s .42s var(--ease-out, ease) both; }

/* ── « ACCÉDER AU DESK » : la seule action pleine de l'écran — une invitation or ── */
.home-skip {
  color: var(--orange-dim, #b8860b); border-color: rgba(227,178,58,.34);
  background: rgba(227,178,58,.06); letter-spacing: var(--ls-caps, .08em); font-weight: 700;
}
.home-skip:hover { color: var(--orange); border-color: rgba(227,178,58,.6); background: rgba(227,178,58,.12); }

@media (prefers-reduced-motion: reduce) {
  .home-overlay::after, .home-name, .home-sess.is-open .home-sess-dot::after, .home-live i,
  .home-top .home-hero, .home-top .home-strip, .home-grid > .home-zone, .home-card { animation: none !important; }
}

/* ════════════════════════════════════════════════════════════════════════════
   ESPACE DE TRAVAIL v2 (03/08) : les TITRES vivent DANS les blocs (grammaire des
   panneaux du desk), plus aucun texte au-dessus, corps bord à bord, TICKER des
   devises en bande fine, « Accéder au desk » rangé dans la rangée d'en-tête.
   ════════════════════════════════════════════════════════════════════════════ */

/* Le bloc = un panneau du desk : cadre unique, en-tête intégré, corps flush. */
.home-zone {
  border: 1px solid var(--hud-line, var(--border)); border-radius: var(--radius);
  background: linear-gradient(180deg, rgba(255,255,255,.02), transparent 36%), var(--bg2);
  overflow: hidden; display: flex; flex-direction: column; position: relative;
  box-shadow: 0 14px 34px -22px rgba(0,0,0,.6);
  transition: border-color .18s ease;
}
.home-zone:hover { border-color: rgba(227,178,58,.34); }
.home-zone::after {
  content: ''; position: absolute; top: 0; left: 10%; right: 10%; height: 1px; pointer-events: none;
  background: linear-gradient(90deg, transparent, rgba(227,178,58,.34), transparent);
  opacity: .4; transition: opacity .2s ease;
}
.home-zone:hover::after { opacity: 1; }
.home-panel-head {
  display: flex; align-items: center; gap: 9px; flex: 0 0 auto;
  height: 30px; padding: 0 10px;
  background: var(--head-bg, #121214); border-bottom: 1px solid var(--hud-line, var(--border));
}
.home-panel-t {
  font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 11px; font-weight: 600;
  letter-spacing: .06em; text-transform: uppercase; color: var(--text2); white-space: nowrap;
}
.home-panel-fill { flex: 1 1 auto; height: 1px; background: linear-gradient(90deg, rgba(227,178,58,.2), transparent 78%); }
.home-zone:hover .home-panel-t { color: var(--text); }
/* Le corps colle aux bords : le cadre du bloc suffit — l'ancien encadré interne disparaît. */
.home-zone .home-zone-body {
  border: 0; border-radius: 0; box-shadow: none; background: transparent;
  flex: 1 1 auto; min-height: 0; padding: 0;
}
.home-zone .home-zone-body::before { display: none; }
.home-zone-body--cards { padding: 10px; overflow-y: auto; }

/* Bouton « Accéder au desk » : dans la rangée d'en-tête, aligné au bandeau des sessions. */
.home-skip { position: static; align-self: center; margin-left: 4px; flex: 0 0 auto; white-space: nowrap; }

/* ── TICKER DES DEVISES : bande fine, mono, fondu aux bords, défilement lent, pause au survol. ── */
.home-ticker {
  height: 0; opacity: 0; overflow: hidden; position: relative; margin: 12px 0 0;
  border: 1px solid var(--hud-line, var(--border)); border-radius: var(--radius);
  background: linear-gradient(180deg, rgba(255,255,255,.015), transparent 60%), var(--bg2);
  transition: height .3s ease, opacity .3s ease;
}
.home-ticker.is-on { height: 30px; opacity: 1; }
.home-ticker::before, .home-ticker::after {
  content: ''; position: absolute; top: 0; bottom: 0; width: 46px; z-index: 2; pointer-events: none;
}
.home-ticker::before { left: 0; background: linear-gradient(90deg, var(--bg2), transparent); }
.home-ticker::after { right: 0; background: linear-gradient(-90deg, var(--bg2), transparent); }
.home-ticker-in {
  display: flex; align-items: center; height: 30px; width: max-content;
  /* Duree pilotee par --home-tk-dur, pose par home.js depuis la LARGEUR mesuree (vitesse
     constante). Repli 30s si la variable manque, pour qu une bande sans JS defile quand meme. */
  animation: homeTicker var(--home-tk-dur, 30s) linear infinite;
}
.home-ticker:hover .home-ticker-in { animation-play-state: paused; }
@keyframes homeTicker { to { transform: translateX(-50%); } }
.home-tk {
  display: inline-flex; align-items: baseline; gap: 7px; padding: 0 16px;
  border-right: 1px solid var(--hud-line, var(--border));
  font-family: var(--font-mono); font-size: 10.5px; white-space: nowrap;
}
.home-tk b { font-weight: 600; letter-spacing: .05em; color: var(--text3); }
.home-tk-px { color: var(--text); font-variant-numeric: tabular-nums; }
.home-tk-chg { font-variant-numeric: tabular-nums; color: var(--text3); }
.home-tk-chg.up { color: #22c55e; }
.home-tk-chg.down { color: #ff5233; }

/* (v5 : le ticker n'est plus frère de .home-grid — l'espacement vit dans le padding de .home-inner) */

/* ── « ANIMATIONS RÉDUITES » : ON RALENTIT, ON NE COUPE PLUS (17/08/2026) ────────────────────────
   Cette règle mettait `animation: none`, et c'est ce qui immobilisait la bande chez l'utilisateur :
   Windows (Accessibilité → Effets visuels → Effets d'animation) demandait de limiter les animations,
   le desk coupait tout. Diagnostic confirmé par la barre de défilement horizontale apparue sous le
   bandeau après l'ajout du repli, visible sur sa capture.
   Un bandeau de cotations n'est pas une décoration : le mouvement EST le contenu, comme sur un
   téléscripteur. Le couper ne réduit pas la gêne, il supprime la fonction. On le ralentit donc de
   moitié plutôt que de l'arrêter — un glissement linéaire lent, sans rebond, sans zoom, sans
   clignotement, c'est-à-dire sans les formes de mouvement qui gênent réellement.
   Et il reste MAÎTRISABLE : survol = pause (règle plus haut), et la bande se fait défiler à la main. */
/* (Exception « animations reduites » RETIREE le 17/08 : le bandeau garde la meme vitesse
   partout, a la demande explicite du proprietaire, repetee. Le mouvement EST le contenu ici ;
   le survol reste le moyen de l arreter.) */

/* ════════════════════════════════════════════════════════════════════════════
   RÉGLAGES DES WIDGETS EN TIROIR LATÉRAL (03/08, référence user) : le panneau
   s'ouvre en volet pleine hauteur au bord droit de la carte ; les choix longs
   (banques, tris) deviennent des RANGÉES pleine largeur, l'actif souligné or
   avec sa coche. S'applique à TOUS les widgets (même contrat déclaratif).
   ════════════════════════════════════════════════════════════════════════════ */
.wdg-pop.wdg-settings {
  top: 0; right: 0; bottom: 0; width: min(300px, 88%);
  border-radius: 0; border: 0; border-left: 1px solid rgba(227,178,58,.32);
  box-shadow: -18px 0 44px rgba(0,0,0,.55);
  padding: 12px 14px; overflow-y: auto;
  animation: wdgSheetIn .18s ease-out;
}
@keyframes wdgSheetIn { from { transform: translateX(14px); opacity: 0; } }
.wdg-settings .wdg-set-row:has(.wdg-set-chips) { flex-direction: column; align-items: stretch; gap: 7px; }
.wdg-settings .wdg-set-row:has(.wdg-set-chips) .wdg-set-lbl { width: auto; padding-top: 0; }
.wdg-settings .wdg-set-chips { flex-direction: column; gap: 6px; }
.wdg-settings .wdg-set-chip {
  width: 100%; text-align: left; border-radius: 5px; padding: 8px 30px 8px 11px;
  font-size: 11px; position: relative;
}
.wdg-settings .wdg-set-chip.on {
  background: rgba(227,178,58,.09); color: var(--orange, #e3b23a);
  border-color: rgba(227,178,58,.6); font-weight: 700;
}
.wdg-settings .wdg-set-chip.on::after {
  content: '✓'; position: absolute; right: 10px; top: 50%; transform: translateY(-50%);
  font-size: 11px; color: var(--orange, #e3b23a);
}
html[data-theme="light"] .wdg-settings .wdg-set-chip.on { color: var(--orange-dim, #b8860b); }

/* ── ESPACE DE TRAVAIL v3 (03/08) : TOUT EN BLOCS — le héros est un bloc de la grille (accueil +
   sessions + bouton), le ticker est un BANDEAU pleine largeur collé sous la topbar. Titres = les
   noms exacts des widgets du desk, plus aucune pastille inventée. ── */
/* Bandeau au VRAI sommet : la marge négative verticale tirait la bande au-dessus du bord du
   conteneur défilant, qui la ROGNAIT de moitié (constaté user « on voit pas bien le ticker »).
   On supprime le padding haut du conteneur à la place — zéro traction, zéro rognage. */
.home-overlay > .home-inner { padding-top: 0; }
.home-ticker { margin: 0 -30px 14px; border-left: 0; border-right: 0; border-top: 0; border-radius: 0; }
.home-ticker.is-on { height: 34px; }
.home-ticker-in { height: 34px; }
.home-tk { font-size: 11px; }
.home-zone--hero .home-zone-body { padding: 16px 18px; display: flex; flex-direction: column; gap: 10px; overflow: hidden; }
.home-zone--hero {
  background:
    radial-gradient(130% 120% at 8% 0%, rgba(227,178,58,.11), transparent 55%),
    linear-gradient(180deg, rgba(255,255,255,.02), transparent 36%), var(--bg2);
}
.home-zone--hero .home-strip {
  flex: 0 0 auto; margin: 6px 0 0;
  display: flex; flex-wrap: wrap; align-content: flex-start;
  border: 1px solid var(--hud-line, var(--border)); border-radius: var(--radius);
  background: rgba(0,0,0,.22); padding: 6px;
}
.home-zone--hero .home-sess { flex: 1 1 46%; }
/* Le bouton s'ancre en BAS du bloc (margin-top auto) — rayon contenu, jamais la pilule qui s'arque. */
.home-zone--hero .home-skip { margin: auto 0 0; width: 100%; text-align: center; padding: 10px 12px; border-radius: 8px; }
/* ⚠️ La règle historique `.home-zone-body > * { height:100% }` (pensée pour « un corps = UN widget »)
   s'appliquait à CHAQUE enfant du héros : les textes se comprimaient à leur minimum et le bouton
   absorbait le reste — mesuré 234 px de haut (la « boîte or vide » constatée). Neutralisée ici. */
.home-zone--hero .home-hero-body > * { height: auto; }
/* (l'ancienne rangée .home-top n'existe plus — le héros vit dans la grille) */
.home-top { display: none; }

/* ── MENU MAISON des <select> de widgets (.dmx-sort-select) : le popup natif se place mal sous le
   zoom d'affichage, et la charte DTP proscrit les composants natifs. Ancré DANS la carte. ── */
.wdg-ddm {
  position: absolute; z-index: 1300; min-width: 150px; max-height: 262px; overflow-y: auto;
  background: var(--pop-bg, #16171b); border: 1px solid rgba(227,178,58,.32); border-radius: var(--radius);
  box-shadow: 0 14px 36px rgba(0,0,0,.55); padding: 4px;
  animation: wdgSheetIn .14s ease-out;
}
.wdg-ddm-it {
  display: flex; align-items: center; justify-content: space-between; gap: 10px; width: 100%;
  background: none; border: 0; border-radius: 4px; cursor: pointer; text-align: left;
  padding: 7px 10px; font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 11px; font-weight: 600;
  color: var(--text2);
}
.wdg-ddm-it:hover { background: var(--row-hover, rgba(255,255,255,.05)); color: var(--text); }
.wdg-ddm-it.on { color: var(--orange, #e3b23a); }
.wdg-ddm-ck { color: var(--orange, #e3b23a); font-size: 11px; }
/* ══ MENU DE SÉLECTION, VERSION LISTE LONGUE (02/09, référence « Price Chart Settings ») ═══════
   Le sélecteur de paire du graphique compte quarante-deux entrées. La référence les rend avec un
   champ de recherche, des puces de classe d'actif et un drapeau par paire : c'est ce qui transforme
   un déroulé qu'on parcourt en une liste qu'on interroge.
   ⚠️ L'en-tête est COLLANT et non fixe : `.wdg-ddm` est lui-même la boîte à défilement (max-height +
   overflow-y). Un en-tête posé en flux normal disparaîtrait dès la première molette, et on se
   retrouverait à chercher le champ de recherche en remontant la liste. */
.wdg-ddm-head {
  position: sticky; top: -4px; z-index: 2; margin: -4px -4px 4px; padding: 6px 6px 5px;
  display: flex; flex-direction: column; gap: 5px;
  background: var(--pop-bg, #16171b); border-bottom: 1px solid var(--hud-line, var(--border));
}
.wdg-ddm-rech {
  width: 100%; box-sizing: border-box; padding: 5px 8px;
  font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 11px; color: var(--text, #e6e8eb);
  background: var(--bg2); border: 1px solid var(--hud-line, var(--border)); border-radius: 4px; outline: none;
  transition: border-color .12s;
}
.wdg-ddm-rech::placeholder { color: var(--text4, #6b7280); }
.wdg-ddm-rech:focus { border-color: rgba(227, 178, 58, .55); }
.wdg-ddm-cls { display: flex; flex-wrap: wrap; gap: 4px; }
.wdg-ddm-cl {
  padding: 3px 8px; font-family: var(--tight, 'Inter Tight', sans-serif); font-size: 10px; font-weight: 600;
  color: var(--text3, #8a8f98); background: transparent;
  border: 1px solid var(--hud-line, var(--border)); border-radius: var(--pill, 999px);
  cursor: pointer; white-space: nowrap; transition: color .12s, border-color .12s, background .12s;
}
.wdg-ddm-cl:hover { color: var(--text); border-color: rgba(227, 178, 58, .45); }
.wdg-ddm-cl.on { color: #0c0c0e; background: var(--orange, #e3b23a); border-color: var(--orange, #e3b23a); }
html[data-theme="light"] .wdg-ddm-cl.on { color: #fff; }
.wdg-ddm-lbl { display: flex; align-items: center; gap: 7px; min-width: 0; }
/* Les deux drapeaux d'une paire se CHEVAUCHENT légèrement, comme le ticker d'accueil : deux
   vignettes côte à côte prendraient la largeur d'un libellé pour dire la même chose. */
.wdg-ddm-fl { display: inline-flex; align-items: center; flex: 0 0 auto; }
.wdg-ddm-fl .cal-flag-wrap { width: 13px; height: 13px; }
.wdg-ddm-fl .cal-flag-wrap + .cal-flag-wrap { margin-left: -4px; }
.wdg-ddm-fl .cal-flag-img { width: 13px; height: 13px; border-radius: 50%; object-fit: cover;
  box-shadow: 0 0 0 1px var(--pop-bg, #16171b); }
/* ⚠️ `.wdg-ddm-it` est en `display: flex` : sans cette règle, l'attribut `hidden` posé par le filtre
   serait sans effet (une déclaration d'auteur bat la feuille du navigateur) et la recherche
   n'aurait l'air de rien faire. */
.wdg-ddm-it[hidden] { display: none; }
.wdg-ddm-vide { padding: 9px 10px; font-size: 10.5px; color: var(--text4, #6b7280); }
.wdg-ddm-vide[hidden] { display: none; }
/* Une liste à drapeaux et à puces a besoin d'un peu plus de largeur que trois options de tri. */
.wdg-ddm:has(.wdg-ddm-head) { min-width: 208px; max-height: 320px; }

/* ── ACCUEIL v4 (03/08 « met comme ceci ») : ticker à drapeaux et segments teintés + cartes de desk
   VISUELLES (le plan 2D en visage, nom Fraunces par-dessus) + « Nouveau desk » dans l'en-tête. ── */

/* Ticker : chaque segment porte sa teinte directionnelle, drapeaux ronds chevauchés de la paire. */
.home-tk { gap: 8px; align-items: center; }
.home-tk.up { background: rgba(34, 197, 94, .07); }
.home-tk.down { background: rgba(255, 61, 0, .07); }
.home-tk-fl { display: inline-flex; align-items: center; flex: 0 0 auto; }
.home-tk-fl img {
  width: 15px; height: 15px; border-radius: 50%; object-fit: cover; display: block;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, .12);
}
.home-tk-fl img + img { margin-left: -5px; }
.home-tk b { color: var(--text2); }
.home-tk.up b, .home-tk.down b { color: var(--text); }

/* Cartes de desk VISUELLES : le plan remplit la carte, le nom se lit par-dessus. */
.home-zone-body--cards .home-cards { grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); gap: 12px; }
.home-card--visu {
  position: relative; display: block; padding: 0; overflow: hidden; min-height: 128px;
  border: 1px solid var(--hud-line, var(--border));
}
/* L'APERÇU REMPLIT LA CARTE (demande user 12/08 « il faut que ça remplisse le bloc »).
   Il était posé dans le flux : sa hauteur venait d'une propriété de ratio, et sa largeur d'un
   contexte de rétrécissement — dans le contenu anonyme d'un <button>, `aspect-ratio` + `min-height`
   se combinaient pour déduire la LARGEUR de la HAUTEUR (74 × 2,15 ≈ 159 px) au lieu de l'inverse :
   le plan tenait dans un coin d'une carte trois fois plus large. En le calant en absolu sur les
   quatre côtés, sa boîte devient DÉFINIE : plus de ratio à honorer, plus de coin vide, et le défaut
   d'`aspect-ratio` sur mobile disparaît de lui-même. Le nom, la méta et l'étoile sont déjà en
   position absolue avec z-index 2 — ils restent au-dessus. */
/* ⚠️ L'APERÇU A SON PROPRE FOND, PLUS SOMBRE QUE LA CARTE (correctif 12/08, régression que j'ai
   introduite le jour même). La carte porte `background: var(--bg2)` = #16171b, et j'ai peint les
   panneaux du plan dans ce MÊME #16171b : ils devenaient invisibles, la carte repassait « vide ».
   Le desk, lui, empile trois niveaux : page sombre, panneau plus clair, en-tête entre les deux.
   On rejoue cette hiérarchie — le fond de l'aperçu prend le rôle de la PAGE, les blocs celui des
   PANNEAUX. C'est ce contraste-là qui fait lire un plan de desk plutôt qu'un aplat. */
.home-card--visu .home-card-face { position: absolute; inset: 0; display: block; background: #0a0a0c; }
/* Disposition SANS widget : on le dit, au lieu de laisser un rectangle noir qu'on prend pour un
   bug. Même grammaire que la tuile « + Nouveau desk » — cadre pointillé or, texte discret. */
.home-card--visu .home-card-vide {
  position: absolute; inset: 10px; display: flex; align-items: center; justify-content: center;
  border: 1px dashed rgba(227, 178, 58, .35); border-radius: 5px;
  color: var(--text4); font-family: var(--tight, "Inter Tight", sans-serif);
  font-size: 11px; letter-spacing: .06em; text-transform: uppercase;
}
.home-card--visu .home-card-face .wdg-thumb { width: 100%; border: 0; border-radius: 0; background: transparent; }
.home-card--visu .home-card-face .wdg-thumb--plan {
  width: 100%; height: 100%; min-height: 0; aspect-ratio: auto;
}
.home-card--visu .home-card-face .wdg-thumb--plan::before { display: none; }
/* Les blocs respirent un peu plus quand ils occupent toute la carte. */
.home-card--visu .home-card-face .wdg-plan-in { inset: 7px; }
.home-card--visu::after {
  content: ''; position: absolute; inset: 0; pointer-events: none;
  background: linear-gradient(0deg, rgba(5, 5, 6, .78), rgba(5, 5, 6, .12) 55%, transparent);
}
.home-card--visu .home-card-fav { position: absolute; top: 8px; right: 10px; z-index: 2; }
.home-card--visu .home-card-nom {
  position: absolute; left: 12px; right: 12px; bottom: 26px; z-index: 2;
  font-family: var(--serif, 'Fraunces', Georgia, serif); font-size: 15px; font-weight: 600; color: #f2f3f5;
  text-shadow: 0 2px 10px rgba(0, 0, 0, .8); text-align: left;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.home-card--visu .home-card-meta { position: absolute; left: 12px; bottom: 10px; z-index: 2; }
.home-card--visu:hover { border-color: rgba(227, 178, 58, .55); }

/* « + Nouveau desk » et compteur dans l'en-tête du bloc, comme la référence. */
/* Le trait TIRETÉ signalait un emplacement à remplir, pas une action : le bouton avait l'air
   inachevé. Il devient une pastille pleine, bord fin et fond doré très dilué — la grammaire des
   cartes du desk — avec un relief au survol et un léger enfoncement au clic. */
.home-desks-new {
  flex: 0 0 auto; display: inline-flex; align-items: center; gap: 6px;
  padding: 5px 12px; cursor: pointer;
  border: 1px solid rgba(227, 178, 58, .34); border-radius: var(--radius, 6px);
  background: linear-gradient(180deg, rgba(227, 178, 58, .10), rgba(227, 178, 58, .04));
  color: var(--orange, #e3b23a); font-family: var(--tight, 'Inter Tight', sans-serif);
  font-size: 11px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .05);
  transition: color .16s, border-color .16s, background .16s, box-shadow .16s, transform .1s;
}
.home-desks-new:hover {
  color: #f0c95c; border-color: rgba(227, 178, 58, .66);
  background: linear-gradient(180deg, rgba(227, 178, 58, .19), rgba(227, 178, 58, .08));
  box-shadow: 0 3px 14px -6px rgba(227, 178, 58, .55), inset 0 1px 0 rgba(255, 255, 255, .09);
}
.home-desks-new:active { transform: translateY(1px); box-shadow: inset 0 1px 3px rgba(0, 0, 0, .35); }
.home-desks-count { flex: 0 0 auto; font-size: 10px; color: var(--text3); }

/* ════════════════════════════════════════════════════════════════════════════
   ACCUEIL v5 (03/08) : COHÉRENCE DESK TOTALE (« les mêmes panneaux que sur le
   desk ») — les blocs reprennent la grammaire EXACTE des cartes de widgets
   (.wdg-card / .wdg-head) ; ticker en bandeau STRUCTUREL hors défilement ;
   héros centré ; Mes desks en grandes cartes centrées ; Force bord à bord.
   ════════════════════════════════════════════════════════════════════════════ */

/* ── TICKER STRUCTUREL : l'overlay devient une colonne (bandeau + contenu défilant). Dans
   .home-inner, le ticker DÉFILAIT sous la topbar (le rognage constaté) ; ici il ne peut plus. ── */
.home-overlay { display: flex; flex-direction: column; overflow: hidden; }
.home-overlay > .home-inner {
  flex: 1 1 auto; min-height: 0; height: auto;
  overflow-y: auto; padding: 14px 30px 20px;
}
.home-inner > .home-grid { margin-top: 0; }
.home-ticker {
  flex: 0 0 auto; margin: 0; border: 0; border-radius: 0;
  border-bottom: 1px solid var(--hud-line, var(--border));
  background: var(--bg2);
}
.home-ticker.is-on { height: 38px; }
.home-ticker-in { height: 38px; }
.home-tk { font-size: 11.5px; padding: 0 18px; height: 100%; }
.home-tk.up { background: rgba(34, 197, 94, .10); }
.home-tk.down { background: rgba(255, 61, 0, .10); }
.home-tk-px { color: var(--text); }

/* ── PANNEAU = CARTE DE WIDGET DU DESK, à l'identique : mêmes fond, cadre, ombre au survol ;
   en-tête = .wdg-head (hauteur --navbar-h, fond --head-bg, titre .wdg-title). Le filet or
   décoratif et le dégradé disparaissent — le desk n'en a pas. ── */
.home-zone {
  background: var(--bg); box-shadow: none;
  transition: border-color .16s, box-shadow .16s;
}
.home-zone::after { display: none; }
.home-zone:hover { border-color: rgba(227, 178, 58, .38); box-shadow: 0 4px 18px rgba(0, 0, 0, .35); }
.home-panel-head {
  height: auto; min-height: var(--navbar-h, 28px); padding: 3px 8px; gap: 6px;
  background: var(--head-bg); border-bottom: 1px solid var(--hud-line, var(--border));
}
.home-panel-t {
  font-size: var(--fs-title, 11.5px); font-weight: var(--fw-semibold, 600);
  letter-spacing: var(--ls-caps, .08em); color: var(--text);
}
.home-panel-fill { background: none; height: auto; }

/* ── FORCE DES DEVISES BORD À BORD : le corps du panneau prend le MÊME anthracite que le fond
   des graphes du desk (#0d0e11) — marges d'axes et de badges se fondent, le graphe semble
   occuper tout le bloc, jusqu'aux rebords. ── */
#home-w-force-devises { background: #0d0e11; }
html[data-theme="light"] #home-w-force-devises { background: #ffffff; }
#home-w-force-devises .wdg-fx-tfbar { height: auto; padding: 5px 8px 3px; }

/* ── HÉROS CENTRÉ : le texte au centre vertical du bloc, le bouton dans son sillage — plus de
   colonne de vide entre le sous-titre et un bouton ancré tout en bas. ── */
.home-zone--hero .home-hero-body { justify-content: center; gap: 8px; padding: 22px 28px; }
.home-zone--hero .home-title { font-size: clamp(26px, 2.4vw, 34px); }
.home-zone--hero .home-skip {
  margin: 22px 0 0; width: auto; align-self: flex-start;
  padding: 10px 26px; border-radius: 6px;
  border-color: rgba(227, 178, 58, .4); color: var(--orange-dim, #b8860b);
}
.home-zone--hero .home-skip:hover { color: var(--orange); background: rgba(227, 178, 58, .1); }

/* ── MES DESKS : les cartes visuelles se CENTRENT dans le bloc (peu de desks = grandes cartes
   posées au centre, pas un timbre dans un coin) et grandissent au survol. ── */
.home-zone-body--cards { display: flex; padding: 14px; }
.home-zone-body--cards .home-cards {
  flex: 1 1 auto; height: auto;
  grid-template-columns: repeat(auto-fit, minmax(220px, 300px));
  justify-content: center; align-content: center; gap: 14px;
}
.home-card--visu { min-height: 144px; }
.home-card--visu .home-card-nom { font-size: 16px; }
.home-card--visu .home-card-face { overflow: hidden; }
.home-card--visu .home-card-face .wdg-thumb { transition: transform .25s var(--ease, ease); }
.home-card--visu:hover .home-card-face .wdg-thumb { transform: scale(1.03); }
.home-card--visu:hover { transform: translateY(-2px); box-shadow: 0 10px 28px rgba(0, 0, 0, .45); }
@media (prefers-reduced-motion: reduce) {
  .home-card--visu:hover .home-card-face .wdg-thumb { transform: none; }
}

/* ════════════════════════════════════════════════════════════════════════════
   MOBILE (03/08, captures user) : accueil sans débordement horizontal + desk.
   ════════════════════════════════════════════════════════════════════════════ */

/* ── ACCUEIL : CAUSE RACINE du « tout est rogné à gauche » — repeat(12, 1fr) = minmax(auto,1fr),
   la largeur MINIMALE d'un widget (table du calendrier…) élargissait donc TOUTES les colonnes
   au-delà de l'écran ; et l'overflow-y:auto de .home-inner rend l'axe X défilable par défaut →
   la page glissait horizontalement. minmax(0,1fr) interdit l'élargissement ; l'axe X est coupé. ── */
.home-grid { grid-template-columns: repeat(12, minmax(0, 1fr)); }
.home-overlay > .home-inner { overflow-x: hidden; }
@media (max-width: 860px) {
  .home-grid { grid-template-columns: minmax(0, 1fr); }
  .home-overlay > .home-inner { padding: 10px 12px 16px; }
  .home-ticker.is-on { height: 34px; }
  .home-ticker-in { height: 34px; }
  .home-tk { padding: 0 12px; gap: 6px; }
  .home-zone--hero .home-hero-body { padding: 18px 16px; }
  .home-zone--hero .home-title { font-size: 24px; }
  .home-zone--hero .home-skip { width: 100%; align-self: stretch; text-align: center; }
  .home-zone-body--cards { padding: 10px; }
  .home-zone-body--cards .home-cards { grid-template-columns: minmax(0, 1fr); }
}

/* ── DESK, panneau à onglets : sur téléphone les onglets DÉFILENT SOUS les icônes d'action
   semi-transparentes (collision constatée sur capture). Les actions deviennent un îlot opaque
   avec un fondu sur leur gauche — les onglets s'éteignent proprement dessous. ── */
@media (max-width: 860px) {
  .wdg-card--tabs > .wdg-head .wdg-actions {
    opacity: 1; background: var(--head-bg);
    box-shadow: -16px 0 12px -4px var(--head-bg);
  }
}

/* ── DESK, horloge mondiale : plancher de hauteur sur téléphone — un conteneur trop bas
   (container-type: size) pouvait laisser un corps quasi vide ; on garantit 3 rangées lisibles,
   le corps du widget défile si la carte est plus basse. ── */
@media (max-width: 560px) {
  .wdg-clockwrap { min-height: 132px; }
}

/* ── FOND DE L'ACCUEIL TRAVAILLÉ (03/08) : scène de terminal en 4 couches — (1) socle charbon en
   léger dégradé vertical, (2) deux ambiances OR (aube haut-gauche + braise basse-droite, signature
   DTP), (3) trame « papier millimétré » de salle de marché (cellules 44px, quasi subliminale),
   (4) vignette périphérique qui recentre l'œil sur les panneaux. L'aura animée existante (::after)
   continue de respirer par-dessus. ── */
.home-overlay {
  background:
    radial-gradient(1250px 520px at 10% -8%, rgba(227, 178, 58, .13), transparent 60%),
    radial-gradient(950px 460px at 97% 110%, rgba(184, 134, 11, .085), transparent 62%),
    radial-gradient(700px 300px at 58% -4%, rgba(227, 178, 58, .05), transparent 55%),
    linear-gradient(180deg, #0b0b0d, #09090b 58%, #0a0a0c);
}
.home-overlay::before {
  background:
    linear-gradient(0deg, rgba(0, 0, 0, .42), transparent 24%),
    radial-gradient(130% 95% at 50% 38%, transparent 55%, rgba(0, 0, 0, .42)),
    repeating-linear-gradient(0deg, rgba(255, 255, 255, .016) 0 1px, transparent 1px 44px),
    repeating-linear-gradient(90deg, rgba(255, 255, 255, .016) 0 1px, transparent 1px 44px),
    repeating-linear-gradient(0deg, rgba(255, 255, 255, .008) 0 1px, transparent 1px 3px);
}
/* Halo d'assise sous le bandeau ticker : la première ligne de l'écran porte une ombre or douce. */
.home-ticker.is-on { box-shadow: 0 14px 34px -20px rgba(227, 178, 58, .3), 0 6px 18px -10px rgba(0, 0, 0, .6); }
/* Les panneaux se détachent du fond : ombre portée courte + assise, sans changer leur cadre. */
.home-zone { box-shadow: 0 10px 30px -18px rgba(0, 0, 0, .75); }
.home-zone:hover { box-shadow: 0 10px 30px -14px rgba(0, 0, 0, .8), 0 4px 18px rgba(0, 0, 0, .35); }

/* ── FOND v2 (03/08 « continue et améliore le fond ») : la scène prend de la matière —
   ambiances or plus affirmées, halo d'horizon sous le ticker, trame millimétrée à DOUBLE
   maille (fine 44px + majeure 220px, façon papier de salle de marché), et GRAIN photographique
   (turbulence SVG inline, self-contained) qui donne le velours et supprime le banding. ── */
.home-overlay {
  background:
    radial-gradient(58% 110px at 50% 0%, rgba(227, 178, 58, .10), transparent),
    radial-gradient(1250px 540px at 10% -8%, rgba(227, 178, 58, .17), transparent 62%),
    radial-gradient(1000px 500px at 97% 112%, rgba(184, 134, 11, .12), transparent 64%),
    radial-gradient(760px 320px at 58% -4%, rgba(227, 178, 58, .06), transparent 55%),
    linear-gradient(180deg, #0c0c0f, #09090b 56%, #0b0a0c);
}
.home-overlay::before {
  background:
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/><feComponentTransfer><feFuncA type='linear' slope='0.055'/></feComponentTransfer></filter><rect width='160' height='160' filter='url(%23n)'/></svg>"),
    linear-gradient(0deg, rgba(0, 0, 0, .44), transparent 26%),
    radial-gradient(130% 95% at 50% 38%, transparent 54%, rgba(0, 0, 0, .44)),
    repeating-linear-gradient(0deg, rgba(255, 255, 255, .028) 0 1px, transparent 1px 220px),
    repeating-linear-gradient(90deg, rgba(255, 255, 255, .028) 0 1px, transparent 1px 220px),
    repeating-linear-gradient(0deg, rgba(255, 255, 255, .017) 0 1px, transparent 1px 44px),
    repeating-linear-gradient(90deg, rgba(255, 255, 255, .017) 0 1px, transparent 1px 44px);
}
/* L'aura respirante gagne légèrement en présence (mêmes 22 s, reduced-motion déjà respecté). */
.home-overlay::after {
  width: 1040px; height: 540px;
  background: radial-gradient(closest-side, rgba(227, 178, 58, .10), transparent 70%);
}

/* ── FOND DYNAMIQUE IDENTITAIRE (03/08 « un fond qui bouge légèrement… qui reflète l'identité de
   DTP ») : sous les panneaux, trois NAPPES aux deux ors signature (#e3b23a vif / #b8860b sombre)
   dérivent en périodes longues désynchronisées (38/46/30 s), et une COURBE DE MARCHÉ FANTÔME —
   ligne de cours or ascendante dessinée maison (SVG inline, self-contained) — glisse très
   lentement dans le tiers bas. Tout est animé UNIQUEMENT en transform (couches composites GPU :
   zéro repaint) ; une respiration organique, jamais un manège. L'ancienne aura ::after est
   remplacée. ── */
.home-overlay::after { display: none; }
.home-decor { position: absolute; inset: 0; z-index: 0; overflow: hidden; pointer-events: none; }
.home-decor i {
  position: absolute; display: block; border-radius: 50%;
  will-change: transform; transform: translate3d(0, 0, 0);
}
.home-decor i:nth-child(1) {
  top: -220px; left: -6%; width: 1150px; height: 560px;
  background: radial-gradient(closest-side, rgba(227, 178, 58, .10), rgba(227, 178, 58, .035) 46%, transparent 72%);
  animation: homeDeriveA 38s ease-in-out infinite alternate;
}
.home-decor i:nth-child(2) {
  bottom: -240px; right: -8%; width: 980px; height: 520px;
  background: radial-gradient(closest-side, rgba(184, 134, 11, .09), rgba(184, 134, 11, .03) 48%, transparent 72%);
  animation: homeDeriveB 46s ease-in-out -14s infinite alternate;
}
.home-decor i:nth-child(3) {
  top: 16%; left: 40%; width: 660px; height: 330px;
  background: radial-gradient(closest-side, rgba(227, 178, 58, .05), transparent 70%);
  animation: homeDeriveC 30s ease-in-out -9s infinite alternate;
}
/* Courbe de cours fantôme : polyline or ascendante (l'identité du métier), répétée en x,
   fondue verticalement par masque — présence subliminale, jamais une déco qui crie. */
.home-decor i:nth-child(4) {
  left: -10%; right: -10%; bottom: 6%; height: 300px; border-radius: 0;
  background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='1400' height='300' viewBox='0 0 1400 300'><path d='M0 224 L58 208 L116 218 L174 184 L232 198 L290 162 L348 176 L406 142 L464 158 L522 126 L580 146 L638 108 L696 128 L754 98 L812 118 L870 84 L928 102 L986 72 L1044 92 L1102 62 L1160 78 L1218 50 L1276 66 L1340 42 L1400 52' fill='none' stroke='rgba(227,178,58,0.09)' stroke-width='2'/><path d='M0 224 L58 208 L116 218 L174 184 L232 198 L290 162 L348 176 L406 142 L464 158 L522 126 L580 146 L638 108 L696 128 L754 98 L812 118 L870 84 L928 102 L986 72 L1044 92 L1102 62 L1160 78 L1218 50 L1276 66 L1340 42 L1400 52' fill='none' stroke='rgba(227,178,58,0.03)' stroke-width='6'/></svg>") repeat-x left bottom / 1400px 300px;
  -webkit-mask-image: linear-gradient(180deg, transparent, #000 34%, #000 78%, transparent);
  mask-image: linear-gradient(180deg, transparent, #000 34%, #000 78%, transparent);
  animation: homeDeriveD 70s ease-in-out -20s infinite alternate;
}
@keyframes homeDeriveA { to { transform: translate3d(74px, 26px, 0) scale(1.06); } }
@keyframes homeDeriveB { to { transform: translate3d(-64px, -22px, 0) scale(1.05); } }
@keyframes homeDeriveC { to { transform: translate3d(42px, 16px, 0) scale(1.04); } }
@keyframes homeDeriveD { to { transform: translate3d(-160px, -8px, 0); } }
@media (prefers-reduced-motion: reduce) { .home-decor i { animation: none; } }
@media (max-width: 860px) { .home-decor i:nth-child(3), .home-decor i:nth-child(4) { display: none; } }

/* ── FOND v4 (03/08 « améliore l'effet » + « pas concentré d'un seul côté, ça casse l'autre
   côté ») : effet PERCEPTIBLE et ÉQUILIBRÉ — la lumière vit aux QUATRE coins (aube gauche
   adoucie, réponse or en haut-droite, braise basse-droite, lueur basse-gauche), dérives plus
   amples, courbe de marché affirmée, et BALAYAGE LUMINEUX : un voile conique or qui tourne en
   120 s (rotation composite GPU) et distribue le mouvement sur TOUT l'écran, façon phare de
   salle des marchés — le fond vit partout, sans jamais gêner la lecture. ── */
.home-overlay {
  background:
    radial-gradient(58% 110px at 50% 0%, rgba(227, 178, 58, .09), transparent),
    radial-gradient(1150px 500px at 8% -8%, rgba(227, 178, 58, .13), transparent 62%),
    radial-gradient(1000px 460px at 94% -6%, rgba(227, 178, 58, .10), transparent 60%),
    radial-gradient(1000px 500px at 96% 112%, rgba(184, 134, 11, .11), transparent 64%),
    radial-gradient(900px 440px at 4% 110%, rgba(184, 134, 11, .08), transparent 62%),
    linear-gradient(180deg, #0c0c0f, #09090b 56%, #0b0a0c);
}
.home-decor i:nth-child(1) {
  background: radial-gradient(closest-side, rgba(227, 178, 58, .15), rgba(227, 178, 58, .05) 46%, transparent 74%);
}
.home-decor i:nth-child(2) {
