}
.home-hero-spark .sp-dot {
  fill: #e3b23a; opacity: 0;
  filter: drop-shadow(0 0 4px rgba(227, 178, 58, .85));
  animation: heroSparkDot 12s linear infinite;
}
@keyframes heroSparkDraw {
  0% { stroke-dashoffset: 1; opacity: 0; }
  6% { opacity: 1; }
  55% { stroke-dashoffset: 0; opacity: 1; }
  84% { stroke-dashoffset: 0; opacity: 1; }
  94% { stroke-dashoffset: 0; opacity: 0; }
