/* Filés : mêmes trajets, présence réduite. */
@keyframes homeFile {
  0%   { transform: translate3d(-36vw, 0, 0); opacity: 0; }
  12%  { opacity: .45; }
  88%  { opacity: .45; }
  100% { transform: translate3d(104vw, 0, 0); opacity: 0; }
