@keyframes homeFileR {
  0%   { transform: translate3d(104vw, 0, 0); opacity: 0; }
  14%  { opacity: .3; }
  86%  { opacity: .3; }
  100% { transform: translate3d(-28vw, 0, 0); opacity: 0; }
