}
#boot-loader .dtp-loader__spin::before {
  content: ''; position: absolute; top: 0; bottom: 0; left: 0; width: 34%;
  border-radius: 3px;
  background: linear-gradient(90deg, rgba(227, 178, 58, .25), #e3b23a 55%, rgba(227, 178, 58, .25));
