.wdg-cx-c.est-fort { font-weight: 700; }
/* Lien faible : le chiffre s'estompe avec le fond, la hiérarchie visuelle suit la mesure. */
.wdg-cx-c.est-faible { color: var(--w-t6, #9aa1ac); }
.wdg-cx-c.est-nd { background: var(--w-s3, rgba(255,255,255,.03)); color: var(--txt-3, #6b7280); font-size: 8px; }
.wdg-cx-pied { flex: 0 0 auto; font-size: 9.5px; line-height: 1.35; color: var(--txt-3, #6b7280); }
/* Carte étroite : les chiffres cèdent, les couleurs et les infobulles restent (une cellule de
   30 px avec « +87 » dedans déborde ; la teinte porte déjà signe et force). */
@container dtpw (max-width: 300px) {
  .wdg-cx-c { font-size: 0; }
