.wdg-ec-head, .wdg-ec-l { display: grid; grid-template-columns: minmax(110px, 1.4fr) minmax(84px, .9fr) minmax(96px, 1fr); gap: 8px; align-items: center; padding: 4px 12px; }
.wdg-ec-head { position: sticky; top: 0; z-index: 1; background: var(--w-s4, #101014); border-bottom: 1px solid var(--hud-line, rgba(255,255,255,.075)); font-size: 9px; font-weight: 600; text-transform: uppercase; letter-spacing: .05em; color: var(--w-t7, #6b7280); }
