.wdg-ec-b { font-size: 10px; font-weight: 700; white-space: nowrap; }
.wdg-ec-b.cv-pos { color: #00e676; }
.wdg-ec-b.cv-neg { color: #ff3d00; }
.wdg-ec-b.cv-neu { color: #ffb300; }
